ERROR_ALREADY_EXISTS = 183
PROCESS_QUERY_LIMITED_INFORMATION = 0x1000
SYNCHRONIZE = 0x00100000
KERNEL32 = ctypes.WinDLL("kernel32", use_last_error=True) if os.name == "nt" else None
if KERNEL32 is not None:
    KERNEL32.CreateMutexW.argtypes = [wintypes.LPVOID, wintypes.BOOL, wintypes.LPCWSTR]
    KERNEL32.CreateMutexW.restype = wintypes.HANDLE
    KERNEL32.OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
    KERNEL32.OpenProcess.restype = wintypes.HANDLE
    KERNEL32.CloseHandle.argtypes = [wintypes.HANDLE]
    KERNEL32.CloseHandle.restype = wintypes.BOOL


def acquire_windows_single_instance_mutex(name):
    if KERNEL32 is None:
        return None
    handle = KERNEL32.CreateMutexW(None, False, name)
    if not handle:
        raise ctypes.WinError(ctypes.get_last_error())
    if ctypes.get_last_error() == ERROR_ALREADY_EXISTS:
        KERNEL32.CloseHandle(handle)
        return None
    return handle


def release_windows_single_instance_mutex(handle):
    if KERNEL32 is None or not handle:
        return
    KERNEL32.CloseHandle(handle)


def is_windows_pid_running(pid):
    try:
        candidate = int(pid or 0)
    except Exception:
        return False
    if candidate <= 0:
        return False
    if KERNEL32 is None:
        try:
            os.kill(candidate, 0)
            return True
        except OSError:
            return False
    handle = KERNEL32.OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION | SYNCHRONIZE, False, candidate)
    if not handle:
        return False
    KERNEL32.CloseHandle(handle)
    return True


def read_pid_file(file_path):
    try:
        with open(file_path, "r", encoding="utf-8") as pid_file:
            return int((pid_file.read() or "").strip() or 0)
    except Exception:
        return 0


def write_pid_file(file_path, pid):
    os.makedirs(os.path.dirname(file_path), exist_ok=True)
    with open(file_path, "w", encoding="utf-8") as pid_file:
        pid_file.write(str(int(pid)))


def remove_pid_file(file_path, expected_pid=None):
    try:
        if expected_pid is not None and os.path.exists(file_path):
            current_pid = read_pid_file(file_path)
            if current_pid and int(current_pid) != int(expected_pid):
                return False
        if os.path.exists(file_path):
            os.remove(file_path)
        return True
    except Exception:
        return False


def get_control_panel_process_status():
    pid = read_pid_file(control_panel_pid_path)
    active = is_windows_pid_running(pid)
    if pid > 0 and not active:
        remove_pid_file(control_panel_pid_path, expected_pid=pid)
    return {
        "pid": pid if pid > 0 else 0,
        "active": active,
    }


def get_runtime_process_status():
    pid = read_pid_file(runtime_pid_path) or int(os.getpid())
    active = bool(runtime_state.get("runtime_process_active", False))
    return {
        "pid": pid if pid > 0 else 0,
        "active": active,
    }


def normalize_auth_mode(mode):
    normalized = normalize_text_content(mode).strip().lower()
    return normalized if normalized in {"api_key", "openai_chatgpt", "codex_oauth", "auto"} else ""


def normalize_runtime_lock_name(name):
    return normalize_runtime_lock_key(normalize_text_content(name))


def get_runtime_lock_snapshot():
    return {key: bool(value) for key, value in RUNTIME_SETTING_LOCKS.items()}


def get_runtime_lock_summary():
    locked = [key for key, enabled in RUNTIME_SETTING_LOCKS.items() if enabled]
    if not locked:
        return "locks=none"
    return "locks=" + ",".join(locked)


def get_overlay_status_summary():
    return (
        f"overlay(tile_grid={'on' if enable_colored_tile_grid else 'off'}, "
        f"cursor_label={'on' if SHOW_CURSOR_LABEL else 'off'}, "
        f"keypoint_grid={'on' if SHOW_KEYPOINT_GRID else 'off'}, "
        f"status_text={'on' if SHOW_STATUS_TEXT_OVERLAY else 'off'})"
    )


def is_runtime_setting_locked(name):
    normalized = normalize_runtime_lock_name(name)
    if not normalized:
        return False
    return bool(RUNTIME_SETTING_LOCKS.get(normalized, False))


def set_runtime_setting_lock(name, enabled=True):
    normalized = normalize_runtime_lock_name(name)
    if not normalized:
        raise ValueError(
            "Unknown lock name. Expected one of: "
            + ", ".join(sorted(RUNTIME_SETTING_LOCKS.keys()))
        )
    with SETTINGS_TRANSACTION_LOCK:
        RUNTIME_SETTING_LOCKS[normalized] = bool(enabled)
        append_runtime_feedback(
            f"Runtime lock {'enabled' if enabled else 'disabled'} for {normalized}."
        )
    return normalized, bool(enabled)


def require_runtime_setting_unlocked(name, action_label="This setting"):
    normalized = normalize_runtime_lock_name(name)
    if normalized and RUNTIME_SETTING_LOCKS.get(normalized, False):
        raise RuntimeError(f"{action_label} is locked by the current runtime policy.")
    return normalized


