def observe_registered_setting(definition):
    """Read a registered setting and the shared version from one in-memory snapshot."""
    state = build_registered_settings_runtime_state()
    return (build_setting_readback(definition.key, state, runtime_active=True, state_age_seconds=0.0),
            build_settings_version(state))


def execute_registered_setting_command(name, args, is_user=True):
    """Run a raw setter once under the transaction lock and verify its readback."""
    definition = setting_command_definition(name)
    shortcut = setting_shortcut_definition(name)
    writes = bool(args or shortcut)
    result = setting_command_result(name, operation=shortcut["operation"] if shortcut else "set" if args else "read")
    try:
        value = parse_setting_command_arguments(name, args)
        result["requested_value"] = value
    except ValueError as error:
        result["reason"] = str(error)
        return result
    with SETTINGS_TRANSACTION_LOCK:
        COMMAND_WORK.current().check()
        try:
            before, before_version = observe_registered_setting(definition)
            result.update(before_value=before.get("value") if before.get("effective") else None,
                          before_version=before_version, after_version=before_version,
                          value=before.get("value") if before.get("effective") else None,
                          value_status=before.get("value_status", "unavailable"))
        except Exception as error:
            result["reason"] = f"Setting observation failed before execution: {error}"
            return result
        if shortcut and shortcut["operation"] == "toggle":
            if not before.get("effective"):
                result["reason"] = f"Cannot toggle {definition.key} without an effective current value."
                return result
            value = (not before["value"] if definition.key == "runtime.live" else
                     "high" if before["value"] == "low" else "low")
            result["requested_value"] = value
        if writes and before.get("locked"):
            result["reason"] = f"{definition.key} is locked by runtime lock {definition.lock_key}."
            display_message("error", result["reason"])
            return result
        if writes and definition.operator_only and not is_user:
            result["reason"] = f"{definition.key} can only be changed by the operator."
            return result
        attempted = False
        try:
            canonical_args = build_setting_command_invocation(definition.key, value)[1] if args else []
            handler = command_dispatch[name.upper()]
            attempted = True
            returned = handler(canonical_args, is_user)
            if command_result_failed(returned):
                result["reason"] = f"Runtime setter reported failure: {name.upper()}."
            else:
                result["success"] = True
        except WorkCancelled as error:
            result.update(cancelled=True, reason=f"Cancelled; earlier setting effects are not undone: {error}")
        except Exception as error:
            result["reason"] = str(error)
        try:
            after, after_version = observe_registered_setting(definition)
            result.update(value=after.get("value") if after.get("effective") else None,
                          value_status=after.get("value_status", "unavailable"), after_version=after_version)
            if result["success"] and (not after.get("effective") or
                                      (writes and not setting_values_equal(definition.key, after.get("value"), value))):
                result.update(success=False, reason=f"Effective readback did not match {definition.key}.")
        except Exception as error:
            result.update(success=False, after_version="", value=None, value_status="unavailable",
                          reason=f"{result['reason']} Setting observation failed after execution: {error}".strip())
        result["effect_status"] = "observed" if result["success"] else "uncertain" if attempted else "not_started"
        return result


def execute_runtime_lock_command(name, args, is_user=True):
    """Serialize a lock read/change with settings transactions and retain observed evidence."""
    key = parse_lock_command_arguments(name, args)
    enabled = LOCK_COMMANDS[name.upper()]
    result = {"schema_version": "aurora_lock_command_result_v1", "command": name.upper(),
              "operation": "read" if not key else "lock" if enabled else "unlock", "lock_key": key,
              "success": False, "effect_status": "not_started", "before_locks": {}, "locks": {},
              "before_version": "", "after_version": "", "reason": ""}
    with SETTINGS_TRANSACTION_LOCK:
        COMMAND_WORK.current().check()
        attempted = False
        try:
            before = build_registered_settings_runtime_state()
            version = build_settings_version(before)
            result.update(before_locks=dict(before["locks"]), locks=dict(before["locks"]),
                          before_version=version, after_version=version)
            attempted = True
            returned = command_dispatch[name.upper()]([key] if key else [], is_user)
            if command_result_failed(returned):
                result["reason"] = f"Runtime lock handler reported failure: {name.upper()}."
            else:
                result["success"] = True
        except WorkCancelled as error:
            result.update(cancelled=True, reason=f"Cancelled; earlier lock effects are not undone: {error}")
        except Exception as error:
            result["reason"] = str(error)
        if attempted:
            try:
                after = build_registered_settings_runtime_state()
                result.update(locks=dict(after["locks"]), after_version=build_settings_version(after))
                if result["success"] and key and result["locks"].get(key) is not enabled:
                    result.update(success=False, reason=f"Runtime lock readback did not match {key}.")
            except Exception as error:
                result.update(success=False, locks={}, after_version="",
                              reason=f"{result['reason']} Lock observation failed after execution: {error}".strip())
        result["effect_status"] = "observed" if result["success"] else "uncertain" if attempted else "not_started"
        return result


def _settings_transaction_receipt_base(request, operation, before_version):
    transaction_id = normalize_text_content(request.get("transaction_id", "")).strip()
    return {
        "schema_version": SETTINGS_TRANSACTION_RECEIPT_SCHEMA_VERSION,
        "registry_schema_version": SETTINGS_REGISTRY_SCHEMA_VERSION,
        "receipt_id": f"settings-receipt-{transaction_id}" if transaction_id else f"settings-receipt-{uuid.uuid4().hex}",
        "transaction_id": transaction_id,
        "operation": operation,
        "scope": normalize_text_content(request.get("scope", "runtime_session")).strip() or "runtime_session",
        "status": "pending",
        "terminal": True,
        "dry_run": operation == "preview",
        "expected_version": normalize_text_content(request.get("expected_version", "")).strip(),
        "before_version": before_version,
        "after_version": before_version,
        "changes": [],
        "rejections": [],
        "rollback_handle": None,
        "no_automatic_replay": True,
        "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
    }


def _remember_settings_transaction_receipt(receipt):
    set_runtime_value("last_settings_transaction_receipt", dict(receipt or {}))
    return receipt


def _capture_settings_transaction_auxiliary():
    return {
        "scheduler": {
            "mode": TURN_SCHEDULER_MODE,
            "heartbeat_seconds": float(TURN_SCHEDULER_HEARTBEAT_SECONDS),
            "min_gap_seconds": float(TURN_SCHEDULER_MIN_GAP_SECONDS),
            "capture_wake_enabled": bool(TURN_SCHEDULER_CAPTURE_WAKE_ENABLED),
            "capture_wake_debounce_seconds": float(TURN_SCHEDULER_CAPTURE_WAKE_DEBOUNCE_SECONDS),
            "post_action_settle_seconds": float(TURN_SCHEDULER_POST_ACTION_SETTLE_SECONDS),
        },
        "game_profile_source": normalize_text_content(
            runtime_state.get("game_profile_source", GAME_PROFILE_SOURCE)
        ).strip() or GAME_PROFILE_SOURCE,
    }


def _invoke_registered_setting_change(key, value, is_user=True):
    command_name, args, command_text = build_setting_command_invocation(key, value)
    handler = command_dispatch.get(command_name)
    if handler is None:
        raise RuntimeError(f"No runtime command handler is registered for {key} ({command_name}).")
    result = handler(args, is_user)
    if result is False or (isinstance(result, dict) and result.get("success") is False):
        raise RuntimeError(f"Runtime setter rejected {command_text}.")
    return command_text


def _restore_scheduler_transaction_auxiliary(auxiliary):
    scheduler = dict((auxiliary or {}).get("scheduler", {}) or {})
    set_turn_scheduler_mode(scheduler["mode"])
    set_turn_heartbeat_seconds(scheduler["heartbeat_seconds"])
    set_turn_min_gap_seconds(scheduler["min_gap_seconds"])
    set_turn_capture_wake_enabled(scheduler["capture_wake_enabled"])
    set_turn_capture_wake_debounce_seconds(scheduler["capture_wake_debounce_seconds"])
    set_turn_post_action_settle_seconds(scheduler["post_action_settle_seconds"])


def _restore_settings_transaction_rows(rows, auxiliary, is_user=True):
    errors = []
    restore_commands = []
    restore_scheduler = False
    for row in reversed(list(rows or [])):
        key = row.get("key", "")
        try:
            if key == "scheduler.profile":
                restore_scheduler = True
                continue
            if key == "game.profile":
                source = normalize_text_content((auxiliary or {}).get("game_profile_source", "command")).strip() or "command"
                set_game_profile(row.get("before_value"), source=source)
                restore_commands.append(f"SET_GAME_PROFILE({row.get('before_value')})")
                continue
            restore_commands.append(
                _invoke_registered_setting_change(key, row.get("before_value"), is_user=is_user)
            )
        except Exception as error:
            errors.append({"key": key, "message": str(error)})
    if restore_scheduler:
        try:
            _restore_scheduler_transaction_auxiliary(auxiliary)
            restore_commands.append("RESTORE_TURN_SCHEDULER_AUXILIARY()")
        except Exception as error:
            errors.append({"key": "scheduler.profile", "message": str(error)})
    return restore_commands, errors


def _build_settings_transaction_change_receipts(plan_changes, state, *, projected=False):
    rows = []
    for change in plan_changes:
        readback = build_setting_readback(
            change.get("key"),
            state,
            runtime_active=True,
            state_age_seconds=0.0,
        )
        rows.append(
            {
                "key": change.get("key"),
                "input_key": change.get("input_key", change.get("key")),
                "before_value": change.get("before_value"),
                "requested_value": change.get("requested_value", change.get("value")),
                "normalized_value": change.get("value"),
                "projected_value": change.get("value") if projected else None,
                "after_value": readback.get("value"),
                "changed": bool(change.get("changed")),
                "apply_timing": change.get("apply_timing", ""),
                "risk_class": change.get("risk_class", ""),
                "effective_readback": readback,
            }
        )
    return rows


def _store_settings_rollback_handle(request, plan, before_auxiliary, after_version):
    handle_id = f"settings-rb-{uuid.uuid4().hex}"
    record = {
        "schema_version": SETTINGS_ROLLBACK_HANDLE_SCHEMA_VERSION,
        "handle_id": handle_id,
        "status": "available",
        "scope": "runtime_session",
        "transaction_id": plan.get("transaction_id", ""),
        "before_version": plan.get("current_version", ""),
        "after_version": after_version,
        "changes": [dict(row) for row in plan.get("changes", []) if row.get("changed")],
        "before_auxiliary": dict(before_auxiliary or {}),
        "created_at": datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z"),
        "expires": "runtime_shutdown",
    }
    SETTINGS_ROLLBACK_STORE[handle_id] = record
    while len(SETTINGS_ROLLBACK_STORE) > SETTINGS_ROLLBACK_STORE_LIMIT:
        SETTINGS_ROLLBACK_STORE.pop(next(iter(SETTINGS_ROLLBACK_STORE)))
    return {
        key: record[key]
        for key in (
            "schema_version",
            "handle_id",
            "status",
            "scope",
            "transaction_id",
            "before_version",
            "after_version",
            "created_at",
            "expires",
        )
    }


def build_settings_transaction_runtime_snapshot():
    with SETTINGS_TRANSACTION_LOCK:
        state = build_registered_settings_runtime_state()
        last_receipt = dict(runtime_state.get("last_settings_transaction_receipt", {}) or {})
        return {
            "schema_version": "aurora_settings_transaction_runtime_v1",
            "registry": settings_registry_summary(),
            "version": build_settings_version(state),
            "scope": "runtime_session",
            "write_enabled": True,
            "atomic_apply": True,
            "expected_version_required": True,
            "transaction_active": bool(runtime_state.get("settings_transaction_active", False)),
            "rollback_handle_count": sum(
                1 for row in SETTINGS_ROLLBACK_STORE.values() if row.get("status") == "available"
            ),
            "last_receipt": {
                key: last_receipt.get(key)
                for key in (
                    "schema_version",
                    "receipt_id",
                    "transaction_id",
                    "operation",
                    "status",
                    "before_version",
                    "after_version",
                    "created_at",
                )
                if key in last_receipt
            },
        }


def _execute_settings_preview_or_apply(request, is_user=True):
    operation = normalize_text_content(request.get("operation", "")).strip().lower()
    state = build_registered_settings_runtime_state()
    plan = plan_settings_transaction(request, state)
    receipt = _settings_transaction_receipt_base(request, operation, plan.get("current_version", ""))
    receipt["plan_schema_version"] = plan.get("schema_version")
    if operation == "apply" and not is_user:
        protected = [row["key"] for row in plan.get("changes", [])
                     if row.get("changed") and resolve_setting_definition(row["key"]).operator_only]
        if protected:
            receipt.update(status="rejected", rejections=[{"code": "operator_only",
                           "message": "Only the operator may change task limits: " + ", ".join(protected)}])
            return False, _remember_settings_transaction_receipt(receipt)
    if not plan.get("valid"):
        receipt["status"] = "rejected"
        receipt["rejections"] = list(plan.get("rejections", []) or [])
        receipt["changes"] = _build_settings_transaction_change_receipts(
            plan.get("changes", []),
            state,
            projected=operation == "preview",
        )
        return False, _remember_settings_transaction_receipt(receipt)

    if operation == "preview":
        receipt["status"] = "previewed"
        receipt["changes"] = _build_settings_transaction_change_receipts(
            plan.get("changes", []),
            state,
            projected=True,
        )
        return True, _remember_settings_transaction_receipt(receipt)

    before_auxiliary = _capture_settings_transaction_auxiliary()
    attempted_rows = []
    applied_commands = []
    try:
        for row in plan.get("changes", []):
            if not row.get("changed"):
                continue
            attempted_rows.append(row)
            applied_commands.append(
                _invoke_registered_setting_change(row.get("key"), row.get("value"), is_user=is_user)
            )
        after_state = build_registered_settings_runtime_state()
        mismatches = []
        for row in plan.get("changes", []):
            readback = build_setting_readback(
                row.get("key"),
                after_state,
                runtime_active=True,
                state_age_seconds=0.0,
            )
            if not setting_values_equal(row.get("key"), readback.get("value"), row.get("value")):
                mismatches.append(row.get("key"))
        if mismatches:
            raise RuntimeError(
                "Effective readback did not match the requested value for: " + ", ".join(mismatches)
            )
    except Exception as error:
        restore_commands, restore_errors = _restore_settings_transaction_rows(
            attempted_rows,
            before_auxiliary,
            is_user=is_user,
        )
        final_state = build_registered_settings_runtime_state()
        final_version = build_settings_version(final_state)
        rolled_back = not restore_errors and final_version == plan.get("current_version")
        receipt["status"] = "failed_rolled_back" if rolled_back else "rollback_failed"
        receipt["after_version"] = final_version
        receipt["applied_commands"] = applied_commands
        receipt["restore_commands"] = restore_commands
        receipt["rejections"] = [{"code": "apply_failed", "message": str(error)}]
        if isinstance(error, WorkCancelled):
            receipt["cancelled"] = True
        if restore_errors:
            receipt["rejections"].append(
                {
                    "code": "rollback_failed",
                    "message": "One or more settings could not be restored.",
                    "details": restore_errors,
                }
            )
        receipt["changes"] = _build_settings_transaction_change_receipts(
            plan.get("changes", []),
            final_state,
        )
        return False, _remember_settings_transaction_receipt(receipt)

    after_state = build_registered_settings_runtime_state()
    after_version = build_settings_version(after_state)
    receipt["status"] = "applied" if attempted_rows else "applied_noop"
    receipt["after_version"] = after_version
    receipt["applied_commands"] = applied_commands
    receipt["changes"] = _build_settings_transaction_change_receipts(
        plan.get("changes", []),
        after_state,
    )
    if attempted_rows:
        receipt["rollback_handle"] = _store_settings_rollback_handle(
            request,
            plan,
            before_auxiliary,
            after_version,
        )
    return True, _remember_settings_transaction_receipt(receipt)


def _execute_settings_rollback(request, is_user=True):
    state = build_registered_settings_runtime_state()
    current_version = build_settings_version(state)
    receipt = _settings_transaction_receipt_base(request, "rollback", current_version)
    expected_version = normalize_text_content(request.get("expected_version", "")).strip()
    handle_id = normalize_text_content(request.get("rollback_handle", "")).strip()
    record = SETTINGS_ROLLBACK_STORE.get(handle_id)
    rejections = []
    if normalize_text_content(request.get("scope", "")).strip().lower() != "runtime_session":
        rejections.append({"code": "scope_not_enabled", "message": "Only runtime_session rollback is enabled."})
    if not expected_version:
        rejections.append({"code": "expected_version_required", "message": "expected_version is required."})
    elif expected_version != current_version:
        rejections.append(
            {
                "code": "version_conflict",
                "message": f"Expected settings version {expected_version}, but current version is {current_version}.",
            }
        )
    if record is None:
        rejections.append({"code": "unknown_rollback_handle", "message": f"Unknown rollback handle: {handle_id or '-'}"})
    elif record.get("status") != "available":
        rejections.append({"code": "rollback_handle_consumed", "message": f"Rollback handle {handle_id} is not available."})
    elif record.get("after_version") != current_version:
        rejections.append(
            {
                "code": "rollback_state_diverged",
                "message": "Current settings no longer match the state produced by this rollback handle.",
            }
        )
    if record and not is_user and any(resolve_setting_definition(row["key"]).operator_only
                                     for row in record.get("changes", [])):
        rejections.append({"code": "operator_only", "message": "Only the operator may roll back task limits."})
    if rejections:
        receipt["status"] = "rejected"
        receipt["rejections"] = rejections
        return False, _remember_settings_transaction_receipt(receipt)

    rows = [dict(row) for row in record.get("changes", [])]
    current_auxiliary = _capture_settings_transaction_auxiliary()
    restore_commands, restore_errors = _restore_settings_transaction_rows(
        rows,
        record.get("before_auxiliary", {}),
        is_user=is_user,
    )
    final_state = build_registered_settings_runtime_state()
    final_version = build_settings_version(final_state)
    if restore_errors or final_version != record.get("before_version"):
        recovery_rows = []
        for row in rows:
            recovery_row = dict(row)
            recovery_row["before_value"] = row.get("value")
            recovery_rows.append(recovery_row)
        recovery_commands, recovery_errors = _restore_settings_transaction_rows(
            recovery_rows,
            current_auxiliary,
            is_user=is_user,
        )
        recovered_state = build_registered_settings_runtime_state()
        recovered_version = build_settings_version(recovered_state)
        recovered = not recovery_errors and recovered_version == current_version
        receipt["status"] = "rollback_failed_recovered" if recovered else "rollback_failed_uncertain"
        receipt["after_version"] = recovered_version
        receipt["restore_commands"] = restore_commands
        receipt["recovery_commands"] = recovery_commands
        receipt["rejections"] = [
            {
                "code": "rollback_failed",
                "message": "Rollback did not reproduce the recorded before-version.",
                "details": restore_errors,
            }
        ]
        if recovery_errors:
            receipt["rejections"].append(
                {
                    "code": "recovery_failed",
                    "message": "Aurora could not fully restore the pre-rollback state.",
                    "details": recovery_errors,
                }
            )
        receipt["changes"] = _build_settings_transaction_change_receipts(rows, recovered_state)
        return False, _remember_settings_transaction_receipt(receipt)

    record["status"] = "consumed"
    record["consumed_at"] = datetime.datetime.now(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
    receipt["status"] = "rolled_back"
    receipt["after_version"] = final_version
    receipt["restore_commands"] = restore_commands
    receipt["changes"] = _build_settings_transaction_change_receipts(rows, final_state)
    receipt["rollback_handle"] = {
        "schema_version": record.get("schema_version"),
        "handle_id": handle_id,
        "status": "consumed",
        "consumed_at": record.get("consumed_at"),
    }
    return True, _remember_settings_transaction_receipt(receipt)


def execute_settings_transaction_request(request, is_user=True):
    operation = normalize_text_content(request.get("operation", "")).strip().lower()
    with SETTINGS_TRANSACTION_LOCK:
        before_version = ""
        attempted = False
        try:
            before_version = build_settings_version(build_registered_settings_runtime_state())
            set_runtime_value("settings_transaction_active", True)
            if operation in {"preview", "apply"}:
                attempted = True
                return _execute_settings_preview_or_apply(request, is_user=is_user)
            if operation == "rollback":
                attempted = True
                return _execute_settings_rollback(request, is_user=is_user)
            state = build_registered_settings_runtime_state()
            receipt = _settings_transaction_receipt_base(request, operation or "unknown", build_settings_version(state))
            receipt["status"] = "rejected"
            receipt["rejections"] = [{"code": "invalid_operation", "message": "Unknown settings transaction operation."}]
            return False, _remember_settings_transaction_receipt(receipt)
        except Exception as error:
            receipt = _settings_transaction_receipt_base(request, operation, before_version)
            receipt["status"] = "failed_uncertain" if attempted else "rejected"
            receipt["after_version"] = ""
            receipt["rejections"] = [{"code": "execution_uncertain" if attempted else "runtime_observation_failed",
                                      "message": str(error)}]
            if isinstance(error, WorkCancelled):
                receipt["cancelled"] = True
            try:
                receipt["after_version"] = build_settings_version(build_registered_settings_runtime_state())
            except Exception as observation_error:
                receipt["rejections"].append({"code": "readback_failed", "message": str(observation_error)})
            # A failed receipt publication must not change an uncertain effect into an admission rejection.
            try:
                _remember_settings_transaction_receipt(receipt)
            except Exception as publication_error:
                receipt["rejections"].append({"code": "receipt_publication_failed", "message": str(publication_error)})
            return False, receipt
        finally:
            set_runtime_value("settings_transaction_active", False)


def _settings_transaction_command(args, is_user, expected_operation):
    request = {
        "transaction_id": "",
        "operation": expected_operation,
        "scope": "runtime_session",
        "expected_version": "",
    }
    try:
        request = parse_settings_transaction_command(f"{expected_operation.upper()}_SETTINGS_TRANSACTION", args)
    except ValueError as error:
        with SETTINGS_TRANSACTION_LOCK:
            state = build_registered_settings_runtime_state()
            receipt = _settings_transaction_receipt_base(
                request,
                expected_operation,
                build_settings_version(state),
            )
            receipt["status"] = "rejected"
            receipt["rejections"] = [{"code": "invalid_request", "message": str(error)}]
            _remember_settings_transaction_receipt(receipt)
        success = False
    else:
        success, receipt = execute_settings_transaction_request(request, is_user=is_user)
    summary = (
        f"Settings transaction {receipt.get('transaction_id') or '-'}: {receipt.get('status')} | "
        f"before={receipt.get('before_version') or '-'} | after={receipt.get('after_version') or '-'}"
    )
    display_message("system" if success else "error", summary)
    return {"success": success, "settings_transaction_receipt": receipt,
            "cancelled": bool(receipt.get("cancelled")),
            "reason": "; ".join(row.get("message", "") for row in receipt.get("rejections", []))}


def preview_settings_transaction_command(args, is_user):
    return _settings_transaction_command(args, is_user, "preview")


def apply_settings_transaction_command(args, is_user):
    return _settings_transaction_command(args, is_user, "apply")


def rollback_settings_transaction_command(args, is_user):
    return _settings_transaction_command(args, is_user, "rollback")


def hash_operator_passcode(passcode):
    normalized = normalize_text_content(passcode).strip()
    if not normalized:
        return ""
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest()


def has_operator_passcode():
    return bool(OPERATOR_PASSCODE_HASH)


def is_operator_passcode_required():
    return bool(OPERATOR_PASSCODE_REQUIRED and has_operator_passcode())


def clear_operator_authorization(reason=""):
    OPERATOR_SECURITY_STATE["authorized_until_epoch"] = 0.0
    OPERATOR_SECURITY_STATE["last_authorized_at"] = ""
    OPERATOR_SECURITY_STATE["last_authorized_source"] = ""
    if reason:
        append_runtime_feedback(reason)


def is_operator_authorized():
    if not is_operator_passcode_required():
        return True
    return float(OPERATOR_SECURITY_STATE.get("authorized_until_epoch", 0.0) or 0.0) > time.time()


def set_operator_passcode(passcode):
    global OPERATOR_PASSCODE_HASH, OPERATOR_PASSCODE_REQUIRED
    hashed = hash_operator_passcode(passcode)
    if not hashed:
        raise ValueError("SET_OPERATOR_PASSCODE requires a non-empty passcode.")
    OPERATOR_PASSCODE_HASH = hashed
    OPERATOR_PASSCODE_REQUIRED = True
    clear_operator_authorization()
    append_runtime_feedback("External operator passcode updated. Privileged operator commands now require authorization.")
    return get_operator_security_snapshot()


def clear_operator_passcode():
    global OPERATOR_PASSCODE_HASH, OPERATOR_PASSCODE_REQUIRED
    OPERATOR_PASSCODE_HASH = ""
    OPERATOR_PASSCODE_REQUIRED = False
    clear_operator_authorization()
    append_runtime_feedback("External operator passcode cleared.")
    return get_operator_security_snapshot()


def set_operator_passcode_required(enabled):
    global OPERATOR_PASSCODE_REQUIRED
    desired = bool(enabled)
    if desired and not has_operator_passcode():
        raise ValueError("Cannot require an operator passcode until one has been set.")
    OPERATOR_PASSCODE_REQUIRED = desired
    if not desired:
        clear_operator_authorization()
    append_runtime_feedback(
        f"External operator passcode requirement {'enabled' if OPERATOR_PASSCODE_REQUIRED else 'disabled'}."
    )
    return get_operator_security_snapshot()


def authorize_operator(passcode, source="external"):
    if not has_operator_passcode():
        raise RuntimeError("No operator passcode is configured.")
    hashed = hash_operator_passcode(passcode)
    if not hashed or hashed != OPERATOR_PASSCODE_HASH:
        raise ValueError("Operator passcode was not accepted.")
    authorized_until_epoch = time.time() + float(OPERATOR_AUTH_TTL_SECONDS)
    OPERATOR_SECURITY_STATE["authorized_until_epoch"] = authorized_until_epoch
    OPERATOR_SECURITY_STATE["last_authorized_at"] = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    OPERATOR_SECURITY_STATE["last_authorized_source"] = normalize_text_content(source).strip() or "external"
    append_runtime_feedback(
        f"External operator authorized for {int(OPERATOR_AUTH_TTL_SECONDS)}s via {OPERATOR_SECURITY_STATE['last_authorized_source']}."
    )
    return get_operator_security_snapshot()


def get_operator_security_snapshot():
    authorized_until_epoch = float(OPERATOR_SECURITY_STATE.get("authorized_until_epoch", 0.0) or 0.0)
    seconds_remaining = max(0, int(round(authorized_until_epoch - time.time())))
    return {
        "passcode_required": bool(OPERATOR_PASSCODE_REQUIRED),
        "has_passcode": has_operator_passcode(),
        "show_passcode_commands": bool(PASSCODE_COMMAND_VISIBILITY),
        "authorized": is_operator_authorized(),
        "authorized_until_epoch": authorized_until_epoch,
        "authorized_seconds_remaining": seconds_remaining,
        "authorization_ttl_seconds": int(OPERATOR_AUTH_TTL_SECONDS),
        "last_authorized_at": normalize_text_content(OPERATOR_SECURITY_STATE.get("last_authorized_at", "")).strip(),
        "last_authorized_source": normalize_text_content(OPERATOR_SECURITY_STATE.get("last_authorized_source", "")).strip(),
    }


def get_operator_security_summary():
    snapshot = get_operator_security_snapshot()
    if not snapshot["has_passcode"]:
        return "operator_security=off | authorized=yes | ttl=0s"
    status = "authorized" if snapshot["authorized"] else "locked"
    remaining = snapshot["authorized_seconds_remaining"]
    source = snapshot.get("last_authorized_source", "") or "-"
    return (
        f"operator_security={'required' if snapshot['passcode_required'] else 'configured'}"
        f" | operator_status={status}"
        f" | operator_ttl={remaining}s"
        f" | operator_source={source}"
        f" | operator_visibility={'raw' if snapshot['show_passcode_commands'] else PASSCODE_COMMAND_MASK}"
    )


def set_passcode_command_visibility(enabled):
    global PASSCODE_COMMAND_VISIBILITY
    PASSCODE_COMMAND_VISIBILITY = bool(enabled)
    append_runtime_feedback(
        f"Passcode command visibility {'enabled' if PASSCODE_COMMAND_VISIBILITY else f'masked as {PASSCODE_COMMAND_MASK}'}. "
        "This affects command/chat/bridge logging and operator-facing previews."
    )
    return PASSCODE_COMMAND_VISIBILITY


def sanitize_sensitive_command_text(text, visible=None):
    if text is None:
        return text
    if visible is None:
        visible = PASSCODE_COMMAND_VISIBILITY
    if visible:
        return text
    normalized_text = normalize_text_content(text)
    if not normalized_text:
        return normalized_text
    return re.sub(
        r'(?i)\b(SET_OPERATOR_PASSCODE|AUTHORIZE_OPERATOR)\s*\((.*?)\)',
        lambda match: f"{match.group(1)}({json.dumps(PASSCODE_COMMAND_MASK, ensure_ascii=False)})",
        normalized_text,
        flags=re.DOTALL,
    )


def sanitize_sensitive_payload(value, visible=None):
    if visible is None:
        visible = PASSCODE_COMMAND_VISIBILITY
    if isinstance(value, str):
        return sanitize_sensitive_command_text(value, visible=visible)
    if isinstance(value, list):
        return [sanitize_sensitive_payload(item, visible=visible) for item in value]
    if isinstance(value, tuple):
        return [sanitize_sensitive_payload(item, visible=visible) for item in value]
    if isinstance(value, dict):
        return {key: sanitize_sensitive_payload(item, visible=visible) for key, item in value.items()}
    return value


def sanitize_sensitive_record(record: dict[str, Any]) -> dict[str, Any]:
    sanitized = sanitize_sensitive_payload(record)
    if isinstance(sanitized, dict):
        return sanitized
    return dict(record)


def update_auth_runtime_state(resolved_mode="", source="", error=""):
    runtime_state["auth_mode_configured"] = AUTH_MODE
    runtime_state["auth_mode_resolved"] = normalize_auth_mode(resolved_mode) or ""
    runtime_state["auth_source"] = normalize_text_content(source).strip()
    runtime_state["auth_error"] = normalize_text_content(error).strip()


def get_codex_oauth_manager():
    global _codex_oauth_manager
    if _codex_oauth_manager is None:
        cache_path = Path(CODEX_OAUTH_CACHE_FILE) if CODEX_OAUTH_CACHE_FILE else Path(codex_oauth_cache_path)
        auth_path = Path(CODEX_OAUTH_AUTH_FILE) if CODEX_OAUTH_AUTH_FILE else None
        _codex_oauth_manager = CodexOAuthManager(
            cache_path=cache_path,
            codex_auth_path=auth_path,
        )
    return _codex_oauth_manager


def get_openai_bearer_token(force_refresh=False):
    global _last_auth_resolution
    errors = []
    if AUTH_MODE == "openai_chatgpt":
        raise ValueError("ChatGPT subscription credentials are restricted to the subscription Responses adapter.")

    if AUTH_MODE in {"codex_oauth", "auto"}:
        try:
            token = get_codex_oauth_manager().get_api_access_token(force_refresh=force_refresh)
            _last_auth_resolution = {
                "mode": "codex_oauth",
                "source": str(get_codex_oauth_manager().cache_path),
                "error": "",
            }
            update_auth_runtime_state("codex_oauth", _last_auth_resolution["source"], "")
            return token, "codex_oauth"
        except CodexOAuthError as error:
            errors.append(str(error))
            if AUTH_MODE == "codex_oauth":
                _last_auth_resolution = {"mode": "codex_oauth", "source": "", "error": str(error)}
                update_auth_runtime_state("codex_oauth", "", str(error))
                raise

    if API_KEY:
        _last_auth_resolution = {"mode": "api_key", "source": "OPENAI_2023_API_KEY" if os.getenv("OPENAI_2023_API_KEY") else "OPENAI_API_KEY", "error": ""}
        update_auth_runtime_state("api_key", _last_auth_resolution["source"], "")
        return API_KEY, "api_key"

    error_text = "; ".join(errors) if errors else "API key not found and codex_oauth is unavailable."
    _last_auth_resolution = {"mode": "", "source": "", "error": error_text}
    update_auth_runtime_state("", "", error_text)
    raise ValueError(error_text)


def build_openai_headers(force_refresh=False):
    token, resolved_mode = get_openai_bearer_token(force_refresh=force_refresh)
    return {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {token}",
    }, resolved_mode


def perform_model_http_request(packet, cancellation_token):
    """Network-only worker: frozen inputs; no runtime/history/command writes."""
    import aurora_execution_evidence as evidence
    evidence.instrumented()
    config = packet["auth"]
    if config["mode"] == "openai_chatgpt":
        if not packet["url"].endswith("/chat/completions"):
            raise ValueError("This endpoint is unavailable for ChatGPT subscription auth; no API-key fallback.")
        from aurora_chatgpt_transport import perform_subscription_request
        response = perform_subscription_request(packet["payload"], cancellation_token, policy=config.get("subscription_policy", "legacy"))
        return response, "openai_chatgpt", "Aurora protected ChatGPT registration"
    if packet["payload"].get("service_tier"):
        raise ValueError("Accelerated tiers currently require the catalog-verified ChatGPT subscription route. Select Regular for this transport.")

    def headers(force_refresh=False):
        oauth_error = None
        if config["mode"] in {"codex_oauth", "auto"}:
            try:
                manager = CodexOAuthManager(
                    cache_path=Path(config["cache_path"]),
                    codex_auth_path=Path(config["auth_path"]) if config["auth_path"] else None,
                )
                token = manager.get_api_access_token(force_refresh=force_refresh)
                return {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}, "codex_oauth", str(manager.cache_path)
            except CodexOAuthError as error:
                oauth_error = error
                if config["mode"] == "codex_oauth":
                    raise
        if config["api_key"]:
            return {"Authorization": f"Bearer {config['api_key']}", "Content-Type": "application/json"}, "api_key", "OPENAI_2023_API_KEY" if os.getenv("OPENAI_2023_API_KEY") else "OPENAI_API_KEY"
        raise ValueError(str(oauth_error) if oauth_error else "API key not found and codex_oauth is unavailable.")

    cancellation_token.check()
    request_headers, resolved_mode, source = headers()
    cancellation_token.check()
    evidence.attempt(packet["payload"], "responses" if packet["url"].endswith("/responses") else "chat_completions", resolved_mode)
    response = requests.post(
        packet["url"], headers=request_headers,
        json=packet["payload"], timeout=packet["timeout"],
    )
    evidence.http_response(response)
    if response.status_code in {401, 403} and resolved_mode == "codex_oauth":
        cancellation_token.check()
        request_headers, resolved_mode, source = headers(force_refresh=True)
        cancellation_token.check()
        evidence.attempt(packet["payload"], "responses" if packet["url"].endswith("/responses") else "chat_completions", resolved_mode)
        response = requests.post(
            packet["url"], headers=request_headers,
            json=packet["payload"], timeout=packet["timeout"],
        )
        evidence.http_response(response)
    return response, resolved_mode, source


def service_runtime_control_during_model_wait():
    """Service ingress/receipts without recursively scheduling another model turn."""
    if threading.current_thread() is not threading.main_thread() or active_runtime_context is None:
        return
    poll_external_reply_bridges()
    MODEL_WORK.current().check()
    drain_runtime_command_results(active_runtime_context)
    drain_runtime_processed_capture(active_runtime_context)
    write_control_panel_state_snapshot()


def post_openai_model_request(payload, endpoint, timeout=None, *, selection=None):
    global _last_auth_resolution
    packet = {
        "payload": payload, "timeout": timeout if timeout is not None else 60,
        "url": f"https://api.openai.com/v1/{endpoint}",
        "auth": {"mode": AUTH_MODE, "api_key": API_KEY, "subscription_policy": SUBSCRIPTION_POLICY,
                 "cache_path": str(CODEX_OAUTH_CACHE_FILE or codex_oauth_cache_path),
                 "auth_path": str(CODEX_OAUTH_AUTH_FILE or "")},
    }
    token = MODEL_WORK.current()
    token.check()
    delivery = current_delivery()
    tracked = delivery is not None and delivery.phase == "prepared" and endpoint in {"chat/completions", "responses"}
    from aurora_execution_evidence import TransportEvidence, observe_transport
    evidence = TransportEvidence(payload, selection)
    if tracked:
        # ContextVars do not cross the network-thread boundary. Carry only frozen
        # local identities in the internal envelope, never in the provider body.
        packet["correlation"] = {
            "inference_request_id": delivery.inference_request_id,
            "task_id": getattr(delivery, "task_id", ""),
            "frame_id": getattr(delivery, "frame_id", ""),
        }
        delivery.transport_evidence = evidence.snapshot()
        delivery.emit("submitted", model=payload.get("model", ""),
                      reason="Request path started; provider receipt is not yet confirmed.")
        COMMAND_READBACKS.mark_request(delivery.inference_request_id, "submitted")
    def transport(frozen):
        with observe_transport(evidence):
            return perform_model_http_request(frozen, token)
    try:
        response, resolved_mode, source = MODEL_IO.call(
            transport, packet, token, service_control=service_runtime_control_during_model_wait,
        )
    finally:
        snapshot = evidence.snapshot(close=True)
        if tracked:
            delivery.transport_evidence = snapshot
    token.check()
    _last_auth_resolution = {"mode": resolved_mode, "source": source, "error": ""}
    update_auth_runtime_state(resolved_mode, source, "")
    if resolved_mode == "openai_chatgpt":
        runtime_state["last_subscription_receipt"] = response.json().get("aurora_subscription", {})
    return response, resolved_mode


def post_openai_chat_completions(payload, timeout=None):
    return post_openai_model_request(payload, "chat/completions", timeout=timeout)


def post_openai_turn_request(payload, *, current_messages, prompt_inclusion_effective=False):
    """Use one explicit model transport; never fall back or replay after failure."""
    token = MODEL_WORK.current()
    if AUTH_MODE == "openai_chatgpt":
        RESPONSES_REASONING.invalidate("Subscription route uses explicit full history; adaptive API-key session remains separate.")
        return post_openai_chat_completions(payload, timeout=180)
    if payload.get("service_tier"):
        raise ValueError("Accelerated tiers are not yet qualified for this Aurora transport. Select Regular.")
    if MODEL_TRANSPORT == "chat_completions":
        RESPONSES_REASONING.invalidate("An intervening Chat Completions turn requires an explicit Responses reset.")
        return post_openai_chat_completions(payload, timeout=60)
    if AUTH_MODE != "api_key":
        raise ResponsesReasoningError("Adaptive Responses requires Aurora API-key auth mode.")
    if prompt_inclusion_effective:
        raise ResponsesReasoningError("Active prompt inclusion/omission filters require the Chat Completions lane until Responses filter parity is proved.")
    base_effort = normalize_reasoning_effort_for_model(DEFAULT_REASONING_EFFORT, ASTRA_MODEL, fallback="low")
    request = RESPONSES_REASONING.prepare(payload, base_effort=base_effort, current_messages=current_messages)
    try:
        response, mode = post_openai_model_request(request.payload, "responses", timeout=180,
            selection={"effective_effort": request.effective_effort, "configuration_update_sent": request.configuration_update_sent})
        token.check()
        if response.status_code != 200:
            raise ResponsesReasoningError(f"Responses HTTP {response.status_code}; inspect status before an explicit reset.")
        data = response.json()
        token.check()
        answer = RESPONSES_REASONING.complete(request, data)
    except Exception as error:
        RESPONSES_REASONING.fail(request, type(error).__name__ + ": response not committed")
        raise
    # Existing callers consume completed text only; retain provider metadata in
    # Model Status and the model-turn receipt instead of masquerading as API fields.
    class CompletedTurn:
        status_code = 200
        def json(self):
            return {"choices": [{"message": {"content": answer}}],
                    "model": data.get("model", ""), "usage": data.get("usage")}
    return CompletedTurn(), mode


def post_openai_embeddings(payload, timeout=None):
    return post_openai_model_request(payload, "embeddings", timeout=timeout)


def validate_model_name(model_name, timeout=25):
    normalized_model = normalize_model_name(model_name)
    if not normalized_model:
        return {
            "ok": False,
            "model": "",
            "error": "Model name must be non-empty.",
        }

    payload = {
        "model": normalized_model,
        "messages": [
            {"role": "system", "content": "You are validating an Aurora runtime model configuration."},
            {"role": "user", "content": "Reply with OK."},
        ],
    }
    if supports_temperature_override(normalized_model):
        payload["temperature"] = 0.0
    if supports_reasoning_effort(normalized_model):
        payload["reasoning_effort"] = get_default_reasoning_effort_for_model(normalized_model)
    if supports_model_verbosity(normalized_model):
        payload["verbosity"] = normalize_model_verbosity(DEFAULT_MODEL_VERBOSITY, fallback="medium")
    if uses_max_completion_tokens(normalized_model):
        payload["max_completion_tokens"] = 24
    else:
        payload["max_tokens"] = 24

    try:
        response, resolved_mode = post_openai_chat_completions(payload, timeout=timeout)
    except Exception as error:
        return {
            "ok": False,
            "model": normalized_model,
            "auth_mode": runtime_state.get("auth_mode_resolved", "") or AUTH_MODE,
            "auth_source": runtime_state.get("auth_source", ""),
            "error": summarize_runtime_text(str(error), max_chars=220),
        }

    if response.status_code != 200:
        try:
            error_payload = response.json()
            error_text = normalize_text_content(error_payload.get("error", {}).get("message", ""))
        except Exception:
            error_text = summarize_runtime_text(response.text, max_chars=220)
        return {
            "ok": False,
            "model": normalized_model,
            "auth_mode": resolved_mode,
            "auth_source": runtime_state.get("auth_source", ""),
            "status_code": response.status_code,
            "error": error_text or f"HTTP {response.status_code}",
        }

    try:
        response_data = response.json()
        reply_text = normalize_text_content(response_data["choices"][0]["message"]["content"]).strip()
    except Exception:
        reply_text = ""

    return {
        "ok": True,
        "model": normalized_model,
        "auth_mode": resolved_mode,
        "auth_source": runtime_state.get("auth_source", ""),
        "reply_preview": summarize_runtime_text(reply_text or "OK", max_chars=80),
        "metadata": build_model_metadata(
            normalized_model,
            source="custom",
            validated=True,
            validated_at=datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            validation_note="Validated with a short chat/completions text call.",
        ),
    }


def add_custom_model_entry(model_name):
    validation: dict[str, Any] = validate_model_name(model_name)
    if not validation.get("ok"):
        return validation
    raw_model_entry = validation.get("metadata") or build_model_metadata(
        model_name,
        source="custom",
        validated=True,
        validated_at=datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        validation_note="Validated with a short chat/completions text call.",
    )
    if not isinstance(raw_model_entry, dict):
        return {"ok": False, "model": normalize_model_name(model_name), "error": "Unable to build model metadata."}
    model_entry: dict[str, Any] = dict(raw_model_entry)
    model_key = normalize_model_name(model_entry.get("name", model_name)) or normalize_model_name(model_name)
    if not model_key:
        return {"ok": False, "model": "", "error": "Model name must be non-empty."}
    model_entry["name"] = model_key
    catalog = load_custom_model_catalog()
    catalog[model_key] = model_entry
    save_custom_model_catalog(catalog)
    validation["saved"] = True
    validation["metadata"] = model_entry
    return validation


def remove_custom_model_entry(model_name):
    normalized_model = normalize_model_name(model_name)
    if not normalized_model:
        return {"ok": False, "model": "", "error": "Model name must be non-empty."}
    if normalized_model in BUILTIN_MULTIMODAL_MODELS:
        return {"ok": False, "model": normalized_model, "error": "Built-in Aurora models cannot be removed."}
    catalog = load_custom_model_catalog()
    if normalized_model not in catalog:
        return {"ok": False, "model": normalized_model, "error": "Model was not found in the custom catalog."}
    del catalog[normalized_model]
    save_custom_model_catalog(catalog)
    return {"ok": True, "model": normalized_model, "removed": True}


