def should_treat_obstruction_signal_as_stale(signal_hint, foreground_title):
    signal_hint = normalize_text_content(signal_hint).strip().lower()
    foreground_title = normalize_text_content(foreground_title).strip()
    lowered_foreground = foreground_title.lower()
    if not signal_hint:
        return False
    if signal_hint not in GAMEPLAY_STALE_TEXT_HINTS:
        return False
    if not foreground_title or not window_title_matches(foreground_title, EMULATOR_WINDOW_TITLE_HINT):
        return False
    if any(window_hint in lowered_foreground for window_hint in GAMEPLAY_OBSTRUCTION_WINDOW_HINTS):
        return False
    scene_hint = normalize_text_content(runtime_state.get("gameplay_scene", "")).strip().lower()
    return scene_hint in {"overworld", "dialog", "main_menu", "battle", "transition", "unknown"}


