def ensure_episodic_memory_store():
    os.makedirs(episodic_memory_dir, exist_ok=True)


def _normalize_episodic_embedding_mode(value, default="auto"):
    normalized = normalize_text_content(value).strip().lower() or normalize_text_content(default).strip().lower() or "auto"
    return normalized if normalized in ALLOWED_EPISODIC_EMBEDDING_MODES else "auto"


def _normalize_episodic_promotion_target(value):
    normalized = normalize_text_content(value).strip().lower()
    return EPISODIC_PROMOTION_TARGET_ALIASES.get(normalized, "")


def _truncate_episodic_embedding_text(text):
    cleaned = normalize_text_content(text).strip()
    if not cleaned:
        return ""
    return summarize_runtime_text(cleaned, max_chars=EPISODIC_MEMORY_EMBEDDING_MAX_INPUT_CHARS)


def _get_episodic_embedding_cache():
    global episodic_embedding_cache_data
    with episodic_embedding_cache_lock:
        if episodic_embedding_cache_data is not None:
            return episodic_embedding_cache_data
        cache_payload = {"version": 1, "items": {}}
        if os.path.exists(episodic_embedding_cache_path):
            try:
                with open(episodic_embedding_cache_path, "r", encoding="utf-8") as handle:
                    loaded = json.load(handle)
                if isinstance(loaded, dict):
                    items = loaded.get("items", {})
                    cache_payload = {
                        "version": int(loaded.get("version", 1) or 1),
                        "items": items if isinstance(items, dict) else {},
                    }
            except Exception:
                cache_payload = {"version": 1, "items": {}}
        episodic_embedding_cache_data = cache_payload
        return episodic_embedding_cache_data


def _save_episodic_embedding_cache(cache_payload):
    global episodic_embedding_cache_data
    with episodic_embedding_cache_lock:
        atomic_write_cache(episodic_embedding_cache_path, cache_payload)
        episodic_embedding_cache_data = cache_payload
        return len(cache_payload.get("items", {}))


def _episodic_embedding_cache_key(model, text, kind="summary"):
    normalized_model = normalize_text_content(model).strip() or EPISODIC_MEMORY_EMBEDDING_MODEL
    normalized_kind = normalize_text_content(kind).strip().lower() or "summary"
    text_bytes = normalize_text_content(text).encode("utf-8")
    digest = hashlib.sha256(text_bytes).hexdigest()
    return f"{normalized_model}:{normalized_kind}:{digest}"


def _update_episodic_embedding_cache_entries(model, entries):
    """Merge under one lock and publish memory only after atomic disk replacement."""
    with episodic_embedding_cache_lock:
        current = _get_episodic_embedding_cache()
        cache_payload = {**current, "items": dict(current.get("items", {}))}
        for row in entries:
            text = _truncate_episodic_embedding_text(row["text"])
            if not text:
                continue
            kind = row.get("kind", "summary")
            cache_payload["items"][_episodic_embedding_cache_key(model, text, kind=kind)] = {
                "model": model, "kind": kind, "text_preview": summarize_runtime_text(text, max_chars=120),
                "updated_at": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
                "vector": validated_vector(row["vector"]),
            }
        return _save_episodic_embedding_cache(cache_payload)


def _update_episodic_embedding_cache_entry(model, text, vector, kind="summary"):
    return _update_episodic_embedding_cache_entries(model, [{"text": text, "vector": vector, "kind": kind}])


def _get_cached_episodic_embedding(model, text, kind="summary"):
    text = _truncate_episodic_embedding_text(text)
    if not text:
        return None
    with episodic_embedding_cache_lock:
        row = _get_episodic_embedding_cache().get("items", {}).get(_episodic_embedding_cache_key(model, text, kind=kind))
        try:
            return validated_vector(row.get("vector")) if isinstance(row, dict) else None
        except ValueError:
            return None


def _get_episodic_embedding_cache_entry_count():
    cache_payload = _get_episodic_embedding_cache()
    return len((cache_payload.get("items", {}) or {}))


def _request_openai_text_embeddings(texts, model):
    cleaned = [_truncate_episodic_embedding_text(text) for text in texts]
    auth_mode = runtime_state.get("auth_mode_resolved", "") or AUTH_MODE
    if not cleaned:
        return {"ok": True, "vectors": [], "auth_mode": auth_mode}
    if any(not text for text in cleaned):
        return {"ok": False, "error": "Embedding input contains empty text.", "auth_mode": auth_mode}
    payload = {"model": normalize_text_content(model).strip() or EPISODIC_MEMORY_EMBEDDING_MODEL,
               "input": cleaned, "encoding_format": "float"}
    try:
        response, auth_mode = post_openai_embeddings(payload, timeout=EPISODIC_MEMORY_EMBEDDING_TIMEOUT_SECONDS)
        if response.status_code >= 400:
            return {"ok": False, "error": f"Embedding HTTP status={response.status_code}.", "auth_mode": auth_mode}
        vectors = parse_embedding_vectors(response.json(), len(cleaned))
    except WorkCancelled:
        raise
    except Exception as error:
        # Do not copy provider bodies, URLs or credentials into persistent state.
        return {"ok": False, "error": f"Embedding request/response failed ({type(error).__name__}).", "auth_mode": auth_mode}
    return {"ok": True, "vectors": vectors, "auth_mode": auth_mode}


def _dot_product(vec_a, vec_b):
    if not vec_a or not vec_b or len(vec_a) != len(vec_b):
        return 0.0
    return sum(float(a) * float(b) for a, b in zip(vec_a, vec_b))


def _vector_norm(vector):
    if not vector:
        return 0.0
    return math.sqrt(sum(float(value) * float(value) for value in vector))


def _cosine_similarity(vec_a, vec_b):
    if not vec_a or not vec_b or len(vec_a) != len(vec_b):
        return 0.0
    norm_a, norm_b = math.hypot(*vec_a), math.hypot(*vec_b)
    if norm_a <= 0 or norm_b <= 0:
        return 0.0
    return max(-1.0, min(1.0, sum((a / norm_a) * (b / norm_b) for a, b in zip(vec_a, vec_b))))


def _normalize_cosine_similarity(score):
    return max(0.0, min(1.0, (float(score) + 1.0) / 2.0))


def _build_episodic_embedding_context(query, request, records, check_cancel=None):
    backend = _normalize_episodic_embedding_mode(request.get("semantic_backend", EPISODIC_MEMORY_EMBEDDINGS_MODE), EPISODIC_MEMORY_EMBEDDINGS_MODE)
    model = normalize_text_content(request.get("embedding_model", "")).strip() or EPISODIC_MEMORY_EMBEDDING_MODEL
    return build_embedding_context(
        query, request, records, model=model, backend=backend,
        auth_mode=runtime_state.get("auth_mode_resolved", "") or AUTH_MODE,
        truncate=_truncate_episodic_embedding_text, get_cached=_get_cached_episodic_embedding,
        request_vectors=_request_openai_text_embeddings, save_entries=_update_episodic_embedding_cache_entries,
        check_cancel=check_cancel or MODEL_WORK.current().check,
    )


def _coerce_episodic_snapshot_count(value):
    try:
        return max(0, int(value))
    except (TypeError, ValueError):
        return 0


def _apply_episodic_snapshot_runtime_record(record, snapshot_count=None):
    if not isinstance(record, dict):
        return
    if snapshot_count is not None:
        set_runtime_value("episodic_memory_snapshot_count", _coerce_episodic_snapshot_count(snapshot_count))
    set_runtime_value("episodic_memory_last_snapshot_id", normalize_text_content(record.get("snapshot_id", "")).strip())
    set_runtime_value("episodic_memory_last_snapshot_timestamp", normalize_text_content(record.get("timestamp", "")).strip())
    set_runtime_value("episodic_memory_last_snapshot_reason", normalize_text_content(record.get("reason", "")).strip())
    set_runtime_value("episodic_memory_last_snapshot_summary", normalize_text_content(record.get("summary_text", "")).strip())
    set_runtime_value("episodic_memory_last_summary_hash", normalize_text_content(record.get("summary_hash", "")).strip())
    try:
        last_epoch = float(record.get("created_at_epoch", 0.0) or 0.0)
    except (TypeError, ValueError):
        last_epoch = 0.0
    set_runtime_value("episodic_memory_last_snapshot_at_epoch", last_epoch)


def initialize_episodic_memory_runtime_state():
    set_runtime_value("episodic_memory_enabled", EPISODIC_MEMORY_ENABLED)
    set_runtime_value("episodic_memory_interval_seconds", EPISODIC_MEMORY_INTERVAL_SECONDS)
    set_runtime_value("episodic_memory_periodic_trigger_enabled", EPISODIC_MEMORY_PERIODIC_TRIGGER_ENABLED)
    set_runtime_value("episodic_memory_scene_trigger_enabled", EPISODIC_MEMORY_SCENE_TRIGGER_ENABLED)
    set_runtime_value("episodic_memory_embeddings_mode", EPISODIC_MEMORY_EMBEDDINGS_MODE)
    set_runtime_value("episodic_memory_embedding_model", EPISODIC_MEMORY_EMBEDDING_MODEL)
    set_runtime_value("episodic_memory_embedding_cache_entries", _get_episodic_embedding_cache_entry_count())
    set_runtime_value("episodic_memory_last_retrieval_backend", "lexical")
    set_runtime_value("episodic_memory_planning_assist_mode", EPISODIC_PLANNING_ASSIST_MODE)
    set_runtime_value("episodic_memory_planning_assist_k", EPISODIC_PLANNING_ASSIST_K)
    set_runtime_value("episodic_memory_planning_assist_cooldown_turns", EPISODIC_PLANNING_ASSIST_COOLDOWN_TURNS)
    snapshot_count = 0
    last_record = None
    if os.path.exists(episodic_memory_path):
        with open(episodic_memory_path, "r", encoding="utf-8") as memory_file:
            for raw_line in memory_file:
                line = raw_line.lstrip("\ufeff").strip()
                if not line:
                    continue
                try:
                    record = json.loads(line)
                except json.JSONDecodeError:
                    continue
                snapshot_count += 1
                last_record = record
    _apply_episodic_snapshot_runtime_record(last_record or {}, snapshot_count=snapshot_count)


initialize_episodic_memory_runtime_state()


def build_gameplay_visibility_signal_text(limit=4):
    parts = []
    for item in list(runtime_state.get("recent_feedback", []) or [])[-limit:]:
        text = normalize_text_content(item).strip().lower()
        if text:
            parts.append(text)
    for item in list(agent_state.recent_context_events or [])[-limit:]:
        text = normalize_text_content(item).strip().lower()
        if text:
            parts.append(text)
    for entry in list(agent_state.chat_history or [])[-limit:]:
        text = normalize_text_content(get_history_entry_text(entry)).strip().lower()
        if text:
            parts.append(text)
    return " | ".join(parts)


def infer_gameplay_visibility_state():
    operating_context = normalize_text_content(runtime_state.get("operating_context", "")).strip().lower() or "unknown"
    foreground_title = normalize_text_content(runtime_state.get("last_foreground_window", "")).strip()
    if not foreground_title:
        foreground_title = normalize_text_content(get_foreground_window_title()).strip()
    lowered_foreground = foreground_title.lower()
    signal_text = build_gameplay_visibility_signal_text(limit=4)
    matching_signal = next((hint for hint in GAMEPLAY_OBSTRUCTION_TEXT_HINTS if hint in signal_text), "")
    matching_window = next((hint for hint in GAMEPLAY_OBSTRUCTION_WINDOW_HINTS if hint in lowered_foreground), "")
    hard_obstruction_signal = next((hint for hint in GAMEPLAY_HARD_OBSTRUCTION_TEXT_HINTS if hint in signal_text), "")
    stale_signal = should_treat_obstruction_signal_as_stale(matching_signal, foreground_title)

    if hard_obstruction_signal and not should_treat_obstruction_signal_as_stale(hard_obstruction_signal, foreground_title):
        return {
            "visibility": "obstructed",
            "reason": f"recent model/runtime text suggests obstruction ({hard_obstruction_signal})",
            "foreground_window": foreground_title,
        }
    if foreground_title and window_title_matches(foreground_title, EMULATOR_WINDOW_TITLE_HINT):
        return {
            "visibility": "visible",
            "reason": f"foreground window matches {EMULATOR_WINDOW_TITLE_HINT}",
            "foreground_window": foreground_title,
        }
    if matching_signal and operating_context == "game" and not stale_signal:
        return {
            "visibility": "obstructed",
            "reason": f"recent model/runtime text suggests obstruction ({matching_signal})",
            "foreground_window": foreground_title,
        }
    if matching_signal and stale_signal:
        return {
            "visibility": "visible",
            "reason": f"foreground window matches {EMULATOR_WINDOW_TITLE_HINT}; stale obstruction text ({matching_signal}) downgraded",
            "foreground_window": foreground_title,
        }
    if foreground_title and (operating_context == "game" or matching_window):
        reason = f"foreground window is '{foreground_title}'"
        if matching_window:
            reason += f" ({matching_window})"
        return {
            "visibility": "obstructed",
            "reason": reason,
            "foreground_window": foreground_title,
        }
    if operating_context == "game":
        return {
            "visibility": "unknown",
            "reason": "game context active but emulator visibility is not yet confirmed",
            "foreground_window": foreground_title,
        }
    return {
        "visibility": "unknown",
        "reason": "operating context is not game",
        "foreground_window": foreground_title,
    }


def refresh_gameplay_visibility_state():
    visibility_info = infer_gameplay_visibility_state()
    set_runtime_value("gameplay_visibility", visibility_info.get("visibility", "unknown"))
    set_runtime_value("gameplay_visibility_reason", visibility_info.get("reason", ""))
    if visibility_info.get("foreground_window"):
        set_runtime_value("last_foreground_window", visibility_info.get("foreground_window", ""))
    return visibility_info


def record_game_input_attempt(requested_key, effective_key="", backend="", command_text="", focus_result=None):
    set_runtime_value("last_game_input_attempt_at_epoch", time.time())
    set_runtime_value("last_game_input_capture_boundary", CAPTURE_SERVICE.boundary())
    set_runtime_value("last_game_input_command", normalize_text_content(command_text or requested_key).strip())
    set_runtime_value("last_game_input_effective_key", normalize_text_content(effective_key or requested_key).strip().lower())
    set_runtime_value("last_game_input_focus_ok", bool((focus_result or {}).get("success", False)))
    set_runtime_value("last_game_input_focus_reason", normalize_text_content((focus_result or {}).get("reason", "")).strip())
    if backend:
        set_runtime_value("last_input_backend", normalize_text_content(backend).strip())
    refresh_gameplay_visibility_state()


def record_focus_recovery_result(trigger, focus_result):
    summary = (
        f"{'success' if focus_result.get('success') else 'failed'} via "
        f"{normalize_text_content(trigger).strip() or 'runtime_hook'}; "
        f"title={normalize_text_content(focus_result.get('title', '')).strip() or 'unknown'}; "
        f"reason={normalize_text_content(focus_result.get('reason', '')).strip() or 'ok'}; "
        f"clicked_client_center={bool(focus_result.get('clicked_client_center', False))}"
    )
    set_runtime_value("last_game_focus_recovery_at_epoch", time.time())
    set_runtime_value("last_game_focus_recovery_summary", summarize_runtime_text(summary, max_chars=180))
    refresh_gameplay_visibility_state()
    return summary


def normalize_reasoning_summary_mode(value, fallback="auto"):
    normalized = normalize_memory_item(value).strip().lower()
    if normalized in ALLOWED_REASONING_SUMMARY_MODES:
        return normalized
    return fallback


def normalize_nonnegative_int(value, fallback=0):
    try:
        return max(0, int(float(value)))
    except (TypeError, ValueError):
        return max(0, int(fallback))


def normalize_pending_queue_mode(value, fallback="normal"):
    normalized = normalize_memory_item(value).strip().lower()
    if normalized in ALLOWED_PENDING_QUEUE_MODES:
        return normalized
    return fallback


def normalize_turn_scheduler_mode(value, fallback="hybrid"):
    normalized = normalize_memory_item(value).strip().lower()
    aliases = {
        "legacy": "per_capture",
        "capture": "per_capture",
        "per_capture": "per_capture",
        "per-capture": "per_capture",
        "capture_tick": "per_capture",
        "capture-tick": "per_capture",
        "event": "event",
        "event_driven": "event",
        "event-driven": "event",
        "tool_loop": "event",
        "tool-loop": "event",
        "hybrid": "hybrid",
        "hybrid_event": "hybrid",
        "hybrid-event": "hybrid",
        "codex_like": "hybrid",
        "codex-like": "hybrid",
    }
    resolved = aliases.get(normalized, normalized)
    if resolved in ALLOWED_TURN_SCHEDULER_MODES:
        return resolved
    return fallback if fallback in ALLOWED_TURN_SCHEDULER_MODES else TURN_SCHEDULER_MODE


def normalize_turn_scheduler_profile_name(value, fallback="balanced"):
    normalized = normalize_memory_item(value).strip().lower()
    aliases = {
        "": fallback,
        "balanced": "balanced",
        "default": "balanced",
        "responsive": "responsive",
        "fast": "responsive",
        "quick": "responsive",
        "conservative": "conservative",
        "slow": "conservative",
        "legacy": "legacy",
        "per_capture": "legacy",
        "per-capture": "legacy",
        "custom": "custom",
    }
    resolved = aliases.get(normalized, normalized)
    if resolved == "custom":
        return "custom"
    if resolved in TURN_SCHEDULER_PROFILES:
        return resolved
    return fallback if fallback in TURN_SCHEDULER_PROFILES else TURN_SCHEDULER_PROFILE_NAME


def infer_turn_scheduler_profile_name():
    for profile_name, profile in TURN_SCHEDULER_PROFILES.items():
        if (
            profile["mode"] == TURN_SCHEDULER_MODE
            and abs(float(profile["heartbeat_seconds"]) - float(TURN_SCHEDULER_HEARTBEAT_SECONDS)) < 1e-9
            and abs(float(profile["min_gap_seconds"]) - float(TURN_SCHEDULER_MIN_GAP_SECONDS)) < 1e-9
            and bool(profile["capture_wake_enabled"]) == bool(TURN_SCHEDULER_CAPTURE_WAKE_ENABLED)
            and abs(float(profile["capture_wake_debounce_seconds"]) - float(TURN_SCHEDULER_CAPTURE_WAKE_DEBOUNCE_SECONDS)) < 1e-9
            and abs(float(profile["post_action_settle_seconds"]) - float(TURN_SCHEDULER_POST_ACTION_SETTLE_SECONDS)) < 1e-9
        ):
            return profile_name
    return "custom"


def get_turn_scheduler_profile_description(profile_name):
    normalized = normalize_turn_scheduler_profile_name(profile_name, fallback="")
    if normalized == "custom":
        return "custom scheduler tuning: manual thresholds or mixed settings"
    return TURN_SCHEDULER_PROFILE_DESCRIPTIONS.get(
        normalized,
        TURN_SCHEDULER_PROFILE_DESCRIPTIONS.get("balanced", "scheduler profile"),
    )


def refresh_turn_scheduler_profile_state():
    global TURN_SCHEDULER_PROFILE_NAME
    TURN_SCHEDULER_PROFILE_NAME = infer_turn_scheduler_profile_name()
    set_runtime_value("turn_scheduler_profile", TURN_SCHEDULER_PROFILE_NAME)
    set_runtime_value(
        "turn_scheduler_profile_description",
        get_turn_scheduler_profile_description(TURN_SCHEDULER_PROFILE_NAME),
    )
    return TURN_SCHEDULER_PROFILE_NAME


def initialize_turn_scheduler_runtime_state():
    set_runtime_value("turn_scheduler_mode", TURN_SCHEDULER_MODE)
    set_runtime_value("turn_scheduler_heartbeat_seconds", TURN_SCHEDULER_HEARTBEAT_SECONDS)
    set_runtime_value("turn_scheduler_min_gap_seconds", TURN_SCHEDULER_MIN_GAP_SECONDS)
    set_runtime_value("turn_scheduler_capture_wake_enabled", TURN_SCHEDULER_CAPTURE_WAKE_ENABLED)
    set_runtime_value("turn_scheduler_capture_wake_debounce_seconds", TURN_SCHEDULER_CAPTURE_WAKE_DEBOUNCE_SECONDS)
    set_runtime_value("turn_scheduler_post_action_settle_seconds", TURN_SCHEDULER_POST_ACTION_SETTLE_SECONDS)
    set_runtime_value("demand_capture_enabled", DEMAND_CAPTURE_ENABLED)
    refresh_turn_scheduler_profile_state()


def get_turn_scheduler_description(mode=None):
    normalized = normalize_turn_scheduler_mode(mode or TURN_SCHEDULER_MODE, fallback=TURN_SCHEDULER_MODE)
    descriptions = {
        "per_capture": "legacy conveyor: every fresh processed screenshot can trigger a turn",
        "event": "event-driven: wake on input, action results, or safety heartbeat",
        "hybrid": "hybrid default: event-driven plus an idle capture-change wake",
    }
    return descriptions.get(normalized, descriptions["hybrid"])


def build_turn_scheduler_summary():
    mode = normalize_turn_scheduler_mode(runtime_state.get("turn_scheduler_mode", TURN_SCHEDULER_MODE), fallback=TURN_SCHEDULER_MODE)
    profile_name = normalize_turn_scheduler_profile_name(
        runtime_state.get("turn_scheduler_profile", TURN_SCHEDULER_PROFILE_NAME),
        fallback=TURN_SCHEDULER_PROFILE_NAME,
    )
    heartbeat = float(runtime_state.get("turn_scheduler_heartbeat_seconds", TURN_SCHEDULER_HEARTBEAT_SECONDS) or TURN_SCHEDULER_HEARTBEAT_SECONDS)
    min_gap = float(runtime_state.get("turn_scheduler_min_gap_seconds", TURN_SCHEDULER_MIN_GAP_SECONDS) or TURN_SCHEDULER_MIN_GAP_SECONDS)
    capture_wake_enabled = bool(runtime_state.get("turn_scheduler_capture_wake_enabled", TURN_SCHEDULER_CAPTURE_WAKE_ENABLED))
    capture_wake_debounce = float(
        runtime_state.get("turn_scheduler_capture_wake_debounce_seconds", TURN_SCHEDULER_CAPTURE_WAKE_DEBOUNCE_SECONDS)
        or TURN_SCHEDULER_CAPTURE_WAKE_DEBOUNCE_SECONDS
    )
    post_action_settle = float(
        runtime_state.get("turn_scheduler_post_action_settle_seconds", TURN_SCHEDULER_POST_ACTION_SETTLE_SECONDS)
        or TURN_SCHEDULER_POST_ACTION_SETTLE_SECONDS
    )
    demand_enabled = bool(runtime_state.get("demand_capture_enabled", DEMAND_CAPTURE_ENABLED))
    demand_pending = bool(runtime_state.get("demand_capture_pending", False))
    demand_reason = normalize_text_content(runtime_state.get("demand_capture_reason", "")).strip() or "capture"
    demand_due_at = float(runtime_state.get("demand_capture_due_at_epoch", 0.0) or 0.0)
    demand_due_in = max(0.0, demand_due_at - time.time()) if demand_pending else 0.0
    demand_status = "off"
    if demand_enabled:
        demand_status = f"pending:{demand_reason}:{demand_due_in:.2f}s" if demand_pending else "on"
    last_reason = normalize_text_content(runtime_state.get("last_turn_wake_reason", "")).strip() or "none"
    return (
        f"profile={profile_name} | mode={mode} ({get_turn_scheduler_description(mode)}) | "
        f"heartbeat={heartbeat:.2f}s | min_gap={min_gap:.2f}s | "
        f"capture_wake={'on' if capture_wake_enabled else 'off'} | "
        f"capture_wake_debounce={capture_wake_debounce:.2f}s | "
        f"post_action_settle={post_action_settle:.2f}s | "
        f"demand_capture={demand_status} | "
        f"last_wake={last_reason}"
    )


def apply_turn_scheduler_profile(profile_name, require_unlock=True):
    global TURN_SCHEDULER_PROFILE_NAME, TURN_SCHEDULER_MODE, TURN_SCHEDULER_HEARTBEAT_SECONDS, TURN_SCHEDULER_MIN_GAP_SECONDS
    global TURN_SCHEDULER_CAPTURE_WAKE_ENABLED, TURN_SCHEDULER_CAPTURE_WAKE_DEBOUNCE_SECONDS
    global TURN_SCHEDULER_POST_ACTION_SETTLE_SECONDS

    if require_unlock:
        require_runtime_setting_unlocked("reasoning", "Turn scheduler profile")
    normalized = coerce_setting_value("scheduler.profile", profile_name)
    profile = TURN_SCHEDULER_PROFILES[normalized]
    TURN_SCHEDULER_PROFILE_NAME = normalized
    TURN_SCHEDULER_MODE = profile["mode"]
    TURN_SCHEDULER_HEARTBEAT_SECONDS = float(profile["heartbeat_seconds"])
    TURN_SCHEDULER_MIN_GAP_SECONDS = float(profile["min_gap_seconds"])
    TURN_SCHEDULER_CAPTURE_WAKE_ENABLED = bool(profile["capture_wake_enabled"])
    TURN_SCHEDULER_CAPTURE_WAKE_DEBOUNCE_SECONDS = float(profile["capture_wake_debounce_seconds"])
    TURN_SCHEDULER_POST_ACTION_SETTLE_SECONDS = float(profile["post_action_settle_seconds"])
    initialize_turn_scheduler_runtime_state()
    append_runtime_feedback(
        f"Turn scheduler profile set to {normalized}: {get_turn_scheduler_profile_description(normalized)}."
    )
    return normalized


