def get_demand_capture_settle_seconds(value=None):
    if value in {"", None}:
        value = DEMAND_CAPTURE_DEFAULT_SETTLE_SECONDS
    try:
        numeric = float(value)
        return max(0.0, numeric) if math.isfinite(numeric) else max(0.0, float(DEMAND_CAPTURE_DEFAULT_SETTLE_SECONDS))
    except (TypeError, ValueError):
        return max(0.0, float(DEMAND_CAPTURE_DEFAULT_SETTLE_SECONDS))


def set_demand_capture_enabled(enabled):
    global DEMAND_CAPTURE_ENABLED
    require_runtime_setting_unlocked("screenshot_interval", "Demand screenshot capture")
    enabled = coerce_setting_value("capture.demand_enabled", enabled)
    DEMAND_CAPTURE_ENABLED = bool(enabled)
    set_runtime_value("demand_capture_enabled", DEMAND_CAPTURE_ENABLED)
    append_runtime_feedback(f"Demand screenshot capture {'enabled' if DEMAND_CAPTURE_ENABLED else 'disabled'}.")
    if DEMAND_CAPTURE_ENABLED:
        try:
            screenshot_capture_wake_event.set()
        except NameError:
            pass
    else:
        cancel_capture_requests("Demand capture disabled", preserve_observation=True)
    return DEMAND_CAPTURE_ENABLED


def mirror_capture_service_state():
    """Compatibility fields mirror one locked service; readers can use its snapshot."""
    with CAPTURE_SERVICE.lock:
        snapshot = CAPTURE_SERVICE.snapshot()
        set_runtime_value("capture_service", snapshot)
        set_runtime_value("capture_request_failure", snapshot["current_failure"])
        pending, completed = snapshot["pending"], snapshot["last_completion"]
        for key, value in {
            "demand_capture_pending": bool(pending),
            "demand_capture_reason": pending.get("reason", ""),
            "demand_capture_requested_at_epoch": pending.get("requested_at_epoch", 0.0),
            "demand_capture_due_at_epoch": pending.get("due_at_epoch", 0.0),
            "demand_capture_request_count": snapshot["request_generation"],
            "demand_capture_completed_count": snapshot["completed_count"],
            "demand_capture_last_at_epoch": completed.get("published_at_epoch", 0.0),
            "demand_capture_last_reason": completed.get("reason", ""),
            "demand_capture_last_latency_ms": completed.get("latency_ms", 0),
        }.items():
            set_runtime_value(key, value)
        return snapshot


def cancel_capture_requests(reason, preserve_observation=False):
    with CAPTURE_SERVICE.lock:
        CAPTURE_SERVICE.cancel(reason, invalidate_frames=not preserve_observation)
        mirror_capture_service_state()
        if not preserve_observation:
            clear_turn_scheduler_command_result_pending()
    screenshot_capture_wake_event.set()


def acquire_runtime_frame(source="capture_worker", replaces_frame_id="", parent_stamp=None, geometry_policy=None, capture_service=None):
    """Stamp immediately around the pixel acquisition, before drawing or I/O."""
    service = capture_service or CAPTURE_SERVICE
    stamp = service.begin(source, replaces_frame_id=replaces_frame_id, parent=parent_stamp,
                          allow_demand=bool(runtime_state.get("demand_capture_enabled", DEMAND_CAPTURE_ENABLED)),
                          require_demand=CAPTURE_MODE == "request_only" and parent_stamp is None)
    if stamp is None:
        return None
    try:
        if (geometry_policy or CAPTURE_GEOMETRY_POLICY) == "verified":
            target = CAPTURE_TARGET
            if target == "legacy_options":
                options = dict(screenshot_options)
                target = ("primary" if options.get("native_cursor_screenshot") else
                          "foreground" if options.get("current_window") else
                          "virtual" if options.get("entire_screen") else "primary")
            image, geometry = capture_geometry.capture_pixels(ImageGrab.grab, target)
        else:
            image = ImageGrab.grab()
            geometry = capture_geometry.FrameGeometry(tuple(image.size), tuple(image.size))
        return CapturedFrame(image, service.finish(stamp), geometry=geometry)
    except Exception as error:
        service.fail("acquisition", error, stamp)
        if service is CAPTURE_SERVICE:
            mirror_capture_service_state()
        raise


def request_demand_capture(reason="manual", settle_seconds=None, *, timeout_seconds=None, max_attempts=None):
    now = time.time()
    normalized_reason = normalize_text_content(reason).strip() or "manual"
    if not bool(runtime_state.get("demand_capture_enabled", DEMAND_CAPTURE_ENABLED)):
        set_runtime_value("demand_capture_last_ignored_reason", normalized_reason)
        set_runtime_value("demand_capture_last_ignored_at_epoch", now)
        return False

    settle_seconds = get_demand_capture_settle_seconds(settle_seconds)
    with CAPTURE_SERVICE.lock:
        generation = CAPTURE_SERVICE.request(normalized_reason, settle_seconds,
            timeout_seconds=CAPTURE_REQUEST_TIMEOUT_SECONDS if timeout_seconds is None else timeout_seconds,
            max_attempts=CAPTURE_REQUEST_MAX_ATTEMPTS if max_attempts is None else max_attempts)
        if runtime_state.get("turn_scheduler_pending_command_result"):
            set_runtime_value("turn_scheduler_capture_request_generation", generation)
        mirror_capture_service_state()
    try:
        screenshot_capture_wake_event.set()
    except NameError:
        pass
    return True


def get_due_demand_capture_reason(now=None):
    if not bool(runtime_state.get("demand_capture_enabled", DEMAND_CAPTURE_ENABLED)):
        return ""
    with CAPTURE_SERVICE.lock:
        return (CAPTURE_SERVICE.snapshot()["pending"].get("reason", "")
                if CAPTURE_SERVICE.demand_wait() == 0 else "")


def get_next_demand_capture_due_at(now=None):
    if not bool(runtime_state.get("demand_capture_enabled", DEMAND_CAPTURE_ENABLED)):
        return 0.0
    remaining = CAPTURE_SERVICE.demand_wait()
    return 0.0 if remaining is None else (time.time() if now is None else float(now)) + remaining


def complete_demand_capture(reason, capture_frame=None):
    """Compatibility readback only; a bare reason cannot acknowledge a frame."""
    completed = mirror_capture_service_state()["last_completion"]
    return bool(capture_frame and completed.get("frame_id") == capture_frame.get("provenance", {}).get("frame_id")
                and completed.get("reason") == reason)


def mark_turn_scheduler_command_result_pending(settle_seconds=None, demand_reason="command_result", request_capture=True, command_entries=None):
    now = time.time()
    settle_seconds = get_demand_capture_settle_seconds(
        TURN_SCHEDULER_POST_ACTION_SETTLE_SECONDS if settle_seconds is None else settle_seconds
    )
    with CAPTURE_SERVICE.lock:
        required_capture = int(runtime_state.get("turn_scheduler_capture_counter", 0) or 0) + 1
        generation = int(runtime_state.get("turn_scheduler_observation_generation", 0) or 0) + 1
        set_runtime_value("turn_scheduler_observation_generation", generation)
        set_runtime_value("turn_scheduler_pending_command_result", True)
        set_runtime_value("turn_scheduler_required_capture_after_action", required_capture)
        set_runtime_value("turn_scheduler_post_action_wait_until_epoch", now + settle_seconds)
        set_runtime_value("turn_scheduler_post_action_boundary", CAPTURE_SERVICE.boundary(settle_seconds))
        if request_capture:
            request_demand_capture(demand_reason, settle_seconds)
        capture_status = CAPTURE_SERVICE.snapshot()
        request = capture_status["pending"] or capture_status["current_failure"]
        set_runtime_value("turn_scheduler_capture_request_generation", request.get("generation", 0))
        if TASK_CONTINUATION_MODE == "bounded":
            TASK_CONTINUATION.record_observation_wait(
                command_entries if command_entries is not None else [current_command_task()],
                runtime_state["turn_scheduler_post_action_boundary"], generation, request.get("generation", 0))


def publish_batch_observation(entries):
    """Coalesce opted-in explicit captures with automatic terminal readbacks."""
    from aurora_capture_provenance import plan_batch_observation
    with CAPTURE_SERVICE.lock:
        selected, evidence = plan_batch_observation(entries, session_id=CAPTURE_SERVICE.session_id,
            lifecycle=CAPTURE_SERVICE.lifecycle, command_generation=COMMAND_WORK.snapshot()["generation"],
            default_settle=get_demand_capture_settle_seconds(TURN_SCHEDULER_POST_ACTION_SETTLE_SECONDS))
        if selected:
            # Never shorten another explicit request's remaining settle boundary.
            pending = CAPTURE_SERVICE.snapshot()["pending"]
            if any((row.get("capture_batch") or {}).get("policy") in {"batch_end", "batch_end_explicit"}
                   for row in selected) and pending:
                evidence["settle_seconds"] = max(evidence["settle_seconds"],
                    pending["due_at_monotonic"] - CAPTURE_SERVICE.monotonic())
            mark_turn_scheduler_command_result_pending(settle_seconds=evidence["settle_seconds"], command_entries=selected)
        evidence.update(request_generation=runtime_state.get("turn_scheduler_capture_request_generation", 0),
                        observed_at_epoch=time.time(), requested=bool(selected))
        set_runtime_value("last_batch_capture", evidence)
    return evidence


def clear_turn_scheduler_command_result_pending(expected_generation=None):
    with CAPTURE_SERVICE.lock:
        if expected_generation is not None and expected_generation != runtime_state.get("turn_scheduler_observation_generation", 0):
            return False
        set_runtime_value("turn_scheduler_pending_command_result", False)
        set_runtime_value("turn_scheduler_required_capture_after_action", 0)
        set_runtime_value("turn_scheduler_post_action_wait_until_epoch", 0.0)
        set_runtime_value("turn_scheduler_post_action_boundary", {})
        set_runtime_value("turn_scheduler_capture_request_generation", 0)
        return True


def register_turn_scheduler_capture(screenshot_file_path, image_timestamp="", capture_hash=None, capture_frame=None):
    capture_hash = normalize_text_content(capture_hash).strip() or compute_image_fingerprint(screenshot_file_path)
    previous_hash = normalize_text_content(runtime_state.get("turn_scheduler_last_capture_hash", "")).strip()
    capture_counter = int(runtime_state.get("turn_scheduler_capture_counter", 0) or 0) + 1
    now = time.time()
    set_runtime_value("turn_scheduler_capture_counter", capture_counter)
    set_runtime_value("turn_scheduler_last_capture_hash", capture_hash)
    set_runtime_value("turn_scheduler_last_capture_ready_at_epoch", now)
    set_runtime_value("last_capture_frame", capture_frame or {
        "path": screenshot_file_path, "timestamp": image_timestamp, "hash": capture_hash,
        "counter": capture_counter, "provenance": {"status": "unknown"},
    })
    if capture_hash and capture_hash != previous_hash:
        set_runtime_value("turn_scheduler_last_capture_changed_at_epoch", now)
    if TASK_CONTINUATION_MODE == "bounded" and capture_frame:
        TASK_CONTINUATION.record_frame_observed(capture_frame)
    return {
        "counter": capture_counter,
        "hash": capture_hash,
        "changed": bool(capture_hash and capture_hash != previous_hash),
        "timestamp": image_timestamp,
        "path": screenshot_file_path,
    }


def should_request_turn_after_command_result(action_entry):
    if not isinstance(action_entry, dict):
        return False
    if (action_entry.get("capture_batch") or {}).get("requests", 0):
        return True  # Controller validates generation/cancellation before requesting pixels.
    # A partially completed/cancelled first input may need observation even when
    # no command reached the successful list. Never automatically replay it.
    if any(row.get("effect_status") in {"submitted", "observed", "uncertain"}
           for row in (action_entry.get("desktop_results") or []) if isinstance(row, dict)):
        return True
    command_candidates = list(action_entry.get("executed_commands", []) or [])
    if action_entry.get("status") == "cancelled" and not command_candidates:
        return False
    if not command_candidates:
        action_text = normalize_text_content(action_entry.get("action", "")).strip()
        if action_text:
            command_candidates = split_commands_preserving_parentheses(action_text)
    capture_requested = False
    for candidate in command_candidates:
        lowered = normalize_text_content(candidate).strip().lower()
        if lowered.startswith(("request_screenshot_capture", "request_demand_capture")):
            capture_requested = True
        if lowered.startswith(("gb:", "pyag:")):
            return True
    if capture_requested:
        return False
    if "desktop_results" in action_entry:
        # Reviewed receipts describe THIS batch. Persistent worker_last_* values
        # can belong to a previous action and must not create memory-only loops.
        return False
    return any(
        normalize_text_content(action_entry.get(field, "")).strip()
        for field in ("worker_last_key", "worker_last_command", "worker_foreground_window")
    )


def evaluate_turn_scheduler(input_pending=False):
    if not (SEND_TO_MODEL and ENABLE_MODEL_RESPONSES):
        set_runtime_value("turn_scheduler_pending_reasons", [])
        return {"should_run": False, "reasons": [], "state": "paused", "detail": "live responses disabled"}

    if TASK_CONTINUATION_MODE == "bounded" and not TASK_CONTINUATION.can_dispatch(operator_input=input_pending):
        task = TASK_CONTINUATION.snapshot()
        set_runtime_value("turn_scheduler_pending_reasons", [])
        return {"should_run": False, "reasons": [],
                "state": "task_stopped", "detail": f"task stopped: {task.get('stop_reason', 'unknown')}; new operator input starts another task"}

    # The thread queue's unfinished count covers the gap between dequeue and
    # COMMAND_WORK.scope(), and remains set until the receipt is published.
    # Legacy process queues lack this counter; retain queue/scope/result checks.
    command_queue_busy = active_command_queue is not None and (
        bool(getattr(active_command_queue, "unfinished_tasks", 0)) or not active_command_queue.empty()
    )
    result_queue_busy = active_runtime_context is not None and not active_runtime_context.command_result_queue.empty()
    if command_queue_busy or COMMAND_WORK.snapshot()["active_scopes"] or result_queue_busy:
        set_runtime_value("turn_scheduler_pending_reasons", [])
        return {"should_run": False, "reasons": [], "state": "commands_running", "detail": "waiting for command batch completion and receipts"}

    with CAPTURE_SERVICE.lock:
        capture_status = CAPTURE_SERVICE.snapshot()
        capture_failure = capture_status["current_failure"]
        failed_observation = bool(capture_failure and capture_failure["generation"] ==
                                  runtime_state.get("turn_scheduler_capture_request_generation", 0))
        capture_frame = copy.deepcopy(runtime_state.get("last_capture_frame", {}))
        latest_capture_path = capture_frame.get("path", normalize_text_content(runtime_state.get("last_screenshot_path", "")).strip())
        latest_capture_timestamp = capture_frame.get("timestamp", normalize_text_content(runtime_state.get("last_screenshot_timestamp", "")).strip())
        capture_counter = capture_frame.get("counter", int(runtime_state.get("turn_scheduler_capture_counter", 0) or 0))
        observation_generation = runtime_state.get("turn_scheduler_observation_generation", 0)
        pending_observation = bool(runtime_state.get("turn_scheduler_pending_command_result", False))
        required_capture = int(runtime_state.get("turn_scheduler_required_capture_after_action", 0) or 0)
        wait_until = float(runtime_state.get("turn_scheduler_post_action_wait_until_epoch", 0.0) or 0.0)
        post_action_boundary = dict(runtime_state.get("turn_scheduler_post_action_boundary", {}))
    last_submitted_capture_counter = int(runtime_state.get("turn_scheduler_last_submitted_capture_counter", 0) or 0)
    last_capture_hash = capture_frame.get("hash", normalize_text_content(runtime_state.get("turn_scheduler_last_capture_hash", "")).strip())
    last_submitted_capture_hash = normalize_text_content(runtime_state.get("turn_scheduler_last_submitted_capture_hash", "")).strip()
    last_capture_changed_at = float(runtime_state.get("turn_scheduler_last_capture_changed_at_epoch", 0.0) or 0.0)
    last_turn_completed_at = float(runtime_state.get("last_turn_completed_at_epoch", 0.0) or 0.0)
    now = time.time()
    reasons = []
    omit_capture = False

    if input_pending:
        reasons.append("user_input")
    readback = TASK_CONTINUATION.readback()
    if READBACK_WAKE_ENABLED and TASK_CONTINUATION_MODE == "bounded":
        reviewed_pending = READBACK_SCOPE == "reviewed" and COMMAND_READBACKS.pending(TASK_CONTINUATION.snapshot().get("task_id", ""))
        if readback["pending"] or reviewed_pending:
            reasons.append("command_readback")

    if latest_capture_path and not last_turn_completed_at:
        reasons.append("startup_capture")

    if pending_observation:
        fresh = (CAPTURE_PROVENANCE_POLICY == "legacy" or CAPTURE_SERVICE.is_fresh(
            capture_frame, post_action_boundary))
        settled = now >= wait_until if CAPTURE_PROVENANCE_POLICY == "legacy" else fresh
        if failed_observation:
            if not input_pending:
                set_runtime_value("turn_scheduler_pending_reasons", [])
                return {"should_run": False, "reasons": [], "state": "capture_failed", "capture_failure": capture_failure,
                        "detail": f"capture request failed: {capture_failure['code']}; request a fresh capture or Cancel work"}
            omit_capture = True
        elif latest_capture_path and capture_counter >= required_capture and settled:
            reasons.append("command_result")
        elif not input_pending:
            # An unrelated heartbeat or capture tick must not bypass the action's
            # observation boundary. Operator text can still interrupt this wait;
            # urgent Pause/Cancel/Shutdown are serviced independently of inference.
            set_runtime_value("turn_scheduler_pending_reasons", [])
            return {"should_run": False, "reasons": [],
                    "state": "waiting_capture", "detail": "waiting for requested post-action capture and settle time"}
        elif CAPTURE_PROVENANCE_POLICY == "verified":
            # Operator text may interrupt, without presenting stale pixels as a
            # new post-action observation. The observation boundary stays pending.
            omit_capture = True

    if TURN_SCHEDULER_MODE == "per_capture":
        if latest_capture_path and capture_counter > last_submitted_capture_counter:
            reasons.append("capture_tick")
    elif (
        TURN_SCHEDULER_MODE == "hybrid"
        and TURN_SCHEDULER_CAPTURE_WAKE_ENABLED
        and latest_capture_path
        and capture_counter > last_submitted_capture_counter
        and last_capture_hash
        and last_capture_hash != last_submitted_capture_hash
        and (not last_capture_changed_at or (now - last_capture_changed_at) >= TURN_SCHEDULER_CAPTURE_WAKE_DEBOUNCE_SECONDS)
    ):
        reasons.append("capture_change")

    if latest_capture_path and TURN_SCHEDULER_HEARTBEAT_SECONDS > 0:
        if not last_turn_completed_at or (now - last_turn_completed_at) >= TURN_SCHEDULER_HEARTBEAT_SECONDS:
            reasons.append("heartbeat")

    ordered = []
    for reason in ("user_input", "command_result", "command_readback", "startup_capture", "capture_tick", "capture_change", "heartbeat"):
        if reason in reasons and reason not in ordered:
            ordered.append(reason)
    set_runtime_value("turn_scheduler_pending_reasons", ordered)

    if not ordered:
        waiting = "waiting_capture" if capture_status["pending"] or CAPTURE_MODE == "heartbeat" else "waiting_timer" if TURN_SCHEDULER_HEARTBEAT_SECONDS > 0 else "quiescent"
        detail = ("no scheduled wake; inspect pending work, request a fresh capture or send operator input" if waiting == "quiescent"
                  else "no wake condition met; waiting for the configured capture/timer event")
        return {"should_run": False, "reasons": [], "state": waiting, "detail": detail}

    if last_turn_completed_at and (now - last_turn_completed_at) < TURN_SCHEDULER_MIN_GAP_SECONDS:
        return {
            "should_run": False,
            "reasons": ordered,
            "detail": f"waiting for min gap {TURN_SCHEDULER_MIN_GAP_SECONDS:.2f}s",
            "state": "minimum_gap",
        }

    detail_parts = [
        f"mode={TURN_SCHEDULER_MODE}",
        f"capture_counter={capture_counter}",
        f"last_submitted_capture_counter={last_submitted_capture_counter}",
        f"capture_timestamp={latest_capture_timestamp or '-'}",
    ]
    return {
        "should_run": True,
        "state": "ready",
        "reasons": ordered,
        "detail": " | ".join(detail_parts),
        "readback_generation": readback["generation"],
        "omit_capture": omit_capture,
        "observation_generation": observation_generation,
        "capture_frame": capture_frame or {"path": latest_capture_path, "timestamp": latest_capture_timestamp,
                                          "counter": capture_counter, "hash": last_capture_hash,
                                          "provenance": {"status": "unknown"}},
    }


def mark_turn_scheduler_dispatch(reasons, details="", image_timestamp="", readback_generation=0, image_attached=True, capture_frame=None, observation_generation=None):
    primary_reason = reasons[0] if reasons else "manual"
    set_runtime_value("last_turn_wake_reason", primary_reason)
    set_runtime_value(
        "last_turn_wake_details",
        summarize_runtime_text(
            f"{details} | reasons={','.join(reasons)} | scheduler={build_turn_scheduler_summary()}",
            max_chars=220,
        ),
    )
    if image_attached:
        set_runtime_value(
            "turn_scheduler_last_submitted_capture_counter",
            (capture_frame or {}).get("counter", int(runtime_state.get("turn_scheduler_capture_counter", 0) or 0)),
        )
        set_runtime_value(
            "turn_scheduler_last_submitted_capture_hash",
            (capture_frame or {}).get("hash", normalize_text_content(runtime_state.get("turn_scheduler_last_capture_hash", "")).strip()),
        )
        set_runtime_value("turn_scheduler_last_submitted_capture_timestamp", image_timestamp or "")
        set_runtime_value("turn_scheduler_last_submitted_frame", copy.deepcopy(capture_frame or {}))
    TASK_CONTINUATION.acknowledge_readback(readback_generation)
    set_runtime_value("turn_scheduler_pending_reasons", [])
    if "command_result" in reasons:
        clear_turn_scheduler_command_result_pending(expected_generation=observation_generation)

def split_option_segments(raw_text):
    text = normalize_text_content(raw_text).strip()
    if not text:
        return []
    segments = []
    current = []
    quote_char = None
    escape_next = False
    nesting_depth = 0

    for char in text:
        if escape_next:
            current.append(char)
            escape_next = False
            continue
        if quote_char:
            current.append(char)
            if char == "\\":
                escape_next = True
            elif char == quote_char:
                quote_char = None
            continue
        if char in {"'", '"'}:
            quote_char = char
            current.append(char)
            continue
        if char in "([{":
            nesting_depth += 1
            current.append(char)
            continue
        if char in ")]}":
            nesting_depth = max(0, nesting_depth - 1)
            current.append(char)
            continue
        if nesting_depth == 0 and char in {";", "\n"}:
            candidate = "".join(current).strip()
            if candidate:
                segments.append(candidate)
            current = []
            continue
        current.append(char)

    trailing = "".join(current).strip()
    if trailing:
        segments.append(trailing)
    return segments


def parse_named_option_pairs(raw_text):
    pairs = {}
    for segment in split_option_segments(raw_text):
        if "=" in segment:
            key, value = segment.split("=", 1)
        elif ":" in segment:
            key, value = segment.split(":", 1)
        else:
            continue
        normalized_key = normalize_memory_item(key).strip().lower().replace(" ", "_")
        normalized_value = strip_wrapping_quotes(normalize_text_content(value).strip())
        if normalized_key:
            pairs[normalized_key] = normalized_value
    return pairs


def build_next_inference_plan_summary(plan=None):
    plan = get_next_inference_plan_snapshot() if plan is None else plan
    if not isinstance(plan, dict):
        return ""
    parts = []
    for key in ("reasoning_effort", "service_tier", "verbosity", "summary_mode", "image_detail", "latest_image_detail", "temperature", "model", "text_model", "vision_model", "reasoning_model"):
        value = normalize_text_content(plan.get(key, "")).strip()
        if value:
            parts.append(f"{key}={value}")
    target_turn = int(plan.get("target_turn", 0) or 0)
    if target_turn:
        parts.append(f"target_turn={target_turn}")
    if plan.get("note"):
        parts.append(f"note={summarize_runtime_text(plan.get('note', ''), max_chars=80)}")
    return " | ".join(parts)


def has_effective_next_inference_plan(plan=None):
    return bool(build_next_inference_plan_summary(plan))



def get_next_inference_plan_snapshot():
    """Return detached queued state; callers cannot mutate the pending plan."""
    with SETTINGS_TRANSACTION_LOCK:
        return copy.deepcopy(agent_state.next_inference_plan)


def clear_next_inference_plan(reason=""):
    with SETTINGS_TRANSACTION_LOCK:
        agent_state.next_inference_plan = create_empty_next_inference_plan()
        globals()["next_inference_plan"] = agent_state.next_inference_plan
        cleared = dict(agent_state.next_inference_plan)
    if reason:
        append_runtime_feedback(reason)
    return cleared



def set_next_inference_plan_from_pairs(pairs, source="operator", auto_generated=False):
    """Replace a validated one-turn plan atomically with respect to locks and consumption."""
    if not isinstance(pairs, dict):
        raise ValueError("Next inference settings require key=value pairs.")
    options = normalize_next_inference_pairs(pairs)
    with SETTINGS_TRANSACTION_LOCK:
        origin = current_task_artifact_origin(automatic=auto_generated)
        require_current_artifact_origin(origin, "plan_carry_policy")
        if any(options.get(key) for key in ("model", "text_model", "vision_model", "reasoning_model")):
            require_runtime_setting_unlocked("models", "Next inference model controls")
        if any(options.get(key) for key in ("reasoning_effort", "verbosity", "summary_mode", "service_tier")):
            require_runtime_setting_unlocked("reasoning", "Next inference reasoning controls")
        if "temperature" in options:
            require_runtime_setting_unlocked("temperature", "Next inference temperature control")
        normalized_plan = create_empty_next_inference_plan()
        normalized_plan.update(options)
        normalized_plan["target_turn"] = options.get("target_turn") or agent_state.inference_counter + 1
        normalized_plan["queued_at_turn"] = agent_state.inference_counter
        normalized_plan["plan_id"] = uuid.uuid4().hex
        normalized_plan["source"] = normalize_text_content(source).strip() or "operator"
        normalized_plan["auto_generated"] = bool(auto_generated)
        normalized_plan["task_origin"] = origin
        agent_state.next_inference_plan = normalized_plan
        globals()["next_inference_plan"] = agent_state.next_inference_plan
        result = copy.deepcopy(normalized_plan)
    append_runtime_feedback(f"Queued next inference plan: {build_next_inference_plan_summary(result)}")
    return result



def resolve_next_inference_plan_for_turn(current_turn):
    """Consume at most one due plan without clearing a concurrent replacement."""
    with SETTINGS_TRANSACTION_LOCK:
        plan = agent_state.next_inference_plan
        if not isinstance(plan, dict):
            return None
        target_turn = int(plan.get("target_turn", 0) or 0)
        if not target_turn or target_turn > current_turn:
            return None
        applied_plan = copy.deepcopy(plan)
        clear_next_inference_plan()
        return applied_plan


def detect_blocked_progress_signal():
    recent_actions = list(get_recent_executed_actions_store()[-3:])
    if any(action.get("outcome_status") in {"likely_failed", "no_visible_change"} for action in recent_actions):
        return True
    recent_text = " ".join(normalize_text_content(item).lower() for item in agent_state.recent_context_events[-4:])
    return any(keyword in recent_text for keyword in ("blocked", "stuck", "cannot", "can't", "no visible change", "failed"))


def has_recent_known_failures(window_turns=3):
    current_turn = int(agent_state.inference_counter)
    for entry in agent_state.known_failures:
        if not isinstance(entry, dict):
            continue
        created_turn = entry.get("created_turn", current_turn)
        if not isinstance(created_turn, int):
            continue
        if (current_turn - created_turn) <= max(1, int(window_turns)):
            return True
    return False


def infer_gameplay_scene_legacy(context_info=None):
    context_info = context_info or infer_operating_context()
    signal_parts = list(context_info.get("signal_parts", []) or [])
    lowered_signal = " | ".join(normalize_text_content(part).lower() for part in signal_parts if part)
    operating_context = normalize_text_content(context_info.get("context", "unknown")).strip().lower() or "unknown"

    scene_scores = {scene_name: 0 for scene_name in GAMEPLAY_SCENES}
    evidence = {scene_name: [] for scene_name in GAMEPLAY_SCENES}
    hint_groups = {
        "title": get_gameplay_scene_title_hints(),
        "main_menu": GAMEPLAY_SCENE_MAIN_MENU_HINTS,
        "dialog": GAMEPLAY_SCENE_DIALOG_HINTS,
        "overworld": GAMEPLAY_SCENE_OVERWORLD_HINTS,
        "battle": set(BATTLE_REASONING_KEYWORDS),
        "transition": GAMEPLAY_SCENE_TRANSITION_HINTS,
    }
    for scene_name, hints in hint_groups.items():
        for hint in hints:
            if hint in lowered_signal:
                scene_scores[scene_name] += 2 if " " in hint else 1
                evidence[scene_name].append(hint)

    if operating_context == "game":
        scene_scores["overworld"] += 1
    if has_game_title_menu_signal(lowered_signal):
        scene_scores["title"] += 1
        scene_scores["main_menu"] += 1
    if any(keyword in lowered_signal for keyword in ("textbox", "dialog", "message box", "speech box", "npc text")):
        scene_scores["dialog"] += 2
    if any(keyword in lowered_signal for keyword in ("wild battle", "trainer battle", "fight", "choose a move", "hp", "pp")):
        scene_scores["battle"] += 2

    best_scene = "unknown"
    best_score = 0
    for scene_name in ("battle", "title", "main_menu", "dialog", "transition", "overworld"):
        score = scene_scores.get(scene_name, 0)
        if score > best_score:
            best_scene = scene_name
            best_score = score

    if operating_context != "game" and best_score < 3:
        best_scene = "unknown"
    elif best_score <= 0:
        best_scene = "unknown"
    elif best_scene == "title" and scene_scores.get("main_menu", 0) >= scene_scores.get("title", 0):
        if any(keyword in lowered_signal for keyword in ("continue", "new game", "option", "save file", "main menu")):
            best_scene = "main_menu"
    elif best_scene == "dialog" and scene_scores.get("battle", 0) >= scene_scores.get("dialog", 0) + 1:
        best_scene = "battle"

    matched_evidence = evidence.get(best_scene, [])[:3]
    summary = "no strong scene evidence" if best_scene == "unknown" else ", ".join(matched_evidence) if matched_evidence else f"{best_scene} inferred from game context"
    return {
        "scene": best_scene,
        "summary": summary,
        "scores": scene_scores,
        "evidence": evidence,
    }


def infer_gameplay_scene(context_info=None):
    if GAMEPLAY_SCENE_POLICY == "legacy":
        result = infer_gameplay_scene_legacy(context_info)
        result.update(policy="legacy", visually_verified=False)
        set_runtime_value("gameplay_scene_evidence", result)
        return result
    context_info = context_info if context_info is not None else {"context": runtime_state.get("operating_context", "unknown")}
    records = context_info.get("scene_observations", runtime_state.get("gameplay_scene_observations", []))
    result = classify_scene(records, now=time.time(), turn=int(agent_state.inference_counter),
                            operating_context=context_info.get("context", "unknown"))
    set_runtime_value("gameplay_scene_evidence", result)
    return result


def record_gameplay_scene_observation(section_items, narrative_text=""):
    """Record only this response's scene/observation text, before command admission."""
    rows = []
    for source, items in (("assistant_scene", section_items.get("gameplay_scene", [])),
                          ("assistant_observation", section_items.get("recent_context", []))):
        for text in items[-4:]:
            rows.append({"source": source, "text": normalize_text_content(text)[:4000],
                         "turn": int(agent_state.inference_counter), "observed_at": time.time()})
    # Unstructured narrative is deliberately not promoted to scene evidence:
    # it routinely mixes plans, quotations, prior receipts and observations.
    if rows:
        set_runtime_value("gameplay_scene_observations", rows)
    return rows


def refresh_gameplay_scene(context_info=None):
    previous_scene = normalize_text_content(runtime_state.get("gameplay_scene", "")).strip().lower() or "unknown"
    context_info = context_info or infer_operating_context()
    scene_info = infer_gameplay_scene(context_info)
    current_scene = normalize_text_content(scene_info.get("scene", "unknown")).strip().lower() or "unknown"
    set_runtime_value("gameplay_scene", current_scene)
    set_runtime_value("gameplay_scene_summary", scene_info.get("summary", ""))
    if current_scene != previous_scene and current_scene != "unknown" and previous_scene != "unknown":
        invalidate_scene_bound_planning_memory(previous_scene, current_scene)
        invalidate_pending_entries_for_scene_change(previous_scene, current_scene)
        maybe_write_scene_change_episodic_snapshot(previous_scene, current_scene)
    return scene_info


def are_gameplay_scenes_compatible(scene_a, scene_b):
    normalized_a = normalize_text_content(scene_a).strip().lower() or "unknown"
    normalized_b = normalize_text_content(scene_b).strip().lower() or "unknown"
    if normalized_a == normalized_b:
        return True
    if "unknown" in {normalized_a, normalized_b}:
        return True
    compatibility_groups = (
        {"title", "main_menu"},
        {"dialog", "battle"},
        {"overworld", "transition"},
    )
    return any(normalized_a in group and normalized_b in group for group in compatibility_groups)


def _scene_change_reason(previous_scene, current_scene):
    return f"scene changed from {previous_scene} to {current_scene}"


def invalidate_scene_bound_planning_memory(previous_scene, current_scene):
    if are_gameplay_scenes_compatible(previous_scene, current_scene):
        return 0

    contradiction_tag = f"scene:{previous_scene}->{current_scene}"
    stale_reason = _scene_change_reason(previous_scene, current_scene)
    invalidated_count = 0
    planning_stores = (
        agent_state.active_questions,
        agent_state.stale_assumptions,
        agent_state.known_failures,
        agent_state.candidate_alternatives,
    )
    for store in planning_stores:
        for entry in store:
            if not isinstance(entry, dict):
                continue
            entry_scene = normalize_text_content(entry.get("scene", "")).strip().lower() or "unknown"
            if entry_scene == "unknown" or are_gameplay_scenes_compatible(entry_scene, current_scene):
                continue
            entry["freshness"] = "stale"
            entry["status"] = "scene_invalidated"
            entry["stale_reason"] = stale_reason
            entry["contradicted_by"] = contradiction_tag
            entry["last_updated_turn"] = int(agent_state.inference_counter)
            entry["timestamp"] = route_timestamp()
            invalidated_count += 1

    if invalidated_count:
        append_runtime_feedback(
            f"Scene change invalidated {invalidated_count} planning memory item(s): {stale_reason}."
        )
        update_pinned_information()
    return invalidated_count


def invalidate_pending_entries_for_scene_change(previous_scene, current_scene):
    with PENDING_COMMAND_LEDGER.mutation(get_pending_command_store()):
        if are_gameplay_scenes_compatible(previous_scene, current_scene):
            return 0

        pending_store = get_pending_command_store()
        contradiction_tag = f"scene:{previous_scene}->{current_scene}"
        stale_reason = _scene_change_reason(previous_scene, current_scene) or contradiction_tag
        removed_entries = []
        for index in range(len(pending_store) - 1, -1, -1):
            entry = pending_store[index]
            if not pending_entry_available(entry):
                continue
            operating_context = normalize_text_content(entry.get("operating_context", "")).strip().lower() or "unknown"
            entry_scene = normalize_text_content(entry.get("scene", "")).strip().lower()
            scene_basis = entry_scene or (previous_scene if operating_context == "game" else "")
            if operating_context != "game" and scene_basis not in GAMEPLAY_SCENES:
                continue
            if not scene_basis or scene_basis == "unknown":
                continue
            if are_gameplay_scenes_compatible(scene_basis, current_scene):
                continue
            removed_entries.append(pending_store.pop(index))

        removed_entries.reverse()
        for entry in removed_entries:
            entry["contradicted_by"] = contradiction_tag
            entry["contradicted_at_turn"] = int(agent_state.inference_counter)
            append_recent_command_proposal(
                entry.get("command", ""),
                source=entry.get("source", "assistant"),
                associated_goal=entry.get("associated_goal", "No specific goal"),
                disposition="contradicted",
                support_count=entry.get("support_count", 1),
                execute_by_inference=entry.get("execute_by_inference"),
            )
            append_recent_action_intent(
                f"Scene contradicted pending command: {entry.get('command', '')}",
                status="contradicted",
                command=entry.get("command", ""),
                source=entry.get("source", "assistant"),
                associated_goal=entry.get("associated_goal", "No specific goal"),
                execute_by_inference=entry.get("execute_by_inference"),
            )
            append_runtime_feedback(
                f"Scene change invalidated pending command {entry.get('command', '')}: {stale_reason}."
            )
            append_command_drip_item(
                agent_state.inference_counter,
                "dropped",
                build_command_drip_item(
                    command=entry.get("command", ""),
                    status="contradicted",
                    reason=_scene_change_reason(previous_scene, current_scene),
                    category=entry.get("category", ""),
                    risk=entry.get("risk", ""),
                    associated_goal=entry.get("associated_goal", "No specific goal"),
                    source=entry.get("source", "assistant"),
                    expected_outcome=entry.get("expected_outcome", ""),
                    family_key=entry.get("family_key", ""),
                    conflict_key=entry.get("conflict_key", ""),
                    support_count=entry.get("support_count", 1),
                    repeat_count=entry.get("repeat_count", 1),
                    execute_by_inference=entry.get("execute_by_inference"),
                    turns_until_due=entry.get("turns_until_due"),
                    queue_mode=entry.get("queue_mode", "normal"),
                    priority_score=entry.get("priority_score", 0),
                    importance_score=entry.get("importance_score", 0),
                    contradicted_by=contradiction_tag,
                    note="scene change invalidated this pending candidate",
                ),
            )

        if removed_entries:
            append_runtime_feedback(
                f"Scene change removed {len(removed_entries)} incompatible pending command(s)."
            )
        return len(removed_entries)


def infer_turn_model_controls(prompt, base_model_name, inference_turn, is_review_turn=False, is_critique_turn=False):
    model_name = normalize_model_name(base_model_name) or base_model_name
    context_info = infer_operating_context()
    scene_info = refresh_gameplay_scene(context_info)
    gameplay_scene = scene_info.get("scene", "unknown")
    world_signal_parts = list(context_info.get("signal_parts", []) or [])
    route_state_snapshot = agent_state.route_state
    for route_key in ("current_area", "target_area", "travel_heading", "last_landmark"):
        route_value = normalize_text_content(route_state_snapshot.get(route_key, "")).strip()
        if route_value:
            world_signal_parts.append(route_value)
    world_signal = " ".join(part.lower() for part in world_signal_parts if part)
    prompt_signal = normalize_text_content(prompt).strip().lower()
    direct_battle_request = any(
        re.search(pattern, prompt_signal)
        for pattern in (
            r"\bcurrently in (?:a )?battle\b",
            r"\bduring (?:a )?battle\b",
            r"\bactive battle\b",
            r"\bbattle screen\b",
            r"\bwild battle\b",
            r"\btrainer battle\b",
            r"\bmove selection\b",
        )
    )
    battle_detected = gameplay_scene == "battle" or (GAMEPLAY_SCENE_POLICY == "legacy" and (any(signal_mentions_keyword(world_signal, keyword) for keyword in BATTLE_REASONING_KEYWORDS) or direct_battle_request))
    blocked_detected = detect_blocked_progress_signal() or has_recent_known_failures(window_turns=3)
    next_turn_override = resolve_next_inference_plan_for_turn(inference_turn)
    plan_source = "default"
    plan_tags = []

    if next_turn_override:
        if next_turn_override.get("model"):
            model_name = normalize_model_name(next_turn_override["model"]) or model_name
        elif is_review_turn and next_turn_override.get("reasoning_model"):
            model_name = normalize_model_name(next_turn_override["reasoning_model"]) or model_name
        elif next_turn_override.get("vision_model") and "image" in prompt_signal:
            model_name = normalize_model_name(next_turn_override["vision_model"]) or model_name
        elif next_turn_override.get("text_model"):
            model_name = normalize_model_name(next_turn_override["text_model"]) or model_name
        plan_source = "manual_override"
        plan_tags.append("queued_next_turn")

    reasoning_effort = None
    if supports_reasoning_effort(model_name):
        if next_turn_override and next_turn_override.get("reasoning_effort"):
            reasoning_effort = normalize_reasoning_effort_for_model(
                next_turn_override["reasoning_effort"],
                model_name,
                fallback=get_default_reasoning_effort_for_model(model_name),
            )
            plan_tags.append(f"reasoning={reasoning_effort}")
        elif is_review_turn and not AUTO_DYNAMIC_INFERENCE_ENABLED:
            reasoning_effort = normalize_reasoning_effort_for_model(REVIEW_REASONING_EFFORT, model_name, fallback="medium")
            plan_source = "review_role"
        elif AUTO_DYNAMIC_INFERENCE_ENABLED:
            if is_critique_turn:
                reasoning_effort = normalize_reasoning_effort_for_model(CRITIQUE_REASONING_EFFORT, model_name, fallback="high")
                plan_source = "auto_critique"
                plan_tags.append("critique_cadence")
            elif is_review_turn:
                reasoning_effort = normalize_reasoning_effort_for_model(REVIEW_REASONING_EFFORT, model_name, fallback="medium")
                plan_source = "auto_review"
                plan_tags.append("review_cadence")
            elif battle_detected:
                reasoning_effort = normalize_reasoning_effort_for_model(BATTLE_REASONING_EFFORT, model_name, fallback="low")
                plan_source = "battle_escalation"
                plan_tags.append("battle_context")
            elif blocked_detected:
                reasoning_effort = normalize_reasoning_effort_for_model("medium", model_name, fallback="medium")
                plan_source = "failure_escalation"
                plan_tags.append("blocked_signal")
        else:
            if battle_detected:
                reasoning_effort = normalize_reasoning_effort_for_model(BATTLE_REASONING_EFFORT, model_name, fallback="low")
            else:
                reasoning_effort = normalize_reasoning_effort_for_model(
                    DEFAULT_REASONING_EFFORT,
                    model_name,
                    fallback=get_default_reasoning_effort_for_model(model_name),
                )

        if reasoning_effort is None:
            reasoning_effort = normalize_reasoning_effort_for_model(
                DEFAULT_REASONING_EFFORT,
                model_name,
                fallback=get_default_reasoning_effort_for_model(model_name),
            )

    effective_verbosity = None
    if supports_model_verbosity(model_name):
        if next_turn_override and next_turn_override.get("verbosity"):
            effective_verbosity = normalize_model_verbosity(next_turn_override["verbosity"], fallback="medium")
        elif AUTO_DYNAMIC_INFERENCE_ENABLED and is_critique_turn:
            effective_verbosity = normalize_model_verbosity(CRITIQUE_MODEL_VERBOSITY, fallback="high")
        elif AUTO_DYNAMIC_INFERENCE_ENABLED and is_review_turn:
            effective_verbosity = normalize_model_verbosity(REVIEW_MODEL_VERBOSITY, fallback="medium")
        elif AUTO_DYNAMIC_INFERENCE_ENABLED and battle_detected:
            effective_verbosity = normalize_model_verbosity(BATTLE_MODEL_VERBOSITY, fallback="low")
        else:
            effective_verbosity = normalize_model_verbosity(DEFAULT_MODEL_VERBOSITY, fallback="medium")

    summary_mode = normalize_reasoning_summary_mode(DEFAULT_REASONING_SUMMARY_MODE, fallback="auto")
    if next_turn_override and next_turn_override.get("summary_mode"):
        summary_mode = normalize_reasoning_summary_mode(next_turn_override["summary_mode"], fallback=summary_mode)

    effective_image_detail = normalize_image_detail(image_detail, fallback="low")
    if next_turn_override and next_turn_override.get("image_detail"):
        override_image_detail = normalize_image_detail(next_turn_override["image_detail"], fallback="")
        if override_image_detail:
            effective_image_detail = override_image_detail
    effective_latest_image_detail = normalize_image_detail(latest_image_detail, fallback=effective_image_detail)
    if next_turn_override and next_turn_override.get("latest_image_detail"):
        override_latest_image_detail = normalize_image_detail(next_turn_override["latest_image_detail"], fallback="")
        if override_latest_image_detail:
            effective_latest_image_detail = override_latest_image_detail
    effective_image_detail = normalize_image_detail_for_model(effective_image_detail, model_name, fallback="low")
    effective_latest_image_detail = normalize_image_detail_for_model(
        effective_latest_image_detail,
        model_name,
        fallback=effective_image_detail,
    )

    temperature = DEFAULT_MODEL_TEMPERATURE if supports_temperature_override(model_name) else None
    if next_turn_override and next_turn_override.get("temperature") not in {"", None} and supports_temperature_override(model_name):
        try:
            temperature = float(next_turn_override["temperature"])
        except ValueError:
            pass

    planning_note = normalize_text_content((next_turn_override or {}).get("note", "")).strip()
    turn_plan = {
        "service_tier": (next_turn_override or {}).get("service_tier") or DEFAULT_SERVICE_TIER,
        "model_name": model_name,
        "inference_plan_id": (next_turn_override or {}).get("plan_id", ""),
        "reasoning_effort": reasoning_effort,
        "verbosity": effective_verbosity,
        "summary_mode": summary_mode,
        "image_detail": effective_image_detail,
        "latest_image_detail": effective_latest_image_detail,
        "temperature": temperature,
        "source": plan_source,
        "note": planning_note,
        "gameplay_scene": gameplay_scene,
        "battle_detected": battle_detected,
        "blocked_detected": blocked_detected,
        "is_review_turn": bool(is_review_turn),
        "is_critique_turn": bool(is_critique_turn),
        "tags": plan_tags,
    }
    set_runtime_value("last_summary_mode", summary_mode)
    set_runtime_value("last_turn_plan_source", plan_source)
    set_runtime_value("next_inference_source", plan_source)
    set_runtime_value("last_planned_image_detail", effective_image_detail)
    set_runtime_value("last_planned_latest_image_detail", effective_latest_image_detail)
    summary_parts = []
    if reasoning_effort:
        summary_parts.append(f"reasoning={reasoning_effort}")
    if effective_verbosity:
        summary_parts.append(f"verbosity={effective_verbosity}")
    summary_parts.append(f"summary={summary_mode}")
    if plan_source:
        summary_parts.append(f"source={plan_source}")
    if planning_note:
        summary_parts.append(f"note={summarize_runtime_text(planning_note, max_chars=80)}")
    set_runtime_value("last_turn_plan_summary", " | ".join(summary_parts))
    return turn_plan


IMPORTANT_HISTORY_EXEMPTIONS = {"Pinned", "Init", "Special", "Handoff"}
HISTORY_CONTEXT_READ_STATE_SCHEMA_VERSION = "history_context_read_state_v1"
HISTORY_CONTEXT_STORE_SUMMARY_SCHEMA_VERSION = "history_context_store_summary_v1"
HISTORY_CONTEXT_POLICY_SCHEMA_VERSION = "history_context_policy_snapshot_v1"
HISTORY_CONTEXT_SERVICE_FACADE_SCHEMA_VERSION = "history_context_service_facade_v1"


def _history_context_content_type(entry):
    if not isinstance(entry, dict):
        return ""
    content = entry.get("content")
    if isinstance(content, dict):
        return normalize_text_content(content.get("type", "")).strip()
    return ""


def _select_recent_prompt_history_from_store(history_store=None):
    recent_text_entries = []
    recent_image_entries = []
    if history_store is None:
        history_store = get_chat_history_store()
    history_store = [entry for entry in (history_store or []) if isinstance(entry, dict)]

    for entry in reversed(history_store):
        content = entry.get("content", {})
        if content.get("type") == "text" and len(recent_text_entries) < MAX_TEXT_CONTEXT_MESSAGES:
            recent_text_entries.append(entry)
        elif content.get("type") == "image" and len(recent_image_entries) < MAX_IMAGE_CONTEXT_MESSAGES:
            recent_image_entries.append(entry)

        if (
            len(recent_text_entries) >= MAX_TEXT_CONTEXT_MESSAGES
            and len(recent_image_entries) >= MAX_IMAGE_CONTEXT_MESSAGES
        ):
            break

    selected_entries = list(reversed(recent_text_entries)) + list(reversed(recent_image_entries))
    selected_entries.sort(key=lambda entry: entry.get("timestamp", ""))
    return selected_entries


def _build_history_context_read_state(recent_prompt_history=None, prompt_diagnostics=None):
    with HISTORY_LOCK:
        if not isinstance(prompt_diagnostics, dict):
            prompt_diagnostics = runtime_state.get("last_prompt_diagnostics", {}) or {}
        if not isinstance(prompt_diagnostics, dict):
            prompt_diagnostics = {}
        history_store = [entry for entry in get_chat_history_store() if isinstance(entry, dict)]
        ensure_message_ids(history_store)
        CONVERSATION_ARCHIVE.observe(history_store)
        if recent_prompt_history is None:
            recent_prompt_history = _select_recent_prompt_history_from_store(history_store=history_store)
        recent_prompt_history = [entry for entry in (recent_prompt_history or []) if isinstance(entry, dict)]
        # Copy together so selected-row identity survives in the detached snapshot.
        history_store, recent_prompt_history = copy.deepcopy((history_store, recent_prompt_history))
        text_entries = [entry for entry in history_store if _history_context_content_type(entry) == "text"]
        image_entries = [entry for entry in history_store if _history_context_content_type(entry) == "image"]
        recent_entry_ids = {id(entry) for entry in recent_prompt_history}
        selected_text_count = sum(1 for entry in recent_prompt_history if _history_context_content_type(entry) == "text")
        selected_image_count = sum(1 for entry in recent_prompt_history if _history_context_content_type(entry) == "image")
        recent_text_count = int(prompt_diagnostics.get("recent_text_messages", selected_text_count) or 0)
        recent_image_count = int(prompt_diagnostics.get("recent_image_messages", selected_image_count) or 0)
        important_text_count = sum(1 for entry in text_entries if entry.get("Exemption") in IMPORTANT_HISTORY_EXEMPTIONS)
        important_text_selected_count = sum(
            1 for entry in text_entries
            if entry.get("Exemption") in IMPORTANT_HISTORY_EXEMPTIONS and id(entry) in recent_entry_ids
        )
        return {
            "schema_version": HISTORY_CONTEXT_READ_STATE_SCHEMA_VERSION,
            "source": "history_context_service",
            "prompt_diagnostics": dict(prompt_diagnostics),
            "history_store": history_store,
            "text_entries": text_entries,
            "image_entries": image_entries,
            "recent_prompt_history": recent_prompt_history,
            "recent_entry_ids": recent_entry_ids,
            "selected_text_count": selected_text_count,
            "selected_image_count": selected_image_count,
            "recent_text_count": recent_text_count,
            "recent_image_count": recent_image_count,
            "message_count": int(prompt_diagnostics.get("message_count", 0) or 0),
            "mode": "last_model_turn" if prompt_diagnostics else "eligible_now_estimate",
            "latest_prompt_available": bool(prompt_diagnostics or normalize_text_content(runtime_state.get("last_prompt_summary", "")).strip()),
            "image_attached": bool(prompt_diagnostics.get("image_attached", False)),
            "state_snapshot_chars": int(prompt_diagnostics.get("state_snapshot_chars", 0) or 0),
            "init_prompt_chars_used": int(prompt_diagnostics.get("init_prompt_chars_used", 0) or 0),
            "init_prompt_chars_total": int(prompt_diagnostics.get("init_prompt_chars_total", 0) or 0),
            "important_text_count": important_text_count,
            "important_text_selected_count": important_text_selected_count,
        }


def _ensure_history_context_read_state(history_read_state=None):
    if (
        isinstance(history_read_state, dict)
        and history_read_state.get("schema_version") == HISTORY_CONTEXT_READ_STATE_SCHEMA_VERSION
    ):
        return history_read_state
    return _build_history_context_read_state()


def _history_context_control_panel_history_tail_from_state(history_read_state, limit=12):
    history_read_state = _ensure_history_context_read_state(history_read_state)
    tail = []
    for entry in history_read_state.get("history_store", [])[-limit:]:
        role = normalize_text_content(entry.get("role", "")).strip() or "unknown"
        text = summarize_runtime_text(get_history_entry_text(entry), max_chars=220)
        if not text:
            continue
        tail.append({"role": role, "text": text})
    return tail


def _history_context_control_panel_image_memory_from_state(history_read_state, limit=12):
    history_read_state = _ensure_history_context_read_state(history_read_state)
    rows = []
    image_entries = [
        entry for entry in history_read_state.get("image_entries", [])
        if normalize_text_content(entry.get("image_path", "")).strip()
    ]
    for entry in image_entries[-limit:]:
        rows.append({
            "path": normalize_text_content(entry.get("image_path", "")).strip(),
            "timestamp": normalize_text_content(entry.get("timestamp", "")).strip(),
            "detail": normalize_text_content(entry.get("content", {}).get("detail", "")).strip(),
            "sticky": bool(entry.get("content", {}).get("sticky", False)),
        })
    return rows


class HistoryContextService:
    """Read-only facade for shared history/context views."""

    def __init__(self, recent_prompt_history=None, prompt_diagnostics=None, read_state=None):
        self._recent_prompt_history = recent_prompt_history
        self._prompt_diagnostics = prompt_diagnostics
        self._read_state = None
        if (
            isinstance(read_state, dict)
            and read_state.get("schema_version") == HISTORY_CONTEXT_READ_STATE_SCHEMA_VERSION
        ):
            self._read_state = read_state

    def read_state(self):
        if self._read_state is None:
            self._read_state = _build_history_context_read_state(
                recent_prompt_history=self._recent_prompt_history,
                prompt_diagnostics=self._prompt_diagnostics,
            )
        return self._read_state

    def recent_prompt_history(self):
        return list(self.read_state().get("recent_prompt_history", []) or [])

    def prompt_window_counts(self):
        state = self.read_state()
        return {
            "selected_text_count": int(state.get("selected_text_count", 0) or 0),
            "selected_image_count": int(state.get("selected_image_count", 0) or 0),
            "recent_text_count": int(state.get("recent_text_count", 0) or 0),
            "recent_image_count": int(state.get("recent_image_count", 0) or 0),
            "message_count": int(state.get("message_count", 0) or 0),
            "important_text_count": int(state.get("important_text_count", 0) or 0),
            "important_text_selected_count": int(state.get("important_text_selected_count", 0) or 0),
            "mode": state.get("mode", "eligible_now_estimate"),
            "latest_prompt_available": bool(state.get("latest_prompt_available", False)),
        }

    def control_panel_history_tail(self, limit=12):
        return _history_context_control_panel_history_tail_from_state(self.read_state(), limit=limit)

    def control_panel_image_memory(self, limit=12):
        return _history_context_control_panel_image_memory_from_state(self.read_state(), limit=limit)

    def facade_snapshot(self):
        counts = self.prompt_window_counts()
        read_methods = [
            {
                "name": "read_state",
                "scope": "shared normalized history/context counts and prompt diagnostics",
                "write_path": False,
                "model_visible_mutation": False,
            },
            {
                "name": "recent_prompt_history",
                "scope": "read current prompt-window candidates without changing packing behavior",
                "write_path": False,
                "model_visible_mutation": False,
            },
            {
                "name": "control_panel_history_tail",
                "scope": "read summarized chat tail for operator UI export",
                "write_path": False,
                "model_visible_mutation": False,
            },
            {
                "name": "control_panel_image_memory",
                "scope": "read retained image rows for operator UI export",
                "write_path": False,
                "model_visible_mutation": False,
            },
            {
                "name": "prompt_window_counts",
                "scope": "read selected text/image counts for diagnostics",
                "write_path": False,
                "model_visible_mutation": False,
            },
        ]
        return {
            "schema_version": HISTORY_CONTEXT_SERVICE_FACADE_SCHEMA_VERSION,
            "enabled": True,
            "status": "read_only_facade_active",
            "read_state_schema": self.read_state().get("schema_version", HISTORY_CONTEXT_READ_STATE_SCHEMA_VERSION),
            "read_methods": read_methods,
            "read_method_count": len(read_methods),
            "write_methods_enabled": False,
            "model_visible_mutation_enabled": False,
            "prompt_packer_uses_facade": True,
            "prompt_window": counts,
            "notes": [
                "The facade centralizes low-risk read helpers only.",
                "Live prompt packing, history append, private histories, and model-visible mark inclusion remain unchanged.",
            ],
        }


def _ensure_history_context_service(history_service=None, history_read_state=None):
    if isinstance(history_service, HistoryContextService):
        return history_service
    return HistoryContextService(read_state=history_read_state)


def _build_control_panel_history_tail(limit=12, history_read_state=None):
    return _ensure_history_context_service(history_read_state=history_read_state).control_panel_history_tail(limit=limit)


def _build_control_panel_image_memory(limit=12, history_read_state=None):
    return _ensure_history_context_service(history_read_state=history_read_state).control_panel_image_memory(limit=limit)


def _normalize_visual_context_path(path):
    text = normalize_text_content(path).strip()
    if not text:
        return ""
    try:
        return os.path.normcase(os.path.abspath(text))
    except Exception:
        return os.path.normcase(text)


def _visual_context_file_row(path, *, lane, source, detail="", timestamp="", sticky=False):
    raw_path = normalize_text_content(path).strip()
    row = {
        "lane": lane,
        "source": source,
        "path": raw_path,
        "name": os.path.basename(raw_path) if raw_path else "",
        "detail": normalize_text_content(detail).strip(),
        "timestamp": normalize_text_content(timestamp).strip(),
        "sticky": bool(sticky),
        "exists": False,
        "size_bytes": None,
        "mtime": None,
    }
    if not raw_path:
        return row
    try:
        stat = os.stat(raw_path)
        row["exists"] = True
        row["size_bytes"] = int(stat.st_size)
        row["mtime"] = datetime.datetime.fromtimestamp(stat.st_mtime).isoformat(timespec="seconds")
    except Exception:
        pass
    sidecar_summary = summarize_image_context_sidecar(raw_path)
    row["image_context"] = sidecar_summary
    row["sidecar_exists"] = bool(sidecar_summary.get("sidecar_exists", False))
    return row


VISUAL_CONTEXT_LOCAL_SCAN_TTL_SECONDS = 30.0
visual_context_local_screenshot_cache = {
    "updated_at": 0.0,
    "limit": 0,
    "rows": [],
    "total": 0,
}


def _iter_local_screenshot_rows(limit=12):
    limit = max(0, int(limit))
    now = time.time()
    cache_rows = visual_context_local_screenshot_cache.get("rows", [])
    cache_limit = int(visual_context_local_screenshot_cache.get("limit", 0) or 0)
    cache_age = now - float(visual_context_local_screenshot_cache.get("updated_at", 0.0) or 0.0)
    if cache_rows and cache_limit >= limit and cache_age <= VISUAL_CONTEXT_LOCAL_SCAN_TTL_SECONDS:
        return list(cache_rows[:limit]), int(visual_context_local_screenshot_cache.get("total", 0) or 0)

    candidates = []
    total = 0
    try:
        with os.scandir(logging_folder) as entries:
            for entry in entries:
                try:
                    if not entry.is_file():
                        continue
                    if not entry.name.lower().endswith((".png", ".jpg", ".jpeg", ".webp", ".bmp", ".gif")):
                        continue
                    stat = entry.stat()
                except Exception:
                    continue
                total += 1
                item = (stat.st_mtime, entry.path)
                if len(candidates) < limit:
                    heapq.heappush(candidates, item)
                elif limit > 0 and item[0] > candidates[0][0]:
                    heapq.heapreplace(candidates, item)
    except Exception:
        return [], 0
    candidates.sort(key=lambda item: item[0], reverse=True)
    rows = [
        _visual_context_file_row(
            path,
            lane="local_only",
            source="screenshots_folder",
            detail="Available on disk; not currently exported as an in-prompt or retained image lane item.",
        )
        for _, path in candidates
    ]
    visual_context_local_screenshot_cache.update({
        "updated_at": now,
        "limit": limit,
        "rows": list(rows),
        "total": total,
    })
    return rows, total


def _build_visual_context_snapshot(screenshot_limit=12, memory_limit=12, history_read_state=None):
    history_read_state = _ensure_history_context_read_state(history_read_state)
    prompt_diagnostics = history_read_state.get("prompt_diagnostics", {}) or {}
    in_prompt = []
    seen_prompt_paths = set()

    for entry in history_read_state.get("recent_prompt_history", []):
        if not isinstance(entry, dict):
            continue
        content = entry.get("content")
        if not isinstance(content, list):
            continue
        for item in content:
            if not isinstance(item, dict) or item.get("type") != "image":
                continue
            image_path = item.get("image_path")
            normalized = _normalize_visual_context_path(image_path)
            if not normalized or normalized in seen_prompt_paths:
                continue
            seen_prompt_paths.add(normalized)
            in_prompt.append(
                _visual_context_file_row(
                    image_path,
                    lane="in_prompt",
                    source="prompt_history",
                    detail="Recent image history eligible for the prompt image lane.",
                    timestamp=entry.get("timestamp", ""),
                )
            )

    current_screenshot_path = normalize_text_content(runtime_state.get("last_screenshot_path", "")).strip()
    current_normalized = _normalize_visual_context_path(current_screenshot_path)
    if prompt_diagnostics.get("image_attached") and current_normalized and current_normalized not in seen_prompt_paths:
        seen_prompt_paths.add(current_normalized)
        in_prompt.insert(
            0,
            _visual_context_file_row(
                current_screenshot_path,
                lane="in_prompt",
                source="current_turn_screenshot",
                detail="Current turn screenshot attached separately from prior image history.",
                timestamp=runtime_state.get("last_screenshot_timestamp", "") or "",
                sticky=True,
            ),
        )

    retained = []
    retained_paths = set()
    for item in _build_control_panel_image_memory(limit=memory_limit, history_read_state=history_read_state):
        if not isinstance(item, dict):
            continue
        image_path = item.get("image_path") or item.get("path")
        normalized = _normalize_visual_context_path(image_path)
        if normalized:
            retained_paths.add(normalized)
        row = _visual_context_file_row(
            image_path,
            lane="retained",
            source="chat_history",
            detail=normalize_text_content(item.get("detail") or "Retained image memory entry."),
            timestamp=item.get("timestamp", ""),
            sticky=bool(item.get("sticky", False)),
        )
        retained.append(row)

    local_rows, local_total = _iter_local_screenshot_rows(limit=max(screenshot_limit * 3, screenshot_limit))
    excluded_paths = seen_prompt_paths | retained_paths
    local_only = []
    for row in local_rows:
        normalized = _normalize_visual_context_path(row.get("path"))
        if normalized and normalized in excluded_paths:
            continue
        local_only.append(row)
        if len(local_only) >= screenshot_limit:
            break

    lanes = [
        {
            "name": "in_prompt",
            "label": "In Prompt",
            "count": len(in_prompt),
            "description": "Images attached to the latest model prompt or eligible through recent prompt history.",
        },
        {
            "name": "retained",
            "label": "Retained",
            "count": len(retained),
            "description": "Image entries Aurora still has in chat/image memory metadata.",
        },
        {
            "name": "local_only",
            "label": "Local Only",
            "count": len(local_only),
            "description": "Recent screenshot files on disk that are available to pull in but are not presently in the prompt lane.",
        },
    ]
    return {
        "summary": {
            "prompt_prior_image_limit": MAX_IMAGE_CONTEXT_MESSAGES,
            "prompt_recent_image_messages": prompt_diagnostics.get("recent_image_messages", 0),
            "current_image_attached": bool(prompt_diagnostics.get("image_attached")),
            "retained_exported_count": len(retained),
            "local_screenshot_count": local_total,
            "lanes": lanes,
        },
        "in_prompt": in_prompt,
        "retained": retained,
        "local_only": local_only,
        "notes": [
            "The current screenshot is attached separately from retained prior image history.",
            "The retained image limit is not the same thing as the number of images visible in one model prompt.",
            "Screenshot filenames are chronological capture ids; they do not currently carry semantic captions.",
        ],
    }


def _image_context_index_row_from_sidecar(sidecar_path):
    data = _read_json_file_safely(sidecar_path)
    capture = data.get("capture", {}) or {}
    hashes = data.get("hashes", {}) or {}
    prompt_state = data.get("prompt_context_state", {}) or {}
    semantic = data.get("semantic", {}) or {}
    statuses = semantic.get("status", {}) or {}
    row = {
        "image_id": normalize_text_content(data.get("image_id", "")).strip(),
        "screenshot_path": normalize_text_content(data.get("screenshot_path", "")).strip(),
        "sidecar_path": normalize_text_content(data.get("sidecar_path", sidecar_path)).strip() or sidecar_path,
        "created_at": normalize_text_content(data.get("created_at", "")).strip(),
        "capture_timestamp": normalize_text_content(capture.get("timestamp", "")).strip(),
        "capture_reason": normalize_text_content(capture.get("reason", "")).strip(),
        "capture_hash": normalize_text_content(hashes.get("capture_hash", "")).strip(),
        "file_sha1_prefix": normalize_text_content(hashes.get("file_sha1_prefix", "")).strip(),
        "caption": normalize_text_content(semantic.get("caption", "")).strip(),
        "ocr_text": normalize_text_content(semantic.get("ocr_text", "")).strip(),
        "caption_status": normalize_text_content(statuses.get("caption", "pending")).strip() or "pending",
        "ocr_status": normalize_text_content(statuses.get("ocr", "pending")).strip() or "pending",
        "tags_status": normalize_text_content(statuses.get("tags", "pending")).strip() or "pending",
        "embeddings_status": normalize_text_content(statuses.get("embeddings", "pending")).strip() or "pending",
        "tags": list(semantic.get("tags", []) or []),
        "embedding_ids": list(semantic.get("embedding_ids", []) or []),
        "visible_to_model_now": bool(prompt_state.get("visible_to_model_now", False)),
        "model_visible_next_turn": bool(prompt_state.get("model_visible_next_turn", False)),
        "exists": False,
        "sidecar_exists": bool(os.path.exists(sidecar_path)),
        "sidecar_mtime": None,
    }
    screenshot_path = row.get("screenshot_path", "")
    try:
        if screenshot_path:
            row["exists"] = bool(os.path.exists(screenshot_path))
    except Exception:
        row["exists"] = False
    try:
        stat = os.stat(sidecar_path)
        row["sidecar_mtime"] = datetime.datetime.fromtimestamp(stat.st_mtime).isoformat(timespec="seconds")
    except Exception:
        pass
    return row


def _iter_recent_image_context_index_rows(limit=12):
    limit = max(0, int(limit))
    candidates = []
    total = 0
    try:
        with os.scandir(image_context_index_dir) as entries:
            for entry in entries:
                try:
                    if not entry.is_file() or not entry.name.lower().endswith(".json"):
                        continue
                    stat = entry.stat()
                except Exception:
                    continue
                total += 1
                item = (stat.st_mtime, entry.path)
                if len(candidates) < limit:
                    heapq.heappush(candidates, item)
                elif limit > 0 and item[0] > candidates[0][0]:
                    heapq.heapreplace(candidates, item)
    except Exception:
        return [], 0
    candidates.sort(key=lambda item: item[0], reverse=True)
    return [_image_context_index_row_from_sidecar(path) for _mtime, path in candidates], total


def _build_image_context_index_snapshot(visual_context=None, limit=12):
    rows, total = _iter_recent_image_context_index_rows(limit=limit)
    sidecar_dir_exists = os.path.isdir(image_context_index_dir)
    manifest_exists = os.path.exists(image_context_index_manifest_path)
    latest_sidecar = normalize_text_content(runtime_state.get("last_image_context_sidecar_path", "")).strip()
    latest_error = normalize_text_content(runtime_state.get("last_image_context_sidecar_error", "")).strip()
    last_backfill = runtime_state.get("last_image_context_backfill", {}) or {}
    if not isinstance(last_backfill, dict):
        last_backfill = {}
    last_update = runtime_state.get("last_image_context_metadata_update", {}) or {}
    if not isinstance(last_update, dict):
        last_update = {}
    last_search = runtime_state.get("last_image_context_search", {}) or {}
    if not isinstance(last_search, dict):
        last_search = {}
    visual_context = visual_context if isinstance(visual_context, dict) else {}
    visual_summary = visual_context.get("summary", {}) if isinstance(visual_context, dict) else {}
    return {
        "summary": {
            "status": "active" if sidecar_dir_exists or rows else "waiting_for_first_capture",
            "mode": "metadata_sidecars",
            "schema_version": IMAGE_CONTEXT_SIDECAR_SCHEMA_VERSION,
            "sidecar_dir": image_context_index_dir,
            "manifest_path": image_context_index_manifest_path,
            "sidecar_dir_exists": sidecar_dir_exists,
            "manifest_exists": manifest_exists,
            "sidecar_count": total,
            "recent_count": len(rows),
            "latest_sidecar_path": latest_sidecar,
            "latest_error": latest_error,
            "local_screenshot_count": visual_summary.get("local_screenshot_count", 0),
            "last_backfill_summary": normalize_text_content(last_backfill.get("summary", "")).strip(),
            "last_backfill_created": int(last_backfill.get("created", 0) or 0),
            "last_backfill_existing": int(last_backfill.get("existing", 0) or 0),
            "last_backfill_failed": int(last_backfill.get("failed", 0) or 0),
            "last_metadata_update": (
                f"{last_update.get('image_id', last_update.get('target', ''))}:"
                f"{','.join(last_update.get('updated_fields', []) or [])}"
                if last_update else ""
            ),
            "last_search_summary": normalize_text_content(last_search.get("summary", "")).strip(),
            "last_search_match_count": int(last_search.get("match_count", 0) or 0),
            "last_search_returned_count": int(last_search.get("returned_count", 0) or 0),
        },
        "expected_fields": [
            "capture.reason",
            "prompt_context_state.visible_to_model_now",
            "hashes.capture_hash",
            "hashes.file_sha1_prefix",
            "semantic.caption",
            "semantic.ocr_text",
            "semantic.tags",
            "semantic.embedding_ids",
        ],
        "recent": rows,
        "last_backfill": last_backfill,
        "last_metadata_update": last_update,
        "last_search": last_search,
        "notes": [
            "Screenshot filenames remain stable epoch-second ids; image meaning lives in sidecar metadata.",
            "Caption, OCR, tags, and embedding ids are filled only through explicit metadata/index commands for now.",
            "Sidecar rows are operator-visible metadata only and do not attach screenshots to the model prompt by themselves.",
        ],
    }


def format_image_context_index_snapshot(snapshot=None):
    snapshot = snapshot or _build_image_context_index_snapshot()
    summary = snapshot.get("summary", {}) or {}
    lines = [
        "Image context index:",
        f"- status={summary.get('status', '-')}; mode={summary.get('mode', '-')}; schema={summary.get('schema_version', '-')}",
        f"- sidecars={summary.get('sidecar_count', 0)} recent={summary.get('recent_count', 0)}; screenshot_files={summary.get('local_screenshot_count', 0)}",
        f"- latest_sidecar={summary.get('latest_sidecar_path') or '-'}",
        f"- manifest={summary.get('manifest_path') or '-'}",
    ]
    backfill_summary = normalize_text_content(summary.get("last_backfill_summary", "")).strip()
    if backfill_summary:
        lines.append(f"- last_backfill={backfill_summary}")
    metadata_update = normalize_text_content(summary.get("last_metadata_update", "")).strip()
    if metadata_update:
        lines.append(f"- last_metadata_update={metadata_update}")
    search_summary = normalize_text_content(summary.get("last_search_summary", "")).strip()
    if search_summary:
        lines.append(f"- last_search={search_summary}")
    latest_error = normalize_text_content(summary.get("latest_error", "")).strip()
    if latest_error:
        lines.append(f"- latest_error={latest_error}")
    fields = snapshot.get("expected_fields", []) or []
    if fields:
        lines.append("- expected_fields=" + ", ".join(fields))
    last_search = snapshot.get("last_search", {}) or {}
    if isinstance(last_search, dict) and last_search:
        lines.append("Last search matches:")
        search_items = last_search.get("items", []) or []
        if not search_items:
            lines.append("- none")
        for row in search_items[:6]:
            hits = row.get("hits", {}) or {}
            hit_text = ", ".join(f"{key}:{value}" for key, value in sorted(hits.items())) or "-"
            lines.append(
                f"- score={row.get('score', 0)} | {row.get('image_id', '-') or '-'} | "
                f"hits={hit_text} | {row.get('capture_reason', '-') or '-'}"
            )
            if row.get("caption"):
                lines.append(f"  caption={summarize_runtime_text(row.get('caption'), max_chars=120)}")
            if row.get("ocr_text"):
                lines.append(f"  ocr={summarize_runtime_text(row.get('ocr_text'), max_chars=120)}")
            if row.get("screenshot_path"):
                lines.append(f"  screenshot={row.get('screenshot_path')}")
    rows = snapshot.get("recent", []) or []
    lines.append("Recent sidecars:")
    if not rows:
        lines.append("- none yet")
    for row in rows[:12]:
        lines.append(
            f"- {row.get('image_id', '-') or '-'} | {row.get('capture_reason', '-') or '-'} | "
            f"hash={row.get('capture_hash') or row.get('file_sha1_prefix') or '-'} | "
            f"caption={row.get('caption_status', '-')} ocr={row.get('ocr_status', '-')} "
            f"tags={len(row.get('tags', []) or [])} embeddings={len(row.get('embedding_ids', []) or [])}"
        )
        if row.get("screenshot_path"):
            lines.append(f"  screenshot={row.get('screenshot_path')}")
        if row.get("caption"):
            lines.append(f"  caption={summarize_runtime_text(row.get('caption'), max_chars=120)}")
        if row.get("ocr_text"):
            lines.append(f"  ocr={summarize_runtime_text(row.get('ocr_text'), max_chars=120)}")
        if row.get("sidecar_path"):
            lines.append(f"  sidecar={row.get('sidecar_path')}")
    notes = snapshot.get("notes", []) or []
    if notes:
        lines.append("Notes:")
        lines.extend(f"- {note}" for note in notes if str(note or "").strip())
    return "\n".join(lines)


def _context_file_shelf_row(
    key,
    label,
    path,
    *,
    kind="file",
    group="project",
    visible_to_model_now=False,
    visible_to_user=True,
    refresh_on_wake=False,
    pinned=False,
    note="",
):
    raw_path = normalize_text_content(path).strip()
    row = {
        "key": normalize_text_content(key).strip(),
        "label": normalize_text_content(label).strip(),
        "path": raw_path,
        "name": os.path.basename(raw_path) if raw_path else "",
        "kind": normalize_text_content(kind).strip() or "file",
        "group": normalize_text_content(group).strip() or "project",
        "visible_to_model_now": bool(visible_to_model_now),
        "visible_to_user": bool(visible_to_user),
        "refresh_on_wake": bool(refresh_on_wake),
        "pinned": bool(pinned),
        "note": normalize_text_content(note).strip(),
        "exists": False,
        "size_bytes": None,
        "mtime": None,
    }
    if not raw_path:
        return row
    try:
        stat = os.stat(raw_path)
        row["exists"] = True
        row["size_bytes"] = int(stat.st_size)
        row["mtime"] = datetime.datetime.fromtimestamp(stat.st_mtime).isoformat(timespec="seconds")
    except Exception:
        pass
    return row


