def build_control_panel_state_snapshot():
    with SETTINGS_TRANSACTION_LOCK:
        snapshot = _build_control_panel_state_snapshot_unlocked()
    snapshot["work"] = {"model_io": MODEL_IO.snapshot(), "model_turns": MODEL_WORK.snapshot(),
                        "commands": COMMAND_WORK.snapshot(), "held_inputs": HELD_INPUTS.snapshot()}
    snapshot["build"] = release_info()
    snapshot["conversation_io"] = {
        "input_recovery_mode": INPUT_RECOVERY_MODE,
        "input_recovery": INPUT_RECOVERY.summary() if INPUT_RECOVERY is not None else {},
        "input_recovery_last_error": runtime_state.get('input_recovery_error', ''),
        "input_recovery_readiness": get_input_recovery_readiness(),
        "last_model_turn_status": runtime_state.get("last_model_turn_status", ""),
        "queued_input_count": get_input_queue_store().qsize(),
    }
    return snapshot


def write_control_panel_state_snapshot(force=False):
    global _last_control_panel_snapshot_write
    now = time.time()
    if not force and (now - _last_control_panel_snapshot_write) < CONTROL_PANEL_EXPORT_INTERVAL_SECONDS:
        return False
    set_runtime_value("control_panel_state_export_last_started_at_epoch", now)
    started = time.perf_counter()
    temp_state_path = f"{control_panel_state_path}.tmp"
    try:
        snapshot = build_control_panel_state_snapshot()
        with open(temp_state_path, "w", encoding="utf-8") as state_file:
            json.dump(snapshot, state_file, indent=2)
        os.replace(temp_state_path, control_panel_state_path)
        completed_at = time.time()
        try:
            state_size = os.path.getsize(control_panel_state_path)
        except Exception:
            state_size = 0
        set_runtime_value("control_panel_state_export_last_success_at_epoch", completed_at)
        set_runtime_value("control_panel_state_export_last_duration_ms", int((time.perf_counter() - started) * 1000.0))
        set_runtime_value("control_panel_state_export_last_size_bytes", int(state_size or 0))
        set_runtime_value("control_panel_state_export_last_error", "")
        set_runtime_value("control_panel_state_export_last_error_at_epoch", 0.0)
        _last_control_panel_snapshot_write = completed_at
        return True
    except Exception as error:
        error_text = summarize_runtime_text(str(error), max_chars=180)
        set_runtime_value("control_panel_state_export_last_error", error_text)
        set_runtime_value("control_panel_state_export_last_error_at_epoch", time.time())
        append_runtime_feedback(f"Control panel state export failed: {error_text}")
        try:
            if os.path.exists(temp_state_path):
                os.remove(temp_state_path)
        except Exception:
            pass
        return False


def write_command_execution_log(event_type, **fields):
    os.makedirs(script_directory, exist_ok=True)
    record: dict[str, Any] = {
        "timestamp": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "session_id": COMMAND_LOG_SESSION_ID,
        "event": event_type,
    }
    record.update(fields)
    record = sanitize_sensitive_record(record)
    with open(command_execution_log_path, "a", encoding="utf-8") as log_file:
        log_file.write(json.dumps(record, ensure_ascii=True) + "\n")
    preview = {
        "event": event_type,
        "command": record.get("command", ""),
        "status": record.get("status", ""),
        "source": record.get("source", ""),
        "request_id": record.get("request_id", ""),
        "expanded_count": len(record.get("expanded_commands", []) or []),
    }
    safe_print("[CMDLOG]", json.dumps(preview, ensure_ascii=True))
    return record


def write_chat_history_log(event_type, **fields):
    os.makedirs(script_directory, exist_ok=True)
    record: dict[str, Any] = {
        "timestamp": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "session_id": COMMAND_LOG_SESSION_ID,
        "event": event_type,
    }
    record.update(fields)
    record = sanitize_sensitive_record(record)
    with open(chat_history_log_path, "a", encoding="utf-8") as log_file:
        log_file.write(json.dumps(record, ensure_ascii=True) + "\n")
    CONVERSATION_ARCHIVE.record_event(record)
    preview = {
        "event": event_type,
        "role": record.get("role", ""),
        "summary": record.get("content_summary", "") or record.get("narrative_summary", "") or record.get("executed_commands", ""),
        "history_length": record.get("history_length", ""),
    }
    if CHAT_LOG_ECHO_ENABLED:
        safe_print("[CHATLOG]", json.dumps(preview, ensure_ascii=True))


def ensure_external_bridge_files():
    os.makedirs(script_directory, exist_ok=True)
    for path in (external_inbox_path, external_drop_path, mutation_admission_log_path):
        if not os.path.exists(path):
            with open(path, "a", encoding="utf-8"):
                pass


def load_external_bridge_state():
    global external_bridge_state
    ensure_external_bridge_files()
    if os.path.exists(external_bridge_state_path):
        try:
            with open(external_bridge_state_path, "r", encoding="utf-8") as state_file:
                loaded = json.load(state_file)
            merged = create_default_external_bridge_state()
            if isinstance(loaded, dict):
                merged.update(loaded)
            external_bridge_state = merged
        except Exception:
            external_bridge_state = create_default_external_bridge_state()
    else:
        external_bridge_state = create_default_external_bridge_state()
    return external_bridge_state


def save_external_bridge_state():
    ensure_external_bridge_files()
    temporary_path = external_bridge_state_path + ".tmp"
    with open(temporary_path, "w", encoding="utf-8") as state_file:
        json.dump(external_bridge_state, state_file, ensure_ascii=True, indent=2)
        state_file.flush()
        os.fsync(state_file.fileno())
    os.replace(temporary_path, external_bridge_state_path)


def write_external_bridge_log(event_type, **fields):
    ensure_external_bridge_files()
    record: dict[str, Any] = {
        "timestamp": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "session_id": COMMAND_LOG_SESSION_ID,
        "event": event_type,
    }
    record.update(fields)
    record = sanitize_sensitive_record(record)
    with open(external_bridge_log_path, "a", encoding="utf-8") as log_file:
        log_file.write(json.dumps(record, ensure_ascii=True) + "\n")
    preview = {
        "event": event_type,
        "source": record.get("source", ""),
        "message_id": record.get("message_id", ""),
        "request_id": record.get("request_id", ""),
    }
    safe_print("[BRIDGE]", json.dumps(preview, ensure_ascii=True))


def get_mutation_admission_journal():
    global mutation_admission_journal
    if mutation_admission_journal is None:
        mutation_admission_journal = MutationAdmissionJournal(
            script_directory,
            session_id=COMMAND_LOG_SESSION_ID,
        )
    return mutation_admission_journal


def get_mutation_admission_summary():
    try:
        return get_mutation_admission_journal().summary()
    except Exception as error:
        return {
            "schema_version": MUTATION_ADMISSION_SCHEMA_VERSION,
            "path": mutation_admission_log_path,
            "status": "error",
            "error": summarize_runtime_text(str(error), max_chars=180),
            "no_automatic_replay": True,
        }


def is_external_mutation_command(command_text, prepared_commands=None):
    try:
        prepared = prepare_command_batch(command_text) if prepared_commands is None else prepared_commands
    except (CommandSyntaxError, ValueError):
        # Malformed/unknown raw requests fail closed and receive a durable rejection.
        return True
    return any(cmd_name.upper() not in READONLY_OPERATOR_COMMANDS
               for command, cmd_name, args, action_context in prepared)


def write_mutation_decision_command_receipt(decision, command_text, message_id):
    fields = build_mutation_decision_receipt(
        decision,
        command=command_text,
        source="external_operator",
        message_id=message_id,
    )
    return write_command_execution_log("command_result", **fields)


def record_mutation_terminal_result(receipt):
    try:
        return get_mutation_admission_journal().record_terminal(receipt)
    except Exception as error:
        append_runtime_feedback(
            "Mutation terminal reconciliation failed: "
            + summarize_runtime_text(str(error), max_chars=180)
        )
        return False


def append_external_message_record(
    text,
    source="manual",
    author="user",
    subject="",
    metadata=None,
    request_id=None,
    message_id=None,
    client_id=None,
):
    normalized_text = normalize_text_content(text).strip()
    if not normalized_text:
        return None

    ensure_external_bridge_files()
    payload_metadata = dict(metadata or {})
    raw = normalize_text_content(payload_metadata.get("ingest_mode", "")).strip().lower() == "raw"
    record = append_control_plane_request(
        script_directory,
        normalized_text,
        raw=raw,
        source=source,
        author=author,
        subject=subject,
        metadata=payload_metadata,
        request_id=request_id,
        message_id=message_id,
        client_id=client_id,
    )
    identity = extract_request_identity(record)
    write_external_bridge_log(
        "message_appended",
        source=source,
        message_id=identity["message_id"],
        request_id=identity["request_id"],
        client_id=identity["client_id"],
        subject=subject,
    )
    return record


def ingest_external_drop_file():
    ensure_external_bridge_files()
    try:
        with open(external_drop_path, "r", encoding="utf-8") as drop_file:
            drop_text = drop_file.read()
    except FileNotFoundError:
        return 0

    normalized_text = normalize_text_content(drop_text).strip()
    checksum = hashlib.sha1(normalized_text.encode("utf-8")).hexdigest() if normalized_text else ""
    if not normalized_text or checksum == external_bridge_state.get("last_drop_checksum", ""):
        return 0

    record = append_external_message_record(
        normalized_text,
        source="file_drop",
        author="user",
        subject=f"{EXTERNAL_OPERATOR_SUBJECT_PREFIX} file drop",
    )
    if not record:
        return 0

    external_bridge_state["last_drop_checksum"] = checksum
    with open(external_drop_path, "w", encoding="utf-8") as drop_file:
        drop_file.write("")
    save_external_bridge_state()
    write_external_bridge_log("drop_ingested", source="file_drop", message_id=record["message_id"])
    return 1


def poll_external_inbox_messages():
    ensure_external_bridge_files()
    offset = int(external_bridge_state.get("inbox_offset", 0) or 0)
    ingested_count = 0
    try:
        batch = read_jsonl_batch(
            external_inbox_path, offset,
            file_identity=external_bridge_state.get("inbox_file_identity", ""),
            discarding_record=external_bridge_state.get("inbox_discarding_record", False),
        )
    except OSError as error:
        append_runtime_feedback(f"External inbox temporarily unavailable: {type(error).__name__}")
        return 0

    if batch["reset"]:
        write_external_bridge_log("inbox_cursor_reset", source="external_inbox", previous_offset=offset)
    for entry in batch["entries"]:
        record = entry["record"]
        envelope_error = entry["error"] or validate_bridge_request(record)
        if envelope_error:
            identity = extract_request_identity(record)
            write_external_bridge_log(
                "message_rejected", source="external_inbox", **identity,
                delivery_status="rejected", reason=envelope_error,
                inbox_line_offset=entry["offset"],
            )
            continue

        text = normalize_text_content(record.get("text", "")).strip()
        if not text:
            continue

        identity = extract_request_identity(record)
        message_id = identity["message_id"]
        request_id = identity["request_id"]
        client_id = identity["client_id"]
        metadata = record.get("metadata") or {}
        ingest_mode = normalize_text_content(metadata.get("ingest_mode", "")).strip().lower()
        if (INPUT_RECOVERY_MODE != 'durable' and ingest_mode != "raw" and message_id
                and message_id == external_bridge_state.get("last_ingested_message_id", "")):
            continue

        source = normalize_text_content(record.get("source", "external")).strip() or "external"
        subject = normalize_text_content(record.get("subject", "")).strip()
        dispatched_as_command = False
        rejected_as_command = False
        duplicate_suppressed = False
        mutation_admission_status = ""
        mutation_admission_id = ""
        mutation_command_digest = ""
        command_delivery_status = ""
        if ingest_mode == "raw":
            try:
                prepared_commands = prepare_command_batch(text)
                allowed, rejection_reason = can_dispatch_external_raw_command(text, prepared_commands)
            except (CommandSyntaxError, ValueError) as error:
                prepared_commands = None
                allowed, rejection_reason = False, str(error)
            mutation_decision = None
            mutation_journal = None
            mutation_decision_handled = False
            if is_external_mutation_command(text, prepared_commands):
                try:
                    mutation_journal = get_mutation_admission_journal()
                    mutation_decision = mutation_journal.reserve(
                        text,
                        client_id=client_id,
                        request_id=request_id,
                        message_id=message_id,
                        command_name=get_command_name_key(text),
                        admitted=allowed,
                        reason=rejection_reason,
                    )
                    mutation_admission_status = mutation_decision.get("decision", "")
                    mutation_admission_id = mutation_decision.get("admission_id", "")
                    mutation_command_digest = mutation_decision.get("command_digest", "")
                except Exception as error:
                    allowed = False
                    mutation_admission_status = "journal_error"
                    rejection_reason = (
                        "Mutating external command rejected because its durable admission "
                        "record could not be written: "
                        + summarize_runtime_text(str(error), max_chars=160)
                    )

                decision_name = normalize_text_content(
                    (mutation_decision or {}).get("decision", "")
                ).strip()
                if decision_name in {
                    "duplicate_terminal",
                    "duplicate_uncertain",
                    "request_conflict",
                }:
                    duplicate_suppressed = True
                    rejected_as_command = decision_name == "request_conflict"
                    command_delivery_status = (
                        "rejected" if rejected_as_command else "duplicate_suppressed"
                    )
                    decision_receipt = write_mutation_decision_command_receipt(
                        mutation_decision,
                        text,
                        message_id,
                    )
                    bridge_event = (
                        "mutation_request_conflict"
                        if decision_name == "request_conflict"
                        else "mutation_duplicate_suppressed"
                    )
                    write_external_bridge_log(
                        bridge_event,
                        source=source,
                        message_id=message_id,
                        request_id=request_id,
                        client_id=client_id,
                        subject=subject,
                        ingest_mode="raw",
                        mutation_admission_id=mutation_admission_id,
                        admission_status=decision_name,
                        duplicate_suppressed=True,
                        replay_attempted=False,
                        terminal=decision_receipt.get("terminal", False),
                        delivery_status=command_delivery_status,
                        reason=decision_receipt.get("reason", ""),
                        preview=summarize_runtime_text(text, max_chars=120),
                    )
                    append_runtime_feedback(decision_receipt.get("reason", ""))
                    mutation_decision_handled = True

            if not mutation_decision_handled and allowed:
                enqueue_or_execute_command(
                    text,
                    is_user=True,
                    source="external_operator",
                    request_id=request_id,
                    message_id=message_id,
                    client_id=client_id,
                    mutation_admission_id=mutation_admission_id,
                    command_digest=mutation_command_digest,
                    prepared_commands=prepared_commands,
                )
                append_runtime_feedback(
                    "External operator command dispatched: "
                    + summarize_runtime_text(sanitize_sensitive_command_text(text), max_chars=96)
                )
                dispatched_as_command = True
                command_delivery_status = "delivered"
            elif not mutation_decision_handled:
                rejected_as_command = True
                command_delivery_status = "rejected"
                append_runtime_feedback(rejection_reason)
                write_external_bridge_log(
                    "message_rejected",
                    source=source,
                    message_id=message_id,
                    request_id=request_id,
                    client_id=client_id,
                    subject=subject,
                    ingest_mode="raw",
                    delivery_status="rejected",
                    mutation_admission_schema_version=(
                        MUTATION_ADMISSION_SCHEMA_VERSION
                        if mutation_admission_status
                        else ""
                    ),
                    mutation_admission_id=mutation_admission_id,
                    admission_status=mutation_admission_status,
                    command_digest=mutation_command_digest,
                    replay_attempted=False,
                    reason=rejection_reason,
                    preview=summarize_runtime_text(text, max_chars=120),
                )
                rejection_receipt = write_command_execution_log(
                    "command_result",
                    receipt_schema_version=COMMAND_RECEIPT_SCHEMA_VERSION,
                    receipt_id=f"receipt-{request_id}" if request_id else "",
                    request_id=request_id,
                    message_id=message_id,
                    client_id=client_id,
                    command=text,
                    source="external_operator",
                    status="rejected",
                    outcome_status="rejected",
                    delivery_status="rejected",
                    terminal=True,
                    mutation_admission_schema_version=(
                        MUTATION_ADMISSION_SCHEMA_VERSION
                        if mutation_admission_status
                        else ""
                    ),
                    mutation_admission_id=mutation_admission_id,
                    admission_status=mutation_admission_status,
                    command_digest=mutation_command_digest,
                    duplicate_suppressed=False,
                    replay_attempted=False,
                    replayed=False,
                    is_user=True,
                    reason=rejection_reason,
                    expanded_commands=[],
                    executed_commands=[],
                    failed_commands=[{"command": text, "reason": rejection_reason}],
                )
                if mutation_decision is not None:
                    record_mutation_terminal_result(rejection_receipt)
        else:
            if ingest_mode == "raw":
                queued_text = text
            elif normalize_text_content(metadata.get("surface", "")).strip().lower() == "chat_head":
                queued_text = text
            else:
                queued_text = f"External reply via {source}: {text}"
            try:
                newly_queued = queue_recoverable_input(queued_text, {
                    "request_id": request_id, "message_id": message_id, "client_id": client_id,
                })
                if not newly_queued:
                    duplicate_suppressed = True
                    command_delivery_status = 'recovery_retained'
            except ValueError as error:
                # Reject an invalid/full admission explicitly; don't poison later
                # input/control records. I/O failures still retain the unread cursor.
                command_delivery_status = 'rejected'
                write_external_bridge_log('message_rejected', source=source, **identity,
                    delivery_status='rejected', reason=str(error), replay_attempted=False)
        touch_last_interaction()
        external_bridge_state["last_ingested_message_id"] = message_id
        external_bridge_state["last_ingested_request_id"] = request_id
        external_bridge_state["last_ingested_client_id"] = client_id
        ingested_count += 1
        write_external_bridge_log(
            "message_ingested",
            source=source,
            message_id=message_id,
            request_id=request_id,
            client_id=client_id,
            subject=subject,
            ingest_mode=ingest_mode or "normal",
            dispatched_as_command=dispatched_as_command,
            rejected_as_command=rejected_as_command,
            mutation_admission_schema_version=(
                MUTATION_ADMISSION_SCHEMA_VERSION
                if mutation_admission_status
                else ""
            ),
            mutation_admission_id=mutation_admission_id,
            admission_status=mutation_admission_status,
            command_digest=mutation_command_digest,
            duplicate_suppressed=duplicate_suppressed,
            replay_attempted=False,
            delivery_status=command_delivery_status or (
                "rejected"
                if rejected_as_command
                else "delivered"
                if dispatched_as_command
                else "routed_as_input"
            ),
            preview=summarize_runtime_text(text, max_chars=120),
        )

    cursor_changed = (
        offset != batch["next_offset"]
        or external_bridge_state.get("inbox_file_identity", "") != batch["file_identity"]
        or external_bridge_state.get("inbox_discarding_record", False) != batch["discarding_record"]
    )
    external_bridge_state.update(
        inbox_offset=batch["next_offset"], inbox_file_identity=batch["file_identity"],
        inbox_discarding_record=batch["discarding_record"],
    )
    if cursor_changed or ingested_count or external_bridge_state.get("inbox_cursor_save_pending"):
        external_bridge_state["inbox_cursor_save_pending"] = True
        try:
            save_external_bridge_state()
        except OSError as error:
            append_runtime_feedback(f"External inbox cursor save will be retried: {type(error).__name__}")
        else:
            external_bridge_state.pop("inbox_cursor_save_pending", None)
    if ingested_count:
        append_runtime_feedback(f"Ingested {ingested_count} external operator message(s).")
    return ingested_count


def poll_external_reply_bridges():
    if not ENABLE_EXTERNAL_REPLY_BRIDGE:
        return 0
    ingested_drop = ingest_external_drop_file()
    ingested_inbox = poll_external_inbox_messages()
    return ingested_drop + ingested_inbox


def cleanup_queue_resource(queue_obj):
    if queue_obj is None:
        return
    close = getattr(queue_obj, "close", None)
    if callable(close):
        try:
            close()
        except Exception:
            pass
    join_thread = getattr(queue_obj, "join_thread", None)
    if callable(join_thread):
        try:
            join_thread()
        except Exception:
            pass


def drain_queue_latest(queue_obj):
    latest_item = None
    dropped_count = 0
    while True:
        try:
            item = queue_obj.get_nowait()
        except queue.Empty:
            break
        latest_item = item
        dropped_count += 1
    return latest_item, max(0, dropped_count - 1)


def replace_queue_latest(queue_obj, item):
    dropped_count = 0
    while True:
        try:
            queue_obj.get_nowait()
            dropped_count += 1
        except queue.Empty:
            break
    queue_obj.put(item)
    return dropped_count


