ctypes.windll.user32.BringWindowToTop.restype = wintypes.BOOL
ctypes.windll.user32.ShowWindow.argtypes = [wintypes.HWND, ctypes.c_int]
ctypes.windll.user32.ShowWindow.restype = wintypes.BOOL
ctypes.windll.user32.SetFocus.argtypes = [wintypes.HWND]
ctypes.windll.user32.SetFocus.restype = wintypes.HWND
