ctypes.windll.user32.GetWindowThreadProcessId.restype = wintypes.DWORD
ctypes.windll.user32.AttachThreadInput.argtypes = [wintypes.DWORD, wintypes.DWORD, wintypes.BOOL]
ctypes.windll.user32.AttachThreadInput.restype = wintypes.BOOL
