SW_RESTORE = 9
SW_SHOW = 5


def get_window_text(hwnd):
    if not hwnd:
        return ""
    length = ctypes.windll.user32.GetWindowTextLengthW(hwnd)
    if length <= 0:
        return ""
    buffer = ctypes.create_unicode_buffer(length + 1)
    ctypes.windll.user32.GetWindowTextW(hwnd, buffer, len(buffer))
    return buffer.value


def window_title_matches(title, title_hint=None):
    title = normalize_text_content(title).strip().lower()
    title_hint = normalize_text_content(title_hint or EMULATOR_WINDOW_TITLE_HINT).strip().lower()
    if not title or not title_hint:
        return False
    return title_hint in title


def get_foreground_window_title():
    hwnd = ctypes.windll.user32.GetForegroundWindow()
    title = get_window_text(hwnd)
    if title:
        set_runtime_value("last_foreground_window", title)
    return title


def find_window_handle_by_title(title_hint):
    title_hint = normalize_text_content(title_hint).strip().lower()
    if not title_hint:
        return None

    matches = []

    @EnumWindowsProc
    def enum_windows_proc(hwnd, lparam):
        if not ctypes.windll.user32.IsWindowVisible(hwnd):
            return True
        title = get_window_text(hwnd)
        if title and title_hint in title.lower():
            matches.append((hwnd, title))
        return True

    ctypes.windll.user32.EnumWindows(enum_windows_proc, 0)
    if not matches:
        return None
    matches.sort(key=lambda item: len(item[1]))
    return matches[0][0]


def get_window_client_center(title_hint=None):
    title_hint = normalize_text_content(title_hint or EMULATOR_WINDOW_TITLE_HINT).strip()
    hwnd = find_window_handle_by_title(title_hint)
    if not hwnd:
        return {"x": None, "y": None, "reason": f"no window matched '{title_hint}'", "hwnd": 0}

    client_rect = wintypes.RECT()
    origin = wintypes.POINT(0, 0)
    if not ctypes.windll.user32.GetClientRect(hwnd, ctypes.byref(client_rect)):
        return {"x": None, "y": None, "reason": "GetClientRect failed", "hwnd": int(hwnd)}
    if not ctypes.windll.user32.ClientToScreen(hwnd, ctypes.byref(origin)):
        return {"x": None, "y": None, "reason": "ClientToScreen failed", "hwnd": int(hwnd)}

    width = max(1, int(client_rect.right - client_rect.left))
    height = max(1, int(client_rect.bottom - client_rect.top))
    return {
        "x": int(origin.x + width // 2),
        "y": int(origin.y + height // 2),
        "width": width,
        "height": height,
        "reason": "window-client-center",
        "hwnd": int(hwnd),
    }


def focus_game_input_target(title_hint=None):
    title_hint = normalize_text_content(title_hint or EMULATOR_WINDOW_TITLE_HINT).strip()
    focus_result = focus_window_by_title(title_hint)
    if not focus_result.get("success") or not GAME_CLIENT_CLICK_TO_FOCUS:
        return focus_result

    center = get_window_client_center(title_hint)
    center_x = center.get("x")
    center_y = center.get("y")
    if center_x is None or center_y is None:
        return focus_result

    try:
        pyautogui.moveTo(int(center_x), int(center_y), duration=0.03)
        pyautogui.click(int(center_x), int(center_y))
        set_runtime_value("last_foreground_window", get_foreground_window_title())
        append_runtime_feedback(f"Clicked emulator client center at ({center_x}, {center_y}) to restore gameplay focus.")
        focus_result["clicked_client_center"] = True
    except Exception as exc:
        focus_result["clicked_client_center"] = False
        focus_result["click_reason"] = str(exc)
    return focus_result


def dismiss_game_input_menu(title_hint=None, presses=2):
    title_hint = normalize_text_content(title_hint or EMULATOR_WINDOW_TITLE_HINT).strip()
    focus_result = focus_window_by_title(title_hint)
    result = {
        "success": bool(focus_result.get("success")),
        "reason": normalize_text_content(focus_result.get("reason", "")).strip(),
        "title": normalize_text_content(focus_result.get("title", "")).strip(),
        "hwnd": int(focus_result.get("hwnd", 0) or 0),
        "escape_presses": 0,
    }
    if not focus_result.get("success"):
        return result

    escape_presses = max(1, int(presses or 1))
    try:
        for _ in range(escape_presses):
            keyboard.press_and_release("esc")
            time.sleep(0.08)
        result["success"] = True
        result["reason"] = f"sent esc x{escape_presses}"
        result["escape_presses"] = escape_presses
        set_last_key_value("esc")
        set_runtime_value("last_input_backend", "keyboard-recovery")
        set_runtime_value("last_foreground_window", get_foreground_window_title())
        append_runtime_feedback(f"Sent ESC x{escape_presses} to dismiss a stray emulator menu or dropdown.")
    except Exception as exc:
        result["success"] = False
        result["reason"] = str(exc)
    return result


def recover_game_input_target(title_hint=None, observation_text="", recovery_triggers=None):
    title_hint = normalize_text_content(title_hint or EMULATOR_WINDOW_TITLE_HINT).strip()
    observation_text = normalize_text_content(observation_text).strip().lower()
    recovery_triggers = [normalize_text_content(item).strip().lower() for item in (recovery_triggers or []) if normalize_text_content(item).strip()]
    combined_text = " | ".join(item for item in [observation_text, ",".join(recovery_triggers)] if item)
    menu_suspected = any(hint in combined_text for hint in ("dropdown", "menu open", "menu", "menubar"))

    focus_result = focus_game_input_target(title_hint)
    recovery_steps = [
        f"focus={'ok' if focus_result.get('success') else 'fail'}:{normalize_text_content(focus_result.get('reason', 'ok')).strip() or 'ok'}"
    ]
    final_result = dict(focus_result)
    final_result["menu_dismissed"] = False
    final_result["escape_presses"] = 0

    if menu_suspected:
        dismiss_result = dismiss_game_input_menu(title_hint, presses=2)
        recovery_steps.append(
            f"esc={'ok' if dismiss_result.get('success') else 'fail'}:{normalize_text_content(dismiss_result.get('reason', 'ok')).strip() or 'ok'}"
        )
        final_result["menu_dismissed"] = bool(dismiss_result.get("success"))
        final_result["escape_presses"] = int(dismiss_result.get("escape_presses", 0) or 0)
        time.sleep(0.10)
        refocus_result = focus_game_input_target(title_hint)
        recovery_steps.append(
            f"refocus={'ok' if refocus_result.get('success') else 'fail'}:{normalize_text_content(refocus_result.get('reason', 'ok')).strip() or 'ok'}"
        )
        if refocus_result:
            final_result.update(refocus_result)

    final_result["recovery_steps"] = "; ".join(recovery_steps)
    final_result["menu_suspected"] = menu_suspected
    return final_result


def focus_window_by_title(title_hint=None):
    title_hint = normalize_text_content(title_hint or EMULATOR_WINDOW_TITLE_HINT).strip()
    if not title_hint:
        return {"success": False, "reason": "missing window title hint", "title": "", "hwnd": 0}

    hwnd = find_window_handle_by_title(title_hint)
    if not hwnd:
        return {"success": False, "reason": f"no visible window matched '{title_hint}'", "title": "", "hwnd": 0}

    current_thread_id = ctypes.windll.kernel32.GetCurrentThreadId()
    foreground_hwnd = ctypes.windll.user32.GetForegroundWindow()
    target_pid = wintypes.DWORD()
    target_thread_id = ctypes.windll.user32.GetWindowThreadProcessId(hwnd, ctypes.byref(target_pid))
    foreground_pid = wintypes.DWORD()
    foreground_thread_id = 0
    if foreground_hwnd:
        foreground_thread_id = ctypes.windll.user32.GetWindowThreadProcessId(foreground_hwnd, ctypes.byref(foreground_pid))

    attached_target = False
    attached_foreground = False
    try:
        if target_thread_id and target_thread_id != current_thread_id:
            attached_target = bool(ctypes.windll.user32.AttachThreadInput(current_thread_id, target_thread_id, True))
        if foreground_thread_id and foreground_thread_id != current_thread_id and foreground_thread_id != target_thread_id:
            attached_foreground = bool(ctypes.windll.user32.AttachThreadInput(current_thread_id, foreground_thread_id, True))

        if ctypes.windll.user32.IsIconic(hwnd):
            ctypes.windll.user32.ShowWindow(hwnd, SW_RESTORE)
        else:
            ctypes.windll.user32.ShowWindow(hwnd, SW_SHOW)

        ctypes.windll.user32.BringWindowToTop(hwnd)
        ctypes.windll.user32.SetActiveWindow(hwnd)
        ctypes.windll.user32.SetForegroundWindow(hwnd)
        ctypes.windll.user32.SetFocus(hwnd)
        time.sleep(0.06)

        active_title = get_foreground_window_title()
        if not window_title_matches(active_title, title_hint):
            try:
                keyboard.press_and_release("alt")
                time.sleep(0.04)
                ctypes.windll.user32.BringWindowToTop(hwnd)
                ctypes.windll.user32.SetForegroundWindow(hwnd)
                ctypes.windll.user32.SetFocus(hwnd)
                time.sleep(0.06)
                active_title = get_foreground_window_title()
            except Exception:
                pass
    finally:
        if attached_target:
            ctypes.windll.user32.AttachThreadInput(current_thread_id, target_thread_id, False)
        if attached_foreground:
            ctypes.windll.user32.AttachThreadInput(current_thread_id, foreground_thread_id, False)

    active_title = get_foreground_window_title()
    success = window_title_matches(active_title, title_hint)
    result = {
        "success": success,
        "reason": "" if success else f"foreground window is '{active_title or 'unknown'}'",
        "title": active_title,
        "hwnd": int(hwnd),
    }
    set_runtime_value("last_foreground_window", active_title)
    if success:
        append_runtime_feedback(f"Focused window: {active_title}")
    else:
        append_runtime_feedback(f"Window focus failed for {title_hint}: {result['reason']}")
    return result


def maybe_run_game_focus_recovery(section_items=None, narrative_text=""):
    operating_context = normalize_text_content(runtime_state.get("operating_context", "")).strip().lower() or "unknown"
    if operating_context != "game":
        return None

    now = time.time()
    last_recovery_epoch = float(runtime_state.get("last_game_focus_recovery_at_epoch", 0.0) or 0.0)
    if last_recovery_epoch and (now - last_recovery_epoch) < GAMEPLAY_FOCUS_RECOVERY_COOLDOWN_SECONDS:
        return None

    recent_game_actions = []
    stalled_game_actions = []
    for entry in list(get_recent_executed_actions_store()[-4:]):
        family_key = normalize_text_content(entry.get("family_key", "")).strip().lower()
        if not family_key.startswith("game-"):
            continue
        recent_game_actions.append(entry)
        if entry.get("outcome_status") in {"likely_failed", "no_visible_change"}:
            stalled_game_actions.append(entry)

    visibility_info = refresh_gameplay_visibility_state()
    observation_text = build_outcome_observation_text(section_items, narrative_text).lower()
    recovery_triggers = []
    if visibility_info.get("visibility") == "obstructed":
        recovery_triggers.append("visibility_obstructed")
    if len(stalled_game_actions) >= GAMEPLAY_FOCUS_RECOVERY_FAILURE_THRESHOLD:
        recovery_triggers.append(f"stalled_game_actions={len(stalled_game_actions)}")
    if any(hint in observation_text for hint in GAMEPLAY_OBSTRUCTION_TEXT_HINTS):
        recovery_triggers.append("obstruction_text")
    last_input_attempt_at = float(runtime_state.get("last_game_input_attempt_at_epoch", 0.0) or 0.0)
    if last_input_attempt_at and (now - last_input_attempt_at) <= 45.0 and not bool(runtime_state.get("last_game_input_focus_ok", False)):
        recovery_triggers.append("recent_game_input_focus_failed")
    last_input_focus_reason = normalize_text_content(runtime_state.get("last_game_input_focus_reason", "")).strip().lower()
    if any(hint in last_input_focus_reason for hint in ("focus", "foreground", "window")):
        recovery_triggers.append("last_input_focus_reason")
    if not recent_game_actions:
        return None
    if not recovery_triggers:
        return None

    focus_result = recover_game_input_target(
        EMULATOR_WINDOW_TITLE_HINT,
        observation_text=observation_text,
        recovery_triggers=recovery_triggers,
    )
    recovery_summary = record_focus_recovery_result(",".join(recovery_triggers), focus_result)
    append_runtime_feedback(f"Gameplay focus recovery attempted: {recovery_summary}")
    write_command_execution_log(
        "focus_recovery",
        command=f"recover_game_input_target({EMULATOR_WINDOW_TITLE_HINT})",
        source="runtime_hook",
        status="success" if focus_result.get("success") else "failed",
        trigger=",".join(recovery_triggers),
        note=recovery_summary,
        foreground_window=runtime_state.get("last_foreground_window", ""),
        gameplay_visibility=runtime_state.get("gameplay_visibility", ""),
        gameplay_visibility_reason=runtime_state.get("gameplay_visibility_reason", ""),
        recovery_steps=focus_result.get("recovery_steps", ""),
        menu_suspected=bool(focus_result.get("menu_suspected", False)),
        menu_dismissed=bool(focus_result.get("menu_dismissed", False)),
        escape_presses=int(focus_result.get("escape_presses", 0) or 0),
    )
    return focus_result


def should_use_game_input_backend(key):
    key = normalize_text_content(key).strip().lower()
    context = current_desktop_action_context()
    if context is not None:
        return context.namespace == "gb"
    if GAME_INPUT_BACKEND == "pyautogui":
        return False
    foreground_title = get_foreground_window_title()
    if window_title_matches(foreground_title, EMULATOR_WINDOW_TITLE_HINT):
        return True
    current_context = normalize_text_content(runtime_state.get("operating_context", "")).strip().lower()
    return current_context == "game" and key in GAME_NAVIGATION_KEYS


def translate_game_backend_key(key):
    normalized_key = normalize_text_content(key).strip().lower()
    context = current_desktop_action_context()
    if context is not None and context.requested_key == normalized_key:
        return context.effective_key
    if normalized_key in GAME_CONTROL_KEY_TRANSLATIONS:
        return GAME_CONTROL_KEY_TRANSLATIONS[normalized_key]
    if normalized_key in GAME_DIRECTION_KEY_TRANSLATIONS:
        return GAME_DIRECTION_KEY_TRANSLATIONS[normalized_key]
    return normalized_key


def is_valid_keyboard_key_token(key):
    normalized_key = normalize_text_content(key).strip().lower()
    translated_key = translate_game_backend_key(normalized_key)
    return normalized_key in pyautogui.KEYBOARD_KEYS or translated_key in pyautogui.KEYBOARD_KEYS


GAME_INPUT_SCANCODES = {
    "escape": 0x01,
    "esc": 0x01,
    "1": 0x02,
    "2": 0x03,
    "3": 0x04,
    "4": 0x05,
    "5": 0x06,
    "6": 0x07,
    "7": 0x08,
    "8": 0x09,
    "9": 0x0A,
    "0": 0x0B,
    "backspace": 0x0E,
    "tab": 0x0F,
    "q": 0x10,
    "w": 0x11,
    "e": 0x12,
    "r": 0x13,
    "t": 0x14,
    "y": 0x15,
    "u": 0x16,
    "i": 0x17,
    "o": 0x18,
    "p": 0x19,
    "enter": 0x1C,
    "return": 0x1C,
    "a": 0x1E,
    "s": 0x1F,
    "d": 0x20,
    "f": 0x21,
    "g": 0x22,
    "h": 0x23,
    "j": 0x24,
    "k": 0x25,
    "l": 0x26,
    "z": 0x2C,
    "x": 0x2D,
    "c": 0x2E,
    "v": 0x2F,
    "b": 0x30,
    "n": 0x31,
    "m": 0x32,
    "space": 0x39,
    "up": 0x48,
    "left": 0x4B,
    "right": 0x4D,
    "down": 0x50,
}
GAME_INPUT_EXTENDED_SCANCODE_KEYS = {"up", "down", "left", "right"}


if os.name == "nt":
    ULONG_PTR = ctypes.POINTER(ctypes.c_ulong)

    class SendInputKeyBdInput(ctypes.Structure):
        _fields_ = [
            ("wVk", ctypes.c_ushort),
            ("wScan", ctypes.c_ushort),
            ("dwFlags", ctypes.c_ulong),
            ("time", ctypes.c_ulong),
            ("dwExtraInfo", ULONG_PTR),
        ]

    class SendInputMouseInput(ctypes.Structure):
        _fields_ = [
            ("dx", ctypes.c_long),
            ("dy", ctypes.c_long),
            ("mouseData", ctypes.c_ulong),
            ("dwFlags", ctypes.c_ulong),
            ("time", ctypes.c_ulong),
            ("dwExtraInfo", ULONG_PTR),
        ]

    class SendInputHardwareInput(ctypes.Structure):
        _fields_ = [
            ("uMsg", ctypes.c_ulong),
            ("wParamL", ctypes.c_short),
            ("wParamH", ctypes.c_ushort),
        ]

    class SendInputUnion(ctypes.Union):
        _fields_ = [
            ("ki", SendInputKeyBdInput),
            ("mi", SendInputMouseInput),
            ("hi", SendInputHardwareInput),
        ]

    class SendInputInput(ctypes.Structure):
        _fields_ = [
            ("type", ctypes.c_ulong),
            ("union", SendInputUnion),
        ]


def send_scancode_key_event(key, is_key_up=False, *, scan_code=None, extended=None):
    if os.name != "nt":
        raise RuntimeError("scan-code game input is only available on Windows")
    normalized_key = normalize_text_content(key).strip().lower()
    if scan_code is None:
        scan_code = GAME_INPUT_SCANCODES.get(normalized_key)
    if scan_code is None:
        raise ValueError(f"no scan-code mapping for key: {key}")
    keyeventf_extendedkey = 0x0001
    keyeventf_keyup = 0x0002
    keyeventf_scancode = 0x0008
    flags = keyeventf_scancode
    is_extended = extended if extended is not None else normalized_key in GAME_INPUT_EXTENDED_SCANCODE_KEYS
    if is_extended:
        flags |= keyeventf_extendedkey
    if is_key_up:
        flags |= keyeventf_keyup
    extra = ctypes.c_ulong(0)
    event = SendInputInput(
        type=1,
        union=SendInputUnion(
            ki=SendInputKeyBdInput(
                0,
                scan_code,
                flags,
                0,
                ctypes.pointer(extra),
            )
        ),
    )
    sent = ctypes.windll.user32.SendInput(1, ctypes.byref(event), ctypes.sizeof(SendInputInput))
    if sent != 1:
        raise ctypes.WinError(ctypes.get_last_error())


def send_scancode_backend_press(key, presses=1, interval=0.0, hold_seconds=0.0):
    token = COMMAND_WORK.current()
    for press_index in range(presses):
        lease = acquire_key_input(key, "scancode", namespace="gb")
        try:
            token.wait(hold_seconds if hold_seconds > 0 else 0.08)
        finally:
            release_input_leases([lease])
        if interval > 0 and press_index < presses - 1:
            token.wait(interval)


def send_keyboard_backend_press(key, presses=1, interval=0.0, hold_seconds=0.0):
    token = COMMAND_WORK.current()
    for press_index in range(presses):
        lease = acquire_key_input(key, "keyboard", namespace="gb")
        try:
            token.wait(hold_seconds if hold_seconds > 0 else 0.0)
        finally:
            release_input_leases([lease])
        if interval > 0 and press_index < presses - 1:
            token.wait(interval)


def get_game_input_backend():
    context = current_desktop_action_context()
    return context.backend if context is not None and context.namespace == "gb" else GAME_INPUT_BACKEND


def send_pyautogui_game_press(key, presses=1, interval=0.0, hold_seconds=0.0):
    token = COMMAND_WORK.current()
    for press_index in range(presses):
        lease = acquire_key_input(key, "pyautogui", namespace="gb")
        try:
            token.wait(hold_seconds if hold_seconds > 0 else 0.08)
        finally:
            release_input_leases([lease])
        if interval > 0 and press_index < presses - 1:
            token.wait(interval)


def game_backend_press(key, presses=1, interval=0.0, hold_seconds=0.0):
    backend = get_game_input_backend()
    if backend == "scancode":
        send_scancode_backend_press(key, presses=presses, interval=interval, hold_seconds=hold_seconds)
        return "scancode"
    if backend == "pyautogui":
        send_pyautogui_game_press(key, presses=presses, interval=interval, hold_seconds=hold_seconds)
        return "pyautogui"
    send_keyboard_backend_press(key, presses=presses, interval=interval, hold_seconds=hold_seconds)
    return "keyboard"


def game_backend_key_down(key):
    backend = get_game_input_backend()
    acquire_key_input(key, backend, namespace="gb", persistent=True)
    return backend


def game_backend_key_up(key):
    context = current_desktop_action_context()
    requested = context.requested_key if context and context.namespace == "gb" else key
    result = release_owned_key(requested, namespace="gb")
    return result["results"][0]["route"]["backend"]


