def get_chat_history_store():
    return agent_state.chat_history


def get_pending_command_store():
    return agent_state.pending_model_commands




def get_pending_command_snapshot():
    with PENDING_COMMAND_LEDGER.lock:
        entries = PENDING_COMMAND_LEDGER.snapshot(get_pending_command_store())
        return {"version": pending_queue_version(entries), "count": len(entries), "entries": entries}


def evaluate_pending_command_policy(command, prepared=None):
    """The most restrictive member governs a proposed/automatic command batch."""
    prepared = prepare_command_batch(command) if prepared is None else prepared
    policies = []
    for text, name, args, route in prepared:
        if route is not None and not text.lower().startswith(("gb:", "pyag:")):
            text = route.namespace.upper() + ":" + text
        policies.append(evaluate_assistant_command_policy(text))
    rank = {"allow": 0, "hold": 1, "reject": 2}
    policy = dict(max(policies, key=lambda item: rank.get(item.get("decision", "hold"), 1)))
    policy["risk"] = max((item.get("risk", "medium") for item in policies),
                         key=lambda risk: {"low": 0, "medium": 1, "high": 2}.get(risk, 2))
    if len({item.get("category", "other") for item in policies}) != 1:
        policy["category"] = "other"
    policy["one_turn_reasoning"] = len(policies) == 1 and policy.get("one_turn_reasoning", False)
    return policy


def prepare_pending_entry(entry):
    prepared = entry.get("_prepared_commands")
    if prepared is None:
        return prepare_command_batch(entry.get("command", ""))
    for text, name, args, route in prepared:
        if not name.startswith("pyag:") and name.upper() not in command_dispatch:
            raise ValueError(f"Queued command is no longer available: {name}")
        validate_command_arguments(name, args)
    return prepared


def record_pending_command_result(result):
    """Keep receipts even if optional feedback/log publication fails."""
    public = {key: value for key, value in result.items() if not key.startswith("_")}
    runtime_state["last_pending_command_result"] = copy.deepcopy(public)
    try:
        write_command_execution_log("pending_transition", **public)
    except Exception as error:
        result.setdefault("warnings", []).append(f"Pending transition log publication failed: {error}")
    return result


def submit_pending_entry(entry, token, automatic=False):
    try:
        token.check()
        MODEL_WORK.current().check()
        COMMAND_WORK.token(token.generation).check()
    except WorkCancelled as error:
        return {"status": "not_started", "reason": str(error), "cancelled": True}
    try:
        submitted = enqueue_or_execute_command(
            entry.get("command", ""), is_user=False,
            associated_goal=entry.get("associated_goal", "No specific goal"),
            why=f"{entry.get('reason', '')} | expected={entry.get('expected_outcome', 'state should change')}",
            source=("auto-threshold:" if automatic else "approved:") + entry.get("source", "assistant"),
            expected_outcome=entry.get("expected_outcome", ""), family_key=entry.get("family_key", ""),
            conflict_key=entry.get("conflict_key", ""), semantic_label=entry.get("semantic_label", ""),
            execution_operating_context=entry.get("operating_context", "unknown"),
            prepared_commands=entry["_prepared_commands"], command_generation=token.generation,
            history_actor=entry.get("history_actor", "unknown"),
            pending_id=entry["pending_id"], pending_attempt_id=entry["pending_attempt_id"])
        status = submitted.get("submission_status", "uncertain")
        return {"status": status, "reason": "" if status in {"queued", "completed"} else "Inspect the correlated command execution receipt.",
                "command_generation": token.generation, "cancelled": status == "cancelled"}
    except Exception as error:
        # A queue put or direct dispatch may already have happened. Never replay.
        return {"status": "uncertain", "reason": str(error), "cancelled": isinstance(error, WorkCancelled)}


def execute_pending_approval(args, automatic=False, operator=False):
    token = COMMAND_WORK.current()
    store = get_pending_command_store()
    with PENDING_COMMAND_LEDGER.lock:
        before = PENDING_COMMAND_LEDGER.snapshot(store)
        try:
            token.check()
            indexes = _resolve_pending_indexes(args)
            if automatic:
                indexes = [index for index in indexes if is_pending_entry_auto_approvable(store[index])[0]]
            reserved = PENDING_COMMAND_LEDGER.reserve(store, indexes, prepare=prepare_pending_entry, check=token.check,
                                                      allow_task_held=operator and not automatic)
        except Exception as error:
            return record_pending_command_result(pending_result(
                "auto_approve" if automatic else "approve", before, PENDING_COMMAND_LEDGER.snapshot(store),
                success=False, effect_status="not_started", reason=str(error), cancelled=isinstance(error, WorkCancelled),
                submissions=[]))
    outcomes, accepted, warnings = [], [], []
    stopped = False
    for entry in reserved:
        outcome = ({"status": "not_started", "reason": "An earlier selected submission failed or was cancelled."}
                   if stopped else submit_pending_entry(entry, token, automatic))
        outcome = PENDING_COMMAND_LEDGER.finish(store, entry, outcome)
        outcomes.append(outcome)
        status = outcome["status"]
        if status in {"queued", "completed", "failed", "cancelled"}:
            accepted.append(entry)
            try:
                append_recent_command_proposal(
                    entry.get("command", ""), source=entry.get("source", "assistant"),
                    associated_goal=entry.get("associated_goal", "No specific goal"),
                    disposition="auto_submitted" if automatic else "submitted",
                    support_count=entry.get("support_count", 1), execute_by_inference=entry.get("execute_by_inference"))
                append_recent_action_intent(
                    f"Submitted pending command: {entry.get('command', '')}", status="submitted",
                    command=entry.get("command", ""), source=entry.get("source", "assistant"),
                    associated_goal=entry.get("associated_goal", "No specific goal"))
            except Exception as error:
                warnings.append(f"Submission accepted; optional feedback failed: {error}")
        if status not in {"queued", "completed"}:
            stopped = True
    after = PENDING_COMMAND_LEDGER.snapshot(store)
    result = pending_result(
        "auto_approve" if automatic else "approve", before, after, success=not stopped,
        effect_status=("uncertain" if any(row["status"] == "uncertain" for row in outcomes) else
                       "submitted" if accepted else "not_started" if stopped else "observed"),
        reason="Inspect submissions; later unstarted items remain held." if stopped else "",
        submissions=outcomes, accepted_count=len(accepted),
        cancelled=any(row.get("cancelled") for row in outcomes), warnings=warnings)
    record_pending_command_result(result)
    if outcomes:
        display_message("system" if result["success"] else "error",
                        f"Pending approval: {len(accepted)} submitted; {len(outcomes) - len(accepted)} retained. "
                        "Submission is separate from execution; inspect correlated receipts.")
    if automatic:
        result["_accepted_entries"] = accepted
    return result


def infer_pending_queue_directive(command_text):
    # Keep the authored namespace until prepare_command_batch freezes its route.
    # Canonical GB syntax uses the PYAG dispatcher internally; normalizing here
    # would turn explicit game controls into literal desktop input on admission.
    cleaned = normalize_text_content(command_text).strip()
    command_name = get_command_name(cleaned).upper()
    queue_mode = PENDING_WRAPPER_MODES.get(command_name)
    if not queue_mode:
        return {"command": cleaned, "queue_mode": None, "directive": ""}
    args = extract_command_arguments(cleaned)
    validate_pending_arguments(command_name, args)
    return {"command": normalize_text_content(args[0]).strip(), "queue_mode": queue_mode, "directive": command_name}


def score_pending_entry(entry, current_turn=None):
    current_turn = agent_state.inference_counter if current_turn is None else int(current_turn)
    support_count = max(1, int(entry.get("support_count", 1) or 1))
    repeat_count = max(1, int(entry.get("repeat_count", 1) or 1))
    turns_until_due = entry.get("turns_until_due")
    queue_mode = normalize_pending_queue_mode(entry.get("queue_mode", DEFAULT_PENDING_QUEUE_MODE), fallback=DEFAULT_PENDING_QUEUE_MODE)
    due_bonus = 0
    if isinstance(turns_until_due, int):
        if turns_until_due <= 0:
            due_bonus = 5
        elif turns_until_due == 1:
            due_bonus = 4
        elif turns_until_due == 2:
            due_bonus = 3
        else:
            due_bonus = max(1, 4 - min(turns_until_due, 3))
    queue_bonus = {"replace": 3, "insert": 2, "normal": 0}.get(queue_mode, 0)
    category_bonus = {
        "memory": 2,
        "runtime": 1,
        "desktop_action": 1,
        "persistence": 0,
        "other": 0,
    }.get(normalize_memory_item(entry.get("category", "other")).lower(), 0)
    associated_goal = normalize_memory_item(entry.get("associated_goal", "")).strip()
    goal_bonus = 2 if associated_goal and associated_goal.lower() != "no specific goal" else 0
    source_bonus = 2 if normalize_memory_item(entry.get("source", "")).strip().lower().startswith("operator") else 0
    expected_bonus = 1 if normalize_memory_item(entry.get("expected_outcome", "")).strip() else 0
    priority_score = max(1, min(12, support_count + due_bonus + queue_bonus))
    importance_score = max(1, min(12, category_bonus + goal_bonus + source_bonus + expected_bonus + min(repeat_count, 2)))
    return {
        "priority_score": priority_score,
        "importance_score": importance_score,
        "queue_mode": queue_mode,
    }


def apply_pending_entry_scores(entry, current_turn=None):
    if not isinstance(entry, dict):
        return entry
    scores = score_pending_entry(entry, current_turn=current_turn)
    entry["priority_score"] = scores["priority_score"]
    entry["importance_score"] = scores["importance_score"]
    entry["queue_mode"] = scores["queue_mode"]
    return entry


def _mark_pending_entry_shifted(entry, new_command, source, associated_goal, inserted_target_turn):
    append_recent_command_proposal(
        entry.get("command", ""),
        source=entry.get("source", source),
        associated_goal=entry.get("associated_goal", associated_goal),
        disposition="deferred",
        support_count=entry.get("support_count", 1),
        execute_by_inference=entry.get("execute_by_inference"),
    )
    append_recent_action_intent(
        f"Deferred pending command: {entry.get('command', '')}",
        status="deferred",
        command=entry.get("command", ""),
        source=source,
        associated_goal=associated_goal,
        execute_by_inference=entry.get("execute_by_inference"),
    )
    append_command_drip_item(
        agent_state.inference_counter,
        "deferred",
        build_command_drip_item(
            command=entry.get("command", ""),
            status="deferred",
            reason=f"shifted back by inserted {new_command}",
            category=entry.get("category", ""),
            risk=entry.get("risk", ""),
            associated_goal=entry.get("associated_goal", associated_goal),
            source=entry.get("source", source),
            expected_outcome=entry.get("expected_outcome", ""),
            family_key=entry.get("family_key", ""),
            conflict_key=entry.get("conflict_key", ""),
            support_count=entry.get("support_count", 1),
            repeat_count=entry.get("repeat_count", 1),
            execute_by_inference=entry.get("execute_by_inference"),
            turns_until_due=entry.get("turns_until_due"),
            queue_mode=entry.get("queue_mode", "normal"),
            priority_score=entry.get("priority_score", 0),
            importance_score=entry.get("importance_score", 0),
            note=f"inserted command took turn {inserted_target_turn}; this candidate was pushed back",
        ),
    )


def shift_pending_entries_for_insert(pending_store, target_turn, operating_context, new_command, source, associated_goal, family_key=""):
    with PENDING_COMMAND_LEDGER.mutation(get_pending_command_store()):
        shifted_entries = []
        for entry in pending_store:
            if not pending_entry_available(entry):
                continue
            if entry.get("operating_context", "unknown") != operating_context:
                continue
            if family_key and entry.get("family_key") == family_key:
                continue
            execute_by_turn = entry.get("execute_by_inference")
            if not isinstance(execute_by_turn, int):
                execute_by_turn = target_turn
            if execute_by_turn < target_turn:
                continue
            entry["execute_by_inference"] = execute_by_turn + 1
            entry["turns_until_due"] = max(0, entry["execute_by_inference"] - agent_state.inference_counter)
            entry["queue_status"] = "deferred"
            apply_pending_entry_scores(entry)
            shifted_entries.append(entry)
            _mark_pending_entry_shifted(entry, new_command, source, associated_goal, target_turn)
        if shifted_entries:
            append_runtime_feedback(
                f"Inserted pending {new_command} and shifted {len(shifted_entries)} queued command(s) back in {operating_context} context."
            )
        return shifted_entries


def replace_immediate_pending_entries(pending_store, target_turn, operating_context, new_command, source, associated_goal, family_key=""):
    with PENDING_COMMAND_LEDGER.mutation(get_pending_command_store()):
        removed_entries = []
        for index in range(len(pending_store) - 1, -1, -1):
            entry = pending_store[index]
            if not pending_entry_available(entry):
                continue
            if entry.get("operating_context", "unknown") != operating_context:
                continue
            if family_key and entry.get("family_key") == family_key:
                continue
            execute_by_turn = entry.get("execute_by_inference")
            if not isinstance(execute_by_turn, int):
                execute_by_turn = target_turn
            if execute_by_turn > target_turn:
                continue
            removed_entries.append(pending_store.pop(index))

        removed_entries.reverse()
        for entry in removed_entries:
            entry["superseded_by"] = sanitize_sensitive_command_text(new_command)
            entry["contradicted_by"] = ""
            entry["superseded_at_turn"] = int(agent_state.inference_counter)
            append_recent_command_proposal(
                entry.get("command", ""),
                source=entry.get("source", source),
                associated_goal=entry.get("associated_goal", associated_goal),
                disposition="unselected",
                support_count=entry.get("support_count", 1),
                execute_by_inference=entry.get("execute_by_inference"),
            )
            append_recent_action_intent(
                f"Unselected pending command: {entry.get('command', '')}",
                status="unselected",
                command=entry.get("command", ""),
                source=source,
                associated_goal=associated_goal,
                execute_by_inference=entry.get("execute_by_inference"),
            )
            append_command_drip_item(
                agent_state.inference_counter,
                "dropped",
                build_command_drip_item(
                    command=entry.get("command", ""),
                    status="unselected",
                    reason=f"replaced by {new_command}",
                    category=entry.get("category", ""),
                    risk=entry.get("risk", ""),
                    associated_goal=entry.get("associated_goal", associated_goal),
                    source=entry.get("source", source),
                    expected_outcome=entry.get("expected_outcome", ""),
                    family_key=entry.get("family_key", ""),
                    conflict_key=entry.get("conflict_key", ""),
                    support_count=entry.get("support_count", 1),
                    repeat_count=entry.get("repeat_count", 1),
                    execute_by_inference=entry.get("execute_by_inference"),
                    turns_until_due=entry.get("turns_until_due"),
                    queue_mode=entry.get("queue_mode", "normal"),
                    priority_score=entry.get("priority_score", 0),
                    importance_score=entry.get("importance_score", 0),
                    superseded_by=entry.get("superseded_by", ""),
                    note="immediate-next candidate was displaced by a replace-mode command",
                ),
            )
        if removed_entries:
            append_runtime_feedback(
                f"Replace-mode pending command {new_command} displaced {len(removed_entries)} immediate queued candidate(s) in {operating_context} context."
            )
        return removed_entries


def get_recent_executed_actions_store():
    if agent_state.shared_recent_executed_actions_ref:
        return list(agent_state.shared_recent_executed_actions_ref)
    return agent_state.recent_executed_actions


def get_input_queue_store():
    return agent_state.queued_user_input


def get_input_recovery():
    """Lazy optional store; startup loads evidence, never re-enqueues old input."""
    global INPUT_RECOVERY
    with INPUT_RECOVERY_LOCK:
        if INPUT_RECOVERY_MODE != 'durable':
            return None
        if INPUT_RECOVERY is None:
            import atexit
            try:
                INPUT_RECOVERY = InputRecovery(Path(__file__).with_name('aurora_input_recovery.json'),
                                               diagnostics=INPUT_RECOVERY_DIAGNOSTICS)
            except Exception as error:
                INPUT_RECOVERY_DIAGNOSTICS.failure('open', error)
                raise
            atexit.register(INPUT_RECOVERY.close)
        return INPUT_RECOVERY


def get_input_recovery_readiness():
    """Non-mutating shared status; inspection never initializes/retries the store."""
    with INPUT_RECOVERY_LOCK:
        return recovery_readiness(INPUT_RECOVERY_MODE, INPUT_RECOVERY, INPUT_RECOVERY_DIAGNOSTICS,
            startup_mode=INPUT_RECOVERY_STARTUP_MODE, startup_source=INPUT_RECOVERY_STARTUP_SOURCE)


def queue_recoverable_input(text, identity):
    with INPUT_RECOVERY_LOCK:
        recovery = get_input_recovery()
        if recovery is not None and not recovery.admit(text, identity):
            return False  # Previously admitted identity: never silently re-enqueue.
        value = TrackedInput(text, identity)
        value.recovery_managed = recovery is not None
        get_input_queue_store().put(value)
        return True


def guard_input_delivery(delivery, phase):
    """Durable request-start evidence is required before network submission."""
    recovery = get_input_recovery()
    if recovery is None or not delivery.references:
        return
    try:
        recovery.delivery(delivery.references, phase, delivery.inference_request_id, delivery.sequence+1,
                          delivery.request_started or phase == 'submitted')
    except Exception as error:
        INPUT_RECOVERY_DIAGNOSTICS.failure('delivery', error)
        set_runtime_value('input_recovery_error', f'{type(error).__name__}: durable delivery record failed; inspect before retrying.')
        if phase not in {'responded', 'failed', 'cancelled', 'not_sent'}:
            raise  # Fail closed before preparation/submission; never replay.


