def get_effective_screenshot_interval():
    try:
        configured_interval = max(0.02, float(time_interval))
    except (TypeError, ValueError):
        configured_interval = 0.12
    try:
        idle_floor = max(0.02, float(idle_screenshot_interval))
    except (TypeError, ValueError):
        idle_floor = 0.50
    if SEND_TO_MODEL and ENABLE_MODEL_RESPONSES:
        return configured_interval
    return max(configured_interval, idle_floor)


def get_next_screenshot_capture_wait_seconds(next_regular_capture_at, now=None):
    now = time.time() if now is None else float(now)
    # A bounded idle wait is interruptible by demand requests and mode changes.
    # Request-only must never fall through to a regular capture, even at startup.
    regular_wait = (3600.0 if CAPTURE_MODE == "request_only" else
                    max(0.0, float(next_regular_capture_at) - now))
    demand_due_at = get_next_demand_capture_due_at(now)
    if demand_due_at:
        demand_wait = max(0.0, demand_due_at - now)
        return min(regular_wait, demand_wait)
    return regular_wait


def get_unchanged_screenshot_persist_interval():
    try:
        return max(0.5, float(unchanged_screenshot_persist_interval))
    except (TypeError, ValueError):
        return 2.5


def should_persist_processed_screenshot(frame_hash, now=None):
    now = time.time() if now is None else float(now)
    force_reason = normalize_text_content(runtime_state.get("screenshot_persist_force_next_reason", "")).strip()
    if force_reason:
        return True, force_reason
    persist_interval = get_unchanged_screenshot_persist_interval()
    last_hash = normalize_text_content(runtime_state.get("screenshot_persist_last_frame_hash", "")).strip()
    last_at = float(runtime_state.get("screenshot_persist_last_at_epoch", 0.0) or 0.0)

    if not frame_hash:
        return True, "no_frame_hash"
    if not last_hash:
        return True, "first_frame"
    if frame_hash != last_hash:
        return True, "changed_frame"
    if not last_at or (now - last_at) >= persist_interval:
        return True, "unchanged_interval"
    return False, "unchanged_skip"


def remember_screenshot_persist_result(frame_hash, persisted, reason, now=None):
    now = time.time() if now is None else float(now)
    if frame_hash:
        set_runtime_value("screenshot_persist_last_frame_hash", frame_hash)
    set_runtime_value("screenshot_persist_interval_seconds", get_unchanged_screenshot_persist_interval())
    set_runtime_value("screenshot_persist_last_decision", reason)
    if persisted:
        set_runtime_value("screenshot_persist_last_at_epoch", now)
        if normalize_text_content(runtime_state.get("screenshot_persist_force_next_reason", "")).strip():
            set_runtime_value("screenshot_persist_force_next_reason", "")
    else:
        skipped = int(runtime_state.get("screenshot_persist_skipped_unchanged_frames", 0) or 0) + 1
        set_runtime_value("screenshot_persist_skipped_unchanged_frames", skipped)

