# Time logger decorator
def time_logger(func):
    @wraps(func)
    def wrapper(*args, **kwargs):
        if not TIME_LOGGING_ENABLED or func.__name__ in NOISY_TIME_LOGGING_FUNCTIONS:
            return func(*args, **kwargs)
        start_time = ftime()
        color = get_color(func.__name__)
        safe_print(f"{color}Starting function '{func.__name__}' at {start_time}{Style.RESET_ALL}")

        result = func(*args, **kwargs)

        end_time = ftime()
        safe_print(f"{color}Function '{func.__name__}' completed at {end_time}{Style.RESET_ALL}")

        # Calculate the time difference (convert to datetime for calculation)
        start_dt = datetime.datetime.strptime(start_time, '%M:%S.%f')
        end_dt = datetime.datetime.strptime(end_time, '%M:%S.%f')
        time_diff = end_dt - start_dt

        safe_print(f"{color}Time taken for '{func.__name__}': {time_diff}{Style.RESET_ALL}")
        return result
    return wrapper



