def initialize_application():
    global init_prompt

    def read_text_file(path):
        for encoding in ("utf-8", "utf-8-sig", "cp1252", "latin-1"):
            try:
                with open(path, "r", encoding=encoding) as f:
                    return f.read().strip()
            except UnicodeDecodeError:
                continue
        with open(path, "r", encoding="utf-8", errors="ignore") as f:
            return f.read().strip()

    # Read the init prompt from a file or use test prompt
    if LOAD_LIVE_INIT_PROMPT:
        INIT_MODE_LOCAL = 'load'
    else:
        INIT_MODE_LOCAL = INIT_MODE

    if INIT_MODE_LOCAL == 'load':
        init_candidates = [
            os.path.join(script_directory, LIVE_INIT_FILENAME),
            os.path.join(script_directory, f"{character_name}_init.txt"),
        ]
        loaded_init_file = None
        for init_file in init_candidates:
            if os.path.exists(init_file):
                init_prompt = read_text_file(init_file)
                set_runtime_value("init_prompt_source", init_file)
                loaded_init_file = init_file
                break
        if loaded_init_file:
            append_runtime_feedback(f"Init prompt loaded from {loaded_init_file}")
            initiate_and_handoff()
        else:
            append_runtime_feedback("No live init file found. Proceeding without an init prompt.")
    elif INIT_MODE_LOCAL == 'test':
        init_prompt = test_init_prompt
        set_runtime_value("init_prompt_source", "built-in short prompt (" + INIT_PROMPT_PROFILE + ")")
        append_runtime_feedback("Using test init prompt.")
        initiate_and_handoff()
    elif INIT_MODE_LOCAL == 'skip':
        append_runtime_feedback("Skipping init prompt loading.")
    else:
        append_runtime_feedback(f"Unknown INIT_MODE: {INIT_MODE_LOCAL}. Proceeding without an init prompt.")

    # Read the handoff summary from a file
    handoff_file = os.path.join(script_directory, f"{character_name}_handoff.txt")
    if os.path.exists(handoff_file):
        handoff_text = read_text_file(handoff_file)
        update_chat_history("system", handoff_text, exemption='Handoff')
        if SEND_TO_MODEL and ENABLE_MODEL_RESPONSES:
            response_text = send_prompt_to_chatgpt(handoff_text)
            if response_text:
                send_prompt_to_chatgpt(response_text)

def initiate_and_handoff():
    agent_state.init_handoff_in_progress = True
    history_store = get_chat_history_store()

    try:
        init_summary = normalize_text_content(init_prompt).strip()
        if init_summary and not any(
            entry.get('Exemption') == 'Init'
            and entry.get('content', {}).get('type') == 'text'
            and init_summary in entry.get('content', {}).get('text', '')
            for entry in history_store
        ):
            update_chat_history("system", init_summary, exemption='Init')
            if SEND_TO_MODEL and ENABLE_MODEL_RESPONSES:
                send_prompt_to_chatgpt(init_summary, role="system", exemption='Init')
    except Exception as e:
        print(f"Error during initiation: {e}")

    agent_state.init_handoff_in_progress = False
