#        sd.sleep(100000000)  # This will keep the audio stream open indefinitely. Adjust as needed.

def transcribe_audio_file(file_path, api_key, model="whisper-1"):
    with open(file_path, "rb") as audio_stream:
        response = requests.post(
            "https://api.openai.com/v1/audio/transcriptions",
            headers={"Authorization": f"Bearer {api_key}"},
            data={"model": model},
            files={"file": (os.path.basename(file_path), audio_stream, "audio/wav")},
            timeout=120,
        )
    response.raise_for_status()
    payload = response.json()
    if isinstance(payload, dict):
        return normalize_text_content(payload.get("text", "")).strip()
    return ""

def audio_input_transcription(audio_queue, error_queue):
    try:
        # Initialize the audio stream here
        with sd.InputStream(callback=lambda indata, frames, time_info, status: audio_callback(indata, frames, time_info, status, audio_queue)):
            sd.sleep(100000000)  # Keep the audio stream open indefinitely
    except Exception as e:
        error_queue.put(('audio', traceback.format_exc()))
        raise




def audio_callback(indata, frames, time_info, status, audio_queue):
    global queued_user_input
    volume_norm = np.linalg.norm(indata) * 10

    if volume_norm < threshold and SEND_TO_MODEL:
        if len(audio_buffer) > sampling_rate * audio_pause_duration:
            if not ENABLE_MODEL_RESPONSES:
                print("Model responses are disabled. Skipping Whisper API call.")
                audio_buffer.clear()
                return
            with tempfile.NamedTemporaryFile(delete=False, suffix=".wav", dir=script_directory) as temp_file:
                audio_data = np.array(audio_buffer, dtype=np.float32)
                audio_segment = AudioSegment(
                    audio_data.tobytes(),
                    frame_rate=sampling_rate,
                    sample_width=audio_data.dtype.itemsize,
                    channels=2
                )

                # Adjust the sample width to a valid value (e.g., 2)
                audio_segment = audio_segment.set_sample_width(2)

                write(temp_file.name, sampling_rate, audio_data.astype('float32'))
                try:
                    audio_api_key, _ = get_openai_bearer_token(force_refresh=False)
                except Exception as error:
                    append_runtime_feedback(f"Audio transcription auth unavailable: {summarize_runtime_text(str(error), max_chars=160)}")
                    audio_buffer.clear()
                    return
                transcribed_text = transcribe_audio_file(temp_file.name, audio_api_key, model="whisper-1")
            print("My Response: ", transcribed_text)

            # Check if sending text to model is enabled
            if SEND_TO_MODEL:
                # Put the transcribed text into the text queue
                #queued_user_input.put(transcribed_text)
                audio_queue.put(transcribed_text)
            else:
                print("Sending text to model is disabled. Ignoring transcribed text.")

            audio_buffer.clear()
    else:
        audio_buffer.extend(indata.tolist())



