def get_command_drip_store():
    return agent_state.command_drip_history


def create_command_drip_bucket(turn):
    return {
        "turn": int(turn),
        "timestamp": datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
        "selected": [],
        "executed": [],
        "failed": [],
        "rejected": [],
        "dropped": [],
        "deferred": [],
        "primary_candidates": [],
        "variant_candidates": [],
        "likely_dropped": [],
        "notes": [],
    }


def trim_command_drip_history():
    store = get_command_drip_store()
    current_turn = agent_state.inference_counter
    earliest_turn = max(0, current_turn - max(1, COMMAND_DRIP_RETENTION_TURNS) + 1)
    store[:] = [
        bucket for bucket in store
        if isinstance(bucket, dict) and int(bucket.get("turn", -1)) >= earliest_turn
    ]
    store.sort(key=lambda item: int(item.get("turn", 0)))


def ensure_command_drip_bucket(turn):
    store = get_command_drip_store()
    normalized_turn = int(turn)
    for bucket in store:
        if int(bucket.get("turn", -1)) == normalized_turn:
            return bucket
    bucket = create_command_drip_bucket(normalized_turn)
    store.append(bucket)
    trim_command_drip_history()
    return bucket


def build_command_drip_item(command="", summary="", status="", reason="", category="", risk="", associated_goal="", source="", expected_outcome="", family_key="", conflict_key="", support_count=0, repeat_count=0, execute_by_inference=None, turns_until_due=None, queue_mode="", priority_score=0, importance_score=0, superseded_by="", contradicted_by="", note="", metadata=None):
    payload = {
        "command": sanitize_sensitive_command_text(command or summary or ""),
        "summary": summarize_runtime_text(summary or command or "", max_chars=180),
        "status": normalize_memory_item(status),
        "reason": summarize_runtime_text(reason, max_chars=180),
        "category": normalize_memory_item(category),
        "risk": normalize_memory_item(risk),
        "associated_goal": summarize_runtime_text(associated_goal, max_chars=120),
        "source": normalize_memory_item(source),
        "expected_outcome": summarize_runtime_text(expected_outcome, max_chars=160),
        "family_key": normalize_memory_item(family_key),
        "conflict_key": normalize_memory_item(conflict_key),
        "support_count": int(support_count or 0),
        "repeat_count": int(repeat_count or 0),
        "execute_by_inference": execute_by_inference if isinstance(execute_by_inference, int) else "",
        "turns_until_due": turns_until_due if isinstance(turns_until_due, int) else turns_until_due or "",
        "queue_mode": normalize_pending_queue_mode(queue_mode, fallback="normal") if queue_mode else "",
        "priority_score": int(priority_score or 0),
        "importance_score": int(importance_score or 0),
        "superseded_by": sanitize_sensitive_command_text(superseded_by),
        "contradicted_by": summarize_runtime_text(contradicted_by, max_chars=120),
        "note": summarize_runtime_text(note, max_chars=180),
    }
    if metadata:
        payload["metadata"] = sanitize_sensitive_payload(metadata)
    return payload


def append_command_drip_item(turn, lane, item):
    bucket = ensure_command_drip_bucket(turn)
    lane_store = bucket.setdefault(lane, [])
    lane_store.append(item)
    del lane_store[:-MAX_COMMAND_DRIP_ITEMS_PER_LANE]
    bucket["timestamp"] = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    trim_command_drip_history()
    return item


def append_command_drip_note(turn, note):
    note_text = summarize_runtime_text(note, max_chars=180)
    if not note_text:
        return None
    bucket = ensure_command_drip_bucket(turn)
    notes_store = bucket.setdefault("notes", [])
    notes_store.append(note_text)
    del notes_store[:-MAX_COMMAND_DRIP_ITEMS_PER_LANE]
    bucket["timestamp"] = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    trim_command_drip_history()
    return note_text


def _command_drip_turn_label(relative_turn):
    if relative_turn == 0:
        return "this turn"
    if relative_turn == 1:
        return "next turn"
    if relative_turn == 2:
        return "two turns out"
    if relative_turn == 3:
        return "three turns out"
    if relative_turn < 0:
        turns_ago = abs(relative_turn)
        return "previous turn" if turns_ago == 1 else f"{turns_ago} turns ago"
    return f"turn +{relative_turn}"


def build_command_drip_snapshot():
    trim_command_drip_history()
    current_turn = agent_state.inference_counter
    lookahead = max(1, COMMAND_DRIP_LOOKAHEAD_TURNS)
    future_buckets = {}

    grouped_future_entries = {}
    for entry in get_pending_command_store():
        target_turn = entry.get("execute_by_inference")
        if not isinstance(target_turn, int):
            target_turn = current_turn + 1
        target_turn = max(current_turn + 1, target_turn)
        if target_turn > current_turn + lookahead:
            continue
        grouped_future_entries.setdefault(target_turn, []).append(entry)

    for target_turn in range(current_turn + 1, current_turn + lookahead + 1):
        bucket = create_command_drip_bucket(target_turn)
        candidates = grouped_future_entries.get(target_turn, [])
        grouped_by_conflict = {}
        for entry in candidates:
            grouping_key = entry.get("conflict_key") or entry.get("family_key") or normalize_action_command(entry.get("command", ""))
            grouped_by_conflict.setdefault(grouping_key, []).append(entry)

        for group_entries in grouped_by_conflict.values():
            ranked_entries = sorted(
                group_entries,
                key=lambda candidate: (
                    -int(candidate.get("priority_score", 0) or 0),
                    -int(candidate.get("importance_score", 0) or 0),
                    -int(candidate.get("support_count", 1) or 1),
                    get_queue_mode_rank(candidate.get("queue_mode", "normal")),
                    get_risk_rank(candidate.get("risk", "high")),
                    int(candidate.get("turns_until_due", 999) if isinstance(candidate.get("turns_until_due"), int) else 999),
                ),
            )
            if not ranked_entries:
                continue
            primary_entry = ranked_entries[0]
            bucket["primary_candidates"].append(
                build_command_drip_item(
                    command=primary_entry.get("command", ""),
                    status=primary_entry.get("queue_status", "queued"),
                    reason=primary_entry.get("reason", ""),
                    category=primary_entry.get("category", ""),
                    risk=primary_entry.get("risk", ""),
                    associated_goal=primary_entry.get("associated_goal", ""),
                    source=primary_entry.get("source", ""),
                    expected_outcome=primary_entry.get("expected_outcome", ""),
                    family_key=primary_entry.get("family_key", ""),
                    conflict_key=primary_entry.get("conflict_key", ""),
                    support_count=primary_entry.get("support_count", 1),
                    repeat_count=primary_entry.get("repeat_count", 1),
                    execute_by_inference=primary_entry.get("execute_by_inference"),
                    turns_until_due=primary_entry.get("turns_until_due"),
                    queue_mode=primary_entry.get("queue_mode", "normal"),
                    priority_score=primary_entry.get("priority_score", 0),
                    importance_score=primary_entry.get("importance_score", 0),
                    superseded_by=primary_entry.get("superseded_by", ""),
                    contradicted_by=primary_entry.get("contradicted_by", ""),
                    note="strongest current candidate for this turn horizon",
                )
            )
            for variant_entry in ranked_entries[1:]:
                variant_item = build_command_drip_item(
                    command=variant_entry.get("command", ""),
                    status=variant_entry.get("queue_status", "queued"),
                    reason=variant_entry.get("reason", ""),
                    category=variant_entry.get("category", ""),
                    risk=variant_entry.get("risk", ""),
                    associated_goal=variant_entry.get("associated_goal", ""),
                    source=variant_entry.get("source", ""),
                    expected_outcome=variant_entry.get("expected_outcome", ""),
                    family_key=variant_entry.get("family_key", ""),
                    conflict_key=variant_entry.get("conflict_key", ""),
                    support_count=variant_entry.get("support_count", 1),
                    repeat_count=variant_entry.get("repeat_count", 1),
                    execute_by_inference=variant_entry.get("execute_by_inference"),
                    turns_until_due=variant_entry.get("turns_until_due"),
                    queue_mode=variant_entry.get("queue_mode", "normal"),
                    priority_score=variant_entry.get("priority_score", 0),
                    importance_score=variant_entry.get("importance_score", 0),
                    superseded_by=variant_entry.get("superseded_by", ""),
                    contradicted_by=variant_entry.get("contradicted_by", ""),
                    note="close variant likely to be dropped unless support or context changes",
                )
                if COMMAND_DRIP_SHOW_VARIANTS:
                    bucket["variant_candidates"].append(variant_item)
                if COMMAND_DRIP_SHOW_LIKELY_DROPPED:
                    bucket["likely_dropped"].append(dict(variant_item))

        future_buckets[target_turn] = bucket

    turns = []
    historical_buckets = [
        bucket for bucket in get_command_drip_store()
        if isinstance(bucket, dict) and int(bucket.get("turn", -1)) >= max(0, current_turn - max(1, COMMAND_DRIP_RETENTION_TURNS) + 1)
    ]
    for bucket in sorted(historical_buckets, key=lambda item: int(item.get("turn", 0))):
        relative_turn = int(bucket.get("turn", 0)) - current_turn
        enriched_bucket = dict(bucket)
        for lane_name in ("selected", "executed", "failed", "rejected", "dropped", "deferred", "primary_candidates", "variant_candidates", "likely_dropped"):
            enriched_bucket.setdefault(lane_name, [])
        enriched_bucket["relative_turn"] = relative_turn
        enriched_bucket["label"] = _command_drip_turn_label(relative_turn)
        turns.append(enriched_bucket)

    for target_turn in range(current_turn + 1, current_turn + lookahead + 1):
        bucket = future_buckets.get(target_turn, create_command_drip_bucket(target_turn))
        relative_turn = target_turn - current_turn
        bucket["relative_turn"] = relative_turn
        bucket["label"] = _command_drip_turn_label(relative_turn)
        turns.append(bucket)

    return {
        "current_turn": current_turn,
        "retention_turns": COMMAND_DRIP_RETENTION_TURNS,
        "lookahead_turns": lookahead,
        "pending_queue_mode": DEFAULT_PENDING_QUEUE_MODE,
        "show_variants": bool(COMMAND_DRIP_SHOW_VARIANTS),
        "show_likely_dropped": bool(COMMAND_DRIP_SHOW_LIKELY_DROPPED),
        "turns": turns,
    }


def build_memory_tier_snapshot():
    on_hand = [
        {"store": "next_inference_plan", "role": "next-turn override / immediate cognitive posture"},
        {"store": "pinned_immediate_actions", "role": "do-now actions that should remain visible every turn"},
        {"store": "pinned_short_term_actions", "role": "next-step actions and near-future intent"},
        {"store": "route_state", "role": "current navigation facts that anchor interpretation of the screenshot"},
        {"store": "recent_context_events", "role": "fresh world facts and immediate situational updates"},
        {"store": "pending_model_commands", "role": "held command queue with support, due-turn pressure, and alternatives"},
        {"store": "recent_action_intents", "role": "what recent turns were trying to do"},
        {"store": "command_drip", "role": "multi-turn command tree: this turn, next turn, and short lookahead variants"},
    ]
    retrievable = [
        {"store": "goals", "role": "active task list that can be consulted without forcing every item into the prompt"},
        {"store": "overarching_goals", "role": "mission-level direction that is stable but not always urgent"},
        {"store": "inventory", "role": "stable world facts that can be pulled back when relevant"},
        {"store": "party_status", "role": "battle/state lookups; useful on demand"},
        {"store": "notes", "role": "stable reminders and facts that should persist without constant foregrounding"},
        {"store": "journal_entries", "role": "longer narrative continuity and lessons learned"},
        {"store": "episodic_snapshots", "role": "periodic and event-triggered compact continuity snapshots for later retrieval"},
        {"store": "significant_past_tasks", "role": "completed or historical milestones"},
        {"store": "chat_history_tail", "role": "recent conversational evidence, not the primary memory substrate"},
        {"store": "image_memory", "role": "retained visual-memory entries that can be inspected when needed"},
    ]

    if 0 < len(agent_state.active_questions) <= 3:
        on_hand.append({"store": "active_questions", "role": "open verification questions that should stay visible while the current scene remains ambiguous"})
    elif agent_state.active_questions:
        retrievable.append({"store": "active_questions", "role": "larger backlog of unresolved questions that can be revisited on review turns"})

    if any(_planning_entry_is_fresh(entry, 3) for entry in agent_state.known_failures):
        on_hand.append({"store": "known_failures", "role": "fresh failures that should bias the next few turns away from repeated mistakes"})
    elif agent_state.known_failures:
        retrievable.append({"store": "known_failures", "role": "older failure history that can be consulted during review or critique"})

    if any(_scene_matches_current(entry) for entry in agent_state.candidate_alternatives):
        on_hand.append({"store": "candidate_alternatives", "role": "scene-relevant fallback actions or route alternatives worth considering now"})
    elif agent_state.candidate_alternatives:
        retrievable.append({"store": "candidate_alternatives", "role": "background alternatives that can be recalled if the active plan fails"})

    if any(_planning_entry_is_fresh(entry, 10) for entry in agent_state.stale_assumptions):
        on_hand.append({"store": "stale_assumptions", "role": "recent assumptions under critique that should stay visible until resolved or replaced"})
    elif agent_state.stale_assumptions:
        retrievable.append({"store": "stale_assumptions", "role": "older assumptions retained for periodic critique rather than every turn"})

    return {"on_hand": on_hand, "retrievable": retrievable}


def normalize_goal_key(goal_text):
    return normalize_memory_item(goal_text).lower()


def iter_all_goals(goals=None):
    goal_source = tasks_list if goals is None else goals
    for goal in goal_source:
        yield goal
        for sub_goal in iter_all_goals(goal.sub_goals):
            yield sub_goal


def goal_exists(goal_text):
    goal_key = normalize_goal_key(goal_text)
    if not goal_key:
        return False
    return any(normalize_goal_key(goal.text) == goal_key for goal in iter_all_goals())


def apriority_goal_exists(goal_text):
    goal_key = normalize_goal_key(goal_text)
    if not goal_key:
        return False
    return any(normalize_goal_key(existing) == goal_key for existing in apriority_tasks)


def merge_recent_context_items(context_items):
    merged = list(agent_state.recent_context_events)
    seen = {normalize_memory_item(item).lower() for item in merged if normalize_memory_item(item)}
    for item in context_items:
        cleaned = normalize_memory_item(item)
        if not cleaned:
            continue
        lowered = cleaned.lower()
        if lowered in seen:
            continue
        merged.append(cleaned)
        seen.add(lowered)
    agent_state.recent_context_events[:] = merged[-MAX_RECENT_CONTEXT_EVENTS:]


def identify_response_section(line):
    stripped = normalize_text_content(line).strip()
    if not stripped:
        return None
    stripped = re.sub(r'^[#>\-\s]+', '', stripped)
    stripped = stripped.strip('*').strip()
    stripped = re.sub(r':\s*$', '', stripped)
    stripped = re.sub(r'\s+', ' ', stripped).lower()
    return RESPONSE_SECTION_ALIASES.get(stripped)


def clean_response_line(line):
    cleaned = normalize_text_content(line).strip()
    cleaned = cleaned.strip("`").strip()
    cleaned = re.sub(r'^\s*[-*+]\s*', '', cleaned)
    cleaned = re.sub(r'^\s*\d+[.)]\s*', '', cleaned)
    return cleaned.strip()


def extract_command_candidate(line, assume_command=False):
    candidate = clean_response_line(line)
    if not candidate:
        return None
    candidate = re.sub(r'^\*\*(?:command|commands|memory update|memory command|update context|next command)\*\*\s*:\s*', '', candidate, flags=re.IGNORECASE)
    candidate = re.sub(r'^(?:command|commands|memory update|memory command|update context|next command)\s*:\s*', '', candidate, flags=re.IGNORECASE)
    candidate = candidate.strip().strip('`').strip()
    if not candidate:
        return None
    if assume_command:
        return candidate
    if is_known_command(candidate):
        return candidate
    return None


def is_non_action_command_text(command_text):
    normalized = normalize_memory_item(command_text).strip().lower().strip(".")
    if not normalized:
        return True
    return normalized in {
        "none",
        "none needed",
        "none needed at this moment",
        "no command",
        "no commands",
        "no action",
        "no action needed",
        "no actions needed",
        "n/a",
        "not applicable",
    }


def split_response_sections(response_text):
    command_lines = []
    tasks_lines = []
    section_items = {
        "recent_context": [],
        "goals": [],
        "apriority_goals": [],
        "overarching_goals": [],
        "unknown_priority": [],
        "current_area": [],
        "target_area": [],
        "travel_heading": [],
        "last_landmark": [],
        "route_intent": [],
        "local_path_plan": [],
        "route_blockers": [],
        "recent_movement_results": [],
        "mid_term_context": [],
        "long_term_context": [],
        "gameplay_scene": [],
        "active_questions": [],
        "stale_assumptions": [],
        "known_failures": [],
        "candidate_alternatives": [],
        "notes": [],
        "journal": [],
        "pinned_immediate_actions": [],
        "pinned_short_term_actions": [],
    }
    narrative_lines = []
    current_section = None
    inline_section_patterns = (
        (r'^(?:observation|observations|state|summary|context)\s*:\s*(.+)$', "recent_context"),
        (r'^(?:goal|priority goal)\s*:\s*(.+)$', "goals"),
        (r'^(?:open goal|apriority goal)\s*:\s*(.+)$', "apriority_goals"),
        (r'^(?:overarching goal)\s*:\s*(.+)$', "overarching_goals"),
        (r'^(?:current area)\s*:\s*(.+)$', "current_area"),
        (r'^(?:target area|destination)\s*:\s*(.+)$', "target_area"),
        (r'^(?:travel heading|heading|general movement)\s*:\s*(.+)$', "travel_heading"),
        (r'^(?:last landmark|landmark)\s*:\s*(.+)$', "last_landmark"),
        (r'^(?:route intent|route)\s*:\s*(.+)$', "route_intent"),
        (r'^(?:next path move|path step|local path step)\s*:\s*(.+)$', "local_path_plan"),
        (r'^(?:blocker|route blocker)\s*:\s*(.+)$', "route_blockers"),
        (r'^(?:movement result|recent movement result)\s*:\s*(.+)$', "recent_movement_results"),
        (r'^(?:mid-term context|medium-term context|mid-term intent)\s*:\s*(.+)$', "mid_term_context"),
        (r'^(?:long-term context|long-term content|long horizon)\s*:\s*(.+)$', "long_term_context"),
        (r'^(?:scene|gameplay scene)\s*:\s*(.+)$', "gameplay_scene"),
        (r'^(?:active question|active questions)\s*:\s*(.+)$', "active_questions"),
        (r'^(?:stale assumption|stale assumptions)\s*:\s*(.+)$', "stale_assumptions"),
        (r'^(?:known failure|known failures|failure)\s*:\s*(.+)$', "known_failures"),
        (r'^(?:candidate alternative|candidate alternatives|alternative)\s*:\s*(.+)$', "candidate_alternatives"),
        (r'^(?:note|notes)\s*:\s*(.+)$', "notes"),
        (r'^(?:journal)\s*:\s*(.+)$', "journal"),
    )

    for raw_line in response_text.strip().splitlines():
        stripped = raw_line.strip()
        if not stripped:
            if current_section in {
                "commands", "recent_context", "goals", "apriority_goals",
                "overarching_goals", "unknown_priority", "current_area",
                "target_area", "travel_heading", "last_landmark",
                "route_intent", "local_path_plan", "route_blockers",
                "recent_movement_results", "mid_term_context", "long_term_context",
                "gameplay_scene", "active_questions", "stale_assumptions",
                "known_failures", "candidate_alternatives", "notes", "journal",
                "pinned_immediate_actions", "pinned_short_term_actions"
            }:
                current_section = None
            continue

        section_name = identify_response_section(stripped)
        if section_name:
            current_section = section_name
            if section_name == "hierarchical_tasks":
                tasks_lines.append(stripped)
            continue

        if current_section == "hierarchical_tasks":
            tasks_lines.append(raw_line.rstrip())
            continue

        command_candidate = extract_command_candidate(raw_line, assume_command=current_section == "commands")
        if command_candidate:
            if is_non_action_command_text(command_candidate):
                continue
            command_lines.append(command_candidate)
            continue

        cleaned_line = clean_response_line(raw_line)
        if not cleaned_line:
            continue

        if current_section in {
            "recent_context", "goals", "apriority_goals", "overarching_goals",
            "unknown_priority", "current_area", "target_area", "travel_heading",
            "last_landmark", "route_intent", "local_path_plan", "route_blockers",
            "recent_movement_results", "mid_term_context", "long_term_context",
            "gameplay_scene", "active_questions", "stale_assumptions",
            "known_failures", "candidate_alternatives", "notes", "journal",
            "pinned_immediate_actions", "pinned_short_term_actions"
        }:
            section_items[current_section].append(cleaned_line)
            continue

        matched_inline_section = False
        for pattern, target_section in inline_section_patterns:
            match = re.match(pattern, cleaned_line, flags=re.IGNORECASE)
            if not match:
                continue
            section_items[target_section].append(match.group(1).strip())
            matched_inline_section = True
            break
        if matched_inline_section:
            continue

        narrative_lines.append(cleaned_line)

    return (
        '; '.join(dedupe_preserve_order(command_lines)).strip('; '),
        "\n".join(tasks_lines).strip(),
        {key: dedupe_preserve_order(values) for key, values in section_items.items() if values},
        "\n".join(narrative_lines).strip(),
    )


def infer_goal_candidates(context_items, fallback_narrative=""):
    combined_text = " ".join(context_items + ([fallback_narrative] if fallback_narrative else []))
    lowered = combined_text.lower()
    inferred_goals = []

    if re.search(r'\b(error|exception|traceback|failed|failure|crash|invalid)\b', lowered):
        inferred_goals.append("Investigate the latest error or failure signal before taking another action")
    if re.search(r'\b(waiting|monitoring) for output\b', lowered):
        inferred_goals.append("Review the next terminal or game output before issuing another desktop action")
    if re.search(r'\b(blocked|stuck|cannot|can\'t|unable|missing|not found|not accessible)\b', lowered):
        inferred_goals.append("Resolve the current blocked or missing-state issue")

    return dedupe_preserve_order(inferred_goals)


def promote_response_memory(section_items, fallback_narrative=""):
    context_items = list(section_items.get("recent_context", []))
    goal_items = list(section_items.get("goals", []))
    apriority_items = list(section_items.get("apriority_goals", []))
    overarching_items = list(section_items.get("overarching_goals", []))
    unknown_priority_items = list(section_items.get("unknown_priority", []))
    current_area_items = list(section_items.get("current_area", []))
    target_area_items = list(section_items.get("target_area", []))
    travel_heading_items = list(section_items.get("travel_heading", []))
    last_landmark_items = list(section_items.get("last_landmark", []))
    route_intent_items = list(section_items.get("route_intent", []))
    local_path_plan_items = list(section_items.get("local_path_plan", []))
    route_blocker_items = list(section_items.get("route_blockers", []))
    movement_result_items = list(section_items.get("recent_movement_results", []))
    mid_term_items = list(section_items.get("mid_term_context", []))
    long_term_items = list(section_items.get("long_term_context", []))
    gameplay_scene_items = list(section_items.get("gameplay_scene", []))
    active_question_items = list(section_items.get("active_questions", []))
    stale_assumption_items = list(section_items.get("stale_assumptions", []))
    known_failure_items = list(section_items.get("known_failures", []))
    candidate_alternative_items = list(section_items.get("candidate_alternatives", []))
    notes_items = list(section_items.get("notes", []))
    journal_items = list(section_items.get("journal", []))
    immediate_items = list(section_items.get("pinned_immediate_actions", []))
    short_term_items = list(section_items.get("pinned_short_term_actions", []))

    if not context_items and fallback_narrative:
        first_line = fallback_narrative.splitlines()[0].strip()
        first_sentence = re.split(r'(?<=[.!?])\s+', first_line)[0].strip()
        candidate_context = first_sentence or first_line
        if 12 <= len(candidate_context) <= 220:
            context_items.append(candidate_context)

    if context_items:
        merge_recent_context_items(context_items)

    for goal_text in goal_items:
        add_goal(goal_text)

    for goal_text in apriority_items:
        add_apriority_goal(goal_text)

    for goal_text in overarching_items:
        add_overarching_goal(goal_text)

    for goal_text in unknown_priority_items:
        add_unknown_priority_candidate(goal_text)

    if current_area_items:
        update_current_area(current_area_items[-1], source="assistant_section")

    if target_area_items:
        update_target_area(target_area_items[-1], source="assistant_section")

    if travel_heading_items:
        update_travel_heading(travel_heading_items[-1], source="assistant_section")

    if last_landmark_items:
        update_last_landmark(last_landmark_items[-1], source="assistant_section")

    if route_intent_items:
        update_route_intent(route_intent_items)

    if local_path_plan_items:
        update_local_path_plan(local_path_plan_items)

    if route_blocker_items:
        update_route_blockers(route_blocker_items)

    if movement_result_items:
        update_recent_movement_results(movement_result_items)

    if mid_term_items:
        update_mid_term_context(mid_term_items)

    if long_term_items:
        update_long_term_context(long_term_items)

    if gameplay_scene_items and GAMEPLAY_SCENE_POLICY == "legacy":
        scene_value = normalize_memory_item(gameplay_scene_items[-1]).lower()
        if scene_value in GAMEPLAY_SCENES:
            set_runtime_value("gameplay_scene", scene_value)
            set_runtime_value("gameplay_scene_summary", f"assistant_section:{scene_value}")

    if active_question_items:
        update_active_questions(
            active_question_items,
            source="assistant_section",
            scene=normalize_memory_item(runtime_state.get("gameplay_scene", "")).lower(),
            metadata={"status": "open"},
        )

    if stale_assumption_items:
        update_stale_assumptions(
            stale_assumption_items,
            source="assistant_section",
            scene=normalize_memory_item(runtime_state.get("gameplay_scene", "")).lower(),
            metadata={"status": "under_review"},
        )

    if known_failure_items:
        update_known_failures(
            known_failure_items,
            source="assistant_section",
            scene=normalize_memory_item(runtime_state.get("gameplay_scene", "")).lower(),
            metadata={"status": "open"},
        )

    if candidate_alternative_items:
        update_candidate_alternatives(
            candidate_alternative_items,
            source="assistant_section",
            scene=normalize_memory_item(runtime_state.get("gameplay_scene", "")).lower(),
            metadata={"status": "candidate"},
        )

    if notes_items:
        update_notes(notes_items)

    for journal_entry in journal_items:
        add_journal_entry(journal_entry)

    if immediate_items:
        update_pinned_immediate_actions(immediate_items)

    if short_term_items:
        update_pinned_short_term_actions(short_term_items)

    for goal_text in infer_goal_candidates(context_items, fallback_narrative):
        add_apriority_goal(goal_text)


def promote_associated_goals_from_tasks():
    for level in hierarchical_tasks[:2]:
        for item in level:
            associated_goal = normalize_memory_item(item.get('associated_goal', ''))
            if associated_goal and associated_goal.lower() not in {'no goal', 'no specific goal', 'none'}:
                add_apriority_goal(associated_goal)


