def append_recent_executed_action(command, timestamp, associated_goal="No specific goal", why="", thought="", **metadata):
    agent_state.recent_executed_actions.append({
        'timestamp': timestamp,
        'action': sanitize_sensitive_command_text(command),
        'associated_goal': associated_goal,
        'why': why,
        'thought': thought,
        'expected_outcome': metadata.get('expected_outcome', ''),
        'family_key': metadata.get('family_key', ''),
        'conflict_key': metadata.get('conflict_key', ''),
        'semantic_label': metadata.get('semantic_label', ''),
        'execution_operating_context': metadata.get('execution_operating_context', ''),
        'execution_context_fingerprint': metadata.get('execution_context_fingerprint', ''),
        'execution_image_hash': metadata.get('execution_image_hash', ''),
        'executed_inference_turn': metadata.get('executed_inference_turn', agent_state.inference_counter),
        'outcome_status': metadata.get('outcome_status', 'pending'),
        'outcome_score': metadata.get('outcome_score', 0),
        'last_outcome_evaluated_turn': metadata.get('last_outcome_evaluated_turn'),
        'outcome_note': metadata.get('outcome_note', ''),
    })
    del agent_state.recent_executed_actions[:-7]


def get_command_name(command):
    cleaned = normalize_action_command(command)
    if not cleaned:
        return ""
    if '(' in cleaned:
        cleaned = cleaned.split('(', 1)[0]
    return cleaned.strip()


def get_risk_rank(risk):
    risk_order = {"low": 0, "medium": 1, "high": 2}
    return risk_order.get(str(risk).strip().lower(), 99)


def get_queue_mode_rank(queue_mode):
    queue_order = {"replace": 0, "insert": 1, "normal": 2}
    return queue_order.get(normalize_pending_queue_mode(queue_mode, fallback="normal"), 99)


def canonicalize_hotkey_tokens(tokens):
    normalized = [normalize_memory_item(token).lower() for token in tokens if normalize_memory_item(token)]
    return "+".join(sorted(dict.fromkeys(normalized)))


def classify_assistant_command(command):
    command_name = get_command_name(command).upper()
    if not command_name:
        return "other"
    if command_name.startswith("PYAG:"):
        return "desktop_action"
    if command_name in ASSISTANT_MEMORY_COMMANDS:
        return "memory"
    if command_name.startswith("TOGGLE") or command_name.startswith("SET_") or command_name.startswith("SHOW_") or command_name in {"STATUS", "HELP"}:
        return "runtime"
    if command_name.startswith("SAVE") or command_name.startswith("LOAD") or command_name.startswith("CLEAR"):
        return "persistence"
    return "other"


def build_semantic_command_identity(command, operating_context="unknown"):
    normalized_command = normalize_action_command(command)
    category = classify_assistant_command(normalized_command)
    command_name = get_command_name(normalized_command).upper()
    pyag_action = get_pyag_action_name(normalized_command)
    args = [arg.lower() for arg in extract_command_arguments(normalized_command)]

    family_key = f"{category}:{normalized_command.lower()}"
    conflict_key = ""
    semantic_label = normalized_command

    if category == "memory":
        family_key = f"memory:{command_name}"
        semantic_label = command_name
        if command_name.startswith("UPDATE_"):
            conflict_key = f"memory-field:{command_name}"
    elif category == "runtime":
        family_key = f"runtime:{command_name}"
        semantic_label = command_name
        conflict_key = family_key
    elif category == "persistence":
        family_key = f"persistence:{command_name}"
        semantic_label = command_name
        conflict_key = family_key
    elif category == "desktop_action":
        if pyag_action == "move_key" and args:
            key = args[0]
            family_key = f"game-move:{key}"
            semantic_label = family_key
            if key in GAME_DIRECTION_AXES:
                conflict_key = f"game-move-axis:{GAME_DIRECTION_AXES[key]}"
        elif pyag_action in {"press", "hold", "release"} and args:
            key = args[0]
            if operating_context == "game" and key in LOW_RISK_GAME_KEYS:
                if key in GAME_DIRECTION_AXES:
                    family_key = f"game-move:{key}"
                    semantic_label = family_key
                    conflict_key = f"game-move-axis:{GAME_DIRECTION_AXES[key]}"
                elif key in GAME_CONFIRM_KEYS:
                    family_key = f"game-confirm:{key}"
                    semantic_label = family_key
                    conflict_key = "game-action:confirm"
                else:
                    family_key = f"game-button:{key}"
                    semantic_label = family_key
                    conflict_key = family_key
            elif operating_context == "game" and key in GAME_CONFIRM_KEYS:
                family_key = f"game-confirm:{key}"
                semantic_label = family_key
                conflict_key = "game-action:confirm"
            elif operating_context == "terminal" and key == "enter":
                family_key = "terminal:submit"
                semantic_label = family_key
                conflict_key = family_key
            elif key == "tab":
                family_key = "focus:tab"
                semantic_label = family_key
                conflict_key = "focus-family:advance"
            else:
                family_key = f"key:{key}"
                semantic_label = family_key
                if key in {"enter", "tab", "space"}:
                    conflict_key = "key-family:advance"
                elif key in {"esc", "escape"}:
                    conflict_key = "key-family:cancel"
        elif pyag_action in {"hotkey", "multi_press", "multi_hold", "multi_release"}:
            hotkey = canonicalize_hotkey_tokens(args)
            if operating_context == "terminal" and hotkey == "ctrl+c":
                family_key = "terminal:interrupt"
                semantic_label = family_key
                conflict_key = family_key
            elif operating_context == "editor" and hotkey in {"ctrl+s", "ctrl+shift+s"}:
                family_key = "editor:save"
                semantic_label = family_key
                conflict_key = "hotkey-family:save"
            else:
                family_key = f"hotkey:{hotkey}"
                semantic_label = family_key
                if hotkey in {"ctrl+s", "ctrl+shift+s"}:
                    conflict_key = "hotkey-family:save"
                elif hotkey in {"ctrl+w", "ctrl+q", "alt+f4"}:
                    conflict_key = "hotkey-family:window-close"
        elif pyag_action in {"click", "doubleclick", "leftclick"}:
            family_key = f"pointer:activate:{operating_context}"
            semantic_label = family_key
        elif pyag_action in {"hold_click", "drag", "move"}:
            family_key = f"pointer:{pyag_action}:{operating_context}"
            semantic_label = family_key
        elif pyag_action.startswith("scroll"):
            family_key = f"viewport:{pyag_action}:{operating_context}"
            semantic_label = family_key
        elif pyag_action == "type":
            family_key = f"type:text-entry:{operating_context}"
            semantic_label = family_key

    return {
        "family_key": family_key,
        "conflict_key": conflict_key,
        "semantic_label": semantic_label,
        "category": category,
        "command_name": command_name,
        "pyag_action": pyag_action,
        "args": args,
    }


def should_replace_pending_representative(existing_entry, new_command, new_policy):
    existing_command = existing_entry.get("command", "")
    if normalize_memory_item(existing_command).lower() == normalize_memory_item(new_command).lower():
        return False

    existing_risk = get_risk_rank(existing_entry.get("risk", "medium"))
    new_risk = get_risk_rank(new_policy.get("risk", "medium"))
    if new_risk < existing_risk:
        return True

    existing_pyag = get_pyag_action_name(existing_command)
    new_pyag = get_pyag_action_name(new_command)
    if new_pyag == "move_key" and existing_pyag in {"press", "hold", "release"}:
        return True

    return False


def supersede_conflicting_pending_entries(pending_store, identity, operating_context, new_command, source, associated_goal):
    with PENDING_COMMAND_LEDGER.mutation(get_pending_command_store()):
        conflict_key = identity.get("conflict_key", "")
        family_key = identity.get("family_key", "")
        if not conflict_key:
            return []

        removed_entries = []
        for index in range(len(pending_store) - 1, -1, -1):
            entry = pending_store[index]
            if not pending_entry_available(entry):
                continue
            if entry.get("operating_context", "unknown") != operating_context:
                continue
            if entry.get("family_key") == family_key:
                continue
            if entry.get("conflict_key") != conflict_key:
                continue
            removed_entries.append(pending_store.pop(index))

        removed_entries.reverse()
        for entry in removed_entries:
            entry["superseded_by"] = sanitize_sensitive_command_text(new_command)
            entry["contradicted_by"] = ""
            entry["superseded_at_turn"] = int(agent_state.inference_counter)
            append_recent_command_proposal(
                entry.get("command", ""),
                source=entry.get("source", "assistant"),
                associated_goal=entry.get("associated_goal", "No specific goal"),
                disposition="superseded",
                support_count=entry.get("support_count", 1),
                execute_by_inference=entry.get("execute_by_inference"),
            )
            append_recent_action_intent(
                f"Superseded pending command: {entry.get('command', '')} -> {new_command}",
                status="superseded",
                command=entry.get("command", ""),
                source=source,
                associated_goal=associated_goal,
                execute_by_inference=entry.get("execute_by_inference"),
            )
            append_runtime_feedback(
                f"Superseded pending {entry.get('command', '')} with {new_command} in {operating_context} context."
            )
            append_command_drip_item(
                agent_state.inference_counter,
                "dropped",
                build_command_drip_item(
                    command=entry.get("command", ""),
                    status="superseded",
                    reason=f"superseded by {new_command}",
                    category=entry.get("category", ""),
                    risk=entry.get("risk", ""),
                    associated_goal=entry.get("associated_goal", "No specific goal"),
                    source=entry.get("source", source),
                    expected_outcome=entry.get("expected_outcome", ""),
                    family_key=entry.get("family_key", ""),
                    conflict_key=entry.get("conflict_key", ""),
                    support_count=entry.get("support_count", 1),
                    repeat_count=entry.get("repeat_count", 1),
                    execute_by_inference=entry.get("execute_by_inference"),
                    turns_until_due=entry.get("turns_until_due"),
                    queue_mode=entry.get("queue_mode", "normal"),
                    priority_score=entry.get("priority_score", 0),
                    importance_score=entry.get("importance_score", 0),
                    superseded_by=entry.get("superseded_by", ""),
                    note="conflicting pending candidate was replaced",
                ),
            )
        return removed_entries


