def assess_command_risk(command):
    category = classify_assistant_command(command)
    normalized_command = normalize_action_command(command)

    if category == "memory":
        return category, "low", "memory update"
    if category == "runtime":
        return category, "medium", "runtime configuration change"
    if category == "persistence":
        return category, "medium", "persistent state or file operation"
    if category != "desktop_action":
        return category, "medium", "unclassified assistant command"

    pyag_action = get_pyag_action_name(normalized_command)
    args = [arg.lower() for arg in extract_command_arguments(normalized_command)]

    if pyag_action in {"press", "hold", "release"} and args:
        key = args[0]
        if key in LOW_RISK_GAME_KEYS:
            return category, "low", f"single in-game style keypress ({key})"
        if key in MEDIUM_RISK_KEYS:
            return category, "medium", f"general desktop keypress ({key})"
        return category, "high", f"unknown keypress ({key})"

    if pyag_action in {"hotkey", "multi_press", "multi_hold", "multi_release"}:
        joined = {token.lower() for token in args}
        if joined & HIGH_RISK_HOTKEY_TOKENS:
            return category, "high", "windowing or destructive hotkey"
        if joined & MEDIUM_RISK_HOTKEY_TOKENS:
            return category, "medium", "workflow hotkey"
        return category, "high", "unreviewed multi-key shortcut"

    if pyag_action in {"click", "doubleclick", "leftclick", "hold_click", "drag", "move"}:
        return category, "high", f"pointer action ({pyag_action})"
    if pyag_action.startswith("scroll"):
        return category, "medium", "scroll action"
    if pyag_action == "type":
        return category, "high", "text entry into the active window"
    if pyag_action == "move_key":
        return category, "low", "tile-style movement command"

    return category, "high", f"unclassified desktop action ({pyag_action or 'pyag'})"


def is_destructive_hotkey(token_set):
    normalized_tokens = {token.lower() for token in token_set if token}
    return any(shortcut.issubset(normalized_tokens) for shortcut in DESTRUCTIVE_HOTKEY_SETS)


def has_game_title_menu_signal(signal_text):
    lowered_signal = normalize_memory_item(signal_text).lower()
    return any(hint in lowered_signal for hint in get_gameplay_title_hints())


def parse_command_int_arg(args, index, default=1):
    try:
        return max(1, int(float(args[index])))
    except (IndexError, TypeError, ValueError):
        return default


def is_game_menu_navigation_action(pyag_action, args):
    if pyag_action == "move_key" and args:
        key = args[0]
        steps = parse_command_int_arg(args, 1, default=1)
        return key in GAME_MENU_DIRECTION_KEYS and steps == 1
    if pyag_action in {"press", "hold", "release"} and args:
        key = args[0]
        return key in GAME_MENU_ALLOWED_PRESS_KEYS
    return False


def is_single_step_game_overworld_action(pyag_action, args):
    if pyag_action == "move_key" and args:
        key = args[0]
        steps = parse_command_int_arg(args, 1, default=1)
        return key in GAME_MENU_DIRECTION_KEYS and steps == 1
    if pyag_action in {"press", "hold", "release"} and args:
        key = args[0]
        return key in {"a", "b", "start", "select"}
    return False


def is_dialog_safe_game_action(pyag_action, args):
    if pyag_action in {"press", "hold", "release"} and args:
        return args[0] in {"a", "b", "start", "select"}
    return False


def build_smoke_test_model_command_script(profile="confirm_cursor", cycle_index=1, focus_point=None, phase="combined"):
    profile = normalize_memory_item(profile).strip().lower() or "confirm_cursor"
    profile_label = get_active_game_profile_label()
    try:
        current_position = pyautogui.position()
        target_x = max(10, min(screen_width - 10, current_position.x + 60))
        target_y = max(10, min(screen_height - 10, current_position.y + 40))
    except Exception:
        target_x, target_y = 200, 200
    focus_x = None
    focus_y = None
    if isinstance(focus_point, dict):
        focus_x, focus_y = get_point_xy(focus_point)
    selected_key = get_smoke_test_cycle_key(cycle_index)
    press_count = SMOKE_TEST_CONFIRM_PRESSES if selected_key == DEFAULT_GAME_CONFIRM_KEY else 1

    if profile == "confirm_cursor":
        return "; ".join([
            f'UPDATE_CONTEXT("Smoke test: {profile_label} title screen visible in VBA emulator; confirm input should advance the game.")',
            f'pyag:press("{DEFAULT_GAME_CONFIRM_KEY}")',
            f'pyag:press("{DEFAULT_GAME_CONFIRM_KEY}")',
            f'pyag:press("{DEFAULT_GAME_CONFIRM_KEY}")',
            f'pyag:move({target_x}, {target_y}, 0.12)',
        ])
    if profile in {"confirm_cursor_until_progress", "title_loop"}:
        if phase == "focus":
            command_parts = [
                f'UPDATE_CONTEXT("Smoke test cycle {cycle_index}: {profile_label} title screen visible in VBA emulator; focus emulator before trying {selected_key}.")',
                f'pyag:focus_window("{EMULATOR_WINDOW_TITLE_HINT}")',
            ]
            if focus_x is not None and focus_y is not None:
                command_parts.append(f'pyag:move({focus_x}, {focus_y}, 0.12)')
                command_parts.append(f'pyag:click({focus_x}, {focus_y}, "left")')
            return "; ".join(command_parts)
        if phase == "confirm":
            return "; ".join([
                f'UPDATE_CONTEXT("Smoke test cycle {cycle_index}: emulator focus attempted; now test {selected_key} as the confirm/start input.")',
                f'pyag:press("{selected_key}", {press_count}, {SMOKE_TEST_CONFIRM_INTERVAL_SECONDS})',
            ])
        command_parts = [
            f'UPDATE_CONTEXT("Smoke test cycle {cycle_index}: {profile_label} title screen visible in VBA emulator; focus emulator and test {selected_key} as the confirm/start input.")',
        ]
        if focus_x is not None and focus_y is not None:
            command_parts.append(f'pyag:move({focus_x}, {focus_y}, 0.12)')
            command_parts.append(f'pyag:click({focus_x}, {focus_y}, "left")')
        command_parts.append(f'pyag:press("{selected_key}", {press_count}, {SMOKE_TEST_CONFIRM_INTERVAL_SECONDS})')
        command_parts.append(f'pyag:move({target_x}, {target_y}, 0.12)')
        return "; ".join(command_parts)
    return "; ".join([
        'UPDATE_CONTEXT("Smoke test mode active.")',
        f'pyag:press("{DEFAULT_GAME_CONFIRM_KEY}")',
    ])


def get_smoke_test_cycle_key(cycle_index):
    if not SMOKE_TEST_CONFIRM_KEY_SEQUENCE:
        return DEFAULT_GAME_CONFIRM_KEY
    cycle_index = max(1, int(cycle_index))
    key_index = min(cycle_index - 1, len(SMOKE_TEST_CONFIRM_KEY_SEQUENCE) - 1)
    return normalize_memory_item(SMOKE_TEST_CONFIRM_KEY_SEQUENCE[key_index]).strip().lower() or DEFAULT_GAME_CONFIRM_KEY


def get_latest_runtime_screenshot_path():
    candidate = normalize_text_content(runtime_state.get("last_screenshot_path", "")).strip()
    if candidate and os.path.exists(candidate):
        return candidate
    try:
        png_files = [
            os.path.join(logging_folder, name)
            for name in os.listdir(logging_folder)
            if name.lower().endswith(".png")
        ]
    except FileNotFoundError:
        return ""
    if not png_files:
        return ""
    return max(png_files, key=os.path.getmtime)


def locate_emulator_focus_point(image_path, model_name=None):
    image_path = normalize_text_content(image_path).strip()
    if not image_path or not os.path.exists(image_path):
        return {"x": None, "y": None, "reason": "no screenshot path available", "model": model_name or SMOKE_TEST_TITLE_CHECK_MODEL}

    try:
        with Image.open(image_path) as image:
            width, height = image.size
    except Exception as error:
        return {"x": None, "y": None, "reason": f"failed to read screenshot: {error}", "model": model_name or SMOKE_TEST_TITLE_CHECK_MODEL}

    base64_image = encode_image_to_base64(image_path)
    if not base64_image:
        return {"x": None, "y": None, "reason": "failed to encode screenshot", "model": model_name or SMOKE_TEST_TITLE_CHECK_MODEL}

    model_name = normalize_text_content(model_name or SMOKE_TEST_TITLE_CHECK_MODEL).strip() or SMOKE_TEST_TITLE_CHECK_MODEL
    prompt = (
        f"The image is {width}x{height} pixels. "
        "Identify a safe click point inside the Pokemon emulator window or game display area that would focus the emulator. "
        "Prefer the visual center of the actual game/title screen area, not the desktop background or window chrome. "
        "Reply with exactly one line: CLICK:x,y"
    )
    payload = {
        "model": model_name,
        "messages": [
            {"role": "system", "content": "You locate a safe focus point in a desktop screenshot."},
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": prompt},
                    {"type": "image_url", "image_url": {"url": f"data:image/png;base64,{base64_image}", "detail": "low"}},
                ],
            },
        ],
    }
    if supports_temperature_override(model_name):
        payload["temperature"] = 0.0
    if uses_max_completion_tokens(model_name):
        payload["max_completion_tokens"] = 32
    else:
        payload["max_tokens"] = 32

    try:
        response, _ = post_openai_chat_completions(payload, timeout=20)
        if response.status_code != 200:
            return {
                "x": width // 2,
                "y": height // 2,
                "reason": f"API error {response.status_code}; fallback center used",
                "model": model_name,
            }
        content = response.json()["choices"][0]["message"]["content"].strip()
    except Exception as error:
        return {
            "x": width // 2,
            "y": height // 2,
            "reason": f"exception: {error}; fallback center used",
            "model": model_name,
        }

    match = re.search(r"CLICK\s*:\s*(\d+)\s*,\s*(\d+)", normalize_text_content(content), flags=re.IGNORECASE)
    if not match:
        return {
            "x": width // 2,
            "y": height // 2,
            "reason": f"unparsed response '{summarize_runtime_text(content, max_chars=80)}'; fallback center used",
            "model": model_name,
        }
    x = max(0, min(width - 1, int(match.group(1))))
    y = max(0, min(height - 1, int(match.group(2))))
    return {"x": x, "y": y, "reason": content, "model": model_name}


def classify_smoke_test_screen_state(image_path, model_name=None):
    image_path = normalize_text_content(image_path).strip()
    if not image_path or not os.path.exists(image_path):
        return {"screen_state": "uncertain", "reason": "no screenshot path available", "model": model_name or SMOKE_TEST_TITLE_CHECK_MODEL}

    base64_image = encode_image_to_base64(image_path)
    if not base64_image:
        return {"screen_state": "uncertain", "reason": "failed to encode screenshot", "model": model_name or SMOKE_TEST_TITLE_CHECK_MODEL}

    model_name = normalize_text_content(model_name or SMOKE_TEST_TITLE_CHECK_MODEL).strip() or SMOKE_TEST_TITLE_CHECK_MODEL
    prompt = (
        f"Classify this {get_active_game_profile_label()} VBA screenshot. "
        "Reply with exactly one line in this format: TITLE: <reason> or NOT_TITLE: <reason> or UNCERTAIN: <reason>. "
        "TITLE means it is still on the startup/title screen or waiting for a confirm press. "
        "NOT_TITLE means it has progressed beyond the title screen into any later game/menu/intro state."
    )
    payload = {
        "model": model_name,
        "messages": [
            {"role": "system", "content": "You classify a single emulator screenshot."},
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": prompt},
                    {"type": "image_url", "image_url": {"url": f"data:image/png;base64,{base64_image}", "detail": "low"}},
                ],
            },
        ],
    }
    if supports_temperature_override(model_name):
        payload["temperature"] = 0.0
    if uses_max_completion_tokens(model_name):
        payload["max_completion_tokens"] = 48
    else:
        payload["max_tokens"] = 48

    try:
        response, _ = post_openai_chat_completions(payload, timeout=20)
        if response.status_code != 200:
            return {
                "screen_state": "uncertain",
                "reason": f"API error {response.status_code}",
                "model": model_name,
                "raw": summarize_runtime_text(response.text, max_chars=160),
            }
        content = response.json()["choices"][0]["message"]["content"].strip()
    except Exception as error:
        return {"screen_state": "uncertain", "reason": f"exception: {error}", "model": model_name}

    normalized = normalize_text_content(content).strip()
    upper = normalized.upper()
    if upper.startswith("NOT_TITLE"):
        state = "not_title"
    elif upper.startswith("TITLE"):
        state = "title"
    else:
        state = "uncertain"
    return {"screen_state": state, "reason": normalized, "model": model_name}


def initialize_smoke_test_state():
    return {
        "enabled": SMOKE_TEST_ENABLED,
        "profile": SMOKE_TEST_PROFILE,
        "started_at": time.time(),
        "next_cycle_at": time.time() + SMOKE_TEST_START_DELAY_SECONDS,
        "cycle_count": 0,
        "cycle_started_at": None,
        "focus_approved_at": None,
        "key_injected_at": None,
        "assessment_done": False,
        "focus_point": None,
        "completed": False,
    }


def maybe_run_smoke_test_step(smoke_state):
    if not smoke_state or not smoke_state.get("enabled") or smoke_state.get("completed"):
        return

    now = time.time()
    elapsed = now - smoke_state["started_at"]
    profile = smoke_state.get("profile", "confirm_cursor")

    if smoke_state.get("cycle_started_at") is None and now >= smoke_state.get("next_cycle_at", now):
        if smoke_state.get("cycle_count", 0) >= SMOKE_TEST_MAX_CYCLES:
            write_command_execution_log(
                "smoke_test_complete",
                source="smoke_test_model",
                status="max_cycles_reached",
                execution_operating_context=runtime_state.get("operating_context", "game"),
            )
            append_runtime_feedback("Smoke test reached max cycles without leaving the title screen.")
            set_agent_running(False)
            smoke_state["completed"] = True
            return
        merge_recent_context_items([
            f"{get_active_game_profile_label()} title screen visible in VBA emulator.",
            "Smoke test active: model should press A a few times and try one cursor move.",
        ])
        set_runtime_value("operating_context", "game")
        smoke_state["cycle_count"] = smoke_state.get("cycle_count", 0) + 1
        latest_image_path = get_latest_runtime_screenshot_path()
        if smoke_state.get("focus_point") is None or smoke_state["cycle_count"] == 1:
            focus_point = get_window_client_center(EMULATOR_WINDOW_TITLE_HINT)
            focus_x, focus_y = get_point_xy(focus_point)
            if focus_x is None or focus_y is None:
                focus_point = locate_emulator_focus_point(latest_image_path)
            smoke_state["focus_point"] = focus_point
            write_command_execution_log(
                "smoke_test_focus_point",
                source="smoke_test_model",
                status="focus_point",
                command=latest_image_path,
                execution_operating_context="game",
                cycle=smoke_state["cycle_count"],
                focus_point=smoke_state.get("focus_point", {}),
            )
        focus_script = build_smoke_test_model_command_script(
            profile,
            cycle_index=smoke_state["cycle_count"],
            focus_point=smoke_state.get("focus_point"),
            phase="focus",
        )
        smoke_state["cycle_started_at"] = now
        smoke_state["focus_approved_at"] = None
        smoke_state["key_injected_at"] = None
        smoke_state["assessment_done"] = False
        write_command_execution_log(
            "smoke_test_focus_inject",
            command=focus_script,
            source="smoke_test_model",
            status="focus_inject",
            execution_operating_context="game",
            cycle=smoke_state["cycle_count"],
        )
        route_assistant_commands(
            focus_script,
            associated_goal=f"Smoke test cycle {smoke_state['cycle_count']}: verify model command execution and cursor movement",
            source="smoke_test_model",
            why="full program smoke test - focus stage",
        )
        return

    cycle_started_at = smoke_state.get("cycle_started_at")
    if cycle_started_at is not None and smoke_state.get("focus_approved_at") is None and (now - cycle_started_at) >= SMOKE_TEST_APPROVE_DELAY_SECONDS:
        pending_store = get_pending_command_store()
        if pending_store:
            approve_pending_command(["all"], is_user=True)
        smoke_state["focus_approved_at"] = now

    focus_approved_at = smoke_state.get("focus_approved_at")
    if (
        cycle_started_at is not None
        and focus_approved_at is not None
        and smoke_state.get("key_injected_at") is None
        and (now - focus_approved_at) >= SMOKE_TEST_FOCUS_SETTLE_SECONDS
    ):
        confirm_script = build_smoke_test_model_command_script(
            profile,
            cycle_index=smoke_state["cycle_count"],
            focus_point=smoke_state.get("focus_point"),
            phase="confirm",
        )
        write_command_execution_log(
            "smoke_test_confirm_inject",
            command=confirm_script,
            source="smoke_test_model",
            status="confirm_inject",
            execution_operating_context="game",
            cycle=smoke_state["cycle_count"],
        )
        route_assistant_commands(
            confirm_script,
            associated_goal=f"Smoke test cycle {smoke_state['cycle_count']}: verify model command execution and cursor movement",
            source="smoke_test_model",
            why="full program smoke test - confirm stage",
        )
        smoke_state["key_injected_at"] = now
        return

    key_injected_at = smoke_state.get("key_injected_at")
    if cycle_started_at is not None and key_injected_at is not None and not smoke_state.get("assessment_done") and (now - key_injected_at) >= SMOKE_TEST_SETTLE_SECONDS:
        latest_image_path = get_latest_runtime_screenshot_path()
        assessment = classify_smoke_test_screen_state(latest_image_path)
        smoke_state["assessment_done"] = True
        write_command_execution_log(
            "smoke_test_screen_assessment",
            source="smoke_test_model",
            status=assessment.get("screen_state", "uncertain"),
            command=latest_image_path,
            execution_operating_context=runtime_state.get("operating_context", "game"),
            cycle=smoke_state.get("cycle_count", 0),
            model=assessment.get("model", ""),
            note=assessment.get("reason", ""),
        )
        append_runtime_feedback(
            f"Smoke test screen assessment after cycle {smoke_state.get('cycle_count', 0)}: "
            f"{assessment.get('screen_state', 'uncertain')} ({assessment.get('reason', '')})"
        )
        if assessment.get("screen_state") == "not_title":
            write_command_execution_log(
                "smoke_test_complete",
                source="smoke_test_model",
                status="title_cleared",
                execution_operating_context=runtime_state.get("operating_context", "game"),
            )
            append_runtime_feedback("Smoke test detected progress beyond the title screen.")
            set_agent_running(False)
            smoke_state["completed"] = True
            return
        smoke_state["cycle_started_at"] = None
        smoke_state["focus_approved_at"] = None
        smoke_state["key_injected_at"] = None
        smoke_state["next_cycle_at"] = now + SMOKE_TEST_RETRY_DELAY_SECONDS

    if elapsed >= SMOKE_TEST_EXIT_AFTER_SECONDS:
        write_command_execution_log(
            "smoke_test_complete",
            source="smoke_test_model",
            status="complete",
            execution_operating_context=runtime_state.get("operating_context", "unknown"),
        )
        append_runtime_feedback("Smoke test duration reached; shutting down the full runtime loop.")
        set_agent_running(False)
        smoke_state["completed"] = True


def infer_expected_outcome(command, operating_context, category=None):
    category = category or classify_assistant_command(command)
    if category == "memory":
        return "working memory and pinned context should update"
    if category == "runtime":
        return "runtime flags or execution mode should change"
    if category == "persistence":
        return "saved state or files should change"
    if category != "desktop_action":
        return "agent state should change"

    identity = build_semantic_command_identity(command, operating_context=operating_context)
    family_key = identity.get("family_key", "")
    pyag_action = get_pyag_action_name(command)
    args = [arg.lower() for arg in extract_command_arguments(command)]
    key = args[0] if args else ""

    if family_key.startswith("game-move:") or (pyag_action in {"press", "hold", "release"} and key in LOW_RISK_GAME_KEYS):
        return "the avatar, menu selection, or game state should visibly change"
    if family_key.startswith("game-confirm:"):
        return "the title screen, menu selection, or game state should advance"
    if family_key == "terminal:submit":
        return "terminal output, prompt state, or command execution should change"
    if family_key == "terminal:interrupt":
        return "the running terminal task should stop or the prompt should return"
    if family_key == "editor:save":
        return "the editor save state should clear or a save confirmation should appear"
    if family_key.startswith("focus:tab"):
        return "focus, selection, or the active field should advance"
    if family_key.startswith("viewport:"):
        return "the viewport should shift"
    if family_key.startswith("pointer:"):
        return "focus, selection, or pointer location should change"
    if family_key.startswith("type:text-entry"):
        return "new text should appear in the active field"
    if pyag_action in {"hotkey", "multi_press", "multi_hold", "multi_release"}:
        return "the focused application should react to the shortcut"
    if pyag_action == "press" and key == "enter":
        return "the focused application should accept or advance the current selection"
    return "the visible application state should change"


def evaluate_task_flow_permission(command, operating_context, gameplay_scene, pyag_action, args):
    """Optional narrow admission changes; execution mode and handlers still enforce authority."""
    if ASSISTANT_POLICY != "task_flow":
        return None
    name = get_command_name(command).upper()
    try:
        if setting_command_definition(name) and not extract_command_arguments(command):
            return "allow", "task-flow registered setting query; no mutation"
        if name in {"SHOW_RUNTIME", "SHOW_NEXT_INFERENCE", "SHOW_RETRIEVAL_RESULT", "SEARCH_COMMANDS", "LOOKUP_COMMAND", "LIST_COMMANDS"}:
            return "allow", "task-flow discovery/readback; no runtime permission change"
        if name in {"REQUEST_SCREENSHOT_CAPTURE", "OBSERVE_SCREEN_CHANGE"}:
            require_runtime_setting_unlocked("screenshot_interval", "Requested capture")
            return ("allow", "task-flow observation request; demand capture enabled") if DEMAND_CAPTURE_ENABLED else (
                "hold", "demand capture is disabled; operator must enable it")
        if name == "SET_NEXT_INFERENCE":
            options = normalize_next_inference_pairs(parse_inference_plan_arguments(name, extract_command_arguments(command)))
            if any(options.get(key) for key in ("model", "text_model", "vision_model", "reasoning_model")):
                require_runtime_setting_unlocked("models", "Next inference model controls")
            if any(options.get(key) for key in ("reasoning_effort", "verbosity", "summary_mode", "service_tier")):
                require_runtime_setting_unlocked("reasoning", "Next inference reasoning controls")
            if "temperature" in options:
                require_runtime_setting_unlocked("temperature", "Next inference temperature control")
            return "allow", "task-flow one-turn plan; session defaults unchanged"
        if (command.strip().upper().startswith("GB:") and operating_context == "game"
                and gameplay_scene == "battle" and args and args[0] in {"a", "b", "up", "down", "left", "right"}):
            if (pyag_action == "press" and len(args) == 1) or (pyag_action == "hold" and len(args) == 2 and 0 < float(args[1]) <= 0.25):
                require_runtime_setting_unlocked("action", "Task-flow battle menu input")
                return "allow", "task-flow bounded battle menu/confirm step; observe the result before another action"
        if (command.strip().upper().startswith("GB:") and operating_context == "game"
                and gameplay_scene == "overworld" and args and args[0] in {"up", "down", "left", "right"}):
            if (pyag_action == "press" and len(args) == 1) or (pyag_action == "hold" and len(args) == 2 and 0 < float(args[1]) <= 1.0):
                require_runtime_setting_unlocked("action", "Task-flow gameplay input")
                return "allow", "task-flow bounded overworld direction; fresh observation required after the sequence"
    except (ValueError, RuntimeError) as error:
        return "reject", str(error)
    return None


def evaluate_assistant_command_policy(command):
    context_info = infer_operating_context()
    operating_context = context_info.get("context", "unknown")
    gameplay_scene = normalize_memory_item(context_info.get("gameplay_scene", "")).lower() or "unknown"
    signal_text = context_info.get("signal_text", "")
    context_fingerprint = context_info.get("context_fingerprint", "")
    identity = build_semantic_command_identity(command, operating_context=operating_context)
    category, risk, rationale = assess_command_risk(command)
    expected_outcome = infer_expected_outcome(command, operating_context, category=category)
    normalized_command = normalize_action_command(command)
    pyag_action = get_pyag_action_name(normalized_command)
    args = [arg.lower() for arg in extract_command_arguments(normalized_command)]
    key = args[0] if args else ""
    hotkey_tokens = set(args)

    decision = "hold"
    policy_reason = rationale
    one_turn_reasoning = get_command_name(command).upper() == "SET_NEXT_REASONING_EFFORT"
    task_control = get_command_name(command).upper() in TASK_CONTROL_COMMANDS
    flow_permission = evaluate_task_flow_permission(command, operating_context, gameplay_scene, pyag_action, args)

    if task_control:
        decision, policy_reason = "allow", "controller task inspection or an opt-in stopping declaration; no action authorization"
    elif flow_permission is not None:
        decision, policy_reason = flow_permission
    elif one_turn_reasoning:
        try:
            validate_command_arguments("SET_NEXT_REASONING_EFFORT", extract_command_arguments(command))
            require_runtime_setting_unlocked("reasoning", "Next-turn reasoning")
        except (ValueError, RuntimeError) as error:
            decision, policy_reason = "reject", str(error)
        else:
            decision = "allow"
            policy_reason = "one-turn effort request is permitted while reasoning is unlocked"
    elif category == "memory":
        decision = "allow"
        policy_reason = "memory updates are safe to apply immediately"
    elif category in {"runtime", "persistence"}:
        decision = "hold"
        policy_reason = "runtime or persistent state changes require review"
    elif category != "desktop_action":
        decision = "hold"
        policy_reason = "unclassified assistant command requires review"
    elif is_destructive_hotkey(hotkey_tokens):
        decision = "reject"
        policy_reason = "destructive or window-closing shortcut rejected"
    elif operating_context == "game":
        title_menu_signal = has_game_title_menu_signal(signal_text) if GAMEPLAY_SCENE_POLICY == "legacy" else gameplay_scene in {"title", "main_menu"}
        effective_scene = gameplay_scene
        if title_menu_signal and effective_scene == "unknown":
            effective_scene = "main_menu"
        if effective_scene in {"title", "main_menu"}:
            if is_game_menu_navigation_action(pyag_action, args):
                decision = "allow"
                policy_reason = f"single-step game menu navigation is appropriate on {effective_scene} screens"
            elif pyag_action in {"click", "doubleclick", "leftclick", "hold_click", "drag", "move", "type", "hotkey", "multi_press", "multi_hold", "multi_release"}:
                decision = "reject"
                policy_reason = f"{effective_scene} screens reject pointer, typing, and multi-action inputs"
            elif pyag_action == "move_key" or (pyag_action in {"press", "hold", "release"} and key in LOW_RISK_GAME_KEYS):
                decision = "hold"
                policy_reason = f"{effective_scene} screens only allow single confirm/cancel/menu-step actions"
            else:
                decision = "hold"
                policy_reason = f"{effective_scene} actions should stay reviewed unless they are an obvious single menu step"
        elif effective_scene == "dialog":
            if is_dialog_safe_game_action(pyag_action, args):
                decision = "allow"
                policy_reason = "dialog scenes allow single confirm/cancel/advance inputs"
            elif pyag_action in {"click", "doubleclick", "leftclick", "hold_click", "drag", "move", "type", "hotkey", "multi_press", "multi_hold", "multi_release", "move_key"}:
                decision = "reject"
                policy_reason = "dialog scenes should not use pointer actions, typing, or multi-step movement"
            else:
                decision = "hold"
                policy_reason = "dialog actions should stay single-step and reviewed"
        elif effective_scene == "overworld":
            if is_single_step_game_overworld_action(pyag_action, args):
                decision = "allow"
                policy_reason = "single-step overworld movement or confirm/menu actions are safe in overworld scenes"
            elif pyag_action == "move_key":
                decision = "hold"
                policy_reason = "multi-step overworld movement should stay reviewed one step at a time"
            elif pyag_action in {"click", "doubleclick", "leftclick", "hold_click", "drag", "move", "type"}:
                decision = "hold"
                policy_reason = "pointer or typing actions still need review in overworld scenes"
            else:
                decision = "hold"
                policy_reason = "non-trivial overworld actions should stay reviewed"
        elif effective_scene == "battle":
            if is_dialog_safe_game_action(pyag_action, args) or is_game_menu_navigation_action(pyag_action, args):
                decision = "hold"
                policy_reason = "battle inputs are plausible but should remain reviewed because state is higher stakes"
            else:
                decision = "reject"
                policy_reason = "battle scenes reject pointer actions, typing, and broad non-menu commands"
        elif effective_scene in {"transition", "unknown"}:
            if category == "desktop_action":
                decision = "hold"
                policy_reason = f"{effective_scene} game scenes prefer observation and memory updates before acting"
            else:
                decision = "hold"
                policy_reason = f"{effective_scene} scene keeps actions reviewed"
        else:
            decision = "hold"
            policy_reason = "game actions should stay reviewed unless the scene strongly supports a low-risk step"
    elif operating_context == "terminal":
        if pyag_action == "move_key":
            decision = "reject"
            policy_reason = "game-specific movement does not fit terminal context"
        elif pyag_action == "press" and key == "enter":
            if any(hint in signal_text for hint in TERMINAL_ENTER_HINTS):
                decision = "allow"
                policy_reason = "terminal context suggests a staged command or waiting prompt"
            else:
                decision = "hold"
                policy_reason = "generic Enter in terminal context needs evidence of a staged command"
        elif pyag_action == "hotkey" and hotkey_tokens == {"ctrl", "c"}:
            decision = "hold"
            policy_reason = "interrupting a terminal process requires review"
        else:
            decision = "hold"
            policy_reason = "terminal actions should stay reviewed unless the shell state is explicit"
    elif operating_context == "editor":
        if pyag_action == "move_key":
            decision = "reject"
            policy_reason = "game-specific movement does not fit editor context"
        elif pyag_action == "hotkey" and hotkey_tokens == {"ctrl", "s"}:
            decision = "hold"
            policy_reason = "saving is plausible but should stay reviewed in editor context"
        else:
            decision = "hold"
            policy_reason = "editor interactions need stronger evidence than a generic screenshot guess"
    elif operating_context == "browser":
        if pyag_action == "move_key":
            decision = "reject"
            policy_reason = "game-specific movement does not fit browser context"
        else:
            decision = "hold"
            policy_reason = "browser interactions need a specific visible target or field"
    else:
        if pyag_action == "move_key":
            decision = "hold"
            policy_reason = "game-style movement is not safe outside confirmed game context"
        else:
            decision = "hold"
            policy_reason = "desktop action needs clearer operating context"

    return {
        "decision": decision,
        "one_turn_reasoning": one_turn_reasoning,
        "task_control": task_control,
        "category": category,
        "risk": risk,
        "rationale": rationale,
        "policy_reason": policy_reason,
        "operating_context": operating_context,
        "context_summary": context_info.get("summary", "no strong evidence"),
        "context_fingerprint": context_fingerprint,
        "expected_outcome": expected_outcome,
        "family_key": identity.get("family_key", ""),
        "conflict_key": identity.get("conflict_key", ""),
        "semantic_label": identity.get("semantic_label", ""),
        "pyag_action": pyag_action,
        "hotkey_tokens": sorted(hotkey_tokens),
    }


def is_urgent_control_command(prepared_commands):
    """Standalone stop/task controls stay in the controller, ahead of queued work."""
    if not prepared_commands or len(prepared_commands) != 1:
        return False
    _, name, args, _ = prepared_commands[0]
    return name in TASK_CONTROL_COMMANDS or name in {"SHUTDOWN_RUNTIME", "CANCEL_ACTIVE_WORK", "RELEASE_HELD_INPUTS"} or (
        name == "SET_LIVE_MODE" and len(args) == 1
        and args[0].strip().lower() in {"off", "false", "0", "safe"}
    )


def execute_command_entry(command_entry):
    """Preserve request identity and full results on queued and urgent paths."""
    with command_task_scope(command_entry), HELD_INPUTS.owner_scope(command_entry), history_actor_scope(command_entry.get("history_actor", "operator" if command_entry.get("is_user") else "unknown")):
        execution_result = handle_commands(
            command_entry["command"], command_entry["is_user"],
            prepared_commands=command_entry.get("prepared_commands"),
            command_generation=command_entry.get("command_generation"),
        )
    result = {key: value for key, value in command_entry.items() if key != "prepared_commands"}
    result.update(execution_result)
    result["action"] = result.pop("command")
    result["status"] = "cancelled" if execution_result.get("cancelled") else (
        "processed" if execution_result.get("success", True) else "failed"
    )
    return result


def enqueue_or_execute_command(
    command,
    is_user,
    associated_goal="No specific goal",
    why="",
    thought="",
    source="user",
    expected_outcome="",
    family_key="",
    conflict_key="",
    execution_operating_context="",
    semantic_label="",
    request_id="",
    message_id="",
    client_id="",
    mutation_admission_id="",
    command_digest="",
    prepared_commands=None,
    pending_id="",
    pending_attempt_id="",
    command_generation=None,
    history_actor=None,
):
    command_generation = COMMAND_WORK.current().generation if command_generation is None else command_generation
    COMMAND_WORK.token(command_generation).check()
    if not is_user:
        MODEL_WORK.current().check()
    if prepared_commands is None:
        prepared_commands = prepare_command_batch(command)
    timestamp = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    if not execution_operating_context:
        execution_operating_context = runtime_state.get("operating_context", "unknown")
    execution_context_fingerprint = runtime_state.get("context_fingerprint", "")
    execution_image_hash = runtime_state.get("last_image_hash", "")
    origin_delivery = current_delivery() if not is_user else None
    parent_task = current_command_task() if not is_user else {}
    parent_budget = (parent_task.get("task_budget_results") or [{}])[-1]
    active_budget = TASK_CONTINUATION.budget_snapshot() if TASK_CONTINUATION_MODE == "bounded" else {}
    budgeted = not is_user and bool(active_budget.get("enabled") or parent_budget)
    task_identity = (getattr(origin_delivery, "task_id", "") or parent_task.get("task_id") or
                     (TASK_CONTINUATION.snapshot().get("task_id", "") if budgeted else ""))
    command_entry = {
        'command_batch_id': 'batch-' + uuid.uuid4().hex,
        'task_id': task_identity,
        'inference_request_id': getattr(origin_delivery, 'inference_request_id', '') or parent_task.get('inference_request_id') or '',
        'command': command,
        'is_user': is_user,
        'history_actor': "operator" if is_user else (history_actor or current_history_actor()),
        'timestamp': timestamp,
        'associated_goal': associated_goal,
        'why': why,
        'thought': thought,
        'source': source,
        'request_id': request_id,
        'pending_id': pending_id,
        'pending_attempt_id': pending_attempt_id,
        'message_id': message_id,
        'client_id': client_id,
        'mutation_admission_id': mutation_admission_id,
        'command_digest': command_digest,
        'prepared_commands': prepared_commands,
        'command_generation': command_generation,
        'expected_outcome': expected_outcome,
        'family_key': family_key,
        'conflict_key': conflict_key,
        'semantic_label': semantic_label,
        'execution_operating_context': execution_operating_context,
        'execution_context_fingerprint': execution_context_fingerprint,
        'execution_image_hash': execution_image_hash,
        'executed_inference_turn': agent_state.inference_counter,
    }
    if budgeted and any(item[1].upper() not in TASK_CONTROL_COMMANDS for item in prepared_commands):
        if parent_budget and parent_budget.get("controller_pid") != os.getpid():
            admission = dict(schema_version=TASK_BUDGET_RESULT_SCHEMA, success=False, allowed=False,
                effect_status="not_started", code="controller_required", task_id=task_identity,
                command_batch_id=command_entry["command_batch_id"], controller_pid=parent_budget.get("controller_pid"),
                reason="Nested budgeted submission requires the owning controller; legacy process workers cannot spend a separate local budget.")
        else:
            admission = TASK_CONTINUATION.admit_commands(task_identity, command_entry["command_batch_id"], len(prepared_commands))
        command_entry["task_budget_results"] = [admission]
        if not admission["allowed"]:
            execution_result = {key: value for key, value in command_entry.items() if key not in {"command", "prepared_commands"}}
            execution_result.update(action=command, status="failed", success=False, executed_commands=[],
                failed_commands=[{"command": command, "reason": admission["reason"], "effect_status": "not_started"}])
            ingest_command_result(execution_result)
            return dict(command_entry, submission_status="not_started", execution_result=execution_result)
    if (not is_user and TASK_CONTINUATION_MODE == "bounded"
            and not TASK_CONTINUATION.check_deadline()
            and any(item[1].upper() not in TASK_CONTROL_COMMANDS for item in prepared_commands)):
        reason = "Bounded task stopped; no new automatic command batch was admitted. Operator controls remain available."
        execution_result = {key: value for key, value in command_entry.items() if key not in {"command", "prepared_commands"}}
        execution_result.update(action=command, status="failed", success=False, executed_commands=[],
                                failed_commands=[{"command": command, "reason": reason, "effect_status": "not_started"}])
        ingest_command_result(execution_result)
        return dict(command_entry, submission_status="failed", execution_result=execution_result)
    TASK_CONTINUATION.record_command_admission(command_entry)
    if active_command_queue is not None and not is_urgent_control_command(prepared_commands):
        active_command_queue.put(command_entry)
        return dict(command_entry, submission_status="queued")
    else:
        execution_result = execute_command_entry(command_entry)
        ingest_command_result(execution_result)
        if (execution_result.get("capture_batch") or {}).get("requests", 0):
            publish_batch_observation([execution_result])
        return dict(command_entry, submission_status=("cancelled" if execution_result.get("cancelled") else
                    "completed" if execution_result.get("success", True) else "failed"), execution_result=execution_result)
    return command_entry


def queue_pending_model_command(command, associated_goal="No specific goal", source="assistant", reason="held for review", policy=None, queue_mode=None):
    with PENDING_COMMAND_LEDGER.mutation(get_pending_command_store()):
        MODEL_WORK.current().check()
        origin = current_task_artifact_origin()
        require_current_artifact_origin(origin, "pending_carry_policy")
        pending_store = get_pending_command_store()
        prepared = prepare_command_batch(command)
        policy = policy or evaluate_pending_command_policy(command, prepared)
        category = policy.get("category", "other")
        risk = policy.get("risk", "medium")
        rationale = policy.get("rationale", "assistant command")
        operating_context = policy.get("operating_context", "unknown")
        context_fingerprint = policy.get("context_fingerprint", "")
        expected_outcome = policy.get("expected_outcome", "the visible state should change")
        policy_reason = policy.get("policy_reason", reason)
        normalized_command = normalize_action_command(command).lower()
        timestamp = route_timestamp()
        current_turn = agent_state.inference_counter
        current_scene = normalize_text_content(runtime_state.get("gameplay_scene", "")).strip().lower() or "unknown"
        target_turn = current_turn + (PENDING_COMMAND_SUPPORT_WINDOW - 1)
        resolved_queue_mode = normalize_pending_queue_mode(
            queue_mode or policy.get("queue_mode") or DEFAULT_PENDING_QUEUE_MODE,
            fallback=DEFAULT_PENDING_QUEUE_MODE,
        )
        if resolved_queue_mode in {"replace", "insert"}:
            target_turn = current_turn + 1
        identity = build_semantic_command_identity(command, operating_context=operating_context)
        family_key = identity.get("family_key", normalized_command)
        conflict_key = identity.get("conflict_key", "")

        if any(not pending_entry_available(row) and row.get("operating_context", "unknown") == operating_context
               and row.get("family_key") == family_key for row in pending_store):
            raise ValueError("This pending family is reserved, uncertain or held for an operator; inspect it before proposing a replacement.")

        supersede_conflicting_pending_entries(
            pending_store,
            identity,
            operating_context,
            command,
            source,
            associated_goal,
        )

        matching_entry = None
        for existing_entry in reversed(pending_store):
            if not pending_entry_available(existing_entry):
                continue
            if existing_entry.get("operating_context", "unknown") != operating_context:
                continue
            if existing_entry.get("family_key") != family_key:
                continue
            matching_entry = existing_entry
            break

        if matching_entry is not None:
            replace_representative = should_replace_pending_representative(matching_entry, command, policy)
            if not replace_representative:
                representative_policy = evaluate_pending_command_policy(
                    matching_entry.get("command", ""), matching_entry.get("_prepared_commands"))
                category = representative_policy.get("category", category)
                risk = representative_policy.get("risk", risk)
                rationale = representative_policy.get("rationale", rationale)
                policy_reason = representative_policy.get("policy_reason", policy_reason)
                expected_outcome = representative_policy.get("expected_outcome", expected_outcome)
            matching_entry["last_seen"] = timestamp
            matching_entry["last_seen_inference"] = current_turn
            matching_entry["repeat_count"] = matching_entry.get("repeat_count", 1) + 1
            matching_entry["support_count"] = matching_entry.get("support_count", 1) + 1
            matching_entry["reason"] = reason
            matching_entry["risk"] = risk
            matching_entry["category"] = category
            matching_entry["rationale"] = rationale
            matching_entry["policy_reason"] = policy_reason
            matching_entry["expected_outcome"] = expected_outcome
            matching_entry["operating_context"] = operating_context
            matching_entry["context_fingerprint"] = context_fingerprint or matching_entry.get("context_fingerprint", "")
            matching_entry["family_key"] = family_key
            matching_entry["conflict_key"] = conflict_key
            matching_entry["semantic_label"] = identity.get("semantic_label", matching_entry.get("semantic_label", family_key))
            matching_entry["queue_mode"] = resolved_queue_mode
            matching_entry["scene"] = current_scene
            matching_entry["superseded_by"] = ""
            matching_entry["contradicted_by"] = ""
            if replace_representative:
                matching_entry["command"] = command
                matching_entry["_prepared_commands"] = prepared
                matching_entry["history_actor"] = current_history_actor()
                matching_entry["task_origin"] = origin
            if resolved_queue_mode == "replace":
                replace_immediate_pending_entries(
                    pending_store,
                    target_turn,
                    operating_context,
                    matching_entry.get("command", command),
                    source,
                    associated_goal,
                    family_key=family_key,
                )
                matching_entry["execute_by_inference"] = target_turn
                matching_entry["queue_status"] = "repositioned"
            elif resolved_queue_mode == "insert":
                shift_pending_entries_for_insert(
                    pending_store,
                    target_turn,
                    operating_context,
                    matching_entry.get("command", command),
                    source,
                    associated_goal,
                    family_key=family_key,
                )
                matching_entry["execute_by_inference"] = target_turn
                matching_entry["queue_status"] = "repositioned"
            else:
                matching_entry["execute_by_inference"] = matching_entry.get("first_seen_inference", current_turn) + (PENDING_COMMAND_SUPPORT_WINDOW - 1)
                matching_entry["queue_status"] = "supported_existing"
            matching_entry["turns_until_due"] = max(0, matching_entry["execute_by_inference"] - current_turn)
            apply_pending_entry_scores(matching_entry, current_turn=current_turn)
            append_recent_command_proposal(
                matching_entry.get("command", command),
                source=source,
                associated_goal=associated_goal,
                disposition="supported_family",
                support_count=matching_entry["support_count"],
                execute_by_inference=matching_entry["execute_by_inference"],
            )
            append_recent_action_intent(
                f"Supported pending command family {family_key}: {matching_entry.get('command', command)}",
                status="supported",
                command=matching_entry.get("command", command),
                source=source,
                associated_goal=associated_goal,
                execute_by_inference=matching_entry["execute_by_inference"],
            )
            append_runtime_feedback(
                f"Supported pending {family_key} in {operating_context} context: {matching_entry.get('command', command)}"
            )
            return matching_entry

        entry = {
            "timestamp": timestamp,
            "command": command,
            "_prepared_commands": prepared,
            "history_actor": current_history_actor(),
            "task_origin": origin,
            "associated_goal": associated_goal,
            "source": source,
            "mode": EXECUTION_MODE,
            "reason": reason,
            "category": category,
            "risk": risk,
            "rationale": rationale,
            "policy_reason": policy_reason,
            "operating_context": operating_context,
            "scene": current_scene,
            "context_fingerprint": context_fingerprint,
            "family_key": family_key,
            "conflict_key": conflict_key,
            "semantic_label": identity.get("semantic_label", family_key),
            "superseded_by": "",
            "contradicted_by": "",
            "expected_outcome": expected_outcome,
            "repeat_count": 1,
            "support_count": 1,
            "first_seen_inference": current_turn,
            "last_seen_inference": current_turn,
            "execute_by_inference": target_turn,
            "turns_until_due": max(0, target_turn - current_turn),
            "queue_status": "queued",
            "queue_mode": resolved_queue_mode,
        }
        apply_pending_entry_scores(entry, current_turn=current_turn)

        if resolved_queue_mode == "replace":
            replace_immediate_pending_entries(
                pending_store,
                target_turn,
                operating_context,
                command,
                source,
                associated_goal,
                family_key=family_key,
            )
        elif resolved_queue_mode == "insert":
            shift_pending_entries_for_insert(
                pending_store,
                target_turn,
                operating_context,
                command,
                source,
                associated_goal,
                family_key=family_key,
            )

        pending_store.append(entry)
        while len(pending_store) > MAX_PENDING_MODEL_COMMANDS:
            removable = next((index for index, row in enumerate(pending_store)
                              if row is not entry and pending_entry_available(row)), None)
            if removable is None:
                raise ValueError("Pending capacity is occupied by reserved, uncertain or task-held items; inspect and clear them explicitly.")
            pending_store.pop(removable)
        PENDING_COMMAND_LEDGER.ensure_identities(pending_store)
        append_recent_command_proposal(
            command,
            source=source,
            associated_goal=associated_goal,
            disposition="queued",
            support_count=entry["support_count"],
            execute_by_inference=entry["execute_by_inference"],
        )
        append_recent_action_intent(
            f"Queued pending command: {command}",
            status="queued",
            command=command,
            source=source,
            associated_goal=associated_goal,
            execute_by_inference=entry["execute_by_inference"],
        )
        append_runtime_feedback(
            f"Held {source} command ({risk}/{category}, mode={resolved_queue_mode}, family={family_key}, context={operating_context}): {command}"
        )
        return entry


def route_assistant_commands(command_text, associated_goal="No specific goal", source="assistant", why="", thought=""):
    MODEL_WORK.current().check()
    execution_mode = EXECUTION_MODE.lower()
    executable_commands = []
    held_commands = []
    rejected_commands = []
    suppressed_count = 0
    operating_context = infer_operating_context().get("context", "unknown")

    try:
        proposals = split_command_batch(command_text)
        has_task_control = False
        for proposal in proposals:
            probe = proposal
            for _ in range(33):
                name = get_command_name(probe).upper()
                if name in TASK_CONTROL_COMMANDS:
                    has_task_control = True
                    break
                if name not in PENDING_WRAPPER_MODES:
                    break
                nested_args = extract_command_arguments(probe)
                if not nested_args:
                    break
                probe = nested_args[0]
        if has_task_control:
            # Do not split an invalid mixed control/action batch into separate
            # proposals or unwrap a pending control before validating it.
            prepare_command_batch(command_text)
        elif TASK_CONTINUATION_MODE == "bounded" and not TASK_CONTINUATION.check_deadline():
            raise CommandSyntaxError("Bounded task stopped; automatic proposals cannot execute or enter the pending queue.")
    except (CommandSyntaxError, ValueError) as error:
        append_runtime_feedback(f"Rejected malformed {source} command batch: {error}")
        return {"executed_entry": None, "held_commands": [], "rejected_commands": [
                    {"command": command_text, "reason": str(error), "context": operating_context}],
                "executed_count": 0, "held_count": 0, "rejected_count": 1, "suppressed_count": 0}

    for command in proposals:
        try:
            directive_info = infer_pending_queue_directive(command)
            normalized_command = normalize_memory_item(directive_info.get("command") or command)
            queue_mode = directive_info.get("queue_mode")
            if not normalized_command or is_non_action_command_text(normalized_command):
                continue
            prepared_proposal = prepare_command_batch(normalized_command)
        except (ValueError, CommandSyntaxError) as error:
            rejected_commands.append({"command": command, "reason": str(error), "context": operating_context})
            append_runtime_feedback(f"Rejected malformed {source} proposal: {error}")
            continue
        if not normalized_command:
            continue
        if is_non_action_command_text(normalized_command):
            continue
        append_recent_command_proposal(
            normalized_command,
            source=source,
            associated_goal=associated_goal,
            disposition='considered',
            execute_by_inference=agent_state.inference_counter + (PENDING_COMMAND_SUPPORT_WINDOW - 1),
        )
        policy = evaluate_pending_command_policy(normalized_command, prepared_proposal)
        command_category = policy.get("category", classify_assistant_command(normalized_command))
        decision = policy.get("decision", "hold")

        if decision == "reject":
            append_recent_action_intent(
                f"Rejected command: {normalized_command}",
                status='rejected',
                command=normalized_command,
                source=source,
                associated_goal=associated_goal,
            )
            rejected_commands.append({
                'command': normalized_command,
                'reason': policy.get('policy_reason', 'rejected by policy'),
                'context': policy.get('operating_context', 'unknown'),
            })
            append_runtime_feedback(
                f"Rejected {source} command in {policy.get('operating_context', 'unknown')} context: "
                f"{normalized_command} ({policy.get('policy_reason', 'rejected by policy')})"
            )
            append_command_drip_item(
                agent_state.inference_counter,
                "rejected",
                build_command_drip_item(
                    command=normalized_command,
                    status="rejected",
                    reason=policy.get('policy_reason', 'rejected by policy'),
                    category=policy.get("category", ""),
                    risk=policy.get("risk", ""),
                    associated_goal=associated_goal,
                    source=source,
                    expected_outcome=policy.get("expected_outcome", ""),
                    family_key=policy.get("family_key", ""),
                    conflict_key=policy.get("conflict_key", ""),
                    note="policy rejected this candidate before queueing",
                ),
            )
            continue

        should_execute = (
            queue_mode is None
            and decision == "allow"
            and (
                policy.get("task_control", False)
                or execution_mode == "auto"
                or (execution_mode == "assist" and (command_category == "memory" or policy.get("one_turn_reasoning", False)))
            )
        )

        hold_reason = policy.get('policy_reason', 'held for review')
        if decision == "allow" and not should_execute:
            hold_reason = f"allowed by policy but held in {EXECUTION_MODE} mode ({command_category})"

        if should_execute:
            supersede_conflicting_pending_entries(
                get_pending_command_store(),
                build_semantic_command_identity(
                    normalized_command,
                    operating_context=policy.get("operating_context", operating_context),
                ),
                policy.get("operating_context", operating_context),
                normalized_command,
                source,
                associated_goal,
            )
            append_recent_action_intent(
                f"Executing command: {normalized_command}",
                status='executing',
                command=normalized_command,
                source=source,
                associated_goal=associated_goal,
            )
            append_command_drip_item(
                agent_state.inference_counter,
                "selected",
                build_command_drip_item(
                    command=normalized_command,
                    status="selected",
                    reason=policy.get("policy_reason", "selected for execution"),
                    category=policy.get("category", ""),
                    risk=policy.get("risk", ""),
                    associated_goal=associated_goal,
                    source=source,
                    expected_outcome=policy.get("expected_outcome", ""),
                    family_key=policy.get("family_key", ""),
                    conflict_key=policy.get("conflict_key", ""),
                    execute_by_inference=agent_state.inference_counter,
                    turns_until_due=0,
                    queue_mode="current",
                    priority_score=12,
                    importance_score=12,
                    note="selected to execute on the current turn",
                ),
            )
            executable_commands.append(normalized_command)
        else:
            try:
                pending_entry = queue_pending_model_command(
                    normalized_command,
                    associated_goal=associated_goal,
                    source=source,
                    reason=hold_reason,
                    policy=policy,
                    queue_mode=queue_mode,
                )
            except (ValueError, CommandSyntaxError) as error:
                rejected_commands.append({"command": normalized_command, "reason": str(error), "context": operating_context})
                append_runtime_feedback(f"Rejected pending proposal: {error}")
                continue
            if pending_entry.get('queue_status') in {'queued', 'supported_existing', 'repositioned', 'deferred'}:
                held_commands.append(pending_entry)
                append_command_drip_note(
                    agent_state.inference_counter,
                    f"Held for future review: {sanitize_sensitive_command_text(normalized_command)} "
                    f"(due turn {pending_entry.get('execute_by_inference', '?')})"
                )
                if pending_entry.get('queue_status') in {'supported_existing', 'repositioned', 'deferred'}:
                    append_command_drip_item(
                        agent_state.inference_counter,
                        "selected",
                        build_command_drip_item(
                            command=pending_entry.get("command", normalized_command),
                            status=pending_entry.get("queue_status", "queued"),
                            reason=pending_entry.get("reason", hold_reason),
                            category=pending_entry.get("category", ""),
                            risk=pending_entry.get("risk", ""),
                            associated_goal=associated_goal,
                            source=source,
                            expected_outcome=pending_entry.get("expected_outcome", ""),
                            family_key=pending_entry.get("family_key", ""),
                            conflict_key=pending_entry.get("conflict_key", ""),
                            support_count=pending_entry.get("support_count", 1),
                            repeat_count=pending_entry.get("repeat_count", 1),
                            execute_by_inference=pending_entry.get("execute_by_inference"),
                            turns_until_due=pending_entry.get("turns_until_due"),
                            queue_mode=pending_entry.get("queue_mode", DEFAULT_PENDING_QUEUE_MODE),
                            priority_score=pending_entry.get("priority_score", 0),
                            importance_score=pending_entry.get("importance_score", 0),
                            note="strengthened or repositioned existing held candidate",
                        ),
                    )
            else:
                suppressed_count += 1
                append_command_drip_item(
                    agent_state.inference_counter,
                    "dropped",
                    build_command_drip_item(
                        command=normalized_command,
                        status="suppressed",
                        reason="duplicate or stronger family candidate already present",
                        category=policy.get("category", ""),
                        risk=policy.get("risk", ""),
                        associated_goal=associated_goal,
                        source=source,
                        expected_outcome=policy.get("expected_outcome", ""),
                        family_key=policy.get("family_key", ""),
                        conflict_key=policy.get("conflict_key", ""),
                        execute_by_inference=pending_entry.get("execute_by_inference"),
                        turns_until_due=pending_entry.get("turns_until_due"),
                        support_count=pending_entry.get("support_count", 1),
                        repeat_count=pending_entry.get("repeat_count", 1),
                        queue_mode=pending_entry.get("queue_mode", DEFAULT_PENDING_QUEUE_MODE),
                        priority_score=pending_entry.get("priority_score", 0),
                        importance_score=pending_entry.get("importance_score", 0),
                        note="close variant did not become the active held candidate",
                    ),
                )

    executed_entry = None
    if executable_commands:
        first_command = executable_commands[0]
        first_policy = evaluate_assistant_command_policy(first_command)
        executed_entry = enqueue_or_execute_command(
            '; '.join(executable_commands),
            is_user=False,
            associated_goal=associated_goal,
            why=why,
            thought=thought,
            source=source,
            expected_outcome=first_policy.get('expected_outcome', ''),
            family_key=first_policy.get('family_key', ''),
            conflict_key=first_policy.get('conflict_key', ''),
            execution_operating_context=first_policy.get('operating_context', 'unknown'),
            semantic_label=first_policy.get('semantic_label', ''),
        )

    if held_commands:
        held_count = len(held_commands)
        display_message(
            'system',
            f"Held {held_count} assistant command{'s' if held_count != 1 else ''} for review. "
            f"Use SHOW_PENDING_COMMANDS() or APPROVE_PENDING(...)."
        )
    if suppressed_count:
        display_message(
            'system',
            f"Suppressed {suppressed_count} repeated held assistant command{'s' if suppressed_count != 1 else ''} "
            f"because the inferred {operating_context} context has not changed."
        )
    if rejected_commands:
        display_message(
            'system',
            f"Rejected {len(rejected_commands)} assistant command{'s' if len(rejected_commands) != 1 else ''} "
            f"that do not fit the inferred {operating_context} context."
        )

    set_runtime_value(
        'last_policy_summary',
        summarize_runtime_text(
            f"context={operating_context}; executed={len(executable_commands)}; "
            f"held={len(held_commands)}; rejected={len(rejected_commands)}; suppressed={suppressed_count}"
        )
    )

    return {
        'executed_entry': executed_entry,
        'held_commands': held_commands,
        'rejected_commands': rejected_commands,
        'executed_count': len(executable_commands),
        'held_count': len(held_commands),
        'rejected_count': len(rejected_commands),
        'suppressed_count': suppressed_count,
    }


def ingest_command_result(action_entry, shared_recent_executed_actions=None):
    if shared_recent_executed_actions is not None:
        agent_state.recent_executed_actions[:] = list(shared_recent_executed_actions)
    else:
        append_recent_executed_action(
            action_entry.get('action', ''),
            action_entry.get('timestamp', datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')),
            action_entry.get('associated_goal', 'No specific goal'),
            why=action_entry.get('why', ''),
            thought=action_entry.get('thought', ''),
            expected_outcome=action_entry.get('expected_outcome', ''),
            family_key=action_entry.get('family_key', ''),
            conflict_key=action_entry.get('conflict_key', ''),
            semantic_label=action_entry.get('semantic_label', ''),
            execution_operating_context=action_entry.get('execution_operating_context', ''),
            execution_context_fingerprint=action_entry.get('execution_context_fingerprint', ''),
            execution_image_hash=action_entry.get('execution_image_hash', ''),
            executed_inference_turn=action_entry.get('executed_inference_turn', agent_state.inference_counter),
            outcome_status=action_entry.get('outcome_status', 'pending'),
            outcome_score=action_entry.get('outcome_score', 0),
      last_outcome_evaluated_turn=action_entry.get('last_outcome_evaluated_turn'),
      outcome_note=action_entry.get('outcome_note', ''),
      )
    worker_last_key = normalize_text_content(action_entry.get("worker_last_key", "")).strip()
    worker_last_command = normalize_text_content(action_entry.get("worker_last_command", "")).strip()
    worker_input_backend = normalize_text_content(action_entry.get("worker_input_backend", "")).strip()
    worker_foreground_window = normalize_text_content(action_entry.get("worker_foreground_window", "")).strip()
    if worker_last_key:
        set_last_key_value(worker_last_key)
    if worker_last_command:
        set_last_command_value(worker_last_command)
    if worker_input_backend:
        set_runtime_value("last_input_backend", worker_input_backend)
    if worker_foreground_window:
        set_runtime_value("last_foreground_window", worker_foreground_window)
    for runtime_key, action_key in (
        ("gameplay_visibility", "worker_gameplay_visibility"),
        ("gameplay_visibility_reason", "worker_gameplay_visibility_reason"),
        ("last_game_input_attempt_at_epoch", "worker_last_game_input_attempt_at_epoch"),
        ("last_game_input_command", "worker_last_game_input_command"),
        ("last_game_input_effective_key", "worker_last_game_input_effective_key"),
        ("last_game_input_focus_ok", "worker_last_game_input_focus_ok"),
        ("last_game_input_focus_reason", "worker_last_game_input_focus_reason"),
        ("last_game_focus_recovery_at_epoch", "worker_last_game_focus_recovery_at_epoch"),
        ("last_game_focus_recovery_summary", "worker_last_game_focus_recovery_summary"),
    ):
        if action_key in action_entry:
            set_runtime_value(runtime_key, action_entry.get(action_key))
    set_runtime_value("last_command_duration_ms", int(action_entry.get("total_command_duration_ms", 0) or 0))
    set_runtime_value("last_command_count", len(action_entry.get("executed_commands", []) or []))
    append_recent_action_intent(
        f"Command {action_entry.get('status', 'processed')}: {sanitize_sensitive_command_text(action_entry.get('action', ''))}",
        status=action_entry.get('status', 'processed'),
        command=sanitize_sensitive_command_text(action_entry.get('action', '')),
        source=action_entry.get('source', 'unknown'),
        associated_goal=action_entry.get('associated_goal', 'No specific goal'),
    )

    source = action_entry.get('source', 'unknown')
    action = action_entry.get('action', '')
    request_id = normalize_text_content(action_entry.get('request_id', '')).strip()
    message_id = normalize_text_content(action_entry.get('message_id', '')).strip()
    client_id = normalize_text_content(action_entry.get('client_id', '')).strip()
    mutation_admission_id = normalize_text_content(
        action_entry.get('mutation_admission_id', '')
    ).strip()
    command_digest = normalize_text_content(action_entry.get('command_digest', '')).strip()
    display_action = sanitize_sensitive_command_text(action)
    status = action_entry.get('status', 'processed')
    executed_turn = action_entry.get('executed_inference_turn', agent_state.inference_counter)
    executed_commands = action_entry.get('executed_commands', [action] if action and status == 'processed' else [])
    failed_commands = action_entry.get('failed_commands', []) or []
    primary_lane = "executed" if status == "processed" else "failed"
    append_command_drip_item(
        executed_turn,
        primary_lane,
        build_command_drip_item(
            command=action,
            status=status,
            reason=f"{status} via {source}",
            associated_goal=action_entry.get('associated_goal', 'No specific goal'),
            source=source,
            expected_outcome=action_entry.get('expected_outcome', ''),
            family_key=action_entry.get('family_key', ''),
            conflict_key=action_entry.get('conflict_key', ''),
            note=f"expanded={len(action_entry.get('expanded_commands', []) or [])}, executed={len(executed_commands)}, failed={len(failed_commands)}",
            metadata={
                "executed_commands": executed_commands,
                "failed_commands": failed_commands,
                "command_timings": action_entry.get('command_timings', []),
                "settings_transaction_receipts": action_entry.get('settings_transaction_receipts', []),
                "setting_results": action_entry.get('setting_results', []),
                "lock_results": action_entry.get('lock_results', []),
                "inference_plan_results": action_entry.get("inference_plan_results", []),
                "default_profile_results": action_entry.get("default_profile_results", []),
                "pending_command_results": action_entry.get("pending_command_results", []),
                "history_command_results": action_entry.get("history_command_results", []),
                "retrieval_results": action_entry.get("retrieval_results", []),
                "goal_file_results": action_entry.get("goal_file_results", []),
                "memory_command_results": action_entry.get("memory_command_results", []),
                "task_control_results": action_entry.get("task_control_results", []),
                "observation_results": action_entry.get("observation_results", []),
                "task_budget_results": action_entry.get("task_budget_results", []),
                "desktop_results": action_entry.get('desktop_results', []),
                "input_cleanup_results": action_entry.get("input_cleanup_results", []),
                "held_input_results": action_entry.get("held_input_results", []),
                "blocked_commands": action_entry.get('blocked_commands', []),
            },
        ),
    )
    for failed in failed_commands:
        append_command_drip_item(
            executed_turn,
            "failed",
            build_command_drip_item(
                command=failed.get("command", ""),
                status="failed",
                reason=failed.get("reason", "command failed"),
                associated_goal=action_entry.get('associated_goal', 'No specific goal'),
                source=source,
                family_key=action_entry.get('family_key', ''),
                conflict_key=action_entry.get('conflict_key', ''),
                note="sub-command failed inside the executed batch",
            ),
        )
    set_runtime_value('last_command_status', summarize_runtime_text(f"{status} via {source}: {display_action}"))
    append_runtime_feedback(f"{status} via {source}: {display_action}")
    command_receipt = write_command_execution_log(
        "command_result",
        receipt_schema_version=COMMAND_RECEIPT_SCHEMA_VERSION,
        receipt_id=f"receipt-{request_id}" if request_id else "receipt-" + action_entry.get("command_batch_id", ""),
        command_batch_id=action_entry.get("command_batch_id", ""),
        task_id=action_entry.get("task_id", ""),
        inference_request_id=action_entry.get("inference_request_id", ""),
        request_id=request_id,
        message_id=message_id,
        client_id=client_id,
        mutation_admission_schema_version=(
            MUTATION_ADMISSION_SCHEMA_VERSION if mutation_admission_id else ""
        ),
        mutation_admission_id=mutation_admission_id,
        admission_status="terminal" if mutation_admission_id else "",
        command_digest=command_digest,
        duplicate_suppressed=False,
        replay_attempted=False,
        replayed=False,
        command=action,
        source=source,
        status=status,
        outcome_status=status,
        delivery_status="completed",
        terminal=True,
        cancelled_commands=action_entry.get('cancelled_commands', []),
        cancellation_reason=action_entry.get('cancellation_reason', ''),
        command_generation=action_entry.get('command_generation'),
        is_user=action_entry.get('is_user', False),
        associated_goal=action_entry.get('associated_goal', 'No specific goal'),
        expected_outcome=action_entry.get('expected_outcome', ''),
        family_key=action_entry.get('family_key', ''),
        conflict_key=action_entry.get('conflict_key', ''),
        semantic_label=action_entry.get('semantic_label', ''),
        execution_operating_context=action_entry.get('execution_operating_context', ''),
        execution_context_fingerprint=action_entry.get('execution_context_fingerprint', ''),
        execution_image_hash=action_entry.get('execution_image_hash', ''),
        executed_inference_turn=executed_turn,
  expanded_commands=action_entry.get('expanded_commands', []),
  executed_commands=action_entry.get('executed_commands', []),
  failed_commands=action_entry.get('failed_commands', []),
  command_timings=action_entry.get('command_timings', []),
  settings_transaction_receipts=action_entry.get('settings_transaction_receipts', []),
  setting_results=action_entry.get('setting_results', []),
  lock_results=action_entry.get('lock_results', []),
  inference_plan_results=action_entry.get('inference_plan_results', []),
  default_profile_results=action_entry.get('default_profile_results', []),
  pending_command_results=action_entry.get('pending_command_results', []),
  history_command_results=action_entry.get('history_command_results', []),
  retrieval_results=action_entry.get('retrieval_results', []),
  goal_file_results=action_entry.get('goal_file_results', []),
  memory_command_results=action_entry.get('memory_command_results', []),
  task_control_results=action_entry.get('task_control_results', []),
  observation_results=action_entry.get('observation_results', []),
  task_budget_results=action_entry.get('task_budget_results', []),
  pending_id=action_entry.get('pending_id', ''),
  pending_attempt_id=action_entry.get('pending_attempt_id', ''),
  desktop_results=action_entry.get('desktop_results', []),
  capture_batch=action_entry.get('capture_batch', {}),
  input_cleanup_results=action_entry.get('input_cleanup_results', []),
  held_input_results=action_entry.get('held_input_results', []),
  blocked_commands=action_entry.get('blocked_commands', []),
  total_command_duration_ms=action_entry.get('total_command_duration_ms', 0),
  last_key=worker_last_key or get_last_key_value(),
  last_command=worker_last_command or get_last_command_value(),
  input_backend=worker_input_backend or runtime_state.get('last_input_backend', ''),
        foreground_window=worker_foreground_window or runtime_state.get('last_foreground_window', ''),
        gameplay_visibility=runtime_state.get('gameplay_visibility', ''),
        gameplay_visibility_reason=runtime_state.get('gameplay_visibility_reason', ''),
        last_game_input_command=runtime_state.get('last_game_input_command', ''),
        last_game_input_effective_key=runtime_state.get('last_game_input_effective_key', ''),
        last_game_focus_recovery_summary=runtime_state.get('last_game_focus_recovery_summary', ''),
        mouse_position=getattr(agent_state, 'mouse_position', {}),
    )
    if mutation_admission_id:
        record_mutation_terminal_result(command_receipt)
    TASK_CONTINUATION.record_command(command_receipt)
    if READBACK_SCOPE == "reviewed" and TASK_CONTINUATION_MODE == "bounded":
        COMMAND_READBACKS.publish(command_receipt)
    if not action_entry.get('is_user', False) and status == 'processed':
        executed_commands = sanitize_sensitive_payload(executed_commands)
        display_message(
            'system',
            f"Model command executed successfully: {summarize_command_batch(executed_commands)}"
        )


def build_outcome_observation_text(section_items=None, narrative_text=""):
    parts = []
    if isinstance(section_items, dict):
        for key in (
            "recent_context", "route_blockers", "recent_movement_results",
            "current_area", "target_area", "travel_heading", "last_landmark"
        ):
            raw_items = section_items.get(key, []) or []
            if isinstance(raw_items, (str, bytes)):
                raw_items = [raw_items]
            for item in raw_items:
                cleaned = normalize_memory_item(item)
                if cleaned:
                    parts.append(cleaned)
    elif isinstance(section_items, (list, tuple, set)):
        for item in section_items:
            cleaned = normalize_memory_item(item)
            if cleaned:
                parts.append(cleaned)
    elif section_items:
        cleaned = normalize_memory_item(section_items)
        if cleaned:
            parts.append(cleaned)
    for item in agent_state.recent_context_events[-4:]:
        cleaned = normalize_memory_item(item)
        if cleaned:
            parts.append(cleaned)
    for item in agent_state.route_state.get("recent_movement_results", [])[-3:]:
        cleaned = normalize_memory_item(item)
        if cleaned:
            parts.append(cleaned)
    if narrative_text:
        parts.append(summarize_runtime_text(narrative_text, max_chars=220))
    return " | ".join(parts).lower()


def observation_contains_any(observation_text, keywords):
    if not observation_text:
        return False
    return any(keyword in observation_text for keyword in keywords)


def infer_action_outcome(entry, observation_text, image_changed, context_changed):
    family_key = entry.get("family_key", "")
    conflict_key = entry.get("conflict_key", "")
    operating_context = entry.get("execution_operating_context", "") or runtime_state.get("operating_context", "unknown")
    category = classify_assistant_command(entry.get("action", ""))

    blocked_signal = observation_contains_any(observation_text, OUTCOME_BLOCKED_KEYWORDS)
    no_change_signal = observation_contains_any(observation_text, OUTCOME_NO_CHANGE_KEYWORDS)
    progress_signal = (
        image_changed
        or context_changed
        or (
            observation_contains_any(observation_text, OUTCOME_PROGRESS_KEYWORDS)
            and not no_change_signal
        )
    )
    terminal_output_signal = observation_contains_any(observation_text, TERMINAL_OUTPUT_PROGRESS_KEYWORDS)
    terminal_interrupt_signal = observation_contains_any(observation_text, TERMINAL_INTERRUPT_PROGRESS_KEYWORDS)
    save_success_signal = observation_contains_any(observation_text, SAVE_SUCCESS_KEYWORDS)
    save_failure_signal = observation_contains_any(observation_text, SAVE_FAILURE_KEYWORDS)
    text_entry_success_signal = observation_contains_any(observation_text, TEXT_ENTRY_SUCCESS_KEYWORDS)
    text_entry_failure_signal = observation_contains_any(observation_text, TEXT_ENTRY_FAILURE_KEYWORDS)
    viewport_shift_signal = observation_contains_any(observation_text, VIEWPORT_SHIFT_KEYWORDS)
    pointer_change_signal = observation_contains_any(observation_text, POINTER_CHANGE_KEYWORDS)
    pointer_failure_signal = observation_contains_any(observation_text, POINTER_FAILURE_KEYWORDS)
    focus_change_signal = observation_contains_any(observation_text, FOCUS_CHANGE_KEYWORDS)

    if category == "memory":
        return "memory_applied", 1, "Memory command applied internally."

    if family_key.startswith("game-move:"):
        movement_progress_signal = progress_signal or observation_contains_any(observation_text, GAME_MOVEMENT_PROGRESS_KEYWORDS)
        movement_blocked_signal = observation_contains_any(observation_text, GAME_MOVEMENT_BLOCKED_KEYWORDS) or (blocked_signal and no_change_signal)
        if movement_progress_signal and not movement_blocked_signal:
            return "likely_progress", 1, "Visual state changed after the movement command."
        if movement_blocked_signal:
            return "likely_failed", -1, "Recent observations suggest movement was blocked."
        if no_change_signal:
            return "no_visible_change", 0, "No clear movement result is visible yet."
        return "unclear", 0, "Movement outcome needs another screenshot to confirm."

    if family_key == "terminal:submit":
        if terminal_output_signal or progress_signal:
            return "likely_progress", 1, "Terminal output or prompt state changed after submit."
        if blocked_signal and no_change_signal:
            return "likely_failed", -1, "Terminal submit appears to have left the shell unchanged."
        if no_change_signal:
            return "no_visible_change", 0, "No new terminal output is visible yet."
        return "unclear", 0, "Terminal submit needs another screenshot to confirm."

    if family_key == "terminal:interrupt":
        if terminal_interrupt_signal or progress_signal:
            return "likely_progress", 1, "Terminal interrupt appears to have changed the running task."
        if no_change_signal:
            return "no_visible_change", 0, "No clear interrupt effect is visible yet."
        if blocked_signal:
            return "likely_failed", -1, "Terminal interrupt still looks blocked."
        return "unclear", 0, "Terminal interrupt needs another screenshot to confirm."

    if family_key == "editor:save" or conflict_key == "hotkey-family:save":
        if save_failure_signal:
            return "likely_failed", -1, "The editor or application reported a save failure."
        if save_success_signal:
            return "likely_progress", 1, "The application reported a successful save."
        if no_change_signal and not progress_signal:
            return "no_visible_change", 0, "No save confirmation is visible yet."
        if progress_signal:
            return "likely_progress", 1, "The editor state changed after the save shortcut."
        return "unclear", 0, "Save outcome needs another screenshot to confirm."

    if family_key.startswith("type:text-entry"):
        if text_entry_failure_signal:
            return "likely_failed", -1, "The requested text does not appear to have been entered."
        if text_entry_success_signal or progress_signal:
            return "likely_progress", 1, "New text or field content is visible after text entry."
        if no_change_signal:
            return "no_visible_change", 0, "No new text is visible yet."
        return "unclear", 0, "Text-entry outcome needs another screenshot to confirm."

    if family_key.startswith("viewport:"):
        if viewport_shift_signal or progress_signal:
            return "likely_progress", 1, "The viewport appears to have moved."
        if blocked_signal:
            return "likely_failed", -1, "The viewport did not move as expected."
        if no_change_signal:
            return "no_visible_change", 0, "No visible scroll effect is confirmed yet."
        return "unclear", 0, "Viewport movement needs another screenshot to confirm."

    if family_key.startswith("pointer:") or family_key == "focus:tab" or family_key in {"key:enter", "key:space"}:
        if pointer_change_signal or focus_change_signal or progress_signal:
            return "likely_progress", 1, "Focus or selection appears to have changed."
        if pointer_failure_signal or (blocked_signal and no_change_signal):
            return "likely_failed", -1, "The pointer or focus action does not appear to have taken effect."
        if no_change_signal:
            return "no_visible_change", 0, "No visible focus or selection change is confirmed yet."
        return "unclear", 0, "Pointer or focus action needs another screenshot to confirm."

    if family_key.startswith("key:") or family_key.startswith("hotkey:"):
        if progress_signal:
            return "likely_progress", 1, f"{operating_context.capitalize()} state changed after the key action."
        if blocked_signal:
            return "likely_failed", -1, "The key action appears blocked or ineffective."
        if no_change_signal:
            return "no_visible_change", 0, "No visible key-action effect is confirmed yet."
        return "unclear", 0, "Key-action outcome needs another screenshot to confirm."

    if progress_signal:
        return "likely_progress", 1, "Visual state changed after the action."
    if blocked_signal:
        return "likely_failed", -1, "Current observations indicate the action may not have succeeded."
    if no_change_signal:
        return "no_visible_change", 0, "No clear screenshot-level effect is visible yet."
    return "unclear", 0, "No strong evidence yet."


def adjust_pending_support_from_outcome(action_entry):
    with PENDING_COMMAND_LEDGER.mutation(get_pending_command_store()):
        pending_store = get_pending_command_store()
        family_key = action_entry.get("family_key", "")
        outcome_score = action_entry.get("outcome_score", 0)
        if not pending_store or not family_key:
            return

        if outcome_score > 0:
            for index in range(len(pending_store) - 1, -1, -1):
                entry = pending_store[index]
                if not pending_entry_available(entry):
                    continue
                if entry.get("family_key") != family_key:
                    continue
                removed = pending_store.pop(index)
                append_recent_command_proposal(
                    removed.get("command", ""),
                    source=removed.get("source", "assistant"),
                    associated_goal=removed.get("associated_goal", "No specific goal"),
                    disposition="resolved_after_success",
                    support_count=removed.get("support_count", 1),
                    execute_by_inference=removed.get("execute_by_inference"),
                )
                append_runtime_feedback(
                    f"Removed redundant pending command after successful outcome: {removed.get('command', '')}"
                )
        elif outcome_score < 0:
            for entry in pending_store:
                if not pending_entry_available(entry):
                    continue
                if entry.get("family_key") != family_key:
                    continue
                entry["support_count"] = max(1, int(entry.get("support_count", 1)) - 1)
                if isinstance(entry.get("execute_by_inference"), int):
                    entry["execute_by_inference"] += 1
                append_recent_command_proposal(
                    entry.get("command", ""),
                    source=entry.get("source", "assistant"),
                    associated_goal=entry.get("associated_goal", "No specific goal"),
                    disposition="downgraded_after_failure",
                    support_count=entry.get("support_count", 1),
                    execute_by_inference=entry.get("execute_by_inference"),
                )
            refresh_pending_command_estimates()


def score_recent_action_outcomes(section_items=None, narrative_text=""):
    current_turn = agent_state.inference_counter
    current_image_hash = runtime_state.get("last_image_hash", "")
    current_context_fingerprint = runtime_state.get("context_fingerprint", "")
    observation_text = build_outcome_observation_text(section_items, narrative_text)
    outcome_summaries = []
    current_scene = normalize_memory_item(runtime_state.get("gameplay_scene", "")).lower()

    for entry in agent_state.recent_executed_actions:
        executed_turn = entry.get("executed_inference_turn", current_turn)
        if executed_turn >= current_turn:
            continue
        if entry.get("outcome_status") in {"likely_progress", "likely_failed", "memory_applied"}:
            continue
        if entry.get("last_outcome_evaluated_turn") == current_turn:
            continue

        family_key = entry.get("family_key", "")
        category = classify_assistant_command(entry.get("action", ""))
        prior_image_hash = entry.get("execution_image_hash", "")
        prior_context_fingerprint = entry.get("execution_context_fingerprint", "")
        image_changed = bool(current_image_hash and prior_image_hash and current_image_hash != prior_image_hash)
        context_changed = bool(
            current_context_fingerprint and prior_context_fingerprint
            and current_context_fingerprint != prior_context_fingerprint
        )
        outcome_status, outcome_score, outcome_note = infer_action_outcome(
            entry,
            observation_text,
            image_changed,
            context_changed,
        )

        entry["outcome_status"] = outcome_status
        entry["outcome_score"] = outcome_score
        entry["outcome_note"] = outcome_note
        entry["last_outcome_evaluated_turn"] = current_turn
        adjust_pending_support_from_outcome(entry)
        append_recent_action_intent(
            f"Outcome {outcome_status}: {entry.get('action', '')}",
            status=outcome_status,
            command=entry.get("action", ""),
            source=entry.get("source", "unknown"),
            associated_goal=entry.get("associated_goal", "No specific goal"),
        )
        if outcome_status == "likely_failed":
            append_known_failure(
                f"{entry.get('action', '')} -> {outcome_note}",
                source="outcome_review",
                scene=current_scene,
                metadata={
                    "status": outcome_status,
                    "family_key": entry.get("family_key", ""),
                    "associated_goal": entry.get("associated_goal", ""),
                },
            )
            append_active_question(
                f"Why did `{entry.get('action', '')}` fail or produce no visible progress?",
                source="outcome_review",
                scene=current_scene,
                metadata={"family_key": entry.get("family_key", "")},
            )
            if str(entry.get("family_key", "")).startswith("game-move:"):
                append_candidate_alternative(
                    "Try a different single-step move or update route blockers before repeating the same movement.",
                    source="outcome_review",
                    scene=current_scene,
                    metadata={"family_key": entry.get("family_key", ""), "status": "candidate"},
                )
        elif outcome_status == "likely_progress" and str(entry.get("family_key", "")).startswith("game-move:"):
            append_stale_assumption(
                "Recent movement succeeded; stale blocked-path assumptions should be re-checked before they continue biasing future route choices.",
                source="outcome_review",
                scene=current_scene,
                metadata={"status": "review"},
            )
        outcome_summaries.append(f"{entry.get('action', '')} -> {outcome_status}")

    if outcome_summaries:
        summary = "; ".join(outcome_summaries[-3:])
        set_runtime_value("last_outcome_summary", summarize_runtime_text(summary, max_chars=180))
        append_runtime_feedback(f"Outcome review: {summary}")
    _prune_planning_store_by_turns(agent_state.active_questions, 20)
    _prune_planning_store_by_turns(agent_state.stale_assumptions, 30)
    _prune_planning_store_by_turns(agent_state.candidate_alternatives, 12)

# Function to process assistant's response
def process_assistant_response(response_text):
    global HIERARCHY_DISPATCH_ARMED
    executed_commands, tasks_section, section_items, narrative_text = split_response_sections(response_text)
    write_chat_history_log(
        "assistant_response_parsed",
        executed_commands=summarize_runtime_text(executed_commands, max_chars=260),
        tasks_present=bool(tasks_section),
        section_keys=sorted(list(section_items.keys())),
        narrative_summary=summarize_runtime_text(narrative_text, max_chars=260),
    )
    queued_command_set = {
        normalize_action_command(command).lower()
        for command in split_commands_preserving_parentheses(executed_commands)
        if normalize_memory_item(command) and not is_non_action_command_text(command)
    }

    if GAMEPLAY_SCENE_POLICY == "evidence":
        record_gameplay_scene_observation(section_items, narrative_text)
        refresh_gameplay_scene()
    score_recent_action_outcomes(section_items, narrative_text)
    outcome_attempt = any(get_command_name(command).upper() == "REPORT_TASK_OUTCOME"
                          for command in split_commands_preserving_parentheses(executed_commands))
    if not outcome_attempt and (TASK_CONTINUATION_MODE != "bounded" or TASK_CONTINUATION.check_deadline()):
        maybe_run_game_focus_recovery(section_items, narrative_text)

    # Handle executed commands
    if executed_commands:
        route_assistant_commands(executed_commands, associated_goal='No specific goal', source='assistant_response')

    # Update hierarchical tasks
    if tasks_section:
        with SETTINGS_TRANSACTION_LOCK, GOAL_LOCK:
            parse_hierarchical_tasks(tasks_section)
            sync_action_horizons_from_hierarchical_tasks()
            HIERARCHY_DISPATCH_ARMED = HIERARCHY_DISPATCH == "legacy"

    promote_response_memory(section_items, narrative_text)
    if tasks_section:
        promote_associated_goals_from_tasks()

    # Execute immediate actions from the updated tasks
    continue_actions = not outcome_attempt and (TASK_CONTINUATION_MODE != "bounded" or TASK_CONTINUATION.check_deadline())
    if continue_actions and HIERARCHY_DISPATCH == "legacy" and HIERARCHY_DISPATCH_ARMED and hierarchical_tasks and hierarchical_tasks[0]:
        immediate_actions = hierarchical_tasks[0]  # Level 1 actions
        execute_immediate_actions(immediate_actions, skip_commands=queued_command_set)

    if continue_actions and (TASK_CONTINUATION_MODE != "bounded" or TASK_CONTINUATION.check_deadline()):
        auto_execute_pending_commands()

    # Update pinned information
    update_pinned_information()



# Define the Goal class
# Goal is imported from aurora_goal_store; existing runtime.Goal callers remain supported.

def execute_immediate_actions(actions, skip_commands=None):
    skip_commands = skip_commands or set()
    for action in actions:
        with SETTINGS_TRANSACTION_LOCK:
            if HIERARCHY_DISPATCH != "legacy" or not HIERARCHY_DISPATCH_ARMED:
                break
            command = action.get('command')
            if command and not command.startswith('TBD'):
                normalized_command = normalize_action_command(command).lower()
                if normalized_command in skip_commands:
                    continue
                associated_goal = action.get('associated_goal', 'No specific goal')
                route_assistant_commands(
                    command,
                    associated_goal=associated_goal,
                    source='immediate_task',
                    why=action.get('why', ''),
                    thought=action.get('thought', '')
                )
            else:
                # Handle placeholders or general suggestions.
                continue



def summarize_hierarchical_action(item):
    payload = normalize_memory_item(item.get('command') or item.get('description') or item.get('type', ''))
    associated_goal = normalize_memory_item(item.get('associated_goal', ''))
    if payload and associated_goal and associated_goal.lower() not in {'no goal', 'no specific goal', 'none'}:
        return f"{payload} | goal={associated_goal}"
    return payload


def sync_action_horizons_from_hierarchical_tasks():
    if HORIZON_SYNC == "preserve":
        return
    immediate_items = []
    short_term_items = []
    mid_term_items = []
    long_term_items = []

    if hierarchical_tasks:
        immediate_items = [
            summary for summary in (
                summarize_hierarchical_action(item) for item in hierarchical_tasks[0]
            )
            if summary
        ]
    if len(hierarchical_tasks) > 1:
        short_term_items = [
            summary for summary in (
                summarize_hierarchical_action(item) for item in hierarchical_tasks[1]
            )
            if summary
        ]
    if len(hierarchical_tasks) > 2:
        mid_term_items = [
            summary for summary in (
                summarize_hierarchical_action(item) for item in hierarchical_tasks[2]
            )
            if summary
        ]
    if len(hierarchical_tasks) > 3:
        for level in hierarchical_tasks[3:]:
            for item in level:
                summary = summarize_hierarchical_action(item)
                if summary:
                    long_term_items.append(summary)

    with GOAL_LOCK:
        agent_state.pinned_immediate_actions[:] = dedupe_preserve_order(immediate_items)[:MAX_ROUTE_ITEMS]
        agent_state.pinned_short_term_actions[:] = dedupe_preserve_order(short_term_items)[:MAX_ROUTE_ITEMS]
        agent_state.mid_term_context[:] = dedupe_preserve_order(mid_term_items)[:MAX_MID_TERM_ITEMS]
        agent_state.long_term_context[:] = dedupe_preserve_order(long_term_items)[:MAX_LONG_TERM_ITEMS]
        horizon_identity_state()

def construct_hierarchical_tasks_text():
    tasks_text = "**Hierarchical Tasks with Immediate Actions:**\n\n"
    for level_num, level in enumerate(hierarchical_tasks, start=1):
        tasks_text += f"- **Level {level_num}**\n\n"
        for idx, item in enumerate(level, start=1):
            if 'command' in item:
                action_type = item.get('type', 'Action')
                tasks_text += f"  - **{action_type} {idx}**: `{item['command']}`\n"
                if item.get('why'):
                    tasks_text += f"    - **Why**: {item['why']}\n"
                if item.get('thought'):
                    tasks_text += f"    - **Thought**: {item['thought']}\n"
                tasks_text += f"    - **Priority**: {item.get('priority', 'No Priority')}\n"
                tasks_text += f"    - **Significance**: {item.get('significance', 'No Significance')}\n"
                tasks_text += f"    - **Associated Goal**: {item.get('associated_goal', 'No Goal')}\n"
                if item.get('notes'):
                    tasks_text += f"    - **Notes**: {item['notes']}\n"
            else:
                # Handle placeholders or general suggestions
                tasks_text += f"  - **Action {idx}**: {item.get('description', 'TBD')}\n"
                tasks_text += f"    - **Priority**: {item.get('priority', 'No Priority')}\n"
                tasks_text += f"    - **Significance**: {item.get('significance', 'No Significance')}\n"
                tasks_text += f"    - **Associated Goal**: {item.get('associated_goal', 'No Goal')}\n"
                if item.get('why'):
                    tasks_text += f"    - **Why**: {item['why']}\n"
                if item.get('thought'):
                    tasks_text += f"    - **Thought**: {item['thought']}\n"
                if item.get('notes'):
                    tasks_text += f"    - **Notes**: {item['notes']}\n"
        tasks_text += "\n"
    return tasks_text




# Function to parse the hierarchical tasks
def parse_hierarchical_tasks(tasks_text):
    agent_state.hierarchical_tasks.clear()

    level_pattern = re.compile(r'^\s*[-*]?\s*\*\*Level\s+(\d+)\*\*', re.IGNORECASE)
    action_pattern = re.compile(r'^\s*[-*]?\s*\*\*(.+?)\s+(\d+)\*\*:\s*`?(.+?)`?\s*$', re.IGNORECASE)
    priority_pattern = re.compile(r'^\s*[-*]?\s*\*\*Priority\*\*:\s*(.+)$', re.IGNORECASE)
    significance_pattern = re.compile(r'^\s*[-*]?\s*\*\*Significance\*\*:\s*(.+)$', re.IGNORECASE)
    associated_goal_pattern = re.compile(r'^\s*[-*]?\s*\*\*Associated Goal\*\*:\s*(.+)$', re.IGNORECASE)
    why_pattern = re.compile(r'^\s*[-*]?\s*\*\*(Why|Reasoning)\*\*:\s*(.+)$', re.IGNORECASE)
    thought_pattern = re.compile(r'^\s*[-*]?\s*\*\*Thought\*\*:\s*(.+)$', re.IGNORECASE)
    notes_pattern = re.compile(r'^\s*[-*]?\s*\*\*Notes\*\*:\s*(.+)$', re.IGNORECASE)

    current_level = None
    current_action = None

    lines = tasks_text.strip().split('\n')
    for line in lines:
        level_match = level_pattern.match(line)
        if level_match:
            current_level = int(level_match.group(1))
            while len(agent_state.hierarchical_tasks) < current_level:
                agent_state.hierarchical_tasks.append([])
            current_action = None  # Reset current_action when a new level starts
            continue

        action_match = action_pattern.match(line)
        if action_match and current_level is not None:
            action_type = action_match.group(1).strip()
            payload = action_match.group(3).strip()
            current_action = {
                'type': action_type,
                'priority': 'No Priority',
                'significance': 'No Significance',
                'associated_goal': 'No Goal',
                'why': '',
                'thought': '',
                'notes': ''
            }
            if is_known_command(payload):
                current_action['command'] = payload
            else:
                current_action['description'] = payload
            agent_state.hierarchical_tasks[current_level - 1].append(current_action)
            continue

        if current_action is not None:
            priority_match = priority_pattern.match(line)
            significance_match = significance_pattern.match(line)
            associated_goal_match = associated_goal_pattern.match(line)
            why_match = why_pattern.match(line)
            thought_match = thought_pattern.match(line)
            notes_match = notes_pattern.match(line)
            if priority_match:
                current_action['priority'] = priority_match.group(1)
            elif significance_match:
                current_action['significance'] = significance_match.group(1)
            elif associated_goal_match:
                current_action['associated_goal'] = associated_goal_match.group(1)
            elif why_match:
                current_action['why'] = why_match.group(2)
            elif thought_match:
                current_action['thought'] = thought_match.group(1)
            elif notes_match:
                current_action['notes'] = notes_match.group(1)
        else:
            # Handle placeholders or general suggestions
            if current_level is not None:
                description_match = re.match(r'^\s*[-*]?\s*\*\*(.+?)\s+(\d+)\*\*:\s*(.+)$', line, re.IGNORECASE)
                if description_match:
                    action_type = description_match.group(1).strip()
                    description = description_match.group(3).strip().strip('`')
                    current_action = {
                        'type': action_type,
                        'description': description,
                        'priority': 'No Priority',
                        'significance': 'No Significance',
                        'associated_goal': 'No Goal',
                        'why': '',
                        'thought': '',
                        'notes': ''
                    }
                    agent_state.hierarchical_tasks[current_level - 1].append(current_action)
                    continue



