def update_pinned_information(shared_recent_executed_actions=None):
    # Memory projection may inspect linked goals. Always acquire goal before history.
    with GOAL_LOCK, HISTORY_LOCK:
        history_store = get_chat_history_store()
        route_state_store = agent_state.route_state
        if shared_recent_executed_actions is None:
            if agent_state.shared_recent_executed_actions_ref is not None:
                shared_recent_executed_actions = list(agent_state.shared_recent_executed_actions_ref)
            else:
                shared_recent_executed_actions = agent_state.recent_executed_actions
        # Remove existing pinned information
        history_store[:] = [entry for entry in history_store if entry.get('Exemption') != 'PinnedInfo']

        # Construct the pinned information text
        pinned_text = "=== Pinned Information ===\n\n"

        if agent_state.overarching_goals:
            pinned_text += "**Overarching Goals:**\n"
            for item in agent_state.overarching_goals:
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        if agent_state.apriority_tasks:
            pinned_text += "**Open-Ended / Apriority Goals:**\n"
            for item in agent_state.apriority_tasks:
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        if agent_state.unknown_priority_candidates:
            pinned_text += "**Unknown-Priority Candidates:**\n"
            for item in agent_state.unknown_priority_candidates:
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        route_scalar_lines = []
        for label, key in (
            ("Current Area", "current_area"),
            ("Target Area", "target_area"),
            ("Travel Heading", "travel_heading"),
            ("Last Landmark", "last_landmark"),
        ):
            value = normalize_memory_item(route_state_store.get(key, ""))
            if value:
                route_scalar_lines.append(f"- {label}: {value}")
        route_status = normalize_memory_item(route_state_store.get("status", ""))
        if route_status:
            route_scalar_lines.append(f"- Status: {route_status}")
        stale_reasons = route_state_store.get("stale_reasons", [])
        if stale_reasons:
            route_scalar_lines.append("- Stale Reasons: " + "; ".join(stale_reasons))
        if route_scalar_lines:
            pinned_text += "**Route State:**\n"
            pinned_text += "\n".join(route_scalar_lines) + "\n\n"

        if agent_state.route_intent:
            pinned_text += "**Route Intent:**\n"
            for item in agent_state.route_intent:
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        if agent_state.local_path_plan:
            pinned_text += "**Local Path Plan:**\n"
            for item in agent_state.local_path_plan:
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        if agent_state.route_blockers:
            pinned_text += "**Route Blockers:**\n"
            for item in agent_state.route_blockers:
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        if route_state_store.get("recent_movement_results"):
            pinned_text += "**Recent Movement Results:**\n"
            for item in route_state_store["recent_movement_results"]:
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        if agent_state.pinned_immediate_actions:
            pinned_text += "**Pinned Immediate Actions:**\n"
            for item in project_horizon_entries(agent_state.pinned_immediate_actions, "pinned_immediate_actions"):
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        if agent_state.pinned_short_term_actions:
            pinned_text += "**Pinned Short-Term Actions:**\n"
            for item in project_horizon_entries(agent_state.pinned_short_term_actions, "pinned_short_term_actions"):
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        if agent_state.mid_term_context:
            pinned_text += "**Mid-Term Context:**\n"
            for item in project_horizon_entries(agent_state.mid_term_context, "mid_term_context"):
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        if agent_state.long_term_context:
            pinned_text += "**Long-Term Context:**\n"
            for item in project_horizon_entries(agent_state.long_term_context, "long_term_context"):
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        if agent_state.notes:
            pinned_text += "**Notes:**\n"
            for item in agent_state.notes:
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        if agent_state.journal_entries:
            pinned_text += "**Journal:**\n"
            pinned_text += build_journal_projection(agent_state.journal_entries) + "\n\n"

        if agent_state.recent_context_events:
            pinned_text += "**Recent Context:**\n"
            for item in agent_state.recent_context_events:
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        if agent_state.notable_inventory:
            pinned_text += "**Inventory:**\n"
            for item in agent_state.notable_inventory:
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        if agent_state.party_status:
            pinned_text += "**Party / Status:**\n"
            for item in agent_state.party_status:
                pinned_text += f"- {item}\n"
            pinned_text += "\n"

        completion_history = build_completed_goal_projection(agent_state.significant_past_tasks)
        if completion_history:
            pinned_text += completion_history + "\n\n"

        # Add hierarchical tasks
        pinned_text += construct_hierarchical_tasks_text()

        # Add recent executed actions
        if shared_recent_executed_actions:
            pinned_text += "**Recent Executed Actions:**\n"
            for entry in shared_recent_executed_actions:
                pinned_text += (
                    f"- [{entry['timestamp']}] {entry['action']} "
                    f"(Goal: {entry['associated_goal']}, Family: {entry.get('family_key', '?')}, "
                    f"Context: {entry.get('execution_operating_context', 'unknown')}, "
                    f"Outcome: {entry.get('outcome_status', 'pending')}, "
                    f"Score: {entry.get('outcome_score', 0)}, "
                    f"Note: {entry.get('outcome_note', 'n/a')})\n"
                )
            pinned_text += "\n"

        if agent_state.recent_action_intents:
            pinned_text += "**Recent Action Intents:**\n"
            for entry in agent_state.recent_action_intents:
                pinned_text += f"- [turn {entry.get('inference_turn', '?')}] {entry.get('summary', '')} ({entry.get('status', 'unknown')})\n"
            pinned_text += "\n"

        if agent_state.recent_command_proposals:
            pinned_text += "**Recent Command Proposals:**\n"
            for entry in agent_state.recent_command_proposals:
                pinned_text += (
                    f"- [turn {entry.get('inference_turn', '?')}] {entry.get('command', '')} "
                    f"(support={entry.get('support_count', 1)}, execute_by_turn={entry.get('execute_by_inference', '?')}, "
                    f"disposition={entry.get('disposition', 'unknown')})\n"
                )
            pinned_text += "\n"

        # Create the pinned message entry
        pinned_message_content = {'type': 'text', 'text': pinned_text}
        pinned_message_entry = {
            'message_id': 'runtime:pinned-information',
            'timestamp': datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
            'role': 'system',
            'token_count': None,
            'Exemption': 'PinnedInfo',
            'content': pinned_message_content
        }

        # Insert the pinned message entry into chat_history just before the most recent message
        if history_store:
            history_store.insert(len(history_store) - 1, pinned_message_entry)
        else:
            # If chat_history is empty, just append the pinned message
            history_store.append(pinned_message_entry)


def add_overarching_goal(goal_text):
    normalized_goal = normalize_memory_item(goal_text)
    if not normalized_goal:
        return
    append_memory_store(agent_state.overarching_goals, [normalized_goal], limit=MAX_OVERARCHING_GOALS)


