# Function to add a goal
def add_goal(goal_text, priority='No Priority', significance='No Significance'):
    with GOAL_LOCK:
        normalized_goal = normalize_memory_item(goal_text)
        if not normalized_goal or goal_exists(normalized_goal):
            return
        goal = Goal(normalized_goal, priority, significance)
        tasks_list.append(goal)
        update_pinned_information()

def add_sub_goal(parent_goal_id, sub_goal_text, priority='No Priority', significance='No Significance'):
    with GOAL_LOCK:
        parent_goal = find_goal_by_id(parent_goal_id)
        if parent_goal:
            sub_goal = Goal(sub_goal_text, priority, significance)
            parent_goal.add_sub_goal(sub_goal)
            update_pinned_information()
            display_message('system', f"Added sub-goal: {sub_goal_text} to goal ID {parent_goal_id}")
        else:
            display_message('error', f"No goal found with ID {parent_goal_id}.")

def format_goal(goal, level=0):
    indent = '  ' * level
    status = '✅' if goal.status == 'Complete' else '❌'
    goal_text = f"{indent}- [{status}] ID {goal.id}: {goal.text} (Priority: {goal.priority}, Significance: {goal.significance})\n"
    for sub_goal in goal.sub_goals:
        goal_text += format_goal(sub_goal, level + 1)
    return goal_text


def find_goal_by_id(goal_id, goals_list=None):
    goal_source = tasks_list if goals_list is None else goals_list
    for goal in goal_source:
        if goal.id == goal_id:
            return goal
        # Recursively search sub-goals
        sub_goal = find_goal_by_id(goal_id, goal.sub_goals)
        if sub_goal:
            return sub_goal
    return None


# Function to add an apriority goal
def add_apriority_goal(goal_text):
    normalized_goal = normalize_memory_item(goal_text)
    if not normalized_goal or apriority_goal_exists(normalized_goal) or goal_exists(normalized_goal):
        return
    apriority_tasks.append(normalized_goal)
    update_pinned_information()

# Function to update inventory
def update_inventory(inventory_items):
    agent_state.notable_inventory[:] = inventory_items.split(';')
    update_pinned_information()

# Function to update party status
def update_party_status(party_status_text):
    agent_state.party_status[:] = party_status_text.split(';')
    update_pinned_information()

# Function to update recent context
def update_recent_context(context_events):
    global recent_context_events
    if isinstance(context_events, str):
        context_items = [item.strip() for item in context_events.split(';') if item.strip()]
    else:
        context_items = [normalize_memory_item(item) for item in context_events if normalize_memory_item(item)]
    merge_recent_context_items(context_items)
    update_pinned_information()

# Function to mark a goal as completed
def mark_goal_as_completed(goal_id):
    with GOAL_LOCK:
        goal = find_goal_by_id(goal_id)
        if goal:
            if goal.status == 'Complete':
                return goal
            goal.status = 'Complete'
            significant_past_tasks.append({
                'timestamp': datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                'goal': goal.text
            })
            # Keep only the last 5 significant goals
            significant_past_tasks[:] = significant_past_tasks[-5:]
            update_pinned_information()
            display_message('system', f"Marked goal {goal_id} as completed")
            return goal
        else:
            raise ValueError(f"No goal found with ID {goal_id}.")




