def execute_desktop_command(cmd_name, args):
    """Return a typed desktop outcome; never replay an input after an exception."""
    name = cmd_name.lower().removeprefix("pyag:")
    handler = pyautogui_dispatch.get(name)
    if handler is None:
        return desktop_result(name, success=False, effect_status="not_started", reason="Unknown desktop action.")
    try:
        desktop_command_arguments(name, args)
    except ValueError as error:
        return desktop_result(name, success=False, effect_status="not_started", reason=str(error))
    try:
        with HELD_INPUTS.owner_scope(command="pyag:" + name):
            if name not in {"release", "multi_release", "screenshot"}:
                HELD_INPUTS.check_ready()
            result = handler(args)
        if isinstance(result, dict) and result.get("schema_version") == "aurora_desktop_result_v1":
            return dict(result, command="pyag:" + name, input_ownership=HELD_INPUTS.snapshot())
        if command_result_failed(result):
            reason = result.get("reason") or result.get("error") if isinstance(result, dict) else "Desktop handler reported failure."
            return desktop_result(name, success=False, effect_status="uncertain", reason=reason or "Desktop handler reported failure.")
        return dict(desktop_result(name), input_ownership=HELD_INPUTS.snapshot())
    except WorkCancelled:
        raise
    except Exception as error:
        display_message("error", f"Desktop action {name} failed: {error}")
        return dict(desktop_result(name, success=False, effect_status=getattr(error, "effect_status", "uncertain"), reason=str(error)),
                    input_ownership=HELD_INPUTS.snapshot())


def handle_pyautogui_command(cmd_name, args):
    return not command_result_failed(execute_desktop_command(cmd_name, args))



def pyautogui_focus_window(args):
    title_hint = desktop_command_arguments("focus_window", args)["title"] or EMULATOR_WINDOW_TITLE_HINT
    result = focus_window_by_title(title_hint)
    if result.get("success"):
        set_last_key_value(f"focus_window:{title_hint}")
        set_runtime_value("last_input_backend", "window-focus")
        record_focus_recovery_result("explicit_focus_window", result)
        message = f"Focused window: {result.get('title', title_hint)}"
        display_message("system", message)
        return desktop_result("focus_window", effect_status="observed", reason=message)
    set_runtime_value("last_input_backend", "window-focus-failed")
    record_focus_recovery_result("explicit_focus_window_failed", result)
    message = f"Target focus was not confirmed for '{title_hint}': {result.get('reason', 'unknown error')}"
    display_message("error", message)
    return desktop_result("focus_window", success=False, effect_status="uncertain", reason=message)


def pyautogui_press(args):
    values = desktop_command_arguments("press", args)
    key, presses, interval = values["key"], values["presses"], values["interval"]
    backend, backend_key, focus_result = "pyautogui", key, {}
    COMMAND_WORK.current().check()
    if should_use_game_input_backend(key):
        focus_result = focus_game_input_target(EMULATOR_WINDOW_TITLE_HINT)
        record_focus_recovery_result(f"pre_game_input_press:{key}", focus_result)
        if not focus_result.get("success"):
            raise DesktopCommandError("Game input was not sent: " + str(focus_result.get("reason", "focus failed")),
                                      effect_status="not_started")
        backend_key = translate_game_backend_key(key)
        hold_seconds = GAME_CONFIRM_HOLD_SECONDS if (
            normalize_text_content(runtime_state.get("operating_context", "")).strip().lower() == "game"
            and key in GAME_CONFIRM_KEYS) else 0.0
        backend = game_backend_press(backend_key, presses=presses, interval=interval, hold_seconds=hold_seconds)
    else:
        send_desktop_key_sequence([key], interval=interval, repetitions=presses)
    set_last_key_value(key)
    set_runtime_value("last_input_backend", backend)
    set_runtime_value("last_foreground_window", get_foreground_window_title())
    record_game_input_attempt(requested_key=key, effective_key=backend_key, backend=backend,
                              command_text=f"press({key}, presses={presses}, interval={interval})",
                              focus_result=focus_result)
    display_message("system", f"Key press submitted: {key}->{backend_key} x{presses} (backend={backend})")



def pyautogui_hold(args):
    values = desktop_command_arguments("hold", args)
    key, duration = values["key"], values["duration"]
    backend, backend_key, focus_result = "pyautogui", key, {}
    if should_use_game_input_backend(key):
        focus_result = focus_game_input_target(EMULATOR_WINDOW_TITLE_HINT)
        record_focus_recovery_result(f"pre_game_input_hold:{key}", focus_result)
        if not focus_result.get("success"):
            raise DesktopCommandError("Game input was not sent: " + str(focus_result.get("reason", "focus failed")),
                                      effect_status="not_started")
        backend_key = translate_game_backend_key(key)
        backend = get_game_input_backend()
    namespace = "gb" if should_use_game_input_backend(key) else "pyag"
    lease = acquire_key_input(backend_key, backend, requested=key, namespace=namespace,
                              persistent=duration is None)
    if duration is not None:
        try:
            COMMAND_WORK.current().wait(duration)
        finally:
            release_input_leases([lease])
    set_last_key_value(key)
    set_runtime_value("last_input_backend", backend)
    set_runtime_value("last_foreground_window", get_foreground_window_title())
    record_game_input_attempt(requested_key=key, effective_key=backend_key, backend=backend,
                              command_text=f"hold({key}, duration={duration})", focus_result=focus_result)
    display_message("system", f"Key held for {duration} seconds: {key}->{backend_key} (backend={backend})")



def move_key_command(args):
    values = desktop_command_arguments("move_key", args)
    move_key(values["key"], values["tiles"])
    set_last_key_value(values["key"])
    display_message("system", f"Submitted {values['key']} movement for {values['tiles']} estimated tiles using legacy timing; verify the actual movement from a fresh image")

def move_key(key, tiles):
    values = desktop_command_arguments("move_key", [key, tiles])
    key, tiles = values["key"], values["tiles"]
    if tiles < 4:
        duration = tiles * 0.175
    elif tiles <= 8:
        duration = tiles * 0.239
    elif tiles < 10:
        duration = tiles * 0.245
    else:
        duration = tiles * 0.265
    COMMAND_WORK.current().wait(1.35)
    pyautogui_hold([key, duration])


