def clear_percentage_except_pinned_and_exempt(command: str):
    with HISTORY_LOCK:
        try:
            percentage_to_clear = float(command[6:].strip()) / 100
            if 0 <= percentage_to_clear <= 1:
                invalidate_responses_history("clear_percentage_except_pinned_and_exempt")
                history_store = get_chat_history_store()

                # Separate out pinned/init/exempted entries and others
                pinned_and_exempted_entries = [
                    entry for entry in history_store
                    if get_history_entry_text(entry).startswith('Pinned Init summary')
                    or get_history_entry_text(entry).startswith('Pinned Handoff context')
                    or get_history_entry_text(entry).startswith('Exemption')
                ]
                other_entries = [entry for entry in history_store if entry not in pinned_and_exempted_entries]

                # Calculate the number of entries to keep
                num_to_keep = int(len(other_entries) * (1 - percentage_to_clear))
                kept_entries = other_entries[:num_to_keep]

                # Merge the kept entries with the pinned/init/exempted ones
                history_store[:] = pinned_and_exempted_entries + kept_entries

                print(f"Cleared {percentage_to_clear*100}% of chat history excluding pinned and exempted entries.")
            else:
                print("Invalid percentage. Please enter a number between 0 and 100.")
        except ValueError:
            print("Invalid command format. Expected format is 'CLEAR%{number}'.")


def add_pinned_init_summary(init_summary: str):
    with HISTORY_LOCK:
        history_store = get_chat_history_store()
        if any(get_history_entry_text(entry).startswith(f'Pinned Init summary: {init_summary}') for entry in history_store):
            print("Handoff summary already in chat history.")
            return

        history_store.append({'role': 'user', 'content': f'Pinned Init summary: {init_summary}'})
        print(f"Pinned Init summary: {init_summary}")

def retrieve_and_add_handoff(handoff_filename: str):
    with HISTORY_LOCK:
        handoff_filepath = handoff_filename if os.path.isabs(handoff_filename) else f"{logging_folder}/{handoff_filename}"

        if not os.path.exists(handoff_filepath):
            print(f"No such file exists: {handoff_filepath}")
            return

        with open(handoff_filepath, "r") as file:
            handoff_summary = file.read().strip()

        history_store = get_chat_history_store()
        if any(get_history_entry_text(entry).startswith(f'Pinned Handoff context: {handoff_summary}') for entry in history_store):
            print("Handoff summary already in chat history.")
            return

        history_store.append({'role': 'assistant', 'content': f'Pinned Handoff context: {handoff_summary}'})
        print(f"Pinned Handoff context from file: {handoff_summary}")


def resolve_handoff_path(file_name=None):
    normalized_name = normalize_text_content(file_name).strip() if file_name else ""
    if not normalized_name:
        normalized_name = f"handoff_{datetime.date.today().strftime('%Y-%m-%d')}.txt"
    if os.path.isabs(normalized_name):
        return normalized_name
    return os.path.join(logging_folder, normalized_name)


def find_previous_handoff_path():
    yesterday = datetime.date.today() - datetime.timedelta(days=1)
    candidates = [
        os.path.join(logging_folder, f"handoff_{yesterday.strftime('%Y-%m-%d')}.txt"),
        os.path.join(logging_folder, f"Handoff_{yesterday.strftime('%Y-%m-%d')}.txt"),
    ]
    for candidate in candidates:
        if os.path.exists(candidate):
            return candidate
    return None


def build_handoff_summary_text():
    update_pinned_information()
    history_store = get_chat_history_store()
    pinned_info_entry = next(
        (entry for entry in reversed(history_store) if entry.get("Exemption") == "PinnedInfo"),
        None,
    )
    pinned_info_text = normalize_text_content(pinned_info_entry.get("content", "")) if pinned_info_entry else ""
    sections = [f"Handoff snapshot generated {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"]
    runtime_summary = get_runtime_mode_summary()
    if runtime_summary:
        sections.append("[Runtime]\n" + runtime_summary)
    auth_summary = get_auth_status_summary()
    if auth_summary:
        sections.append("[Auth]\n" + auth_summary)
    latest_feedback = list(runtime_state.get("recent_feedback", []) or [])
    if latest_feedback:
        sections.append("[Recent Feedback]\n" + "\n".join(f"- {item}" for item in latest_feedback[-8:]))
    if pinned_info_text:
        sections.append(pinned_info_text)
    else:
        snapshot = build_agent_state_snapshot()
        if snapshot:
            sections.append(snapshot)
    return "\n\n".join(section.strip() for section in sections if section and section.strip())


def save_handoff_summary(file_name=None):
    handoff_path = resolve_handoff_path(file_name)
    handoff_summary = build_handoff_summary_text()
    os.makedirs(os.path.dirname(handoff_path), exist_ok=True)
    with open(handoff_path, "w", encoding="utf-8") as handoff_file:
        handoff_file.write(handoff_summary)
    return handoff_path, handoff_summary


def clear_history_entries_by_exemption(exemption_name):
    command = {"Init": "CLEAR_INIT", "Pinned": "CLEAR_PIN", "Handoff": "CLEAR_HANDOFF"}.get(exemption_name)
    if command is None:
        raise ValueError("Expected Init, Pinned or Handoff exemption.")
    result = execute_history_command(command, [])
    if not result["success"]:
        raise RuntimeError(result["reason"])
    return result["removed_count"]


def clear_recent_context_memory():
    invalidate_responses_history("clear_recent_context_memory")
    agent_state.recent_context_events.clear()
    update_pinned_information()


def clear_route_state_memory():
    invalidate_responses_history("clear_route_state_memory")
    route_state_store = agent_state.route_state
    agent_state.route_intent.clear()
    agent_state.local_path_plan.clear()
    agent_state.route_blockers.clear()
    movement_results_store = route_state_store.get("recent_movement_results", [])
    if isinstance(movement_results_store, list):
        movement_results_store.clear()
    route_state_store["current_area"] = ""
    route_state_store["target_area"] = ""
    route_state_store["travel_heading"] = ""
    route_state_store["last_landmark"] = ""
    route_state_store["status"] = "unknown"
    route_state_store["stale_reasons"] = []
    route_state_store["field_meta"] = {}
    route_state_store["last_updated"] = ""
    update_pinned_information()


def clear_non_pinned_entries():
    return execute_history_command("CLEAR_NONPIN", [])




# Function to check if daily summary has been completed
def daily_summary_completed(date):
    filename = f"{logging_folder}/daily_summary_{date}.txt"
    return os.path.exists(filename)

# Function to save daily summary
def save_daily_summary():
    date = datetime.date.today().strftime("%Y-%m-%d")
    if not daily_summary_completed(date):
        summary_prompt = "Summarize the important events and points from Aurora's perspective today."
        daily_summary_text = normalize_text_content(send_prompt_to_chatgpt(summary_prompt))
        with open(f"{logging_folder}/daily_summary_{date}.txt", "w", encoding="utf-8") as log_file:
            log_file.write(daily_summary_text)
        print("Daily summary saved.")

# Function to check if it's time to save the daily summary
def check_daily_summary_time():
    current_time = datetime.datetime.now().time()
    daily_summary_time = datetime.time(hour=19)  # 7 PM
    return current_time >= daily_summary_time

def daily_summary():
    current_time = datetime.datetime.now()
    if current_time.hour == 19:  # 7 pm
        summary = normalize_text_content(
            send_prompt_to_chatgpt("Summarize today's important events and points from Aurora's perspective.")
        )
        if summary:
            send_prompt_to_chatgpt(summary)
        with open(f"{logging_folder}/daily_summary_{current_time.strftime('%Y-%m-%d')}.txt", "w", encoding="utf-8") as log_file:
            log_file.write(summary)
        print("Daily summary saved.")

# Function to check for handoff from previous day
def check_previous_handoff():
    today = datetime.date.today()
    yesterday = today - datetime.timedelta(days=1)
    handoff_filename = f"{logging_folder}/handoff_{yesterday.strftime('%Y-%m-%d')}.txt"
    if os.path.exists(handoff_filename):
        with open(handoff_filename, "r", encoding="utf-8") as handoff_file:
            handoff_text = handoff_file.read()
        response_text = send_prompt_to_chatgpt(handoff_text)
        if response_text:
            send_prompt_to_chatgpt(response_text)

# Function to perform shutdown procedure for the current ChatGPT instance and exit the program
def shutdown_chatgpt_instance_and_exit():
    set_agent_running(False)
    date = datetime.date.today().strftime("%Y-%m-%d")
    if not daily_summary_completed(date):
        save_daily_summary()
    handoff_summary = f"Handoff {date}: " + normalize_text_content(hbuffer[-1] if hbuffer else "")
    with open(f"{logging_folder}/handoff_{date}.txt", "w", encoding="utf-8") as log_file:
        log_file.write(handoff_summary)
    print("Handoff summary saved.")
    # Exit the program
    print("Exiting the program.")
    sys.exit()

def terminate_instance():
    daily_summary()
    handoff_summary = normalize_text_content(send_prompt_to_chatgpt("Create a handoff summary for the next instance."))
    if handoff_summary:
        send_prompt_to_chatgpt(handoff_summary)
    with open(f"{logging_folder}/Handoff_{datetime.datetime.now().strftime('%Y-%m-%d')}.txt", "w", encoding="utf-8") as log_file:
        log_file.write(handoff_summary)
        print("Handoff summary saved.")
    # You can use sys.exit() to exit the program
    sys.exit()


# Function to restart ChatGPT instance
def restart_chatgpt_instance():
    # Send init_prompt and handoff_prompt to the new instance
    response_text = send_prompt_to_chatgpt(init_prompt)
    if response_text:
        send_prompt_to_chatgpt(response_text)
    if hbuffer:
        handoff_prompt = hbuffer[-1]
        response_text = send_prompt_to_chatgpt(handoff_prompt)

    # Send init_prompt and handoff_prompt to the new instance
    response_text = send_prompt_to_chatgpt(init_prompt)


