def build_pinned_tasks_snapshot():
    with GOAL_LOCK:
        ledger = horizon_identity_state()
        data_to_save = {
            'goals_list': encode_goals(tasks_list, include_identity=ledger is not None),
            'apriority_goals': apriority_tasks,
            'overarching_goals': overarching_goals,
            'unknown_priority_candidates': unknown_priority_candidates,
            'notable_inventory': notable_inventory,
            'party_status': party_status,
            'recent_context_events': recent_context_events,
            'route_intent': route_intent,
            'local_path_plan': local_path_plan,
            'route_blockers': route_blockers,
            'route_state': {
                'current_area': route_state.get('current_area', ''),
                'target_area': route_state.get('target_area', ''),
                'travel_heading': route_state.get('travel_heading', ''),
                'last_landmark': route_state.get('last_landmark', ''),
                'status': route_state.get('status', 'unknown'),
                'stale_reasons': route_state.get('stale_reasons', []),
                'field_meta': route_state.get('field_meta', {}),
                'last_updated': route_state.get('last_updated', ''),
            },
            'recent_movement_results': recent_movement_results,
            'notes': notes,
            'journal_entries': journal_entries,
            'pinned_immediate_actions': pinned_immediate_actions,
            'pinned_short_term_actions': pinned_short_term_actions,
            'mid_term_context': mid_term_context,
            'long_term_context': long_term_context,
            'recent_action_intents': recent_action_intents,
            'recent_command_proposals': recent_command_proposals,
            'command_drip_history': agent_state.command_drip_history,
            'hierarchical_tasks': hierarchical_tasks,
            'significant_past_goals': significant_past_tasks,
            'recent_executed_actions': recent_executed_actions
        }
        if ledger is not None:
            data_to_save['horizon_identity'] = ledger.export()
        return copy.deepcopy(data_to_save)

def save_pinned_tasks(file_name="pinned_tasks.json"):
    token = COMMAND_WORK.current()
    with GOAL_LOCK:
        goal_count = len(list(iter_all_goals()))
        evidence = write_goal_document(file_name, build_pinned_tasks_snapshot(),
                                       format=GOAL_SAVE_FORMAT, check_cancel=token.check)
    return dict(evidence, success=True, effect_status="applied", goal_count=goal_count)

def load_pinned_tasks(file_name="pinned_tasks.json"):
    token = COMMAND_WORK.current()
    with GOAL_LOCK:
        token.check()
        data, file_hash, saved_format = read_goal_document(file_name)
        replacement_goals = decode_goals(data["goals_list"])
        replacement_identity = HorizonIdentityLedger(data, data['horizon_identity']) if 'horizon_identity' in data else None
        token.check()
        before = hashlib.sha256(json.dumps(build_pinned_tasks_snapshot(), sort_keys=True).encode()).hexdigest()
        # Full validation and reconstruction precede publication. Preserve list
        # identities used by legacy module aliases and route-state aliases.
        try:
            agent_state.tasks_list[:] = replacement_goals
            for disk_name, state_name in GOAL_LIST_FIELDS.items():
                getattr(agent_state, state_name)[:] = data[disk_name]
            agent_state.horizon_identity = replacement_identity
            route = data["route_state"]
            for key in ("current_area", "target_area", "travel_heading", "last_landmark", "status", "last_updated"):
                agent_state.route_state[key] = route[key]
            agent_state.route_state["stale_reasons"][:] = route["stale_reasons"]
            agent_state.route_state["field_meta"].clear()
            agent_state.route_state["field_meta"].update(route["field_meta"])
            after = hashlib.sha256(json.dumps(build_pinned_tasks_snapshot(), sort_keys=True).encode()).hexdigest()
        except Exception as error:
            return {"success": False, "effect_status": "failed_uncertain", "before_hash": before,
                    "file_hash": file_hash, "reason": f"Task publication failed; memory may be partially updated: {error}"}
    result = {"success": True, "effect_status": "applied", "before_hash": before, "after_hash": after,
              "file_hash": file_hash, "format": saved_format, "goal_count": len(list(iter_all_goals()))}
    try:
        update_pinned_information()
    except Exception as error:
        result["refresh_warning"] = str(error)
    return result

def toggle_power_word(args, is_user):
    global REQUIRE_POWER_WORD
    REQUIRE_POWER_WORD = not REQUIRE_POWER_WORD
    display_message("system", f"POWER_WORD requirement toggled to {'ON' if REQUIRE_POWER_WORD else 'OFF'}.")


def normalize_execution_mode(value):
    normalized = normalize_text_content(value).strip().lower()
    if normalized in {'safe', 'review'}:
        return 'safe'
    if normalized in {'assist', 'guided'}:
        return 'assist'
    if normalized in {'auto', 'live'}:
        return 'auto'
    return None


def normalize_model_name(value):
    normalized = normalize_text_content(value).strip()
    if not normalized:
        return None
    return normalized


def set_model_transport(value):
    global MODEL_TRANSPORT
    normalized = coerce_setting_value("model.transport", value)
    require_runtime_setting_unlocked("models", "Model transport")
    if normalized != MODEL_TRANSPORT:
        if MODEL_IO.busy or RESPONSES_REASONING.snapshot()["status"] == "in_flight":
            raise ResponsesReasoningError("Wait for model I/O to finish draining before changing transport.")
        MODEL_TRANSPORT = normalized
    return MODEL_TRANSPORT


def reset_responses_session_command(args, is_user):
    if args:
        raise ValueError("RESET_RESPONSES_SESSION takes no arguments.")
    require_runtime_setting_unlocked("reasoning", "Responses session reset")
    if MODEL_IO.busy:
        raise ResponsesReasoningError("Wait for model I/O to finish draining before resetting Responses.")
    RESPONSES_REASONING.reset("operator" if is_user else "assistant")
    display_message("system", "Responses continuation reset. The next request starts a new chain from current Aurora context; no old request is replayed.")
    return True


def set_model_transport_command(args, is_user):
    if not args:
        display_message("system", f"Current model transport: {MODEL_TRANSPORT}")
        return True
    value = set_model_transport(args[0])
    display_message("system", f"Model transport set to {value}; live mode and active models are controlled separately. Responses uses Astra, API-key auth and stored provider history.")
    return True


