def set_high_detail(value):
    global High_Detail
    normalized = normalize_text_content(value).strip()
    if not normalized:
        raise ValueError("high_detail requires a value.")
    lowered = normalized.lower()
    if lowered in {"true", "all", "t", "a"}:
        High_Detail = lowered
    else:
        try:
            High_Detail = int(normalized)
        except ValueError as error:
            raise ValueError("high_detail must be an integer or one of true/all/t/a.") from error
    append_runtime_feedback(f"Global High_Detail set to: {High_Detail}")
    return High_Detail


def set_max_images_in_history(value):
    global MAX_IMAGES_IN_HISTORY
    try:
        numeric = int(value)
    except (TypeError, ValueError) as error:
        raise ValueError("max_images_in_history must be an integer.") from error
    if numeric < 0:
        raise ValueError("max_images_in_history must be 0 or greater.")
    MAX_IMAGES_IN_HISTORY = numeric
    append_runtime_feedback(f"Global MAX_IMAGES_IN_HISTORY set to: {MAX_IMAGES_IN_HISTORY}")
    return MAX_IMAGES_IN_HISTORY


