def get_auth_status_summary():
    configured_mode = normalize_auth_mode(runtime_state.get("auth_mode_configured", AUTH_MODE)) or AUTH_MODE
    resolved_mode = normalize_auth_mode(runtime_state.get("auth_mode_resolved", "")) or "unresolved"
    source = normalize_text_content(runtime_state.get("auth_source", "")).strip() or "-"
    error = summarize_runtime_text(runtime_state.get("auth_error", ""), max_chars=120)
    summary = f"auth={configured_mode}->{resolved_mode} | auth_source={source}"
    if error:
        summary += f" | auth_error={error}"
    return summary


