def pending_queue_mode_operator_note(mode):
    normalized = normalize_pending_queue_mode(mode, fallback="normal")
    descriptions = {
        "normal": "normal holds the new pending command in its near-term place",
        "insert": "insert claims the next slot and defers later pending commands",
        "replace": "replace/override claims the next slot and marks displaced immediate commands dropped",
    }
    return descriptions.get(normalized, descriptions["normal"])


def build_queue_next_action_runtime_cue():
    try:
        refresh_pending_command_estimates()
    except Exception:
        pass
    pending_store = get_pending_command_store()
    try:
        queue_bridge = build_queue_bridge_monitor_snapshot(
            runtime_active=bool(runtime_state.get("runtime_process_active", True))
        )
    except Exception:
        queue_bridge = {}

    if not queue_bridge.get("bridge_caught_up", True):
        latest_id = queue_bridge.get("latest_raw_inbox_message_id", "") or "-"
        return f"Next: wait for bridge ingestion to catch up to raw inbox {summarize_runtime_text(latest_id, max_chars=28)}."
    if not queue_bridge.get("command_result_caught_up", True):
        latest_status = queue_bridge.get("latest_external_command_result_status", "") or "pending"
        return f"Next: wait for command-result logging to catch up ({latest_status})."
    capture_failure = runtime_state.get("capture_request_failure") or {}
    if capture_failure:
        return f"Next: capture request failed ({capture_failure.get('code', 'unknown')}); request a fresh capture or Cancel work. Native calls still running may require a runtime restart."
    if bool(runtime_state.get("demand_capture_pending", False)):
        reason = normalize_text_content(runtime_state.get("demand_capture_reason", "")).strip() or "capture"
        return f"Next: capture requested observation for {summarize_runtime_text(reason, max_chars=42)}, then scheduler can wake."
    if bool(runtime_state.get("turn_scheduler_pending_command_result", False)):
        return "Next: command-result wake is waiting for the follow-up observation/turn boundary."
    if has_effective_next_inference_plan(agent_state.next_inference_plan):
        return "Next: queued model-turn override applies once; pending commands stay separate."
    due_count = int(queue_bridge.get("due_pending_count", 0) or 0)
    if due_count > 0:
        return f"Next: {due_count} due pending command(s) need approval or auto-policy."
    if pending_store:
        return f"Next: {len(pending_store)} pending command(s) are held for support, approval, or clear."
    pending_reasons = list(runtime_state.get("turn_scheduler_pending_reasons", []) or [])
    if pending_reasons:
        reasons = summarize_runtime_text(", ".join(str(item) for item in pending_reasons), max_chars=70)
        return f"Next: scheduler wake pending for {reasons}."
    return "Next: queue lanes are idle; the scheduler controls the next model turn."


