def execute_inference_plan_command(name, args, is_user=True):
    """Observe queue transitions; a receipt never claims the provider applied these values."""
    operation = "clear" if name == "CLEAR_NEXT_INFERENCE" else "replace" if args else "read"
    result = {"schema_version": INFERENCE_PLAN_RESULT_SCHEMA, "command": name, "operation": operation,
              "success": False, "effect_status": "not_started", "requested_options": {},
              "before_plan": {}, "plan": {}, "before_version": "", "after_version": "",
              "scope": "one_model_turn", "reason": ""}
    with SETTINGS_TRANSACTION_LOCK:
        try:
            before = get_next_inference_plan_snapshot()
            result.update(before_plan=before, before_version=inference_plan_version(before))
            options = parse_inference_plan_arguments(name, args)
            result["requested_options"] = dict(options)
            if operation == "clear":
                clear_next_inference_plan()
            elif operation == "replace":
                if name == "SET_NEXT_REASONING_EFFORT":
                    options["note"] = normalize_memory_item(options.get("note", "")).strip() or "one-turn reasoning effort override"
                set_next_inference_plan_from_pairs(options, source="operator" if is_user else "assistant",
                                                   auto_generated=not is_user)
            result.update(success=True, effect_status="observed")
        except (ValueError, RuntimeError) as error:
            result["reason"] = str(error)
            if not result["before_version"]:
                result["effect_status"] = "uncertain"
        except Exception as error:
            result.update(effect_status="uncertain", reason=f"Unexpected inference-plan failure: {error}")
        try:
            after = get_next_inference_plan_snapshot()
            result.update(plan=after, after_version=inference_plan_version(after))
            if not result["success"] and result["after_version"] != result["before_version"]:
                result["effect_status"] = "uncertain"
        except Exception as error:
            result.update(success=False, effect_status="uncertain", reason=f"Plan readback failed: {error}")
    if result["success"]:
        summary = build_next_inference_plan_summary(result["plan"]) or "none"
        display_message("system", f"Next inference plan [{operation}]: {summary}. {build_queue_next_action_runtime_cue()}")
    else:
        display_message("error", result["reason"])
    return result


