def show_model_status_command(args, is_user):
    status = build_model_status_snapshot()
    stateful_family = status.get("stateful_preset_family", {}) or {}
    profile_lines = []
    for key in ("text", "vision", "reasoning"):
        profile = status["profiles"].get(key) or {}
        supported_efforts = ",".join(profile.get("supported_reasoning_efforts", []) or []) or "-"
        profile_lines.append(
            f"- {key}: {profile.get('name', '-')}"
            f" | reasoning_effort={profile.get('supports_reasoning_effort', False)}"
            f" ({supported_efforts})"
            f" | temperature={profile.get('supports_temperature_override', False)}"
            f" | verbosity={profile.get('supports_verbosity', False)}"
            f" | image_original={profile.get('supports_original_image_detail', False)}"
            f" | summary={profile.get('supports_reasoning_summary', False)}"
        )
    stateful_profile_lines = []
    for profile in stateful_family.get("profiles", []) or []:
        stateful_profile_lines.append(
            f"- stateful_profile {profile.get('name', '-')}: "
            f"mode={profile.get('state_mode', '-')} | api={profile.get('api_path', '-')} | "
            f"transport={profile.get('transport_status', '-')} | recap={profile.get('recap_policy', '-')}"
        )
    lines = [
        "Model status:",
        f"- transport={status['transport']}",
        "- responses_reasoning=" + json.dumps(status["responses_reasoning"], ensure_ascii=False),
        f"- text_model={status['text_model']}",
        f"- vision_model={status['vision_model']}",
        f"- reasoning_model={status['reasoning_model']}",
        f"- default_reasoning_effort={status['reasoning_effort']}",
        f"- battle_reasoning_effort={status['battle_reasoning_effort']}",
        f"- review_reasoning_effort={status.get('review_reasoning_effort', '-')}",
        f"- critique_reasoning_effort={status.get('critique_reasoning_effort', '-')}",
        f"- verbosity={status['verbosity']}",
        f"- review_verbosity={status.get('review_verbosity', '-')}",
        f"- battle_verbosity={status.get('battle_verbosity', '-')}",
        f"- critique_verbosity={status.get('critique_verbosity', '-')}",
        f"- summary_mode={status['summary_mode']}",
        f"- auto_dynamic_inference={status.get('auto_dynamic_inference', False)}",
        f"- temperature={status['temperature']}",
        f"- screenshot_interval_seconds={status['screenshot_interval_seconds']}",
        f"- review_turn_interval={status['review_turn_interval']}",
        f"- critique_turn_interval={status.get('critique_turn_interval', '-')}",
        f"- approx_review_cycle_seconds={status['approx_review_cycle_seconds']}",
        f"- approx_battle_review_cycle_seconds={status['approx_battle_review_cycle_seconds']}",
        f"- approx_critique_cycle_seconds={status.get('approx_critique_cycle_seconds', '-')}",
        f"- next_inference={build_next_inference_plan_summary(status.get('next_inference')) or 'none'}",
        f"- stateful_family={stateful_family.get('family', '-')}",
        f"- stateful_status={stateful_family.get('status', '-')}",
        f"- stateful_active_profile={stateful_family.get('active_profile', '-')}",
        f"- stateful_mode={stateful_family.get('active_state_mode', '-')} | api={stateful_family.get('active_api_path', '-')}",
        f"- stateful_live_transport={stateful_family.get('live_transport', '-')} | changed={stateful_family.get('transport_changed', False)}",
        f"- stateful_ids=conversation:{stateful_family.get('conversation_id') or '-'} previous_response:{stateful_family.get('previous_response_id') or '-'}",
        *stateful_profile_lines,
        *profile_lines,
        *[f"- stateful note: {note}" for note in stateful_family.get("notes", [])],
        *[f"- note: {note}" for note in status.get("notes", [])],
    ]
    display_message('system', "\n".join(lines))
    return True


