def update_image_context_metadata_command(args, is_user):
    if len(args) < 2:
        display_message(
            'error',
            "UPDATE_IMAGE_CONTEXT_METADATA requires target plus fields. "
            "Example: UPDATE_IMAGE_CONTEXT_METADATA(1779061279, caption=\"Control Panel smoke\", tags=\"control_panel;smoke\")"
        )
        return False
    target = normalize_text_content(args[0]).strip()
    option_text = "; ".join(normalize_text_content(arg).strip() for arg in args[1:] if normalize_text_content(arg).strip())
    pairs = parse_named_option_pairs(option_text)
    try:
        result = update_image_context_metadata(target, pairs)
    except Exception as error:
        display_message('error', str(error))
        return False
    fields = ",".join(result.get("updated_fields", []) or [])
    display_message(
        'system',
        "Image context metadata updated:\n"
        f"- image_id={result.get('image_id') or '-'}\n"
        f"- fields={fields or '-'}\n"
        f"- tags={'; '.join(result.get('tags', []) or []) or '-'}\n"
        f"- sidecar={result.get('sidecar_path') or '-'}"
    )
    return True


def search_image_context_index_command(args, is_user):
    if not args:
        display_message('error', "SEARCH_IMAGE_CONTEXT_INDEX requires a query and optional limit.")
        return False
    query = normalize_text_content(args[0]).strip()
    limit = args[1] if len(args) > 1 else None
    try:
        result = search_image_context_index(query, limit)
    except Exception as error:
        display_message('error', str(error))
        return False
    lines = [f"Image context search: {result.get('summary', '')}"]
    items = result.get("items", []) or []
    if not items:
        lines.append("- No matching sidecars.")
    for row in items:
        hits = row.get("hits", {}) or {}
        hit_text = ", ".join(f"{key}:{value}" for key, value in sorted(hits.items())) or "-"
        lines.append(
            f"- score={row.get('score', 0)} | {row.get('image_id', '-') or '-'} | "
            f"hits={hit_text} | {row.get('capture_reason', '-') or '-'}"
        )
        if row.get("caption"):
            lines.append(f"  caption={summarize_runtime_text(row.get('caption'), max_chars=140)}")
        if row.get("ocr_text"):
            lines.append(f"  ocr={summarize_runtime_text(row.get('ocr_text'), max_chars=140)}")
        if row.get("tags"):
            lines.append(f"  tags={'; '.join(row.get('tags', []) or [])}")
        if row.get("screenshot_path"):
            lines.append(f"  screenshot={row.get('screenshot_path')}")
    display_message('system', "\n".join(lines))
    return True


