def get_reference_missing_message():
    return (
        f"Aurora reference mirror not found at {AURORA_REFERENCE_ROOT}. "
        "Run regenerate_aurora_skill_refs.ps1 to refresh the mirrored references."
    )


def show_reference_topics_command(args, is_user):
    if not AURORA_REFERENCE_ROOT.exists():
        display_message('error', get_reference_missing_message())
        return False
    display_message('system', get_reference_topics_summary())
    return True


def show_reference_pack_command(args, is_user):
    if not AURORA_REFERENCE_ROOT.exists():
        display_message('error', get_reference_missing_message())
        return False
    pack_name = get_reference_pack_name(args[0] if args else "")
    if not pack_name:
        available = ", ".join(sorted(AURORA_REFERENCE_PACK_PATHS.keys()))
        display_message('error', f"SHOW_REFERENCE_PACK requires one of: {available}.")
        return False
    path = AURORA_REFERENCE_PACK_PATHS.get(pack_name)
    if not path or not path.exists():
        display_message('error', f"No mirrored reference pack found for {pack_name}.")
        return False
    display_message('system', f"Aurora reference pack [{pack_name}] | path={path}\n\n{get_reference_display_text(path, max_chars=20000)}")
    return True


def search_reference_pack_command(args, is_user):
    if not AURORA_REFERENCE_ROOT.exists():
        display_message('error', get_reference_missing_message())
        return False
    if not args:
        display_message('error', "SEARCH_REFERENCE_PACK requires query text and optionally a pack name or all.")
        return False
    query = normalize_text_content(args[0]).strip()
    if not query:
        display_message('error', "SEARCH_REFERENCE_PACK requires non-empty query text.")
        return False
    pack_arg = normalize_text_content(args[1]).strip() if len(args) > 1 else "all"
    lowered_query = query.lower()
    if pack_arg.lower() in {"", "all", "*"}:
        pack_names = list(AURORA_REFERENCE_PACK_PATHS.keys())
    else:
        pack_name = get_reference_pack_name(pack_arg)
        if not pack_name:
            available = ", ".join(sorted(AURORA_REFERENCE_PACK_PATHS.keys()))
            display_message('error', f"SEARCH_REFERENCE_PACK pack must be one of: {available}, or all.")
            return False
        pack_names = [pack_name]
    matches = []
    for pack_name in pack_names:
        path = AURORA_REFERENCE_PACK_PATHS.get(pack_name)
        text = read_reference_text(path) if path else ""
        if not text:
            continue
        for line in text.splitlines():
            stripped = line.strip()
            if stripped and lowered_query in stripped.lower():
                matches.append(f"- [{pack_name}] {stripped}")
    if not matches:
        scope = ", ".join(pack_names)
        display_message('system', f"No reference-pack matches found for '{query}' in {scope}.")
        return True
    scope = "all packs" if len(pack_names) > 1 else pack_names[0]
    display_message('system', f"Reference-pack search for '{query}' [{scope}]:\n" + "\n".join(matches[:24]))
    return True


def reference_shorthand_command(args, is_user):
    if not args:
        display_message(
            'error',
            "REF requires a reference query or pack name. Examples: REF(roadmap) or REF(queue semantics, roadmap).",
        )
        return False
    first = normalize_text_content(args[0]).strip()
    if not first:
        display_message('error', "REF requires non-empty query text or a pack name.")
        return False
    if len(args) == 1:
        pack_name = get_reference_pack_name(first)
        if pack_name:
            display_message('system', f"REF shorthand expands to: SHOW_REFERENCE_PACK({pack_name})")
            return show_reference_pack_command([pack_name], is_user)
        display_message('system', f"REF shorthand expands to: SEARCH_REFERENCE_PACK({json.dumps(first)}, all)")
        return search_reference_pack_command([first, "all"], is_user)
    pack_arg = normalize_text_content(args[1]).strip() or "all"
    display_message('system', f"REF shorthand expands to: SEARCH_REFERENCE_PACK({json.dumps(first)}, {pack_arg})")
    return search_reference_pack_command([first, pack_arg], is_user)


