def set_episodic_embeddings_command(args, is_user):
    global EPISODIC_MEMORY_EMBEDDINGS_MODE
    desired = normalize_text_content(args[0] if args else "").strip().lower()
    if not desired:
        display_message('system', f"Episodic semantic backend is {runtime_state.get('episodic_memory_embeddings_mode', EPISODIC_MEMORY_EMBEDDINGS_MODE)}.")
        return True
    aliases = {
        "lexical": "off",
        "off": "off",
        "auto": "auto",
        "embedding": "force",
        "embeddings": "force",
        "force": "force",
    }
    normalized = aliases.get(desired, "")
    if normalized not in ALLOWED_EPISODIC_EMBEDDING_MODES:
        display_message('error', "SET_EPISODIC_EMBEDDINGS requires off, auto, or force.")
        return False
    EPISODIC_MEMORY_EMBEDDINGS_MODE = normalized
    set_runtime_value("episodic_memory_embeddings_mode", normalized)
    display_message('system', f"Episodic semantic backend set to {normalized}. {get_episodic_memory_status_summary()}")
    return True


