    global EPISODIC_PLANNING_ASSIST_MODE
    desired = normalize_text_content(args[0] if args else "").strip().lower()
    if not desired:
        display_message(
            'system',
            f"Episodic planning assist is {runtime_state.get('episodic_memory_planning_assist_mode', EPISODIC_PLANNING_ASSIST_MODE)}.",
        )
        return True
    aliases = {
        "off": "off",
        "review": "review",
        "critique": "critique",
        "review_critique": "review_critique",
        "planning": "review_critique",
        "on": "review_critique",
        "bounded": "review_critique",
    }
    normalized = aliases.get(desired, "")
    if normalized not in ALLOWED_EPISODIC_PLANNING_ASSIST_MODES:
        display_message('error', "SET_EPISODIC_PLANNING_ASSIST requires off, review, critique, or review_critique.")
        return False
    EPISODIC_PLANNING_ASSIST_MODE = normalized
    set_runtime_value("episodic_memory_planning_assist_mode", normalized)
    display_message('system', f"Episodic planning assist set to {normalized}. {get_episodic_memory_status_summary()}")
    return True


