def show_episodic_memory_status_command(args, is_user):
    latest = _read_episodic_snapshot_records(limit=1)
    last_promoted_target = normalize_text_content(runtime_state.get("episodic_memory_last_promoted_target", "")).strip()
    last_promoted_summary = normalize_text_content(runtime_state.get("episodic_memory_last_promoted_summary", "")).strip()
    lines = [
        "Episodic memory status:",
        f"- {get_episodic_memory_status_summary()}",
        f"- path={episodic_memory_path}",
        f"- embeddings_mode={runtime_state.get('episodic_memory_embeddings_mode', EPISODIC_MEMORY_EMBEDDINGS_MODE)}",
        f"- embedding_model={runtime_state.get('episodic_memory_embedding_model', EPISODIC_MEMORY_EMBEDDING_MODEL)}",
        f"- embedding_cache_entries={int(runtime_state.get('episodic_memory_embedding_cache_entries', 0) or 0)}",
        f"- planning_assist_mode={runtime_state.get('episodic_memory_planning_assist_mode', EPISODIC_PLANNING_ASSIST_MODE)}",
        f"- planning_assist_k={int(runtime_state.get('episodic_memory_planning_assist_k', EPISODIC_PLANNING_ASSIST_K) or EPISODIC_PLANNING_ASSIST_K)}",
        f"- planning_assist_cooldown_turns={int(runtime_state.get('episodic_memory_planning_assist_cooldown_turns', EPISODIC_PLANNING_ASSIST_COOLDOWN_TURNS) or EPISODIC_PLANNING_ASSIST_COOLDOWN_TURNS)}",
        f"- planning_cooldown_remaining_turns={int(runtime_state.get('episodic_memory_planning_cooldown_remaining_turns', 0) or 0)}",
        f"- planning_next_eligible_turn={int(runtime_state.get('episodic_memory_planning_next_eligible_turn', 0) or 0)}",
        f"- planning_last_decision={runtime_state.get('episodic_memory_planning_last_decision', '-') or '-'} @ turn {int(runtime_state.get('episodic_memory_planning_last_decision_turn', 0) or 0)}",
        f"- periodic_trigger={'on' if bool(runtime_state.get('episodic_memory_periodic_trigger_enabled', EPISODIC_MEMORY_PERIODIC_TRIGGER_ENABLED)) else 'off'}",
        f"- scene_trigger={'on' if bool(runtime_state.get('episodic_memory_scene_trigger_enabled', EPISODIC_MEMORY_SCENE_TRIGGER_ENABLED)) else 'off'}",
    ]
    if last_promoted_target or last_promoted_summary:
        lines.append(
            f"- last_promoted={EPISODIC_PROMOTION_TARGET_LABELS.get(last_promoted_target, last_promoted_target or '-')}: "
            f"{summarize_runtime_text(last_promoted_summary or '-', max_chars=180)}"
        )
    if latest:
        record = latest[-1]
        lines.append(f"- latest_summary={summarize_runtime_text(record.get('summary_text', ''), max_chars=180)}")
        tags = ", ".join(record.get("tags", [])[:8])
        if tags:
            lines.append(f"- latest_tags={tags}")
    display_message('system', "\n".join(lines))
    return True


