def _prompt_inclusion_snapshot_fresh(snapshot, max_age_seconds=PROMPT_INCLUSION_REVIEW_MAX_AGE_SECONDS):
    if not isinstance(snapshot, dict):
        return False
    try:
        generated = float(snapshot.get("generated_at_epoch", 0.0) or 0.0)
    except (TypeError, ValueError):
        generated = 0.0
    return bool(generated and (time.time() - generated) <= float(max_age_seconds))


def _resolve_prompt_inclusion_review_snapshot(kind, requested):
    normalized = normalize_text_content(requested).strip()
    normalized_lower = normalized.lower()
    if kind == "preview":
        latest_key = "prompt_inclusion_preview_last_snapshot"
        builder = build_prompt_inclusion_preview_snapshot
        id_key = "preview_id"
    else:
        latest_key = "prompt_inclusion_activation_checklist_last_snapshot"
        builder = build_prompt_inclusion_activation_checklist_snapshot
        id_key = "checklist_id"
    if normalized_lower in {"fresh", "auto"}:
        snapshot = builder()
        if kind == "preview":
            set_runtime_value("prompt_inclusion_preview_last_status", snapshot.get("status", "watch"))
            set_runtime_value("prompt_inclusion_preview_last_summary", snapshot.get("summary", ""))
            set_runtime_value("prompt_inclusion_preview_last_snapshot", snapshot)
        else:
            set_runtime_value("prompt_inclusion_activation_checklist_last_status", snapshot.get("status", "watch"))
            set_runtime_value("prompt_inclusion_activation_checklist_last_summary", snapshot.get("summary", ""))
            set_runtime_value("prompt_inclusion_activation_checklist_last_snapshot", snapshot)
        return snapshot, ""
    snapshot = runtime_state.get(latest_key)
    if not isinstance(snapshot, dict):
        return {}, f"No latest Prompt Inclusion {kind} snapshot is available. Run SHOW_PROMPT_INCLUSION_{'PREVIEW' if kind == 'preview' else 'ACTIVATION_CHECKLIST'}() first or use {kind}_id=fresh."
    if not _prompt_inclusion_snapshot_fresh(snapshot):
        return {}, f"Latest Prompt Inclusion {kind} snapshot is stale. Run a fresh review or use {kind}_id=fresh."
    snapshot_id = normalize_text_content(snapshot.get(id_key, "")).strip()
    if normalized_lower in {"latest", ""}:
        return snapshot, ""
    if normalized and normalized != snapshot_id:
        return {}, f"Prompt Inclusion {kind} id mismatch: requested {normalized}, latest is {snapshot_id or '-'}."
    return snapshot, ""


def set_prompt_inclusion_activation_command(args, is_user):
    if not args:
        display_message('system', format_prompt_inclusion_activation_status(build_prompt_inclusion_activation_snapshot()))
        return True
    action = normalize_text_content(args[0]).strip().lower()
    option_text = "; ".join(normalize_text_content(arg).strip() for arg in args[1:] if normalize_text_content(arg).strip())
    pairs = parse_named_option_pairs(option_text)
    if action in {"off", "false", "0", "disable", "disabled"}:
        confirm = normalize_text_content(pairs.get("confirm", "") or pairs.get("confirmation", "")).strip().lower()
        if confirm and confirm not in {"rollback", "off", "disable", "disabled", "yes", "confirmed"}:
            display_message('error', "SET_PROMPT_INCLUSION_ACTIVATION(off) confirm must be rollback/off/yes when supplied.")
            return False
        previous = get_prompt_inclusion_activation_state()
        state = _default_prompt_inclusion_activation_state()
        state["deactivated_at"] = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        state["last_note"] = normalize_text_content(pairs.get("note", "")).strip() or "operator disabled activation"
        state["last_operator_confirm"] = confirm or "rollback"
        state["activation_id"] = normalize_text_content(previous.get("activation_id", "")).strip()
        state = set_prompt_inclusion_activation_state(state)
        snapshot = build_prompt_inclusion_activation_snapshot(activation_state=state, offline_proof={})
        set_runtime_value("prompt_inclusion_activation_last_snapshot", snapshot)
        append_runtime_feedback("Prompt Inclusion activation disabled.")
        display_message('system', format_prompt_inclusion_activation_status(snapshot))
        return True
    if action not in {"on", "true", "1", "enable", "enabled"}:
        display_message('error', "SET_PROMPT_INCLUSION_ACTIVATION requires on/off.")
        return False

    confirm = normalize_text_content(pairs.get("confirm", "") or pairs.get("confirmation", "")).strip().lower()
    if confirm != "offline_proof":
        display_message('error', "SET_PROMPT_INCLUSION_ACTIVATION(on) requires confirm=offline_proof after reviewing the Prompt Ledger.")
        return False
    preview_ref = pairs.get("preview_id", "") or pairs.get("preview", "")
    checklist_ref = pairs.get("checklist_id", "") or pairs.get("checklist", "")
    if not preview_ref or not checklist_ref:
        display_message('error', "SET_PROMPT_INCLUSION_ACTIVATION(on) requires preview_id=latest|fresh|... and checklist_id=latest|fresh|....")
        return False
    preview, preview_error = _resolve_prompt_inclusion_review_snapshot("preview", preview_ref)
    if preview_error:
        display_message('error', preview_error)
        return False
    checklist, checklist_error = _resolve_prompt_inclusion_review_snapshot("checklist", checklist_ref)
    if checklist_error:
        display_message('error', checklist_error)
        return False
    if preview.get("hard_guardrail_flags"):
        display_message('error', "Prompt Inclusion preview has hard guardrail flags; activation refused.")
        return False
    if not bool(checklist.get("ready_for_activation_review", False)):
        display_message('error', "Prompt Inclusion activation checklist is not ready for review; activation refused.")
        return False
    include_prompt_pins = _prompt_inclusion_bool_from_pairs(pairs, "include_prompt_pins", default=True)
    enforce_do_not_include = _prompt_inclusion_bool_from_pairs(pairs, "enforce_do_not_include", default=True)
    if not include_prompt_pins and not enforce_do_not_include:
        display_message('error', "Activation would have no selected effect. Enable include_prompt_pins or enforce_do_not_include.")
        return False
    now = time.time()
    activation_id = f"window19_prompt_inclusion_activation_{int(now * 1000)}"
    state = {
        "schema_version": PROMPT_INCLUSION_ACTIVATION_STATE_SCHEMA_VERSION,
        "enabled": True,
        "status": "on",
        "include_prompt_pins": include_prompt_pins,
        "enforce_do_not_include": enforce_do_not_include,
        "activation_id": activation_id,
        "activated_at": datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "deactivated_at": "",
        "preview_id": normalize_text_content(preview.get("preview_id", "")).strip(),
        "checklist_id": normalize_text_content(checklist.get("checklist_id", "")).strip(),
        "review_generated_at_epoch": max(
            float(preview.get("generated_at_epoch", 0.0) or 0.0),
            float(checklist.get("generated_at_epoch", 0.0) or 0.0),
        ),
        "offline_proof_id": "",
        "offline_proof_status": "pending",
        "offline_proof_generated_at_epoch": 0.0,
        "live_model_payload_mutation_allowed": False,
        "last_operator_confirm": confirm,
        "last_note": normalize_text_content(pairs.get("note", "")).strip(),
    }
    proof = build_prompt_inclusion_offline_proof_snapshot(activation_state=state)
    state["offline_proof_id"] = proof.get("proof_id", "")
    state["offline_proof_status"] = proof.get("status", "warning")
    state["offline_proof_generated_at_epoch"] = float(proof.get("generated_at_epoch", 0.0) or 0.0)
    state["live_model_payload_mutation_allowed"] = proof.get("status") == "ok"
    state = set_prompt_inclusion_activation_state(state)
    proof["activation_id"] = state.get("activation_id", "")
    proof["live_model_payload_mutation_allowed"] = bool(state.get("live_model_payload_mutation_allowed", False))
    set_runtime_value("prompt_inclusion_offline_proof_last_snapshot", proof)
    snapshot = build_prompt_inclusion_activation_snapshot(activation_state=state, offline_proof=proof)
    set_runtime_value("prompt_inclusion_activation_last_snapshot", snapshot)
    append_runtime_feedback(
        f"Prompt Inclusion activation {'enabled' if state.get('live_model_payload_mutation_allowed') else 'reviewed'} with proof {proof.get('proof_id', '-')}: {proof.get('status', '-')}"
    )
    display_message('system', format_prompt_inclusion_activation_status(snapshot))
    return proof.get("status") == "ok"


