def assign_agent_task_command(args, is_user):
    if not args:
        display_message(
            'error',
            "ASSIGN_AGENT_TASK requires an agent id and title/objective/context. Example: ASSIGN_AGENT_TASK(scout, title=\"Check visuals\", objective=\"Review newest screenshot posture\")"
        )
        return False
    agent_id = normalize_text_content(args[0]).strip()
    option_text = "; ".join(normalize_text_content(arg).strip() for arg in args[1:] if normalize_text_content(arg).strip())
    pairs = parse_named_option_pairs(option_text)
    if args[1:] and not any(key in pairs for key in ("title", "name", "objective", "goal", "task", "context", "brief", "details", "expected", "expected_output", "output", "deliverable", "note", "reason")):
        pairs["objective"] = normalize_text_content(args[1]).strip().strip("\"'")
    try:
        record = assign_agent_task(agent_id, pairs)
    except Exception as error:
        display_message('error', str(error))
        return False
    write_command_execution_log(
        "agent_task_packet_assign",
        command="ASSIGN_AGENT_TASK",
        status="ok",
        agent_id=record.get("agent_id", ""),
        task_id=record.get("task_id", ""),
        task_status=record.get("status", ""),
        visibility=record.get("visibility", ""),
        parent_visible=bool(record.get("parent_visible", False)),
        prompt_ledger_visible=bool(record.get("prompt_ledger_visible", False)),
        parent_chat_history_written=False,
        model_visible_now=False,
        model_visible_next_turn=False,
        pending_command_inserted=False,
        command_execution_enabled=False,
    )
    display_message(
        'system',
        "Agent task packet assigned:\n"
        f"- agent={record.get('agent_id')} | task={record.get('task_id')}\n"
        f"- status={record.get('status')} | visibility={record.get('visibility')} | priority={record.get('priority')}\n"
        f"- title={summarize_runtime_text(record.get('title', ''), max_chars=180)}\n"
        "- parent_chat_history_written=False\n"
        "- model_visible_now=False\n"
        "- pending_command_inserted=False\n"
        "- command_execution_enabled=False"
    )
    return True


