def show_pending_commands_command(args, is_user):
    validate_pending_arguments("SHOW_PENDING_COMMANDS", args)
    snapshot = get_pending_command_snapshot()
    pending_store = snapshot["entries"]
    candidate_status = format_agent_pending_candidate_status()
    gate_status = format_agent_pending_gate_status()
    dry_run_status = format_agent_pending_insert_dry_run_status()
    if not pending_store:
        display_message(
            'system',
            f"No pending assistant commands. {build_queue_next_action_runtime_cue()}\n\n{candidate_status}\n\n{gate_status}\n\n{dry_run_status}"
        )
        return pending_result("show", pending_store, pending_store, entries=pending_store)
    refresh_pending_command_estimates()

    lines = [
        "Pending assistant commands (pending-command planning lane):",
        f"Queue version: {snapshot['version']} | use version:<hash> with selectors for stale-read protection.",
        build_queue_next_action_runtime_cue(),
        "Approve submits chosen held commands through the normal runtime path; Clear drops them without execution.",
        "Scopes: index, all, risk, category, exact command, family key, semantic label or id:pending-<id>.",
        (
            "Queue modes: normal holds in place; insert claims next slot and defers later pending commands; "
            "replace/override claims next slot and marks displaced immediate commands dropped."
        ),
    ]
    for idx, entry in enumerate(pending_store, start=1):
        lines.append(
            f"{idx}. id:{entry.get('pending_id', '')} state={entry.get('pending_state', 'held')} [{entry.get('timestamp', '?')}] {entry.get('command', '')} "
            f"(goal={entry.get('associated_goal', 'No specific goal')}, risk={entry.get('risk', 'unknown')}, "
            f"category={entry.get('category', 'other')}, family={entry.get('family_key', '?')}, "
            f"conflict={entry.get('conflict_key', '-')}, reason={entry.get('reason', 'pending')}, "
            f"context={entry.get('operating_context', 'unknown')}, repeats={entry.get('repeat_count', 1)}, "
            f"support={entry.get('support_count', 1)}, first_turn={entry.get('first_seen_inference', '?')}, "
            f"last_turn={entry.get('last_seen_inference', '?')}, execute_by_turn={entry.get('execute_by_inference', '?')}, "
            f"turns_until_due={entry.get('turns_until_due', '?')}, "
            f"expected={entry.get('expected_outcome', 'state should change')}, "
            f"rationale={entry.get('rationale', 'n/a')}, policy={entry.get('policy_reason', 'n/a')})"
        )
        if entry.get("source") == "sub_agent_pending_insert" or entry.get("source_dry_run_id"):
            lines.append(
                f"   sub_agent_insert: agent={entry.get('source_agent_id', '-') or '-'} | "
                f"review={entry.get('source_review_link_id', '-') or '-'} | "
                f"dry_run={entry.get('source_dry_run_id', '-') or '-'} | "
                f"manual_approval_required={entry.get('manual_approval_required', False)} | "
                f"rollback=CLEAR_PENDING_COMMANDS({idx})"
            )
    lines.append("")
    lines.append(candidate_status)
    lines.append("")
    lines.append(gate_status)
    lines.append("")
    lines.append(dry_run_status)
    display_message('system', "\n".join(lines))

    return pending_result("show", pending_store, pending_store, entries=pending_store)



def _resolve_pending_indexes(args, default_all=False):
    return PENDING_COMMAND_LEDGER.select(
        get_pending_command_store(), args, normalize=normalize_action_command, default_all=default_all)



