def clear_pending_commands_command(args, is_user):
    with PENDING_COMMAND_LEDGER.lock:
        store = get_pending_command_store()
        before = PENDING_COMMAND_LEDGER.snapshot(store)
        try:
            indexes = _resolve_pending_indexes(args, default_all=True)
            if not is_user and any(store[index].get("pending_state") == "task_held" for index in indexes):
                raise ValueError("Prior-task held proposals require operator approval or clearing.")
            if any(store[index].get("pending_state") == "reserved" for index in indexes):
                raise ValueError("A selected pending item is being submitted; wait for its receipt or cancel active work before clearing.")
            selected = [store[index] for index in indexes]
            with PENDING_COMMAND_LEDGER.mutation(store):
                for index in reversed(indexes):
                    store.pop(index)
                for entry in selected:
                    append_recent_command_proposal(
                        entry.get("command", ""), source=entry.get("source", "assistant"),
                        associated_goal=entry.get("associated_goal", "No specific goal"), disposition="cleared",
                        support_count=entry.get("support_count", 1), execute_by_inference=entry.get("execute_by_inference"))
                    append_recent_action_intent(
                        f"Cleared pending command: {entry.get('command', '')}", status="cleared",
                        command=entry.get("command", ""), source=entry.get("source", "assistant"),
                        associated_goal=entry.get("associated_goal", "No specific goal"),
                        execute_by_inference=entry.get("execute_by_inference"))
            result = pending_result("clear", before, PENDING_COMMAND_LEDGER.snapshot(store),
                                    affected_ids=[entry["pending_id"] for entry in selected],
                                    cleared_count=len(selected), execution_cancelled=False,
                                    uncertain_ids=[entry["pending_id"] for entry in selected if entry.get("pending_state") == "uncertain"])
        except Exception as error:
            result = pending_result("clear", before, PENDING_COMMAND_LEDGER.snapshot(store),
                                    success=False, effect_status="not_started", reason=str(error))
    record_pending_command_result(result)
    display_message('system' if result["success"] else 'error',
                    f"Cleared {result.get('cleared_count', 0)} pending command(s); no command executed. {result['reason']}")
    return result

