def recall_previous_summary_command(args, is_user):
    handoff_path = find_previous_handoff_path()
    character_hint = args[0].strip() if args else character_name
    init_path = os.path.join(script_directory, f"{character_hint}_init.txt")
    sections = []
    if handoff_path and os.path.exists(handoff_path):
        with open(handoff_path, "r", encoding="utf-8") as handoff_file:
            sections.append("[Previous Handoff]\n" + handoff_file.read().strip())
    else:
        sections.append("[Previous Handoff]\nNo previous handoff file was found.")
    if os.path.exists(init_path):
        with open(init_path, "r", encoding="utf-8", errors="replace") as init_file:
            sections.append("[Init Profile]\n" + init_file.read().strip())
    else:
        sections.append(f"[Init Profile]\nNo init profile found at {init_path}.")
    display_message('system', "\n\n".join(sections))


