def start_process(target, args):
    """Start either a daemon thread or a process, depending on the runtime mode."""
    # Stateful workers share cancellation tokens and the live settings owner.
    if not USE_PROCESS_WORKERS or target in {command_handler, chatgpt_process, screenshot_capture, drawing_worker}:
        class ThreadWorker:
            def __init__(self, thread):
                self.thread = thread
                self.pid = None

            def is_alive(self):
                return self.thread.is_alive()

            def terminate(self):
                return None

            def join(self, timeout=None):
                self.thread.join(timeout if timeout is not None else 0.2)

        worker = threading.Thread(target=target, args=args, daemon=True)
        worker.start()
        return ThreadWorker(worker)

    p = Process(target=target, args=args)
    p.daemon = True
    p.start()
    return p

class Context:
    def __init__(self):
        queue_factory = MPQueue if USE_PROCESS_WORKERS else queue.Queue
        self.audio_queue = queue_factory()
        self.text_queue = queue_factory()
        self.drawing_input_queue = queue_factory()
        self.drawing_output_queue = queue_factory()
        self.image_history_queue = queue_factory()
        self.command_queue = queue_factory()   # Command queue
        self.command_result_queue = queue_factory()
        self.chatgpt_input_queue = queue_factory()
        self.chatgpt_response_queue = queue_factory()
        self.error_queue = queue_factory()
        self.manager = Manager() if USE_PROCESS_WORKERS else None
        if self.manager is not None:
            self.shared_chat_history = self.manager.list()
            self.shared_image_history = self.manager.list()
            self.shared_recent_executed_actions = self.manager.list()  # Shared list for recent commands
            self.state_manager = self.manager.dict()
        else:
            self.shared_chat_history = agent_state.chat_history
            self.shared_image_history = []
            self.shared_recent_executed_actions = agent_state.recent_executed_actions
            self.state_manager = {}
        self.restart_counts = {}

    def close(self):
        for queue_obj in (
            self.audio_queue,
            self.text_queue,
            self.drawing_input_queue,
            self.drawing_output_queue,
            self.image_history_queue,
            self.command_queue,
            self.command_result_queue,
            self.chatgpt_input_queue,
            self.chatgpt_response_queue,
            self.error_queue,
        ):
            cleanup_queue_resource(queue_obj)
        if self.manager is not None:
            try:
                self.manager.shutdown()
            except Exception:
                pass

def monitor_and_restart_processes(processes, context):
    for name, p in list(processes.items()):
        if not p.is_alive():
            restart_count = context.restart_counts.get(name, 0) + 1
            context.restart_counts[name] = restart_count
            if restart_count > MAX_PROCESS_RESTARTS:
                safe_print(f"Process '{name}' exceeded restart limit; leaving it stopped.")
                processes.pop(name, None)
                continue
            safe_print(f"Process '{name}' (PID {p.pid}) terminated unexpectedly. Restarting ({restart_count}/{MAX_PROCESS_RESTARTS})...")
            # Restart logic based on process name
            if name == 'audio':
                if not ENABLE_AUDIO_CAPTURE:
                    continue
                processes[name] = start_process(audio_input_transcription, (context.audio_queue, context.error_queue))
            elif name == 'text':
                if not ENABLE_TEXT_INPUT_PROCESS:
                    continue
                processes[name] = start_process(user_text_input, (context.text_queue, context.error_queue))
            elif name == 'screenshot':
                processes[name] = start_process(screenshot_capture, (context.drawing_input_queue, context.error_queue))
            elif name == 'drawing':
                processes[name] = start_process(drawing_worker, (context.drawing_input_queue, context.drawing_output_queue, context.error_queue))
            elif name == 'command':
                processes[name] = start_process(command_handler, (context.command_queue, context.command_result_queue, context.shared_recent_executed_actions, context.error_queue))
            elif name == 'chatgpt':
                if not ENABLE_CHATGPT_WORKER:
                    continue
                processes[name] = start_process(chatgpt_process, (context.chatgpt_input_queue, context.chatgpt_response_queue, context.shared_chat_history, context.error_queue))
            elif name == 'image_history':
                if not ENABLE_IMAGE_HISTORY_WORKER:
                    continue
                processes[name] = start_process(image_history_manager, (context.image_history_queue, context.shared_image_history, context.error_queue))
            else:
                safe_print(f"Unknown process name: {name}. Cannot restart.")

    # Handle errors
        while not context.error_queue.empty():
            process_name, error_trace = context.error_queue.get()
            print(f"Process '{process_name}' terminated with an exception:")
            print(error_trace)
            # Optionally log the error or take additional actions
    worker_status = {}
    for name, process in processes.items():
        worker_status[name] = {
            "pid": int(getattr(process, "pid", 0) or 0),
            "active": bool(process.is_alive()),
            "restart_count": int(context.restart_counts.get(name, 0) or 0),
        }
    set_runtime_value("worker_process_status", worker_status)
    set_runtime_value("worker_restart_counts", dict(context.restart_counts))


def build_cli_parser():
    parser = argparse.ArgumentParser(description="Aurora 2 runtime launcher")

    auth_group = parser.add_mutually_exclusive_group()
    auth_group.add_argument("--auth-mode", choices=["api_key", "openai_chatgpt", "codex_oauth", "auto"], dest="auth_mode")
    auth_group.add_argument("-api", "--api", action="store_const", const="api_key", dest="auth_mode")
    auth_group.add_argument("-oauth", "--oauth", action="store_const", const="codex_oauth", dest="auth_mode")
    auth_group.add_argument("--auto-auth", action="store_const", const="auto", dest="auth_mode")

    live_group = parser.add_mutually_exclusive_group()
    live_group.add_argument("--live", dest="live_mode", action="store_true")
    live_group.add_argument("--offline", "--no-live", dest="live_mode", action="store_false")
    parser.set_defaults(live_mode=None)

    init_group = parser.add_mutually_exclusive_group()
    init_group.add_argument("--live-init", dest="load_live_init_prompt", action="store_true")
    init_group.add_argument("--no-live-init", dest="load_live_init_prompt", action="store_false")
    parser.set_defaults(load_live_init_prompt=None)

    sound_group = parser.add_mutually_exclusive_group()
    sound_group.add_argument("--sound", dest="sound_effects", action="store_true")
    sound_group.add_argument("--no-sound", dest="sound_effects", action="store_false")
    parser.set_defaults(sound_effects=None)

    chat_echo_group = parser.add_mutually_exclusive_group()
    chat_echo_group.add_argument("--chat-log-echo", dest="chat_log_echo", action="store_true")
    chat_echo_group.add_argument("--no-chat-log-echo", dest="chat_log_echo", action="store_false")
    parser.set_defaults(chat_log_echo=None)

    tile_grid_group = parser.add_mutually_exclusive_group()
    tile_grid_group.add_argument("--tile-grid", dest="tile_grid", action="store_true")
    tile_grid_group.add_argument("--no-tile-grid", dest="tile_grid", action="store_false")
    parser.set_defaults(tile_grid=None)

    cursor_label_group = parser.add_mutually_exclusive_group()
    cursor_label_group.add_argument("--cursor-label", dest="cursor_label", action="store_true")
    cursor_label_group.add_argument("--no-cursor-label", dest="cursor_label", action="store_false")
    parser.set_defaults(cursor_label=None)

    keypoint_grid_group = parser.add_mutually_exclusive_group()
    keypoint_grid_group.add_argument("--keypoint-grid", dest="keypoint_grid", action="store_true")
    keypoint_grid_group.add_argument("--no-keypoint-grid", dest="keypoint_grid", action="store_false")
    parser.set_defaults(keypoint_grid=None)

    status_overlay_group = parser.add_mutually_exclusive_group()
    status_overlay_group.add_argument("--status-overlay", dest="status_overlay", action="store_true")
    status_overlay_group.add_argument("--no-status-overlay", dest="status_overlay", action="store_false")
    parser.set_defaults(status_overlay=None)

    smoke_group = parser.add_mutually_exclusive_group()
    smoke_group.add_argument("--smoke-test", dest="smoke_test", action="store_true")
    smoke_group.add_argument("--no-smoke-test", dest="smoke_test", action="store_false")
    parser.set_defaults(smoke_test=None)

    parser.add_argument("-b", "--battle-profile", action="store_true", help="Bias startup toward Pokemon/gameplay operation.")
    parser.add_argument("--execution-mode", choices=["safe", "assist", "auto"])
    parser.add_argument("--action-mode", choices=["gb", "pyag", "none"])
    parser.add_argument("--model", help="Set text, vision, and reasoning models together.")
    parser.add_argument("--text-model")
    parser.add_argument("--vision-model")
    parser.add_argument("--reasoning-model")
    parser.add_argument("--model-transport", choices=MODEL_TRANSPORTS, help="Opt-in Responses/Astra transport; default chat_completions.")
    parser.add_argument("--thinking", "--reasoning-effort", dest="reasoning_effort", choices=sorted(ALLOWED_REASONING_EFFORTS))
    parser.add_argument("--battle-thinking", "--battle-reasoning-effort", dest="battle_reasoning_effort", choices=sorted(ALLOWED_REASONING_EFFORTS))
    parser.add_argument("--review-thinking", dest="review_reasoning_effort", choices=sorted(ALLOWED_REASONING_EFFORTS))
    parser.add_argument("--critique-thinking", dest="critique_reasoning_effort", choices=sorted(ALLOWED_REASONING_EFFORTS))
    parser.add_argument("--verbosity", choices=sorted(ALLOWED_MODEL_VERBOSITY))
    parser.add_argument("--review-verbosity", choices=sorted(ALLOWED_MODEL_VERBOSITY))
    parser.add_argument("--battle-verbosity", choices=sorted(ALLOWED_MODEL_VERBOSITY))
