    turn_capture_group = parser.add_mutually_exclusive_group()
    turn_capture_group.add_argument("--turn-capture-wake", dest="turn_capture_wake", action="store_true")
    turn_capture_group.add_argument("--no-turn-capture-wake", dest="turn_capture_wake", action="store_false")
