    demand_capture_group = parser.add_mutually_exclusive_group()
    demand_capture_group.add_argument("--demand-capture", dest="demand_capture", action="store_true")
    demand_capture_group.add_argument("--no-demand-capture", dest="demand_capture", action="store_false")
    parser.set_defaults(demand_capture=None)
