    episodic_group = parser.add_mutually_exclusive_group()
    episodic_group.add_argument("--episodic-memory", dest="episodic_memory", action="store_true")
    episodic_group.add_argument("--no-episodic-memory", dest="episodic_memory", action="store_false")
    parser.set_defaults(episodic_memory=None)
    parser.add_argument("--episodic-memory-interval-seconds", type=float)
    parser.add_argument("--init-mode", choices=["load", "test", "skip"])
    parser.add_argument("--game-profile", choices=sorted(ALLOWED_GAME_PROFILES))
    parser.add_argument("--smoke-profile")
    parser.add_argument("--login-codex-oauth", action="store_true", help="Open the ChatGPT/Codex OAuth login helper and continue startup.")
    parser.add_argument("--with-ui", "--ui", dest="with_ui", action="store_true", help="Launch the Aurora control panel UI alongside the runtime.")
    parser.add_argument("--no-ui", dest="with_ui", action="store_false")
    parser.set_defaults(with_ui=None)
    parser.add_argument("--lock-auth", action="store_true", help="Prevent runtime changes to auth mode.")
    parser.add_argument("--lock-live", action="store_true", help="Prevent runtime changes to live/offline mode.")
    parser.add_argument("--lock-execution", action="store_true", help="Prevent runtime changes to execution mode.")
    parser.add_argument("--lock-action", action="store_true", help="Prevent runtime changes to implicit action mode.")
    parser.add_argument("--lock-models", action="store_true", help="Prevent runtime changes to text/vision/reasoning model names.")
    parser.add_argument("--lock-overlay", action="store_true", help="Prevent runtime changes to overlay/grid controls.")
    parser.add_argument("--lock-runtime-settings", action="store_true", help="Prevent runtime changes to reasoning effort, temperature, screenshot interval, live init, sound, time logging, and chat log echo.")
    parser.add_argument("--lock-all-controls", action="store_true", help="Prevent runtime changes to all main control-plane settings.")
    parser.add_argument("--show-config", action="store_true", help="Print resolved startup configuration before starting.")
    parser.add_argument("--status-only", action="store_true", help="Print resolved startup configuration and exit.")
    parser.add_argument("--validate-model", help="Validate a model with a short chat/completions request and print JSON.")
    parser.add_argument("--add-model", action="store_true", help="Persist a validated model into Aurora's custom model catalog.")
    parser.add_argument("--remove-model", help="Remove a model from Aurora's custom model catalog and print JSON.")
    return parser


