def persist_runtime_capture(image, capture_hash, persist_reason, image_timestamp="", stamp=None, geometry=None):
    """Publish one artifact and its exact acquisition identity, then acknowledge."""
    if stamp is not None and not CAPTURE_SERVICE.accepts(stamp):
        return None
    if geometry is not None and tuple(image.size) != geometry.image_size:
        raise ValueError("Published pixels do not match their frame geometry")
    acquired_epoch = stamp.acquired_start_epoch if stamp else time.time()
    image_timestamp = image_timestamp or datetime.datetime.fromtimestamp(acquired_epoch).strftime('%Y-%m-%d %H:%M:%S')
    screenshot_file_path = save_capture(image, logging_folder)
    screenshot_file_hash = compute_image_fingerprint(screenshot_file_path, max_bytes=16 * 1024 * 1024)
    artifact = capture_artifacts.capture_reference(screenshot_file_path, stamp.frame_id, logging_folder) if stamp else {}
    with CAPTURE_SERVICE.lock:
        if stamp is not None and not CAPTURE_SERVICE.accepts(stamp):
            os.unlink(screenshot_file_path)  # our new, unpublished immutable file
            return None
        capture_frame = {"path": screenshot_file_path, "timestamp": image_timestamp, "hash": capture_hash,
                         "counter": int(runtime_state.get("turn_scheduler_capture_counter", 0) or 0) + 1,
                         "provenance": stamp.to_dict() if stamp else {"status": "unknown"},
                         "geometry": geometry.to_dict() if geometry else {"status": "unknown"}, "artifact": artifact}
        sidecar = ""
        try:
            sidecar = write_image_context_sidecar(
                screenshot_file_path, image_timestamp=image_timestamp, capture_hash=capture_hash,
                capture_reason=build_image_context_capture_reason(persist_reason),
                persist_reason=persist_reason, file_hash=screenshot_file_hash, capture_frame=capture_frame,
            )
        finally:
            if not sidecar:
                # Both names belong to this newly created, unpublished artifact.
                for owned_path in (screenshot_file_path, get_image_context_sidecar_path(screenshot_file_path)):
                    try:
                        os.unlink(owned_path)
                    except FileNotFoundError:
                        pass
        if not sidecar:
            raise OSError("Capture metadata publication failed")
        if stamp and not CAPTURE_SERVICE.publish(stamp, path=screenshot_file_path, timestamp=image_timestamp,
                                                capture_hash=capture_hash, counter=capture_frame["counter"], geometry=geometry, artifact=artifact):
            # Deadline checks include slow metadata I/O. Never advance scheduler
            # state after the service rejected this newly written artifact.
            for owned_path in (screenshot_file_path, sidecar):
                try:
                    os.unlink(owned_path)
                except FileNotFoundError:
                    pass
            mirror_capture_service_state()
            return None
        set_image_timestamp_value(image_timestamp)
        set_runtime_value("last_screenshot_path", screenshot_file_path)
        set_runtime_value("last_screenshot_timestamp", image_timestamp)
        remember_screenshot_persist_result(capture_hash, True, persist_reason)
        register_turn_scheduler_capture(screenshot_file_path, image_timestamp=image_timestamp,
                                        capture_hash=capture_hash, capture_frame=capture_frame)
        mirror_capture_service_state()
    return screenshot_file_path, image_timestamp


def drain_runtime_processed_capture(context):
    # Handle processed images
    stamp = None
    geometry = None
    published = False
    try:
        processed_payload, dropped_processed_frames = drain_queue_latest(context.drawing_output_queue)
        if processed_payload is None:
            raise queue.Empty
        if isinstance(processed_payload, CapturedFrame):
            processed_image, processed_frame_hash, stamp = processed_payload.image, processed_payload.capture_hash, processed_payload.stamp
            geometry = processed_payload.geometry
            if not CAPTURE_SERVICE.accepts(stamp):
                return
        elif isinstance(processed_payload, tuple) and len(processed_payload) == 2:
            processed_image, processed_frame_hash = processed_payload
        else:
            processed_image = processed_payload
            processed_frame_hash = compute_image_object_fingerprint(processed_image)
        should_persist, persist_reason = should_persist_processed_screenshot(processed_frame_hash)
        if stamp and CAPTURE_SERVICE.matches_pending(stamp):
            should_persist, persist_reason = True, f"demand_capture:{stamp.request_reason}"
        if not should_persist:
            remember_screenshot_persist_result(processed_frame_hash, False, persist_reason)
            if dropped_processed_frames:
                append_runtime_feedback(f"Dropped {dropped_processed_frames} stale processed frame(s) before unchanged-frame skip.")
            raise queue.Empty
        publication = persist_runtime_capture(
            processed_image, processed_frame_hash, persist_reason, stamp=stamp, geometry=geometry,
        )
        if publication is None:
            return
        screenshot_file_path, image_timestamp = publication
        published = True
        if dropped_processed_frames:
            append_runtime_feedback(f"Dropped {dropped_processed_frames} stale processed frame(s) before handling.")
        if ENABLE_IMAGE_HISTORY_WORKER:
            context.image_history_queue.put(screenshot_file_path)
        else:
            store_image(screenshot_file_path, context.shared_image_history)
    except queue.Empty:
        pass
    except Exception as error:
        if published:
            append_runtime_feedback("Published capture could not be added to image history; inspect the history worker/storage.")
        else:
            CAPTURE_SERVICE.fail("publication", error, stamp)
            mirror_capture_service_state()
            append_runtime_feedback("Capture publication failed; inspect capture state for retry status and artifact cleanup.")



def drain_runtime_command_results(context):
    processed = 0
    observation_entries = []
    while processed < 128:
        try:
            action_entry = context.command_result_queue.get_nowait()
        except queue.Empty:
            break
        ingest_command_result(action_entry, shared_recent_executed_actions=list(context.shared_recent_executed_actions))
        if should_request_turn_after_command_result(action_entry):
            observation_entries.append(action_entry)
        processed += 1
    if processed:
        update_pinned_information(list(context.shared_recent_executed_actions))
        if observation_entries:
            publish_batch_observation(observation_entries)
        write_control_panel_state_snapshot(force=True)
    return processed


def main():
    global queued_user_input, chat_history, tasks_list, apriority_tasks, notable_inventory
    global party_status, recent_context_events, pinned_immediate_actions, pinned_short_term_actions
    global recent_executed_actions, significant_past_tasks, hierarchical_tasks
    global pending_model_commands, runtime_state
    global inference_counter, token_counter, last_interaction_time, init_handoff_in_progress
    global last_command, image_timestamp, last_key, mouse_position, text_count, image_or_other_count
    global audio_buffer, running
    global font, overlay
    global screenbuffer, hbuffer
    global active_command_queue, shared_recent_executed_actions_ref
    global active_runtime_context
        # Initialize variables
    agent_state.reset().bind_globals()
    try:
        get_input_recovery()  # Recover evidence only; no automatic input replay.
    except Exception:
        # Publish the failed prerequisite without starting workers or silently falling back.
        set_runtime_value('runtime_process_active', False)
        write_control_panel_state_snapshot(force=True)
        raise
    global CAPTURE_SERVICE
    CAPTURE_SERVICE = CaptureService()
    mirror_capture_service_state()
    initialize_game_profile_runtime_state()
    initialize_turn_scheduler_runtime_state()
    runtime_state["auth_mode_configured"] = AUTH_MODE
    runtime_state["active_action_mode"] = normalize_action_mode(ACTIVE_ACTION_MODE) or "none"
    runtime_state["last_model_temperature"] = DEFAULT_MODEL_TEMPERATURE
    runtime_state["runtime_process_active"] = True
    runtime_state["runtime_pid"] = int(os.getpid())
    runtime_state["runtime_started_at_epoch"] = time.time()
    write_pid_file(runtime_pid_path, os.getpid())


    # Initialize font (if mutable)
    font = load_font(font_size)

    # Ensure the logging folder exists
    if not os.path.exists(logging_folder):
        os.makedirs(logging_folder)
    ensure_episodic_memory_store()
    ensure_external_bridge_files()
    load_external_bridge_state()
    initialize_episodic_memory_runtime_state()
    write_control_panel_state_snapshot(force=True)

    # Initialize Context
    context = Context()
    active_runtime_context = context
    agent_state.attach_command_handles(context.command_queue, context.shared_recent_executed_actions)


    # Start threads and processes
    #audio_thread = threading.Thread(target=run_audio_stream)
    #audio_thread.daemon = True
    #audio_thread.start()

    # Start other threads and processes


    # Initialize the application before workers start consuming process-local state.
    initialize_overlay()
    initialize_application()
    smoke_test_state = initialize_smoke_test_state()
    if smoke_test_state.get("enabled"):
        set_execution_mode("auto")
        append_runtime_feedback(
            f"Smoke test enabled with profile={smoke_test_state.get('profile', 'confirm_cursor')}."
        )
    if CONTROL_PANEL_ENABLED:
        try:
            launch_control_panel()
        except Exception as error:
            append_runtime_feedback(f"Failed to launch control panel: {summarize_runtime_text(str(error), max_chars=140)}")
    write_control_panel_state_snapshot(force=True)

    # Start processes
    processes = {}
    if ENABLE_AUDIO_CAPTURE:
        processes['audio'] = start_process(audio_input_transcription, (context.audio_queue, context.error_queue))
    if ENABLE_TEXT_INPUT_PROCESS:
        processes['text'] = start_process(user_text_input, (context.text_queue, context.error_queue))
    processes['screenshot'] = start_process(screenshot_capture, (context.drawing_input_queue, context.error_queue))
    processes['drawing'] = start_process(drawing_worker, (context.drawing_input_queue, context.drawing_output_queue, context.error_queue))
    processes['command'] = start_process(command_handler, (context.command_queue, context.command_result_queue, context.shared_recent_executed_actions, context.error_queue))
    if ENABLE_CHATGPT_WORKER:
        processes['chatgpt'] = start_process(chatgpt_process, (context.chatgpt_input_queue, context.chatgpt_response_queue, context.shared_chat_history, context.error_queue))
    if ENABLE_IMAGE_HISTORY_WORKER:
        processes['image_history'] = start_process(image_history_manager, (context.image_history_queue, context.shared_image_history, context.error_queue))

    # Main loop
    try:
        while is_agent_running():
            # Monitor and restart processes
            mirror_capture_service_state()
            monitor_and_restart_processes(
                processes,
                context
            )
            maybe_run_smoke_test_step(smoke_test_state)
            poll_external_reply_bridges()
            maybe_write_periodic_episodic_snapshot()
            tick_execution_recording()
            write_control_panel_state_snapshot()
            if not is_agent_running():
                break

            # Route data between processes

            # Handle errors
            while not context.error_queue.empty():
                process_name, error_trace = context.error_queue.get()
                print(f"Process '{process_name}' terminated with an exception:")
                print(error_trace)
                # Optionally log the error or take additional actions

            # Handle audio input
            try:
                transcribed_text = context.audio_queue.get_nowait()
                if is_command(transcribed_text):
                    enqueue_or_execute_command(transcribed_text, is_user=True, source='audio_input')
                else:
                    get_input_queue_store().put(transcribed_text)
            except queue.Empty:
                pass

            # Handle user text input
            try:
                user_input = context.text_queue.get_nowait()
                if is_command(user_input):
                    enqueue_or_execute_command(user_input, is_user=True, source='text_input')
                else:
                    get_input_queue_store().put(user_input)
            except queue.Empty:
                pass

            drain_runtime_processed_capture(context)

            if ENABLE_CHATGPT_WORKER:
                try:
                    # send_prompt_to_chatgpt already displays and routes accepted
                    # replies. Re-routing here could execute a reply twice.
                    context.chatgpt_response_queue.get_nowait()
                except queue.Empty:
                    pass

            drain_runtime_command_results(context)

            maybe_run_due_inference_turn()

            # Other main loop logic
            time.sleep(0.1)
    except KeyboardInterrupt:
        print("Terminating all processes.")
    finally:
        set_agent_running(False)
        safe_print("Aurora runtime shutdown starting.")
        shutdown_result_deadline = time.monotonic() + 0.75
        shutdown_quiet_cycles = 0
        shutdown_results_processed = False
        while time.monotonic() < shutdown_result_deadline:
            drained_result = False
            while True:
                try:
                    action_entry = context.command_result_queue.get_nowait()
                except queue.Empty:
                    break
                ingest_command_result(
                    action_entry,
                    shared_recent_executed_actions=list(context.shared_recent_executed_actions),
                )
                drained_result = True
                shutdown_results_processed = True
            if drained_result:
                shutdown_quiet_cycles = 0
            else:
                shutdown_quiet_cycles += 1
            if (
                shutdown_quiet_cycles >= 3
                and context.command_queue.empty()
                and context.command_result_queue.empty()
            ):
                break
            time.sleep(0.025)
        if shutdown_results_processed:
            update_pinned_information(list(context.shared_recent_executed_actions))
        runtime_state["runtime_process_active"] = False
        write_control_panel_state_snapshot(force=True)
        # Terminate all processes
        for name, p in processes.items():
            p.terminate()
        # Wait for processes to finish
        for name, p in processes.items():
            p.join(0.5)
        set_runtime_value("worker_shutdown_survivors", [name for name, p in processes.items() if p.is_alive()])
        if EXECUTION_RECORDING_SERVICE is not None:
            EXECUTION_RECORDING_SERVICE.close(timeout=5)
        mirror_capture_service_state()
        context.close()
        active_runtime_context = None
        terminate_launched_control_panel()
        safe_print("Aurora runtime shutdown finished.")
        write_control_panel_state_snapshot(force=True)
        remove_pid_file(runtime_pid_path, expected_pid=os.getpid())
        release_windows_single_instance_mutex(runtime_instance_mutex)
        if smoke_test_state.get("enabled") and smoke_test_state.get("completed") and SMOKE_TEST_FORCE_EXIT:
            safe_print("Smoke test forcing clean process exit.")
            sys.stdout.flush()
            sys.stderr.flush()
            os._exit(0)

if __name__ == '__main__':
    cli_parser = build_cli_parser()
    cli_args = cli_parser.parse_args()
    apply_cli_args(cli_args)

    if cli_args.remove_model:
        print(json.dumps(remove_custom_model_entry(cli_args.remove_model), ensure_ascii=True))
        sys.exit(0)

    if cli_args.validate_model:
        result = add_custom_model_entry(cli_args.validate_model) if cli_args.add_model else validate_model_name(cli_args.validate_model)
        print(json.dumps(result, ensure_ascii=True))
        sys.exit(0)

    if cli_args.show_config or cli_args.status_only:
        print(json.dumps(build_startup_config_snapshot(), indent=2))

    if cli_args.status_only:
        sys.exit(0)

    runtime_instance_mutex = acquire_windows_single_instance_mutex("Aurora2RuntimeMain")
    if runtime_instance_mutex is None:
        print("Aurora2 is already running. Duplicate launch blocked.")
        sys.exit(0)

    main()
